--  DDL for View achfile_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "achfile_view" (
  "featureActionId", "companyId", "createdby", 
  "createdts", "status", "roleId", 
  "scheduledDate", "amount", "fromAccountNumber"
) AS 
SELECT 
  "achfile"."featureActionId" "featureActionId", 
  "achfile"."companyId" "companyId", 
  "achfile"."createdby" "createdby", 
  "achfile"."createdts" "createdts", 
  "achfile"."status" "status", 
  "achfile"."roleId" "roleId", 
  CAST(
    "achfilerecord"."effectiveDate" as TIMESTAMP(0)
  ) "scheduledDate", 
  "achfilerecord"."offsetAmount" "amount", 
  "achfilerecord"."offsetAccountNumber" "fromAccountNumber" 
FROM 
  (
    "achfile" 
    JOIN "achfilerecord" ON (
      (
        "achfile"."achFile_id" = "achfilerecord"."achFileId"
      )
    )
  );
--  DDL for View achtransaction_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "achtransaction_view" (
  "transaction_id", "fromAccount", 
  "effectiveDate", "requestId", "createdby", 
  "roleId", "createdts", "maxAmount", 
  "status", "transactionType_id", 
  "templateType_id", "companyId", 
  "templateRequestType_id", "softDelete", 
  "templateName", "confirmationNumber", 
  "actedBy", "template_id", "updatedts", 
  "totalAmount", "featureActionId", 
  "fromAccountNumber", "amount", "scheduledDate"
) AS 
SELECT 
  "achtransaction"."transaction_id" "transaction_id", 
  "achtransaction"."fromAccount" "fromAccount", 
  "achtransaction"."effectiveDate" "effectiveDate", 
  "achtransaction"."requestId" "requestId", 
  "achtransaction"."createdby" "createdby", 
  "achtransaction"."roleId" "roleId", 
  "achtransaction"."createdts" "createdts", 
  "achtransaction"."maxAmount" "maxAmount", 
  "achtransaction"."status" "status", 
  "achtransaction"."transactionType_id" "transactionType_id", 
  "achtransaction"."templateType_id" "templateType_id", 
  "achtransaction"."companyId" "companyId", 
  "achtransaction"."templateRequestType_id" "templateRequestType_id", 
  "achtransaction"."softDelete" "softDelete", 
  "achtransaction"."templateName" "templateName", 
  "achtransaction"."confirmationNumber" "confirmationNumber", 
  "achtransaction"."actedBy" "actedBy", 
  "achtransaction"."template_id" "template_id", 
  "achtransaction"."updatedts" "updatedts", 
  "achtransaction"."totalAmount" "totalAmount", 
  "achtransaction"."featureActionId" "featureActionId", 
  "achtransaction"."fromAccount" "fromAccountNumber", 
  "achtransaction"."totalAmount" "amount", 
  CAST(
    "achtransaction"."effectiveDate" as TIMESTAMP(0)
  ) "scheduledDate" 
FROM 
  "achtransaction";

--  DDL for View actiondependency_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "actiondependency_view" (
  "actionName", "dependencyAction", 
  "featureId", "actionStatus", "featureStatus"
) AS 
SELECT 
  "dependentactions"."dependentactionId" "actionName", 
  "dependentactions"."actionId" "dependencyAction", 
  "dependentactions"."featureId" "featureId", 
  "featureaction"."status" "actionStatus", 
  "feature"."Status_id" "featureStatus" 
FROM 
  (
    (
      "dependentactions" 
      LEFT JOIN "featureaction" ON (
        (
          "dependentactions"."dependentactionId" = "featureaction"."id"
        )
      )
    ) 
    LEFT JOIN "feature" ON (
      (
        "dependentactions"."featureId" = "feature"."id"
      )
    )
  );
--  DDL for View alertattribute_view

CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "alertattribute_view" ("alertattribute_id", "alertattribute_LanguageCode", "alertattribute_name", "alertattribute_type", "alertattribute_softdeleteflag", "alertattributelistvalues_id", "alertattributelistvalues_AlertAttributeId", "alertattributelistvalues_LanguageCode", "alertattributelistvalues_name", "alertattributelistvalues_softdeleteflag", "alertattribute_companyLegalUnit") AS 
  SELECT "alertattribute"."id" "alertattribute_id"  , 
          "alertattribute"."LanguageCode" "alertattribute_LanguageCode"  , 
          "alertattribute"."name" "alertattribute_name"  , 
          "alertattribute"."type" "alertattribute_type"  , 
          "alertattribute"."softdeleteflag" "alertattribute_softdeleteflag"  , 
          "alertattributelistvalues"."id" "alertattributelistvalues_id"  , 
          "alertattributelistvalues"."AlertAttributeId" "alertattributelistvalues_AlertAttributeId"  , 
          "alertattributelistvalues"."LanguageCode" "alertattributelistvalues_LanguageCode"  , 
          "alertattributelistvalues"."name" "alertattributelistvalues_name"  , 
          "alertattributelistvalues"."softdeleteflag" "alertattributelistvalues_softdeleteflag",
          "alertattribute"."companyLegalUnit" "alertattribute_companyLegalUnit"  
     FROM ( "alertattribute"  
            LEFT JOIN "alertattributelistvalues"    ON ( ( "alertattribute"."id" = "alertattributelistvalues"."AlertAttributeId" ) ) 
             );
--  DDL for View alertcategory_view

CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "alertcategory_view" ("alertcategory_id", "alertcategory_status_id", "alertcategory_accountLevel", "alertcategory_DisplaySequence", "alertcategory_softdeleteflag", "alertcategory_Name", "alertcategory_freqId", "alertcategory_freqValue", "alertcategory_companyLegalUnit", "alertcategory_companyLegalunit", "alertcategory_freqTime", "Groups_count", "Alerts_count", "alertcategorytext_LanguageCode", "alertcategorytext_DisplayName", "alertcategorytext_Description", "alertcategorytext_createdby", "alertcategorytext_modifiedby", "alertcategorytext_createdts", "alertcategorytext_lastmodifiedts", "alertcategorytext_synctimestamp", "alertcategorytext_softdeleteflag") AS 
  SELECT "dbxalertcategory"."id" "alertcategory_id"  , 
          "dbxalertcategory"."status_id" "alertcategory_status_id"  , 
          "dbxalertcategory"."accountLevel" "alertcategory_accountLevel"  , 
          "dbxalertcategory"."DisplaySequence" "alertcategory_DisplaySequence"  , 
          "dbxalertcategory"."softdeleteflag" "alertcategory_softdeleteflag"  , 
          "dbxalertcategory"."Name" "alertcategory_Name"  , 
          "dbxalertcategory"."defaultFrequencyId" "alertcategory_freqId"  , 
          "dbxalertcategory"."defaultFrequencyValue" "alertcategory_freqValue"  , 
         "dbxalertcategory"."companyLegalUnit" "alertcategory_companyLegalUnit",
         "dbxalertcategory"."companyLegalUnit" "alertcategory_companyLegalunit",
          to_char("dbxalertcategory"."defaultFrequencyTime",'hh24:mi:ss') "alertcategory_freqTime"  , 
          ( SELECT COUNT("dbxalerttype"."id")   
            FROM "dbxalerttype"  
             WHERE  ( "dbxalerttype"."AlertCategoryId" = "dbxalertcategory"."id" ) ) "Groups_count"  , 
          ( SELECT SUM("alerttype_view"."Alerts_count")   
            FROM "alerttype_view"  
             WHERE  ( "alerttype_view"."alerttype_AlertCategoryId" = "dbxalertcategory"."id" ) ) "Alerts_count"  , 
          "dbxalertcategorytext"."LanguageCode" "alertcategorytext_LanguageCode"  , 
          "dbxalertcategorytext"."DisplayName" "alertcategorytext_DisplayName"  , 
          "dbxalertcategorytext"."Description" "alertcategorytext_Description"  , 
