          "dbxalertcategorytext"."createdts" "alertcategorytext_createdts"  , 
          "dbxalertcategorytext"."lastmodifiedts" "alertcategorytext_lastmodifiedts"  , 
          "dbxalertcategorytext"."synctimestamp" "alertcategorytext_synctimestamp"  , 
          "dbxalertcategorytext"."softdeleteflag" "alertcategorytext_softdeleteflag"   
     FROM ( "dbxalertcategorytext"  
            JOIN "dbxalertcategory"    ON ( ( "dbxalertcategorytext"."AlertCategoryId" = "dbxalertcategory"."id" ) ) 
             );

