--  DDL for View alerttypeaccounttype_view

CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "alerttypeaccounttype_view" ("accounttype_TypeID", "accounttype_TypeDescription", "accounttype_displayName", "alerttype_AlertTypeId", "alerttype_Name", "isSupported", "alerttype_softdeleteflag") AS 
  SELECT "accounttype"."TypeID" "accounttype_TypeID"  , 
          "accounttype"."TypeDescription" "accounttype_TypeDescription"  , 
          "accounttype"."displayName" "accounttype_displayName"  , 
          "dbxalerttype"."id" "alerttype_AlertTypeId"  , 
          "dbxalerttype"."Name" "alerttype_Name"  , 
          ( SELECT CASE  
                        WHEN ( COUNT(0)  > 0 ) THEN 1 
                   ELSE 0 
                      END col   
            FROM "alerttypeaccounttype"  
             WHERE  ( ( "alerttypeaccounttype"."AccountTypeId" = "accounttype"."TypeID" ) 
                      AND ( "alerttypeaccounttype"."AlertTypeId" = "dbxalerttype"."id" ) ) ) "isSupported"  , 
          "dbxalerttype"."softdeleteflag" "alerttype_softdeleteflag"   
     FROM "alerttypeaccounttype"  
            JOIN "accounttype"    ON "alerttypeaccounttype"."AccountTypeId" = "accounttype"."TypeID" 
            JOIN "dbxalerttype"    ON "alerttypeaccounttype"."AlertTypeId" = "dbxalerttype"."id";


--  DDL for View alerttypeapp_view
  
CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "alerttypeapp_view" ("app_Id", "alerttype_AlertTypeId", "alerttype_Name", "APP_NAME", "app_Description", "isSupported", "alerttype_softdeleteflag", "app_softdeleteflag") AS 
  SELECT "app"."id" "app_Id"  , 
          "dbxalerttype"."id" "alerttype_AlertTypeId"  , 
          "dbxalerttype"."Name" "alerttype_Name"  , 
          "app"."Name" APP_NAME  , 
          "app"."Description" "app_Description"  , 
          ( SELECT CASE  
                        WHEN ( COUNT(0)  > 0 ) THEN 1 
                   ELSE 0 
                      END col   
            FROM "alerttypeapp"  
             WHERE  ( "alerttypeapp"."AppId" = "app"."id" 
                      AND "alerttypeapp"."AlertTypeId" = "dbxalerttype"."id" ) ) "isSupported"  , 
          "dbxalerttype"."softdeleteflag" "alerttype_softdeleteflag"  , 
          "app"."softdeleteflag" "app_softdeleteflag"   
     FROM "alerttypeapp"  
            JOIN "app"    ON "alerttypeapp"."AppId" = "app"."id" 
            JOIN "dbxalerttype"    ON "alerttypeapp"."AlertTypeId" = "dbxalerttype"."id";

