  "archivedrequestmessage"."RepliedBy_Name" "requestmessage_RepliedBy_Name", 
  "archivedrequestmessage"."MessageDescription" "requestmessage_MessageDescription", 
  "archivedrequestmessage"."ReplySequence" "requestmessage_ReplySequence", 
  "archivedrequestmessage"."IsRead" "requestmessage_IsRead", 
  "archivedrequestmessage"."createdby" "requestmessage_createdby", 
  "archivedrequestmessage"."modifiedby" "requestmessage_modifiedby", 
  "archivedrequestmessage"."createdts" "requestmessage_createdts", 
  "archivedrequestmessage"."lastmodifiedts" "requestmessage_lastmodifiedts", 
  "archivedrequestmessage"."synctimestamp" "requestmessage_synctimestamp", 
  "archivedrequestmessage"."softdeleteflag" "requestmessage_softdeleteflag", 
  "archivedmessageattachment"."id" "messageattachment_id", 
  "archivedmessageattachment"."AttachmentType_id" "messageattachment_AttachmentType_id", 
  "archivedmessageattachment"."Media_id" "messageattachment_Media_id", 
  "archivedmessageattachment"."createdby" "messageattachment_createdby", 
  "archivedmessageattachment"."modifiedby" "messageattachment_modifiedby", 
  "archivedmessageattachment"."createdts" "messageattachment_createdts", 
  "archivedmessageattachment"."lastmodifiedts" "messageattachment_lastmodifiedts", 
  "archivedmessageattachment"."softdeleteflag" "messageattachment_softdeleteflag", 
  "archivedmedia"."id" "media_id", 
  "archivedmedia"."Name" "media_Name", 
  "archivedmedia"."Size" "media_Size", 
  "archivedmedia"."Type" "media_Type", 
  "archivedmedia"."Description" "media_Description", 
  "archivedmedia"."Url" "media_Url", 
  "archivedmedia"."createdby" "media_createdby", 
  "archivedmedia"."modifiedby" "media_modifiedby", 
  "archivedmedia"."lastmodifiedts" "media_lastmodifiedts", 
  "archivedmedia"."synctimestamp" "media_synctimestamp", 
  "archivedmedia"."softdeleteflag" "media_softdeleteflag" 
FROM 
  (
    (
      (
        (
          (
            (
              "archivedcustomerrequest" 
              JOIN "archivedrequestmessage" ON (
                (
                  "archivedcustomerrequest"."id" = "archivedrequestmessage"."CustomerRequest_id"
                )
              )
            ) 
            JOIN "customer" ON (
              (
                "archivedcustomerrequest"."Customer_id" = "customer"."id"
              )
            )
          ) 
          JOIN "requestcategory" ON (
            (
              "archivedcustomerrequest"."RequestCategory_id" = "requestcategory"."id"
            )
          )
        ) 
        LEFT JOIN "systemuser" ON (
          (
            "archivedcustomerrequest"."AssignedTo" = "systemuser"."id"
          )
        )
      ) 
      LEFT JOIN "archivedmessageattachment" ON (
        (
          "archivedrequestmessage"."id" = "archivedmessageattachment"."RequestMessage_id"
        )
      )
    ) 
    LEFT JOIN "archivedmedia" ON (
      (
        "archivedmessageattachment"."Media_id" = "archivedmedia"."id"
      )
    )
  );
--  DDL for View autosubscribedalertsview

CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "autosubscribedalertsview" ("categoryid", "groupid", "alertsubtypeid", "Name", "isAccountLevel", "attributeId", "alertConditionId", "value1", "value2", "Status_id", "Description", "isGlobal", "defaultFrequencyId", "defaultFrequencyValue", "defaultFrequencyTime", "recipienttype", "createdby", "modifiedby", "createdts", "lastmodifiedts", "synctimestamp", "softdeleteflag", "isAutoSubscribeEnabled", "externalSystem") AS 
  SELECT "dbxalertcategory"."id" "categoryid"  , 
          "dbxalerttype"."id" "groupid"  , 
          "alertsubtype"."id" "alertsubtypeid"  , 
          "alertsubtype"."Name" , 
          "alertsubtype"."isAccountLevel" , 
          "alertsubtype"."attributeId" , 
          "alertsubtype"."alertConditionId" , 
          "alertsubtype"."value1" , 
          "alertsubtype"."value2" , 
          "alertsubtype"."Status_id" , 
          "alertsubtype"."Description" , 
          "alertsubtype"."isGlobal" , 
          "alertsubtype"."defaultFrequencyId" , 
          "alertsubtype"."defaultFrequencyValue" , 
          "alertsubtype"."defaultFrequencyTime" , 
          "alertsubtype"."recipienttype" , 
          "alertsubtype"."createdby" , 
          "alertsubtype"."modifiedby" , 
          "alertsubtype"."createdts" , 
          "alertsubtype"."lastmodifiedts" , 
          "alertsubtype"."synctimestamp" , 
          "alertsubtype"."softdeleteflag" , 
          "alertsubtype"."isAutoSubscribeEnabled" , 
