--  DDL for View bankfortransfer_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "bankfortransfer_view" (
  "id", "Bank_Code", "Bank_Name", "Logo", 
  "Status_id", "Bank_Url", "Address_id", 
  "AddressLine1", "AddressLine2", 
  "City_id", "City_Name", "Region_id", 
  "Region_Name", "Country_id", "Country_Name", 
  "Routing_Code", "Routing_Number", 
  "Service_id", "Service_Name"
) AS 
SELECT 
  "bankfortransfer"."id" "id", 
  "bankfortransfer"."Code" "Bank_Code", 
  "bankfortransfer"."Name" "Bank_Name", 
  "bankfortransfer"."Logo" "Logo", 
  "bankfortransfer"."Status_id" "Status_id", 
  "bankfortransfer"."Url" "Bank_Url", 
  "bankfortransfer"."Address_id" "Address_id", 
  "address"."addressLine1" "AddressLine1", 
  "address"."addressLine2" "AddressLine2", 
  "address"."City_id" "City_id", 
  "city"."Name" "City_Name", 
  "region"."id" "Region_id", 
  "region"."Name" "Region_Name", 
  "region"."Country_id" "Country_id", 
  "country"."Name" "Country_Name", 
  "bankservice"."RoutingCode" "Routing_Code", 
  "bankservice"."RoutingNumber" "Routing_Number", 
  "bankservice"."Service_id" "Service_id", 
  "service"."Name" SERVICE_NAME 
FROM 
  (
    (
      (
        (
          (
            (
              "bankfortransfer" 
              LEFT JOIN "bankservice" ON (
                (
                  "bankfortransfer"."id" = "bankservice"."BankForTransfer_id"
                )
              )
            ) 
            JOIN "address" ON (
              (
                "bankfortransfer"."Address_id" = "address"."id"
              )
            )
          ) 
          JOIN "city" ON (
            (
              "address"."City_id" = "city"."id"
            )
          )
        ) 
        JOIN "region" ON (
          (
            "address"."Region_id" = "region"."id"
          )
        )
      ) 
      JOIN "country" ON (
        (
          "region"."Country_id" = "country"."id"
        )
      )
    ) 
    JOIN "service" ON (
      (
        "bankservice"."Service_id" = "service"."id"
      )
    )
  );
--  DDL for View branch_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "branch_view" (
  "Branch_id", "Branch_Typeid", "Branch_Name", 
  "Branch_DisplayName", "Branch_Description", 
  "Branch_Code", "Branch_PhoneNumber", 
  "Branch_EmailId", "Branch_Status_id", 
  "Branch_IsMainBranch", "Branch_WorkSchedule_id", 
  "Branch_MainBranchCode", "Branch_WebSiteUrl", 
  "City_id", "City_Name", "Address_id", 
  "Branch_Complete_Addr", "Branch_createdby", 
  "Branch_modifiedby", "Branch_createdts", 
  "Branch_lastmodifiedts", "Branch_synctimestamp"
) AS 
SELECT 
  loc."id" "Branch_id", 
  NVL(loc."Type_id", '') "Branch_Typeid", 
  NVL(loc."Name", '') "Branch_Name", 
  NVL(loc."DisplayName", '') "Branch_DisplayName", 
  NVL(loc."Description", '') "Branch_Description", 
  NVL(loc."Code", '') "Branch_Code", 
  NVL(loc."PhoneNumber", '') "Branch_PhoneNumber", 
  NVL(loc."EmailId", '') "Branch_EmailId", 
  NVL(loc."Status_id", '') "Branch_Status_id", 
  NVL(
    CAST(
      loc."IsMainBranch" as VARCHAR2(50)
    ), 
    ''
  ) "Branch_IsMainBranch", 
  NVL(loc."WorkSchedule_id", '') "Branch_WorkSchedule_id", 
  NVL(loc."MainBranchCode", '') "Branch_MainBranchCode", 
  NVL(loc."WebSiteUrl", '') "Branch_WebSiteUrl", 
  "address"."City_id" "City_id", 
  "city"."Name" "City_Name", 
  loc."Address_id" "Address_id", 
  "address"."addressLine1" || ', ' || NVL("address"."addressLine2", '') || ', ' || "city"."Name" || ', ' || "region"."Name" || ', ' || "country"."Name" || ', ' || NVL("address"."zipCode", '') "Branch_Complete_Addr", 
  NVL(loc."createdby", '') "Branch_createdby", 
  NVL(loc."modifiedby", '') "Branch_modifiedby", 
  NVL(loc."createdts", NULL) "Branch_createdts", 
  NVL(loc."lastmodifiedts", NULL) "Branch_lastmodifiedts", 
  NVL(loc."synctimestamp", NULL) "Branch_synctimestamp" 
FROM 
  (
    (
      (
        (
          "location" loc 
          JOIN "address" ON (
            (
              (
                loc."Address_id" = "address"."id"
              ) 
              AND (loc."Type_id" = 'Branch')
            )
          )
        ) 
        JOIN "city" ON (
          (
            "city"."id" = "address"."City_id"
          )
        )
      ) 
      JOIN "region" ON (
        (
          "region"."id" = "address"."Region_id"
        )
      )
    ) 
    JOIN "country" ON (
      (
        "city"."Country_id" = "country"."id"
      )
    )
  );
--  DDL for View businesstypes_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "businesstypes_view" (
  "BusinessType_id", "BusinessType_name", 
  "minAuthSignatory", "maxAuthSignatory", 
  "Groups_count", "Default_group", 
  "Customers_Count", "DefaultGroupCustomers_Count"
) AS 
SELECT 
  "businesstype"."id" "BusinessType_id", 
  "businesstype"."name" "BusinessType_name", 
  "businesstype"."minAuthSignatory" "minAuthSignatory", 
  "businesstype"."maxAuthSignatory" "maxAuthSignatory", 
  (
    SELECT 
      COUNT("groupbusinesstype"."Group_id") 
    FROM 
      "groupbusinesstype" 
    WHERE 
      "groupbusinesstype"."BusinessType_id" = "businesstype"."id"
  ) "Groups_count", 
  (
    SELECT 
      "groupbusinesstype"."Group_id" "Group_id" 
    FROM 
      "groupbusinesstype" 
    WHERE 
      (
        "groupbusinesstype"."BusinessType_id" = "businesstype"."id"
      ) 
      AND (
        "groupbusinesstype"."isDefaultGroup" = 1
      )
  ) "Default_group", 
  (
    SELECT 
      COUNT(
        "customerbusinesstype"."Customer_id"
      ) 
    FROM 
      "customerbusinesstype" 
    WHERE 
      (
        "customerbusinesstype"."BusinessType_id" = "businesstype"."id"
      )
  ) "Customers_Count", 
  (
    SELECT 
      COUNT("customergroup"."Customer_id") 
    FROM 
      "customergroup" 
    WHERE 
      (
        (
          "customergroup"."Group_id" = 'Default_group'
        ) 
        AND "customergroup"."Customer_id" IN (
          SELECT 
            "customerbusinesstype"."Customer_id" 
          FROM 
            "customerbusinesstype" 
          WHERE 
            "customerbusinesstype"."BusinessType_id" = "businesstype"."id"
        )
      )
  ) "DefaultGroupCustomers_Count" 
FROM 
  "businesstype";

--  DDL for View card_request_notification_count_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "card_request_notification_count_view" (
  "customerId", "cardNumber", "reqType", 
  "requestcount"
) AS 
SELECT 
  tbl$1."customerId", 
  tbl$1."cardNumber", 
  tbl$1."reqType", 
  tbl$1."requestcount" 
FROM 
  (
    SELECT 
      cardaccountrequest_alias."Customer_id" "customerId", 
      cardaccountrequest_alias."CardAccountNumber" "cardNumber", 
      'REQUEST' "reqType", 
      COUNT(
        cardaccountrequest_alias."CardAccountNumber"
      ) "requestcount" 
    FROM 
      "cardaccountrequest" cardaccountrequest_alias 
    GROUP BY 
      cardaccountrequest_alias."Customer_id", 
      cardaccountrequest_alias."CardAccountNumber" 
    ORDER BY 
      cardaccountrequest_alias."Customer_id", 
      cardaccountrequest_alias."CardAccountNumber" FETCH FIRST 9223372036854775807 ROWS ONLY
  ) tbl$1 
UNION 
SELECT 
  notificationcardinfo_alias."Customer_id" "customerId", 
  notificationcardinfo_alias."CardNumber" "cardNumber", 
  'NOTIFICATION' "reqType", 
  1 "requestcount" 
FROM 
  "notificationcardinfo" notificationcardinfo_alias;

--  DDL for View cardaccountrequest_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "cardaccountrequest_view" (
  "Request_id", "Date", "TYPE", "CardAccountNumber", 
  "CardAccountName", "Reason", "AccountType", 
  "Status", "CustomerId", "CommunicationValue", 
  "DeliveryMode", "Address"
) AS 
SELECT 
  "cardaccountrequest"."id" "Request_id", 
  "cardaccountrequest"."Date" "Date", 
  "cardaccountrequesttype"."DisplayName" "TYPE", 
  "cardaccountrequest"."CardAccountNumber" "CardAccountNumber", 
  "cardaccountrequest"."CardAccountName" "CardAccountName", 
  "cardaccountrequest"."RequestReason" "Reason", 
  "cardaccountrequest"."AccountType" "AccountType", 
  (
    SELECT 
      "status"."Description" 
    FROM 
      "status" 
    WHERE 
      (
        "cardaccountrequest"."Status_id" = "status"."id"
      ) FETCH FIRST 1 ROWS ONLY
  ) "Status", 
  "cardaccountrequest"."Customer_id" "CustomerId", 
  "customercommunication"."Value" "CommunicationValue", 
  "communicationtype"."Description" "DeliveryMode", 
  "address"."addressLine2" || "address"."addressLine1" || "address"."addressLine3" || "address"."addressLine1" || "city"."Name" || "address"."addressLine1" || "region"."Name" || "address"."addressLine1" || "country"."Name" || "address"."addressLine1" || "address"."zipCode" "Address" 
FROM 
  (
    (
      (
        (
          (
            (
              (
                "cardaccountrequest" 
                LEFT JOIN "cardaccountrequesttype" ON (
                  (
                    "cardaccountrequest"."RequestType_id" = "cardaccountrequesttype"."id"
                  )
                )
              ) 
              LEFT JOIN "address" ON (
                (
                  "cardaccountrequest"."Address_id" = "address"."id"
                )
              )
            ) 
            LEFT JOIN "city" ON (
              (
                "address"."City_id" = "city"."id"
              )
            )
          ) 
          LEFT JOIN "region" ON (
            (
              "address"."Region_id" = "region"."id"
            )
          )
        ) 
        LEFT JOIN "country" ON (
          (
            "city"."Country_id" = "country"."id"
          )
        )
      ) 
      LEFT JOIN "customercommunication" ON (
        (
          "cardaccountrequest"."Communication_id" = "customercommunication"."id"
        )
      )
    ) 
    LEFT JOIN "communicationtype" ON (
      (
        "customercommunication"."Type_id" = "communicationtype"."id"
      )
    )
  );
