--  DDL for View composite_actions_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "composite_actions_view" (
  "id", "Name", "Description", "Action_id", 
  "Feature_id", "Permission_id", "isEnabled", 
  "createdby", "modifiedby", "createdts", 
  "lastmodifiedts", "synctimestamp", 
  "softdeleteflag"
) AS 
SELECT 
  "compositeaction"."id" "id", 
  CASE WHEN (
    CASE WHEN "compositeaction"."Action_id" IS NULL THEN 1 ELSE 0 END <> 0
  ) THEN "compositeaction"."Name" ELSE "featureaction"."name" END "Name", 
  CASE WHEN (
    CASE WHEN "compositeaction"."Action_id" IS NULL THEN 1 ELSE 0 END <> 0
  ) THEN "compositeaction"."Description" ELSE "featureaction"."description" END "Description", 
  "compositeaction"."Action_id" "Action_id", 
  "compositeaction"."Feature_id" "Feature_id", 
  "compositeaction"."Permission_id" "Permission_id", 
  "compositeaction"."isEnabled" "isEnabled", 
  "compositeaction"."createdby" "createdby", 
  "compositeaction"."modifiedby" "modifiedby", 
  "compositeaction"."createdts" "createdts", 
  "compositeaction"."lastmodifiedts" "lastmodifiedts", 
  "compositeaction"."synctimestamp" "synctimestamp", 
  "compositeaction"."softdeleteflag" "softdeleteflag" 
FROM 
  (
    "compositeaction" 
    LEFT JOIN "featureaction" ON (
      (
        "featureaction"."id" = "compositeaction"."Action_id"
      )
    )
  );
