  "request_count"
) AS 
SELECT 
  "requestcategory"."id" "requestcategory_id", 
  MIN("requestcategory"."Name") "requestcategory_Name", 
  COUNT("customerrequest"."id") "request_count" 
FROM 
  (
    "requestcategory" 
    LEFT JOIN "customerrequest" ON (
      (
        (
          "customerrequest"."RequestCategory_id" = "requestcategory"."id"
        ) 
        AND (
          "customerrequest"."Status_id" = 'SID_OPEN'
        )
      )
    )
  ) 
GROUP BY 
  "requestcategory"."id" 
ORDER BY 
  "requestcategory"."id" FETCH FIRST 9223372036854775807 ROWS ONLY;

--  DDL for View customer_request_csr_count_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customer_request_csr_count_view" (
  "customerrequest_Status_id", "status_Description", 
  "customerrequest_assignedTo", "request_count"
) AS 
SELECT 
  "customerrequest"."Status_id" "customerrequest_Status_id", 
  
  /* 
                       *   SSMA warning messages: 
                       *   M2SS0104: Non aggregated column DESCRIPTION is aggregated with Min(..) in Select, Orderby and Having clauses. 
                       *   M2SS0104: Non aggregated column ID is aggregated with Min(..) in Select, Orderby and Having clauses. 
                       */
  (
    SELECT 
      ("status"."Description") "Description" 
    FROM 
      "status" 
    WHERE 
      "status"."id" = "customerrequest"."Status_id" FETCH FIRST 1 ROWS ONLY
  ) "status_Description", 
  "customerrequest"."AssignedTo" "customerrequest_assignedTo", 
  COUNT("customerrequest"."id") "request_count" 
FROM 
  "customerrequest" 
GROUP BY 
  "customerrequest"."AssignedTo", 
  "customerrequest"."Status_id";

