  "requestmessage"."lastmodifiedts" "requestmessage_lastmodifiedts", 
  "requestmessage"."synctimestamp" "requestmessage_synctimestamp", 
  "requestmessage"."softdeleteflag" "requestmessage_softdeleteflag", 
  "messageattachment"."id" "messageattachment_id", 
  "messageattachment"."AttachmentType_id" "messageattachment_AttachmentType_id", 
  "messageattachment"."Media_id" "messageattachment_Media_id", 
  "messageattachment"."createdby" "messageattachment_createdby", 
  "messageattachment"."modifiedby" "messageattachment_modifiedby", 
  "messageattachment"."createdts" "messageattachment_createdts", 
  "messageattachment"."lastmodifiedts" "messageattachment_lastmodifiedts", 
  "messageattachment"."softdeleteflag" "messageattachment_softdeleteflag", 
  "media"."id" "media_id", 
  "media"."Name" "media_Name", 
  "media"."Size" "media_Size", 
  "media"."Type" "media_Type", 
  "media"."Description" "media_Description", 
  "media"."Url" "media_Url", 
  "media"."createdby" "media_createdby", 
  "media"."modifiedby" "media_modifiedby", 
  "media"."lastmodifiedts" "media_lastmodifiedts", 
  "media"."synctimestamp" "media_synctimestamp", 
  "media"."softdeleteflag" "media_softdeleteflag" 
FROM 
  (
    (
      (
        (
          (
            (
              "customerrequest" 
              JOIN "customer" ON (
                (
                  "customerrequest"."Customer_id" = "customer"."id"
                )
              )
            ) 
            JOIN "requestcategory" ON (
              (
                "customerrequest"."RequestCategory_id" = "requestcategory"."id"
              )
            )
          ) 
          JOIN "requestmessage" ON (
            (
              "customerrequest"."id" = "requestmessage"."CustomerRequest_id"
            )
          )
        ) 
        LEFT JOIN "systemuser" ON (
          (
            "customerrequest"."AssignedTo" = "systemuser"."id"
          )
        )
      ) 
      LEFT JOIN "messageattachment" ON (
        (
          "requestmessage"."id" = "messageattachment"."RequestMessage_id"
        )
      )
    ) 
    LEFT JOIN "media" ON (
      (
        "messageattachment"."Media_id" = "media"."id"
      )
    )
  );
--  DDL for View customer_request_status_count_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customer_request_status_count_view" ("Count", "Status_id") AS 
SELECT 
  tbl$1."Count", 
  tbl$1."Status_id" 
FROM 
  (
    
    /* 
                             *   SSMA warning messages: 
                             *   M2SS0219: Converted operator may not work exactly the same as in MySQL 
                             */
    SELECT 
      COUNT(cr."id") "Count", 
      s1."id" "Status_id" 
    FROM 
      (
        "status" s1 
        INNER JOIN "customerrequest" cr ON (
          (s1."id" = cr."Status_id")
        )
      ) 
    WHERE 
      (
        (
          s1."Type_id" = 'STID_CUSTOMERREQUEST'
        ) 
        AND (
          s1."id" IN (
            'SID_CANCELLED', 'SID_DELETED', 
            'SID_INPROGRESS', 'SID_ONHOLD', 
            'SID_OPEN', 'SID_RESOLVED'
          )
        )
      ) 
    GROUP BY 
      s1."id" 
    ORDER BY 
      "Status_id" FETCH FIRST 9223372036854775807 ROWS ONLY
  ) tbl$1 
UNION ALL 
SELECT 
  COUNT(acr."id") COUNT, 
  s2."id" "Status_id" 
FROM 
  (
    "status" s2 
    JOIN "archivedcustomerrequest" acr ON (
      (s2."id" = acr."Status_id")
    )
  ) 
WHERE 
  (
    (
      s2."Type_id" = 'STID_CUSTOMERREQUEST'
    ) 
    AND (s2."id" = 'SID_ARCHIVED')
  ) 
GROUP BY 
  s2."id" 
ORDER BY 
  "Status_id" FETCH FIRST 9223372036854775807 ROWS ONLY;

--  DDL for View customerbasicinfo_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customerbasicinfo_view" (
  "Username", "FirstName", "MiddleName", 
  "LastName", "Name", "Salutation", 
  "Customer_id", "SSN", "CustomerSince", 
  "Gender", "DateOfBirth", "CustomerStatus_id", 
  "CustomerStatus_name", "MaritalStatus_id", 
  "MaritalStatus_name", "SpouseName", 
  "DrivingLicenseNumber", "lockedOn", 
  "lockCount", "EmployementStatus_id", 
  "EmployementStatus_name", "CustomerFlag_ids", 
  "CustomerFlag", "IsEnrolledForOlb", 
  "IsStaffMember", "Branch_id", "Branch_name", 
  "Branch_code", "IsOlbAllowed", "IsAssistConsented", 
  "isEagreementSigned", "isCombinedUser", 
  "CustomerType_id", "CustomerType_Name", 
  "CustomerType_Description", "Customer_Role", 
  "isEAgreementRequired", "organisation_id", 
  "organisation_name", "PrimaryPhoneNumber", 
  "PrimaryEmailAddress", "DocumentsSubmitted", 
  "ApplicantChannel", "Product", "Reason"
) AS 
SELECT 
  "customer"."UserName" "Username", 
  min("customer"."FirstName") "FirstName", 
  min("customer"."MiddleName") "MiddleName", 
  min("customer"."LastName") "LastName", 
  NVL("customer"."FirstName", '') || ' ' || NVL("customer"."MiddleName", '') || ' ' || NVL("customer"."LastName", '') "Name", 
  "customer"."Salutation" "Salutation", 
  "customer"."id" "Customer_id", 
  "customer"."Ssn" "SSN", 
  "customer"."createdts" "CustomerSince", 
  "customer"."Gender" "Gender", 
  "customer"."DateOfBirth" "DateOfBirth", 
  "customer"."Status_id" "CustomerStatus_id", 
  customerstatus."Description" "CustomerStatus_name", 
  "customer"."MaritalStatus_id" "MaritalStatus_id", 
  "maritalstatus"."Description" "MaritalStatus_name", 
  "customer"."SpouseName" "SpouseName", 
  "customer"."DrivingLicenseNumber" "DrivingLicenseNumber", 
  "customer"."lockedOn" "lockedOn", 
  "customer"."lockCount" "lockCount", 
  "customer"."EmployementStatus_id" "EmployementStatus_id", 
  employementstatus."Description" "EmployementStatus_name", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "customerflagstatus"."Status_id" as nvarchar2(2000)
        ), 
        ','
      ) 
    FROM 
      "customerflagstatus" 
    WHERE 
      (
        "customerflagstatus"."Customer_id" = "customer"."id"
      )
  ) "CustomerFlag_ids", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "status"."Description" as nvarchar2(2000)
        ), 
        ','
      ) 
    FROM 
      "status" 
    WHERE 
      "status"."id" IN (
        SELECT 
          "customerflagstatus"."Status_id" 
        FROM 
          "customerflagstatus" 
        WHERE 
          (
            "customerflagstatus"."Customer_id" = "customer"."id"
          )
      )
  ) "CustomerFlag", 
  "customer"."IsEnrolledForOlb" AS "IsEnrolledForOlb", 
  "customer"."IsStaffMember" "IsStaffMember", 
  "customer"."Location_id" "Branch_id", 
  "location"."Name" "Branch_name", 
  "location"."Code" "Branch_code", 
  "customer"."IsOlbAllowed" "IsOlbAllowed", 
  "customer"."IsAssistConsented" "IsAssistConsented", 
  "customer"."isEagreementSigned" "isEagreementSigned", 
  "customer"."isCombinedUser" "isCombinedUser", 
  decode(
    "customer"."isCombinedUser", '1', 
    'TYPE_ID_RETAIL,TYPE_ID_BUSINESS', 
    "customer"."CustomerType_id"
  ) "CustomerType_id", 
  decode(
    "customer"."isCombinedUser", '1', 
    'Retail Banking,Business Banking', 
    "customertype"."Name"
  ) "CustomerType_Name", 
  decode(
    "customer"."isCombinedUser", '1', 
    'Retail and Business Banking User', 
    "customertype"."Description"
  ) "CustomerType_Description", 
  
  /*IIF(("customer"."isCombinedUser" = '1'), 
                'TYPE_ID_RETAIL,TYPE_ID_BUSINESS', 
                "customer"."CustomerType_id")  "CustomerType_id", 
            IIF(("customer"."isCombinedUser" = '1'), 
                'Retail Banking,Business Banking', 
                "customertype"."Name")  "CustomerType_Name", 
            IIF(("customer"."isCombinedUser" = '1'), 
                'Retail and Business Banking User', 
                "customertype"."Description")  "CustomerType_Description", */
  (
    SELECT 
      "membergroup"."Name" 
    FROM 
      "membergroup" 
    WHERE 
      "membergroup"."id" IN (
        SELECT 
          "customergroup"."Group_id" 
        FROM 
          "customergroup" 
        WHERE 
          (
            "customer"."id" = "customergroup"."Customer_id"
          )
      ) FETCH FIRST 1 ROWS ONLY
  ) "Customer_Role", 
  (
    SELECT 
      "membergroup"."isEAgreementActive" 
    FROM 
      "membergroup" 
    WHERE 
      "membergroup"."id" IN (
        SELECT 
          "customergroup"."Group_id" 
        FROM 
          "customergroup" 
        WHERE 
          (
            "customer"."id" = "customergroup"."Customer_id"
          )
      ) FETCH FIRST 1 ROWS ONLY
  ) "isEAgreementRequired", 
  "customer"."Organization_Id" "organisation_id", 
  "organisation"."Name" "organisation_name", 
  primaryphone."Value" "PrimaryPhoneNumber", 
  primaryemail."Value" "PrimaryEmailAddress", 
  CAST(
    "customer"."DocumentsSubmitted" as nvarchar2(2000)
  ) "DocumentsSubmitted", 
  "customer"."ApplicantChannel" "ApplicantChannel", 
  "customer"."Product" "Product", 
  CAST(
    "customer"."Reason" as nvarchar2(2000)
  ) "Reason" 
FROM 
  (
    (
      (
        (
          (
            (
              (
                (
                  "customer" 
                  LEFT JOIN "location" ON (
                    (
                      "customer"."Location_id" = "location"."id"
                    )
                  )
                ) 
                LEFT JOIN "organisation" ON (
                  (
                    "customer"."Organization_Id" = "organisation"."id"
                  )
                )
              ) 
              LEFT JOIN "customertype" ON (
                (
                  "customer"."CustomerType_id" = "customertype"."id"
                )
              )
            ) 
            LEFT JOIN "status" customerstatus ON (
              (
                "customer"."Status_id" = customerstatus."id"
              )
            )
          ) 
          LEFT JOIN "status" "maritalstatus" ON (
            (
              "customer"."MaritalStatus_id" = "maritalstatus"."id"
            )
          )
        ) 
        LEFT JOIN "status" employementstatus ON (
          (
            "customer"."EmployementStatus_id" = employementstatus."id"
          )
        )
      ) 
      LEFT JOIN "customercommunication" primaryphone ON (
        (
          (
            primaryphone."Customer_id" = "customer"."id"
          ) 
          AND (primaryphone."isPrimary" = 1) 
          AND (
            primaryphone."Type_id" = 'COMM_TYPE_PHONE'
          )
        )
      )
    ) 
    LEFT JOIN "customercommunication" primaryemail ON (
      (
        (
          primaryemail."Customer_id" = "customer"."id"
        ) 
        AND (primaryemail."isPrimary" = 1) 
        AND (
          primaryemail."Type_id" = 'COMM_TYPE_EMAIL'
        )
      )
    )
  ) 
GROUP BY 
  "customer"."id", 
  "customer"."UserName", 
  "customer"."FirstName", 
  "customer"."MiddleName", 
  "customer"."LastName", 
  "customer"."Salutation", 
  "customer"."Ssn", 
  "customer"."createdts", 
  "customer"."Gender", 
  "customer"."DateOfBirth", 
  "customer"."Status_id", 
  customerstatus."Description", 
  "customer"."MaritalStatus_id", 
  "maritalstatus"."Description", 
  "customer"."SpouseName", 
  "customer"."DrivingLicenseNumber", 
  "customer"."lockedOn", 
  "customer"."lockCount", 
  "customer"."EmployementStatus_id", 
  "customer"."EmployementStatus_id", 
  employementstatus."Description", 
  "customer"."IsEnrolledForOlb", 
  "customer"."IsStaffMember", 
  "customer"."Location_id", 
  "location"."Name", 
  "location"."Code", 
  "customer"."IsOlbAllowed", 
  "customer"."IsAssistConsented", 
  "customer"."IsAssistConsented", 
  "customer"."isEagreementSigned", 
  "customer"."isCombinedUser", 
  "customer"."CustomerType_id", 
  "customertype"."Name", 
  "customertype"."Description", 
  "customer"."Organization_Id", 
  "organisation"."Name", 
  primaryphone."Value", 
  primaryemail."Value", 
  CAST(
    "customer"."DocumentsSubmitted" as nvarchar2(2000)
  ), 
  "customer"."ApplicantChannel", 
  "customer"."Product", 
  CAST(
    "customer"."Reason" as nvarchar2(2000)
  );
