  "membergroup"."Name" "Group_name", 
  "membergroup"."Description" "Group_Desc", 
  "membergroup"."Status_id" "GroupStatus_id", 
  (
    SELECT 
      "status"."Description" 
    FROM 
      "status" 
    WHERE 
      (
        "membergroup"."Status_id" = "status"."id"
      )
  ) "GroupStatus_name", 
  "membergroup"."createdby" "Group_createdby", 
  "membergroup"."modifiedby" "Group_modifiedby", 
  "membergroup"."createdts" "Group_createdts", 
  "membergroup"."lastmodifiedts" "Group_lastmodifiedts", 
  "membergroup"."synctimestamp" "Group_synctimestamp", 
  "membergroup"."Type_id" "Group_Type_id" 
