  (
    "customergroup" 
    JOIN "membergroup" ON (
      (
        "customergroup"."Group_id" = "membergroup"."id"
      )
    )
  );
--  DDL for View customergroups_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customergroups_view" (
  "customerCount", "servicedefinitionId", 
  "groupId", "companyLegalUnit"
) AS 
SELECT 
  COUNT(
    DISTINCT ("customergroup"."Customer_id")
  ) "customerCount", 
  "groupservicedefinition"."serviceDefinitionId" "servicedefinitionId", 
  "groupservicedefinition"."Group_id" "groupId", 
  "groupservicedefinition"."companyLegalUnit" "companyLegalUnit" 
FROM 
  "groupservicedefinition" 
  JOIN "contract" ON "contract"."servicedefinitionId" = "groupservicedefinition"."serviceDefinitionId" 
  JOIN "customergroup" ON "customergroup"."Group_id" = "groupservicedefinition"."Group_id" 
  AND "customergroup"."contractId" = "contract"."id" 
GROUP BY 
  "groupservicedefinition"."companyLegalUnit", 
  "groupservicedefinition"."Group_id", 
  "groupservicedefinition"."serviceDefinitionId";

