CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customerpermissions_view" (
  "Customer_id", "Service_id", "Service_name", 
  "Service_description", "Service_notes", 
  "Status_id", "Status_description", 
  "TransactionFee_id", "TransactionFee_description", 
  "TransactionLimit_id", "TransactionLimit_description", 
  "ServiceType_id", "ServiceType_description", 
  "MinTransferLimit", "MaxTransferLimit", 
  "Display_Name", "Display_Description"
) AS 
SELECT 
  "customerentitlement"."Customer_id" "Customer_id", 
  "customerentitlement"."Service_id" "Service_id", 
  "service"."Name" SERVICE_NAME, 
  "service"."Description" "Service_description", 
  "service"."Notes" "Service_notes", 
  "service"."Status_id" "Status_id", 
  "status"."Description" "Status_description", 
  "customerentitlement"."TransactionFee_id" "TransactionFee_id", 
  "transactionfee"."Description" "TransactionFee_description", 
  "customerentitlement"."TransactionLimit_id" "TransactionLimit_id", 
  "transactionlimit"."Description" "TransactionLimit_description", 
  "service"."Type_id" "ServiceType_id", 
  "servicetype"."Description" "ServiceType_description", 
  "service"."MinTransferLimit" "MinTransferLimit", 
  "service"."MaxTransferLimit" "MaxTransferLimit", 
  "service"."DisplayName" "Display_Name", 
  "service"."DisplayDescription" "Display_Description" 
FROM 
  (
    (
      (
        (
          (
            "customerentitlement" 
            LEFT JOIN "service" ON (
              (
                "customerentitlement"."Service_id" = "service"."id"
              )
            )
          ) 
          LEFT JOIN "status" ON (
            (
              "service"."Status_id" = "status"."id"
            )
          )
        ) 
        LEFT JOIN "transactionfee" ON (
          (
            "transactionfee"."id" = "customerentitlement"."TransactionFee_id"
          )
        )
      ) 
      LEFT JOIN "transactionlimit" ON (
        (
          "transactionlimit"."id" = "customerentitlement"."TransactionLimit_id"
        )
      )
    ) 
    LEFT JOIN "servicetype" ON (
      (
        "servicetype"."id" = "service"."Type_id"
      )
    )
  );
--  DDL for View customerrequests_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customerrequests_view" (
  "id", "softdeleteflag", "priority", 
  "requestCreatedDate", "recentMsgDate", 
  "requestcategory_id", "customer_id", 
  "username", "status_id", "statusIdentifier", 
  "requestsubject", "accountid", "assignTo", 
  "totalmsgs", "readmsgs", "unreadmsgs", 
  "firstMessage", "msgids", "totalAttachments"
) AS 
SELECT 
  "customerrequest"."id" "id", 
  "customerrequest"."softdeleteflag" "softdeleteflag", 
  "customerrequest"."Priority" "priority", 
  "customerrequest"."createdts" "requestCreatedDate", 
  max("requestmessage"."createdts") "recentMsgDate", 
  "requestcategory"."Name" "requestcategory_id", 
  "customerrequest"."Customer_id" "customer_id", 
  "customer"."UserName" "username", 
  (
    SELECT 
      "status"."Description" 
    FROM 
      "status" 
      join "customerrequest" ON (
        "status"."id" = "customerrequest"."Status_id"
      ) FETCH FIRST 1 ROWS ONLY
  ) "status_id", 
  "customerrequest"."id" "statusIdentifier", 
  "customerrequest"."RequestSubject" "requestsubject", 
  "customerrequest"."Accountid" "accountid", 
  ("systemuser"."FirstName") || (' ') || min("systemuser"."LastName") "assignTo", 
  count("requestmessage"."id") "totalmsgs", 
  count(
    (
      CASE WHEN (
        "requestmessage"."IsRead" = 'true'
      ) THEN 1 END
    )
  ) "readmsgs", 
  count(
    (
      CASE WHEN (
        "requestmessage"."IsRead" = 'false'
      ) THEN 1 END
    )
  ) "unreadmsgs", 
  substring_index(
    (
      LISTAGG(
        CAST(
          "requestmessage"."MessageDescription" as varchar2(4000)
        ), 
        '||'
      ) WITHIN GROUP (
        order by 
          "requestmessage"."createdts" ASC, 
          "requestmessage"."id" ASC
      )
    ), 
    '||', 
    1
  ) "firstMessage", 
  
  /*coalesce( 
        substr(listagg(      
            cast("requestmessage"."MessageDescription" as varchar2(4000)),'||') 
           within group (order by "requestmessage"."createdts" asc, "requestmessage"."id" asc), 
          1, 
          (nullif( 
            instr( 
              listagg( 
                cast("requestmessage"."MessageDescription" as varchar2(4000)), 
                '||' 
              ) within group (order by "requestmessage"."createdts" asc, "requestmessage"."id" asc), '||', 1, 1),0) - 1) 
        ) 
        listagg( 
          cast("requestmessage"."MessageDescription" as varchar2(4000)), 
          '||' 
        ) within group (order by "requestmessage"."createdts" asc, "requestmessage"."id" asc) 
      ) "firstMessage",*/
  listagg(
    CAST(
      "requestmessage"."id" as varchar2(4000)
    ), 
    ','
  ) AS "msgids", 
  count("messageattachment"."id") "totalAttachments" 
FROM 
  (
    (
      (
        (
          (
            "customerrequest" 
            left join "requestmessage" on(
              (
                "customerrequest"."id" = "requestmessage"."CustomerRequest_id"
              )
            )
          ) 
          left join "requestcategory" on(
            (
              "requestcategory"."id" = "customerrequest"."RequestCategory_id"
            )
          )
        ) 
        left join "customer" on(
          (
            "customer"."id" = "customerrequest"."Customer_id"
          )
        )
      ) 
      left join "messageattachment" on(
        (
          "messageattachment"."RequestMessage_id" = "requestmessage"."id"
        )
      )
    ) 
    left join "systemuser" on(
      (
        "systemuser"."id" = "customerrequest"."AssignedTo"
      )
    )
  ) 
group by 
  "customerrequest"."id", 
  "customerrequest"."softdeleteflag", 
  "customerrequest"."Priority", 
  "customerrequest"."createdts", 
  "requestcategory"."Name", 
  "customerrequest"."Customer_id", 
  "customer"."UserName", 
  "customerrequest"."RequestSubject", 
  "customerrequest"."Accountid", 
  "systemuser"."FirstName" 
order by 
  "customerrequest"."createdts" DESC, 
  "customerrequest"."id" FETCH FIRST 100 ROWS ONLY;

--  DDL for View customersecurityquestion_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "customersecurityquestion_view" (
  "Customer_id", "SecurityQuestion_id", 
  "CustomerAnswer", "isTypeBusiness", 
  "createdby", "modifiedby", "createdts", 
  "lastmodifiedts", "Question", "QuestionStatus_id", 
  "CustomerStatus_id"
) AS 
SELECT 
  "customersecurityquestions"."Customer_id" "Customer_id", 
  "customersecurityquestions"."SecurityQuestion_id" "SecurityQuestion_id", 
  "customersecurityquestions"."CustomerAnswer" "CustomerAnswer", 
  "customersecurityquestions"."isTypeBusiness" "isTypeBusiness", 
  "customersecurityquestions"."createdby" "createdby", 
  "customersecurityquestions"."modifiedby" "modifiedby", 
  "customersecurityquestions"."createdts" "createdts", 
  "customersecurityquestions"."lastmodifiedts" "lastmodifiedts", 
  "securityquestion"."Question" "Question", 
  "securityquestion"."Status_id" "QuestionStatus_id", 
  "customer"."Status_id" "CustomerStatus_id" 
FROM 
  (
    (
      "customersecurityquestions" 
      JOIN "securityquestion" ON (
        (
          "securityquestion"."id" = "customersecurityquestions"."SecurityQuestion_id"
        )
      )
    ) 
    JOIN "customer" ON (
      (
        "customer"."id" = "customersecurityquestions"."Customer_id"
      )
    )
  );
