  "feature_status_id", "action_code", 
  "action_name", "action_description", 
  "action_role_type_id", "category", 
  "accesspolicyId", "actionlevelId", 
  "status", "limitType_id", "value", 
  "companyLegalUnit"
) AS 
SELECT 
  "featureaction"."Feature_id" "feature_code", 
  "feature_view"."Name" "feature_name", 
  "feature_view"."Type_Id" "feature_type_id", 
  "feature_view"."Status_Id" "feature_status_id", 
  "featureaction"."id" "action_code", 
  "featureaction"."name" "action_name", 
  "featureaction"."description" "action_description", 
  "far"."RoleType_id" "action_role_type_id", 
  "featureaction"."Type_id" "category", 
  "featureaction"."accesspolicyId" "accesspolicyId", 
  "featureaction"."actionlevelId" "actionlevelId", 
  "featureaction"."status" "status", 
  "actionlimit"."LimitType_id" "limitType_id", 
  "actionlimit"."value" "value", 
  "featureaction"."companyLegalUnit" "companyLegalUnit" 
