    (
      (
        "featureaction" 
        LEFT JOIN "featureactionroletype" "far" ON (
          (
            "far"."Action_id" = "featureaction"."id"
          )
        )
      ) 
      LEFT JOIN "feature_view" ON (
        (
          "feature_view"."Code" = "featureaction"."Feature_id"
        )
