--  DDL for View feature_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "feature_view" (
  "Code", "Type", "Type_Id", "Name", 
  "Status", "Status_Id"
) AS 
SELECT 
  "feature"."id" "Code", 
  LISTAGG(
    CAST(
      "membergrouptype"."description" as nvarchar2(2000)
    ), 
    ','
  ) TYPE, 
  LISTAGG(
    CAST(
      "membergrouptype"."id" as nvarchar2(2000)
    ), 
    ','
  ) TYPE_ID, 
  MIN("feature"."name") "name", 
  MIN("status"."Description") STATUS, 
  MIN("status"."id") "Status_Id" 
FROM 
  (
    (
      (
        "feature" 
        LEFT JOIN "featureroletype" fr ON (
          (fr."Feature_id" = "feature"."id")
        )
      ) 
      LEFT JOIN "membergrouptype" ON (
        (
          "membergrouptype"."id" = fr."RoleType_id"
        )
      )
    ) 
    LEFT JOIN "status" ON (
      (
        "feature"."Status_id" = "status"."id"
      )
    )
  ) 
GROUP BY 
  "feature"."id";

--  DDL for View get_all_features_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "get_all_features_view" (
  "id", "name", "description", "Type_id", 
  "Service_Fee", "Status_id", "companyLegalUnit", 
  "roleTypeId", "languageId", "displayName", 
  "displayDescription", "roleTypeName", 
  "monetaryActions", "nonMonetaryActions"
) AS 
SELECT 
  "feature"."id" "id", 
  "feature"."name" "name", 
  "feature"."description" "description", 
  "feature"."Type_id" "Type_id", 
  "feature"."Service_Fee" "Service_Fee", 
  "feature"."Status_id" "Status_id", 
  "feature"."companyLegalUnit" "companyLegalUnit", 
  "featureroletype"."RoleType_id" "roleTypeId", 
  "featuredisplaynamedescription"."Locale_id" "languageId", 
  "featuredisplaynamedescription"."displayName" "displayName", 
  "featuredisplaynamedescription"."displayDescription" "displayDescription", 
  "membergrouptype"."description" "roleTypeName", 
  (
    SELECT 
      COUNT(DISTINCT "featureaction"."id") 
    FROM 
      "featureaction" 
    WHERE 
      (
        (
          "feature"."id" = "featureaction"."Feature_id"
        ) 
        AND (
          "featureaction"."Type_id" = 'MONETARY'
        )
      )
  ) "monetaryActions", 
  (
    SELECT 
      COUNT(DISTINCT "featureaction"."id") 
    FROM 
      "featureaction" 
    WHERE 
      (
        (
          "feature"."id" = "featureaction"."Feature_id"
        ) 
        AND (
          "featureaction"."Type_id" = 'NON_MONETARY'
        )
      )
  ) "nonMonetaryActions" 
FROM 
  (
    (
      (
        "feature" 
        LEFT JOIN "featureroletype" ON (
          (
            "featureroletype"."Feature_id" = "feature"."id"
          )
        )
      ) 
      LEFT JOIN "featuredisplaynamedescription" ON (
        (
          "featuredisplaynamedescription"."Feature_id" = "feature"."id"
        )
      )
    ) 
    LEFT JOIN "membergrouptype" ON (
      (
        "featureroletype"."RoleType_id" = "membergrouptype"."id"
      )
    )
  );
