CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "get_feature_actions_view" (
  "actionId", "featureId", "actionName", 
  "isAccountLevel", "actionDescription", 
  "isMFAApplicable", "isPrimary", 
  "notes", "typeId", "actionDisplaySequence", 
  "actionDependency", "actionStatus","companyLegalUnit" ,
  "actionType", "accessPolicy", "limitGroup", 
