  "dependentActionName", "dependentFeatureId", 
  "termsAndConditionCode", "termsAndConditionTitle", 
  "termsAndConditionDescription", 
  "roleTypeName"
) AS 
SELECT 
  "featureaction"."id" "actionId", 
  "featureaction"."Feature_id" "featureId", 
  "featureaction"."name" "actionName", 
  "featureaction"."isAccountLevel" "isAccountLevel", 
  "featureaction"."description" "actionDescription", 
  "featureaction"."isMFAApplicable" "isMFAApplicable", 
  "featureaction"."isPrimary" "isPrimary", 
  "featureaction"."notes" "notes", 
  "featureaction"."Type_id" "typeId", 
  "featureaction"."DisplaySequence" "actionDisplaySequence", 
  "featureaction"."dependency" "actionDependency", 
  "featureaction"."status" "actionStatus", 
  "featureaction"."companyLegalUnit" "companyLegalUnit",
  "featureactionroletype"."RoleType_id" "actionType", 
  "accesspolicy"."name" "accessPolicy", 
  "limitgroup"."name" "limitGroup", 
  "featureaction"."accesspolicyId" "accessPolicyId", 
  "featureaction"."limitgroupId" "limitGroupId", 
  "feature"."Status_id" "featureStatus", 
  "feature"."name" "featureName", 
  "feature"."description" "featureDescription", 
  "feature"."Type_id" "featureType", 
  "featureroletype"."RoleType_id" "featureGroup", 
  "feature"."DisplaySequence" "featureDisplaySequence", 
  "feature"."isPrimary" "isFeaturePrimary", 
  "actionlevel"."name" "actionlevel", 
  "featureaction"."actionlevelId" "actionlevelId", 
  "actiondisplaynamedescription"."Locale_id" "localeId", 
  "actiondisplaynamedescription"."displayName" "displayName", 
  "actiondisplaynamedescription"."displayDescription" "displayDescription", 
  "actionlimit"."LimitType_id" "limitTypeId", 
  "actionlimit"."value" "value", 
  "dependentactions_view"."dependentactionId" "dependentactionId", 
  "dependentactions_view"."featureName" "dependentFeatureName", 
  "dependentactions_view"."actionName" "dependentActionName", 
  "dependentactions_view"."featureId" "dependentFeatureId", 
  "termandcondition"."Code" "termsAndConditionCode", 
  "termandcondition"."Title" "termsAndConditionTitle", 
  "termandcondition"."Description" "termsAndConditionDescription", 
  "membergrouptype"."description" "roleTypeName" 
FROM 
  (
    (
      (
        (
          (
            (
              (
                (
                  (
                    (
                      (
                        "featureaction" 
                        LEFT JOIN "feature" ON (
                          (
                            "feature"."id" = "featureaction"."Feature_id"
                          )
                        )
                      ) 
                      LEFT JOIN "actiondisplaynamedescription" ON (
                        (
                          "actiondisplaynamedescription"."Action_id" = "featureaction"."id"
                        )
                      )
                    ) 
                    LEFT JOIN "accesspolicy" ON (
                      (
                        "featureaction"."accesspolicyId" = "accesspolicy"."id"
                      )
                    )
                  ) 
                  LEFT JOIN "featureroletype" ON (
                    (
                      "featureroletype"."Feature_id" = "feature"."id"
                    )
                  )
                ) 
                LEFT JOIN "featureactionroletype" ON (
                  (
                    "featureaction"."id" = "featureactionroletype"."Action_id"
                  )
                )
              ) 
              LEFT JOIN "termandcondition" ON (
                (
                  "featureaction"."TermsAndConditions_id" = "termandcondition"."id"
                )
              )
            ) 
            LEFT JOIN "limitgroup" ON (
              (
                "featureaction"."limitgroupId" = "limitgroup"."id"
              )
            )
          ) 
          LEFT JOIN "actionlevel" ON (
            (
              "featureaction"."actionlevelId" = "actionlevel"."id"
            )
          )
        ) 
        LEFT JOIN "dependentactions_view" ON (
          (
            "featureaction"."id" = "dependentactions_view"."actionId"
          )
        )
      ) 
      LEFT JOIN "membergrouptype" ON (
        (
          "featureactionroletype"."RoleType_id" = "membergrouptype"."id"
        )
      )
    ) 
    LEFT JOIN "actionlimit" ON (
      (
        "actionlimit"."Action_id" = "featureaction"."id"
      )
    )
  );
