--  DDL for View groups_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "groups_view" (
  "Group_id", "Type_id", "Type_Name", 
  "Group_Desc", "Status_id", "Group_Name", 
  "companyLegalUnit", "isEAgreementActive", 
  "isApplicabletoAllServices", "Entitlements_Count", 
  "Customers_Count", "Status"
) AS 
SELECT 
  "membergroup"."id" "Group_id", 
  "membergroup"."Type_id" "Type_id", 
  "membergrouptype"."description" "Type_Name", 
  "membergroup"."Description" "Group_Desc", 
  "membergroup"."Status_id" "Status_id", 
  "membergroup"."Name" "Group_Name", 
  "membergroup"."companyLegalUnit" AS "companyLegalUnit", 
  "membergroup"."isEAgreementActive" "isEAgreementActive", 
  (
    CASE "membergroup"."isApplicabletoAllServices" WHEN 1 THEN 'true' ELSE 'false' END
  ) "isApplicabletoAllServices", 
  (
    SELECT 
      COUNT("groupentitlement"."Group_id") 
    FROM 
      "groupentitlement" 
    WHERE 
      (
        "groupentitlement"."Group_id" = "membergroup"."id"
      )
  ) "Entitlements_Count", 
  (
    SELECT 
      COUNT(
        DISTINCT ("customergroup"."Customer_id")
      ) 
    FROM 
      "customergroup" 
    WHERE 
      (
        "customergroup"."Group_id" = "membergroup"."id"
      )
  ) "Customers_Count", 
  (
    CASE CAST(
      "membergroup"."Status_id" as varchar2(50 char)
    ) WHEN 'SID_ACTIVE' THEN 'Active' ELSE 'Inactive' END
  ) "Status" 
FROM 
  (
    "membergroup" 
    JOIN "membergrouptype" ON (
      (
        "membergroup"."Type_id" = "membergrouptype"."id"
      )
    )
  );
--  DDL for View groupservices_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "groupservices_view" (
  "Group_id", "Service_id", "Service_name", 
  "Service_description", "Service_notes", 
  "Status_id", "Status_description", 
  "TransactionFee_id", "TransactionFee_description", 
  "TransactionLimit_id", "TransactionLimit_description", 
  "ServiceType_id", "ServiceType_description", 
  "Channel_id", "ChannelType_description", 
  "MinTransferLimit", "MaxTransferLimit", 
  "Display_Name", "Display_Description"
) AS 
SELECT 
  "groupentitlement"."Group_id" "Group_id", 
  "groupentitlement"."Service_id" "Service_id", 
  MIN("service"."Name") "Service_name", 
  MIN("service"."Description") "Service_description", 
  MIN("service"."Notes") "Service_notes", 
  MIN("service"."Status_id") "Status_id", 
  MIN("status"."Description") "Status_description", 
  MIN(
    "groupentitlement"."TransactionFee_id"
  ) "TransactionFee_id", 
  MIN("transactionfee"."Description") "TransactionFee_description", 
  MIN(
    "groupentitlement"."TransactionLimit_id"
  ) "TransactionLimit_id", 
  MIN(
    "transactionlimit"."Description"
  ) "TransactionLimit_description", 
  MIN("service"."Type_id") "ServiceType_id", 
  MIN("servicetype"."Description") "ServiceType_description", 
  
  /*(SELECT "status"."Description"  
                FROM "status"  
                 WHERE  ( "status"."id" = MIN("service"."Status_id")  )  ) "Status_description"  , 
           ( SELECT "transactionfee"."Description"  
                FROM "transactionfee"  
                 WHERE  ( "transactionfee"."id" = MIN("groupentitlement"."TransactionFee_id")  ) ) "TransactionFee_description", 
           ( SELECT "transactionlimit"."Description"  
                FROM "transactionlimit"  
                 WHERE  ( "transactionlimit"."id" = MIN("groupentitlement"."TransactionLimit_id")  ) ) "TransactionLimit_description"  , 
           ( SELECT "servicetype"."Description"  
                FROM "servicetype"  
                 WHERE  ( "servicetype"."id" = MIN("service"."Type_id")  ) ) "ServiceType_description"  , 
           */
  LISTAGG(
    CAST(
      sc."Channel_id" as nvarchar2(2000)
    ), 
    ','
  ) "Channel_id", 
  LISTAGG(
    CAST(
      "servicechannel"."Description" as nvarchar2(2000)
    ), 
    ','
  ) "ChannelType_description", 
  MIN("service"."MinTransferLimit") "MinTransferLimit", 
  MIN("service"."MaxTransferLimit") "MaxTransferLimit", 
  MIN("service"."DisplayName") "Display_Name", 
  MIN("service"."DisplayDescription") "Display_Description" 
  /*FROM ( ( ( "groupentitlement"  
                    LEFT JOIN "service"    ON ( ( "groupentitlement"."Service_id" = "service"."id" ) ) 
                     )  
                  LEFT JOIN "service_channels" sc   ON ( ( sc."Service_id" = "service"."id" ) ) 
                   )  
                LEFT JOIN "servicechannel"    ON ( ( sc."Channel_id" = "servicechannel"."id" ) ) 
                 ) */
FROM 
  (
    (
      (
        (
          (
            (
              (
                "groupentitlement" 
                LEFT JOIN "service" ON (
                  (
                    "groupentitlement"."Service_id" = "service"."id"
                  )
                )
              ) 
              LEFT JOIN "status" ON (
                (
                  "status"."id" = "service"."Status_id"
                )
              )
            ) 
            LEFT JOIN "service_channels" sc ON (
              (sc."Service_id" = "service"."id")
            )
          ) 
          LEFT JOIN "servicechannel" ON (
            (
              sc."Channel_id" = "servicechannel"."id"
            )
          )
        ) 
        LEFT JOIN "transactionfee" ON (
          (
            "transactionfee"."id" = "groupentitlement"."TransactionFee_id"
          )
        )
      ) 
      LEFT JOIN "transactionlimit" ON (
        (
          "transactionlimit"."id" = "groupentitlement"."TransactionLimit_id"
        )
      )
    ) 
    LEFT JOIN "servicetype" ON (
      (
        "servicetype"."id" = "service"."Type_id"
      )
    )
  ) 
GROUP BY 
  "groupentitlement"."Group_id", 
  "groupentitlement"."Service_id";

