--  DDL for View internalactiondependency_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "internalactiondependency_view" (
  "actionName", "dependencyAction", 
  "featureId", "actionStatus", "featureStatus"
) AS 
SELECT 
  "internalactiondependentactions"."dependentactionId" "actionName", 
  "internalactiondependentactions"."actionId" "dependencyAction", 
  "internalactiondependentactions"."featureId" "featureId", 
  "internalfeatureaction"."status" "actionStatus", 
  "internalfeature"."Status_id" "featureStatus" 
FROM 
  (
    (
      "internalactiondependentactions" 
      LEFT JOIN "internalfeatureaction" ON (
        (
          "internalactiondependentactions"."dependentactionId" = "internalfeatureaction"."id"
        )
      )
    ) 
    LEFT JOIN "internalfeature" ON (
      (
        "internalactiondependentactions"."featureId" = "internalfeature"."id"
      )
    )
  );
--  DDL for View internalpermission_featureaction_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "internalpermission_featureaction_view" (
  "featureId", "actionId", "permissionId"
) AS 
SELECT 
  "ifa"."Feature_id" "featureId", 
  "pa"."actionId" "actionId", 
  "pa"."permissionId" "permissionId" 
FROM 
  (
    (
      "permissionaction" "pa" 
      JOIN "internalfeatureaction" "ifa" ON (
        (
          ("pa"."actionId" = "ifa"."id") 
          AND (
            "ifa"."status" = 'SID_ACTION_ACTIVE'
          )
        )
      )
    ) 
    JOIN "internalfeature" "ifes" ON (
      (
        ("ifes"."id" = "ifa"."Feature_id") 
        AND (
          "ifes"."Status_id" = 'SID_FEATURE_ACTIVE'
        )
      )
    )
  );
--  DDL for View internalpermission_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "internalpermission_view" (
  "permissionId", "permissionName", 
  "DESCRIPTION", "STATUS", "numberOfFeatures", 
  "legalEntityIds"
) AS 
SELECT 
  "internalpermission"."id" "permissionId", 
  "internalpermission"."Name" "permissionName", 
  "internalpermission"."Description" "DESCRIPTION", 
  "internalpermission"."Status_id" "STATUS", 
  (
    SELECT 
      COUNT(
        DISTINCT ("id")
      ) "numberOfFeatures" 
    FROM 
      "internalfeature"
  ) "numberOfFeatures", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "legalEntityId" AS NVARCHAR2(2000)
        ), 
        ','
      ) 
    FROM 
      "permissionlegalentity"
  ) "legalEntityIds" 
FROM 
  (
    (
      (
        (
          "internalpermission" 
          LEFT JOIN "permissionaction" ON (
            (
              "permissionaction"."permissionId" = "internalpermission"."id"
            )
          )
        ) 
        LEFT JOIN "permissionlegalentity" ON (
          (
            "permissionlegalentity"."permissionId" = "internalpermission"."id"
          )
        )
      ) 
      LEFT JOIN "internalfeatureaction" ON (
        (
          "internalfeatureaction"."id" = "permissionaction"."actionId"
        )
      )
    ) 
    LEFT JOIN "internalfeature" ON (
      (
        "internalfeature"."id" = "internalfeatureaction"."Feature_id"
      )
    )
  );
