  "internalactiondisplaynamedescription"."Locale_id" "localeId", 
  "internalactiondisplaynamedescription"."displayName" "displayName", 
  "internalactiondisplaynamedescription"."displayDescription" "displayDescription", 
  "internalusers_dependentactions_view"."dependentactionId" "dependentactionId", 
  "internalusers_dependentactions_view"."featureId" "dependentFeatureId", 
