OR REPLACE FORCE NONEDITIONABLE VIEW "internalusers_features_view" (
  "id", "NAME", "DESCRIPTION", "Status_id", 
  "displaySequence", "isPrimary", 
  "languageId", "displayName", "displayDescription", 
  "numberOfActions"
) AS 
SELECT 
  "internalfeature"."id" "id", 
