--  DDL for View internalusers_view


  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "internalusers_view" ("User_id", "Username", "UserType", "ReportingManager", "userTypeName", "Status_id", "Status_Desc", "FirstName", "MiddleName", "LastName", "companyLegalUnit", "lastLogints", "Name", "Email", "Role_id", "Role_Desc", "Role_Name", "Permission_Count", "lastmodifiedts", "createdts", "Work_Addr", "Home_Addr", "Home_AddressID", "Home_AddressLine1", "Home_AddressLine2", "Home_CityName", "Home_CityID", "Home_StateName", "Home_StateID", "Home_CountryName", "Home_CountryID", "Home_Zipcode", "Work_AddressID", "Work_AddressLine1", "Work_AddressLine2", "Work_CityName", "Work_CityID", "Work_StateName", "Work_StateID", "Work_CountryName", "Work_CountryID", "Work_Zipcode", "lobId", "lobName", "branchName") AS 
  SELECT ("systemuser"."id") "User_id"  ,
          ("systemuser"."Username") "Username"  ,
          ( SELECT "internalusertype"."userType" 
            FROM "internalusertype" 
             WHERE  ( "systemuser"."id" = "internalusertype"."userId" ) 
              FETCH FIRST 1 ROWS ONLY ) "UserType"  ,
          ( SELECT "internalusermanager"."manager" 
            FROM "internalusermanager" 
             WHERE  ( "systemuser"."id" = "internalusermanager"."userId" ) 
              FETCH FIRST 1 ROWS ONLY ) "ReportingManager"  ,
          ( SELECT "usertype"."name" 
            FROM "usertype" 
             WHERE  "usertype"."id" IN ( SELECT "internalusertype"."userType" 
                                     FROM "internalusertype" 
                                      WHERE  ( "systemuser"."id" = "internalusertype"."userId" ) )
           ) "userTypeName"  ,
          ("systemuser"."Status_id") "Status_id"  ,
          ("status"."Description") "Status_Desc"  ,
          ("systemuser"."FirstName") "FirstName"  ,
          ("systemuser"."MiddleName") "MiddleName"  ,
          ("systemuser"."LastName") "LastName"  ,
          ("systemuser"."companyLegalUnit") "companyLegalUnit"  ,
          ("systemuser"."lastLogints") "lastLogints"  ,
          ("systemuser"."FirstName") || ' ' || ("systemuser"."LastName") "Name"  ,
          ("systemuser"."Email") "Email"  ,
          ( SELECT "userrole"."Role_id" "Role_id"  
            FROM "userrole" 
             WHERE  ( ("systemuser"."id") = "userrole"."User_id" ) 
              FETCH FIRST 1 ROWS ONLY ) "Role_id"  ,
          ( SELECT "role"."Description" "Description"  
            FROM "role" 
             WHERE  "role"."id" IN ( SELECT "userrole"."Role_id" "Role_id"  
                                 FROM "userrole" 
                                  WHERE  ( ("systemuser"."id") = "userrole"."User_id" ) )
             
              FETCH FIRST 1 ROWS ONLY ) "Role_Desc"  ,
          ( SELECT "role"."Name" "Name"  
            FROM "role" 
             WHERE  "role"."id" IN ( SELECT "userrole"."Role_id" "Role_id"  
                                 FROM "userrole" 
                                  WHERE  ( ("systemuser"."id") = "userrole"."User_id" ) )
             
              FETCH FIRST 1 ROWS ONLY ) "Role_Name"  ,
          (( SELECT COUNT("userpermission"."Permission_id")  
             FROM "userpermission" 
              WHERE  ( ("systemuser"."id") = "userpermission"."User_id" ) ) + ( SELECT COUNT("rolepermission"."Permission_id")  
                                                                        FROM "rolepermission" 
                                                                         WHERE  "rolepermission"."Role_id" IN ( SELECT "userrole"."Role_id" "Role_id"  
                                                                                                            FROM "userrole" 
                                                                                                             WHERE  ( ("systemuser"."id") = "userrole"."User_id" ) )
           )) "Permission_Count"  ,
          ("systemuser"."lastmodifiedts") "lastmodifiedts"  ,
          ("systemuser"."createdts") "createdts"  ,
          ( SELECT ("workaddress"."addressLine1") || ', ' || NVL(("workaddress"."addressLine2"), ' ') || ', ' || ( SELECT ("city"."Name") "Name"  
                                                                                                           FROM "city" 
                                                                                                            WHERE  ( "city"."id" = ("workaddress"."City_id") ) ) || ', ' || ( SELECT ("region"."Name") "Name"  
                                                                                                                                                                      FROM "region" 
                                                                                                                                                                       WHERE  ( "region"."id" = ("workaddress"."Region_id") ) ) || ', ' || ( SELECT ("country"."Name") "Name"  
                                                                                                                                                                                                                                     FROM "country" 
                                                                                                                                                                                                                                      WHERE  "country"."id" IN ( SELECT ("city"."Country_id") "Country_id"  
                                                                                                                                                                                                                                                             FROM "city" 
                                                                                                                                                                                                                                                              WHERE  ( "city"."id" = ("workaddress"."City_id") ) )
                    ) || ', ' || ("workaddress"."zipCode") 
              FROM DUAL  ) "Work_Addr"  ,
          ( SELECT ("homeaddress"."addressLine1") || u', ' || NVL(("homeaddress"."addressLine2"), ' ') || u', ' || NVL(("homeaddress"."cityName"), ' ') || u', ' || ( SELECT ("region"."Name") "Name"
                                                                                                                                                          FROM "region" 
                                                                                                                                                           WHERE  ( "region"."id" = ("homeaddress"."Region_id") ) ) || u', ' || ( SELECT ("country"."Name") "Name"  
                                                                                                                                                                                                                          FROM "country" 
                                                                                                                                                                                                                           WHERE  "country"."id" IN ( SELECT ("region"."Country_id") "Country_id"  
                                                                                                                                                                                                                                                  FROM "region" 
                                                                                                                                                                                                                                                   WHERE  ( "region"."id" = ("homeaddress"."Region_id") ) )
                    ) || u', ' || ("homeaddress"."zipCode") 
              FROM DUAL  ) "Home_Addr"  ,
          ( SELECT NVL(("homeaddress"."id"), u'') 
              FROM DUAL  ) "Home_AddressID"  ,
          ( SELECT NVL(("homeaddress"."addressLine1"), u'') 
              FROM DUAL  ) "Home_AddressLine1"  ,
          ( SELECT NVL(("homeaddress"."addressLine2"), u'') 
              FROM DUAL  ) "Home_AddressLine2"  ,
          ( SELECT NVL(("homeaddress"."cityName"), u'') 
              FROM DUAL  ) "Home_CityName"  ,
          ( SELECT NVL(("homeaddress"."City_id"), u'') 
              FROM DUAL  ) "Home_CityID"  ,
          ( SELECT NVL(( SELECT ("region"."Name") "Name"
                         FROM "region" 
                          WHERE  ( "region"."id" = ("homeaddress"."Region_id") ) ), u'') 
              FROM DUAL  ) "Home_StateName"  ,
          ( SELECT NVL(("homeaddress"."Region_id"), u'') 
              FROM DUAL  ) "Home_StateID"  ,
          ( SELECT NVL(( SELECT ("country"."Name") "Name"  
                         FROM "country" 
                          WHERE  "country"."id" IN ( SELECT ("region"."Country_id") "Country_id"
                                                 FROM "region"
                                                  WHERE  ( "region"."id" = ("homeaddress"."Region_id") ) )
                        ), u'') 
              FROM DUAL  ) "Home_CountryName" ,
          ( SELECT NVL(( SELECT ("country"."id") "id"
                         FROM "country" 
                          WHERE  "country"."id" IN ( SELECT ("region"."Country_id") "Country_id"  
                                                 FROM "region" 
                                                  WHERE  ( "region"."id" = ("homeaddress"."Region_id") ) )
                        ), u'') 
              FROM DUAL  ) "Home_CountryID"  ,
          ( SELECT NVL(("homeaddress"."zipCode"), u'') 
              FROM DUAL  ) "Home_Zipcode"  ,
          ( SELECT NVL(("workaddress"."id"), u'') 
              FROM DUAL  ) "Work_AddressID"  ,
          ( SELECT NVL(("workaddress"."addressLine1"), u'') 
              FROM DUAL  ) "Work_AddressLine1"  ,
          ( SELECT NVL(("workaddress"."addressLine2"), u'') 
              FROM DUAL  ) "Work_AddressLine2"  ,
          ( SELECT NVL(( SELECT ("city"."Name") "Name"
                         FROM "city" 
                          WHERE  ( "city"."id" = ("workaddress"."City_id") ) ), u'') 
              FROM DUAL  ) "Work_CityName"  ,
          ( SELECT NVL(("workaddress"."City_id"), u'') 
              FROM DUAL  ) "Work_CityID"  ,
          ( SELECT NVL(( SELECT ("region"."Name") "Name"  
                         FROM "region" 
                          WHERE  ( "region"."id" = ("workaddress"."Region_id") ) ), u'') 
              FROM DUAL  ) "Work_StateName"  ,
          ( SELECT NVL(("workaddress"."Region_id"), u'') 
              FROM DUAL  ) "Work_StateID"  ,
          ( SELECT NVL(( SELECT ("country"."Name") "Name"  
                         FROM "country" 
                          WHERE  "country"."id" IN ( SELECT ("city"."Country_id") "Country_id"  
                                                 FROM "city" 
                                                  WHERE  ( "city"."id" = ("workaddress"."City_id") ) )
                        ), u'') 
              FROM DUAL  ) "Work_CountryName"  ,
          ( SELECT NVL(( SELECT ("country"."id") "id"  
                         FROM "country" 
                          WHERE  "country"."id" IN ( SELECT ("city"."Country_id") "Country_id"  
                                                 FROM "city" 
                                                  WHERE  ( "city"."id" = ("workaddress"."City_id") ) )
                        ), u'') 
              FROM DUAL  ) "Work_CountryID"  ,
          ( SELECT NVL(("workaddress"."zipCode"), u'') 
              FROM DUAL  ) "Work_Zipcode"  ,
          ( SELECT   LISTAGG("userlob"."lobId", ',') 
            FROM "userlob" 
             WHERE  ( "systemuser"."id" = "userlob"."userId" ) ) "lobId"  ,
          ( SELECT   LISTAGG("lobtext"."displayName", ',') 
            FROM "lobtext" 
             WHERE  "lobtext"."lobId" IN ( SELECT "userlob"."lobId" 
                                       FROM "userlob" 
                                        WHERE  ( "systemuser"."id" = "userlob"."userId" ) )
           ) "lobName"  ,
          ( SELECT "location"."Name" 
            FROM "location"
             WHERE  ( "workaddress"."id" = "location"."Address_id" ) ) "branchName"  
     FROM ( ( ( "systemuser" 
                JOIN "status"    ON ( ( "systemuser"."Status_id" = "status"."id" ) )
                 ) 
              LEFT JOIN "address" "homeaddress"   ON ( "homeaddress"."id" IN ( SELECT "useraddress"."Address_id" 
                                                                                   FROM "useraddress" 
                                                                                    WHERE  ( ( "systemuser"."id"= "useraddress"."User_id" )
                                                                                             AND ( "useraddress"."Type_id" = 'ADR_TYPE_HOME' ) ) )
             )
               ) 
            LEFT JOIN "address" "workaddress"   ON ( "workaddress"."id" IN ( SELECT "useraddress"."Address_id" 
                                                                                 FROM "useraddress"
                                                                                  WHERE  ( ( "systemuser"."id" = "useraddress"."User_id" )
                                                                                           AND ( "useraddress"."Type_id" = 'ADR_TYPE_WORK' ) ) )
           )
             );


--  DDL for View internaluserskc_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "internaluserskc_view" (
  "User_id", "UserType", "ReportingManager", 
  "lobId", "lobName", "userTypeName", 
  "Work_AddressID", "Work_AddressLine1", 
  "Work_AddressLine2", "Work_CityName", 
  "Work_CityID", "Work_StateName", 
  "Work_StateID", "Work_CountryName", 
  "Work_CountryID", "Work_Zipcode", 
  "branchName", "Work_Addr"
) AS 
SELECT 
  "internalusertype"."userId" "User_id", 
  "internalusertype"."userType" "UserType", 
  (
    SELECT 
      "internalusermanager"."manager" 
    FROM 
      "internalusermanager" 
    WHERE 
      (
        "internalusertype"."userId" = "internalusermanager"."userId"
      ) FETCH FIRST 1 ROWS ONLY
  ) "ReportingManager", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "userlob"."lobId" AS NVARCHAR2(2000)
        ), 
        ','
      ) 
    FROM 
      "userlob" 
    WHERE 
      (
        "internalusertype"."userId" = "userlob"."userId"
      )
  ) "lobId", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "lobtext"."displayName" AS NVARCHAR2(2000)
        ), 
        ','
      ) 
    FROM 
      "lobtext" 
    WHERE 
      "lobtext"."lobId" IN (
        SELECT 
          "userlob"."lobId" 
        FROM 
          "userlob" 
        WHERE 
          (
            "internalusertype"."userId" = "userlob"."userId"
          )
      )
  ) "lobName", 
  (
    SELECT 
      "usertype"."name" 
    FROM 
      "usertype" 
    WHERE 
      "usertype"."id" IN (
        SELECT 
          "internalusertype"."userType" 
        FROM 
          "internalusertype" 
        WHERE 
          (
            "internalusertype"."userId" = "internalusertype"."userId"
          ) FETCH FIRST 1 ROWS ONLY
      )
  ) "userTypeName", 
  (
    SELECT 
      CASE WHEN "workaddress"."id" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_AddressID", 
  (
    SELECT 
      CASE WHEN "workaddress"."addressLine1" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_AddressLine1", 
  (
    SELECT 
      CASE WHEN "workaddress"."addressLine2" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_AddressLine2", 
  (
    SELECT 
      CASE WHEN (
        SELECT 
          "city"."Name" 
        FROM 
          "city" 
        WHERE 
          (
            "city"."id" = "workaddress"."City_id"
          )
      ) IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_CityName", 
  (
    SELECT 
      CASE WHEN "workaddress"."City_id" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_CityID", 
  (
    SELECT 
      CASE WHEN (
        SELECT 
          "region"."Name" 
        FROM 
          "region" 
        WHERE 
          (
            "region"."id" = "workaddress"."Region_id"
          )
      ) IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_StateName", 
  (
    SELECT 
      CASE WHEN "workaddress"."Region_id" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_StateID", 
  (
    SELECT 
      CASE WHEN (
        SELECT 
          "country"."Name" 
        FROM 
          "country" 
        WHERE 
          "country"."id" IN (
            SELECT 
              "city"."Country_id" 
            FROM 
              "city" 
            WHERE 
              (
                "city"."id" = "workaddress"."City_id"
              )
          )
      ) IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_CountryName", 
  (
    SELECT 
      CASE WHEN (
        SELECT 
          "country"."id" 
        FROM 
          "country" 
        WHERE 
          "country"."id" IN (
            SELECT 
              "city"."Country_id" 
            FROM 
              "city" 
            WHERE 
              (
                "city"."id" = "workaddress"."City_id"
              )
          )
      ) IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_CountryID", 
  (
    SELECT 
      CASE WHEN "workaddress"."zipCode" IS NULL THEN ' ' ELSE NULL END col 
    FROM 
      DUAL
  ) "Work_Zipcode", 
  (
    SELECT 
      "location"."Name" 
    FROM 
      "location" 
    WHERE 
      (
        "workaddress"."id" = "location"."Address_id"
      )
  ) "branchName", 
  (
    SELECT 
      ("workaddress"."addressLine1") || ', ' || NVL(
        ("workaddress"."addressLine2"), 
        ' '
      ) || ', ' || (
        SELECT 
          ("city"."Name") "Name" 
        FROM 
          "city" 
        WHERE 
          (
            "city"."id" = ("workaddress"."City_id")
          )
      ) || ', ' || (
        SELECT 
          ("region"."Name") "Name" 
        FROM 
          "region" 
        WHERE 
          (
            "region"."id" = ("workaddress"."Region_id")
          )
      ) || ', ' || (
        SELECT 
          ("country"."Name") "Name" 
        FROM 
          "country" 
        WHERE 
          "country"."id" IN (
            SELECT 
              ("city"."Country_id") "Country_id" 
            FROM 
              "city" 
            WHERE 
              (
                "city"."id" = ("workaddress"."City_id")
              )
          )
      ) || ', ' || ("workaddress"."zipCode") 
    FROM 
      DUAL
  ) "Work_Addr" 
FROM 
  (
    (
      "internalusertype" 
      JOIN "internalusermanager" ON (
        (
          "internalusertype"."userId" = "internalusermanager"."userId"
        )
      )
    ) 
    LEFT JOIN "address" "workaddress" ON (
      "workaddress"."id" IN (
        SELECT 
          "useraddress"."Address_id" 
        FROM 
          "useraddress" 
        WHERE 
          (
            (
              "internalusertype"."userId" = "useraddress"."User_id"
            ) 
            AND (
              "useraddress"."Type_id" = 'ADR_TYPE_WORK'
            )
          )
      )
    )
  );
--  DDL for View lead_csr_count_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "lead_csr_count_view" ("csrId", "count") AS 
SELECT 
  "lead"."csr_id" "csrId", 
  COUNT("lead"."id") COUNT 
FROM 
  "lead" 
GROUP BY 
  "lead"."csr_id" 
ORDER BY 
  "lead"."csr_id" FETCH FIRST 9223372036854775807 ROWS ONLY;
  --  DDL for View lead_status_count_view
  
CREATE 
  OR REPLACE FORCE NONEDITIONABLE VIEW "lead_status_count_view" ("count", "leadStatus") AS 
SELECT 
  tbl$1.COUNT, 
  tbl$1."leadStatus" 
FROM 
  (
    SELECT 
      COUNT(le."id") COUNT, 
      s1."id" "leadStatus" 
    FROM 
      (
        "status" s1 
        LEFT JOIN "lead" le ON (
          (s1."id" = le."status_id")
        )
      ) 
    WHERE 
      (
        (s1."Type_id" = 'STID_LEADSTATUS') 
        AND (s1."id" <> 'SID_ARCHIVED')
      ) 
    GROUP BY 
      s1."id" 
    ORDER BY 
      "leadStatus" FETCH FIRST 9223372036854775807 ROWS ONLY
  ) tbl$1 
UNION 
SELECT 
  COUNT(ale."id") COUNT, 
  s2."id" "leadStatus" 
FROM 
  (
    "status" s2 
    LEFT JOIN "archivedlead" ale ON (
      (s2."id" = ale."status_id")
    )
  ) 
WHERE 
  (
    (s2."Type_id" = 'STID_LEADSTATUS') 
    AND (s2."id" = 'SID_ARCHIVED')
  ) 
GROUP BY 
  s2."id" 
ORDER BY 
  "leadStatus" FETCH FIRST 9223372036854775807 ROWS ONLY;

