--  DDL for View locationservices_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "locationservices_view" (
  "Location_id", "Location_Name", "Location_Display_Name", 
  "Location_Description", "Location_Phone_Number", 
  "Location_EmailId", "Location_Latitude", 
  "Location_Longitude", "Location_Address_id", 
  "Location_IsMainBranch", "Location_IsMobile", 
  "Location_Status_id", "Location_Type_id", 
  "Location_Code", "Location_DeleteFlag", 
  "Location_WorkScheduleId", "Facility_id", 
  "Facility_code", "Facility_name", 
  "Facility_description", "currencies", 
  "Location_CustomerSegement", "Weekday_StartTime", 
  "Weekday_EndTime", "Sunday_StartTime", 
  "Sunday_EndTime", "Saturday_StartTime", 
  "Saturday_EndTime", "ADDRESS"
) AS 
SELECT 
  "location"."id" "Location_id", 
  "location"."Name" "Location_Name", 
  "location"."DisplayName" "Location_Display_Name", 
  "location"."Description" "Location_Description", 
  "location"."PhoneNumber" "Location_Phone_Number", 
  "location"."EmailId" "Location_EmailId", 
  "address"."latitude" "Location_Latitude", 
  "address"."logitude" "Location_Longitude", 
  "address"."id" "Location_Address_id", 
  "location"."IsMainBranch" "Location_IsMainBranch", 
  "location"."isMobile" "Location_IsMobile", 
  "location"."Status_id" "Location_Status_id", 
  "location"."Type_id" "Location_Type_id", 
  "location"."Code" "Location_Code", 
  "location"."softdeleteflag" "Location_DeleteFlag", 
  "location"."WorkSchedule_id" "Location_WorkScheduleId", 
  "facility"."id" "Facility_id", 
  "facility"."code" "Facility_code", 
  "facility"."name" "Facility_name", 
  "facility"."description" "Facility_description", 
  (
    SELECT 
      LISTAGG("currency"."code", ',') 
    FROM 
      "currency" 
      JOIN "locationcurrency" ON "currency"."code" = "locationcurrency"."currency_code" 
      AND "locationcurrency"."Location_id" = "location"."id"
  ) "currencies", 
  (
    SELECT 
      LISTAGG(
        CAST(
          "customersegment"."id" as varchar2(2000)
        ), 
        ','
      ) 
    FROM 
      "customersegment" 
      JOIN "locationcustomersegment" ON "customersegment"."id" = "locationcustomersegment"."segment_id" 
      AND "locationcustomersegment"."Location_id" = "location"."id"
  ) "Location_CustomerSegement", 
  weekday."StartTime" "Weekday_StartTime", 
  weekday."EndTime" "Weekday_EndTime", 
  sunday."StartTime" "Sunday_StartTime", 
  sunday."EndTime" "Sunday_EndTime", 
  saturday."StartTime" "Saturday_StartTime", 
  saturday."EndTime" "Saturday_EndTime", 
  (
    "address"."addressLine1" || ', ' || NVL("address"."cityName", ' ') || ', ' || (
      SELECT 
        "region"."Name" 
      FROM 
        "region" 
      WHERE 
        (
          "region"."id" = "address"."Region_id"
        )
    ) || ', ' || (
      SELECT 
        "country"."Name" 
      FROM 
        "country" 
      WHERE 
        "country"."id" IN (
          SELECT 
            "region"."Country_id" 
          FROM 
            "region" 
          WHERE 
            (
              "region"."id" = "address"."Region_id"
            )
        )
    ) || ', ' || "address"."zipCode"
  ) "ADDRESS" 
FROM 
  "location" 
  LEFT JOIN "locationfacility" ON "location"."id" = "locationfacility"."Location_id" 
  LEFT JOIN "facility" ON "locationfacility"."facility_id" = "facility"."id" 
  LEFT JOIN "dayschedule" WEEKDAY ON "location"."WorkSchedule_id" = weekday."WorkSchedule_id" 
  AND weekday."WeekDayName" = 'MONDAY' 
  LEFT JOIN "dayschedule" sunday ON "location"."WorkSchedule_id" = sunday."WorkSchedule_id" 
  AND sunday."WeekDayName" = 'SUNDAY' 
  LEFT JOIN "dayschedule" saturday ON "location"."WorkSchedule_id" = saturday."WorkSchedule_id" 
  AND saturday."WeekDayName" = 'SATURDAY' 
  JOIN "address" ON "address"."id" = "location"."Address_id";

