--  DDL for View periodiclimitservice_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "periodiclimitservice_view" (
  "Service_id", "TransactionFee_id", 
  "TransactionLimit_id", "PeriodLimit_id", 
  "Period_id", "Period_Name", "MaximumLimit", 
  "Code", "Currency"
) AS 
SELECT 
  "service"."id" "Service_id", 
  "service"."TransactionFee_id" "TransactionFee_id", 
  "service"."TransactionLimit_id" "TransactionLimit_id", 
  "periodiclimit"."id" "PeriodLimit_id", 
  "periodiclimit"."Period_id" "Period_id", 
  "period"."Name" "Period_Name", 
  "periodiclimit"."MaximumLimit" "MaximumLimit", 
  "periodiclimit"."Code" "Code", 
  "periodiclimit"."Currency" "Currency" 
FROM 
  (
    (
      "periodiclimit" 
      JOIN "service" ON (
        (
          "service"."TransactionLimit_id" = "periodiclimit"."TransactionLimit_id"
        )
      )
    ) 
    JOIN "period" ON (
      (
