--  DDL for View permissions_view

CREATE OR REPLACE FORCE NONEDITIONABLE VIEW  "permissions_view" 
AS 
   SELECT ("permission"."id") "Permission_id"  , 
          ("permission"."Type_id") "PermissionType_id"  , 
          ("permission"."Name") "Permission_Name"  , 
          ("permission"."Description") "Permission_Desc"  ,
          ("permission"."companyLegalUnit") "companyLegalUnit"  ,   
          ("permission"."Status_id") "Status_id"  , 
          ("status"."Description") "Status_Desc"  , 
          ( SELECT COUNT(DISTINCT "rolepermission"."Role_id")   
            FROM "rolepermission"  
             WHERE  "rolepermission"."Permission_id" = ("permission"."id") ) "Role_Count"  , 
          (( SELECT COUNT("userpermission"."Permission_id")   
             FROM "userpermission"  
              WHERE  "userpermission"."Permission_id" = ("permission"."id") ) + ( SELECT COUNT("userrole"."User_id")   
                                                                          FROM "userrole"  
                                                                           WHERE  "userrole"."Role_id" IN ( SELECT "rolepermission"."Role_id" "Role_id"   
                                                                                                        FROM "rolepermission"  
                                                                                                         WHERE  "rolepermission"."Permission_id" = ("permission"."id") ) 
           )) "Users_Count"  , 
          CASE ("permission"."Status_id") 
                                     WHEN N'SID_ACTIVE' THEN N'Active' 
          ELSE N'Inactive' 
             END "Status"   
     FROM ( "permission"  
            JOIN "status"    ON ( ( "permission"."Status_id" = "status"."id" ) ) 
             );




