  "updatedts", "isDirect", "softdeleteflag"
) AS 
SELECT 
  "userpermission"."User_id" "User_id", 
  "userpermission"."Permission_id" "Permission_id", 
  "permission"."Name" "Permission_Name", 
  "permission"."Status_id" "Permission_Status_id", 
  "permission"."Description" "Permission_Description", 
  "systemuser"."Status_id" "User_Status_id", 
  "systemuser"."Username" "UserName", 
  "systemuser"."Email" "Email", 
  "systemuser"."FirstName" "FirstName", 
  "systemuser"."MiddleName" "MiddleName", 
  "systemuser"."LastName" "LastName", 
  "systemuser"."createdby" "createdby", 
  "systemuser"."modifiedby" "updatedby", 
  "systemuser"."createdts" "createdts", 
  "systemuser"."lastmodifiedts" "updatedts", 
  'true' "isDirect", 
  "systemuser"."softdeleteflag" "softdeleteflag" 
FROM 
  (
    (
      "userpermission" 
      JOIN "systemuser" ON (
        (
          "userpermission"."User_id" = "systemuser"."id"
        )
      )
    ) 
    JOIN "permission" ON (
      (
        "userpermission"."Permission_id" = "permission"."id"
      )
    )
  ) 
UNION 
SELECT 
  "userrole"."User_id" "User_id", 
  "rolepermission"."Permission_id" "Permission_id", 
  "permission"."Name" "Permission_Name", 
  "permission"."Status_id" "Permission_Status_id", 
  "permission"."Description" "Permission_Description", 
