  "systemuser"."createdby" "createdby", 
  "systemuser"."modifiedby" "updatedby", 
  "systemuser"."createdts" "createdts", 
  "systemuser"."lastmodifiedts" "updatedts", 
  'false' "isDirect", 
  "systemuser"."softdeleteflag" "softdeleteflag" 
FROM 
  (
    (
      (
        "rolepermission" 
        JOIN "userrole" ON (
          (
            "userrole"."Role_id" = "rolepermission"."Role_id"
          )
        )
      ) 
      JOIN "systemuser" ON (
        (
          "userrole"."User_id" = "systemuser"."id"
        )
      )
    ) 
    JOIN "permission" ON (
      (
        "rolepermission"."Permission_id" = "permission"."id"
