CREATE OR REPLACE FORCE NONEDITIONABLE VIEW  "roles_view" 
AS 
  SELECT ("role"."id") "role_id"  , 
          ("role"."Type_id") "roleType_id"  , 
          ("role"."Name") "role_Name"  , 
          ("role"."Description") "role_Desc"  , 
          ("role"."Status_id") "Status_id" , 
          ("role"."companyLegalUnit") "companyLegalUnit"  ,       
          ("status"."Description") "Status_Desc"  , 
          ( SELECT COUNT("rolepermission"."Role_id")   
            FROM "rolepermission"  
             WHERE ( "rolepermission"."Role_id" = ("role"."id") AND ("rolepermission"."companyLegalUnit" = "role"."companyLegalUnit"))) "permission_Count"  , 
          ( SELECT COUNT("userrole"."User_id")   
            FROM "userrole"  
             WHERE  ("userrole"."Role_id" IN ( SELECT ("rolepermission"."Role_id") "Role_id"   
                                          FROM "rolepermission"  
                                           WHERE  "rolepermission"."Role_id" = ("role"."id") )
          AND 
          "userrole"."companyLegalUnit" IN (SELECT "rolepermission"."companyLegalUnit"
                       FROM "rolepermission"
                       WHERE ("rolepermission"."companyLegalUnit" = "role"."companyLegalUnit" ) ) ) ) "Users_Count"  , 
          CASE ("role"."Status_id") 
                               WHEN N'SID_ACTIVE' THEN N'Active' 
          ELSE N'Inactive' 
             END "Status"   
  FROM ( "role"  
            JOIN "status"    ON ( ( "role"."Status_id" = "status"."id" ) ) );


