  --  DDL for View service_view
  
CREATE 
  OR REPLACE FORCE NONEDITIONABLE VIEW "service_view" (
    "id", "Type_id", "Channel_id", "Channel", 
    "Name", "Description", "DisplayName", 
    "DisplayDescription", "Category_Id", 
    "Code", "Status_id", "Notes", "MaxTransferLimit", 
    "MinTransferLimit", "TransferDenominations", 
    "IsFutureTransaction", "TransactionCharges", 
    "IsAuthorizationRequired", "IsSMSAlertActivated", 
    "SMSCharges", "IsBeneficiarySMSAlertActivated", 
    "BeneficiarySMSCharge", "HasWeekendOperation", 
    "IsOutageMessageActive", "IsAlertActive", 
    "IsTCActive", "IsAgreementActive", 
    "IsCampaignActive", "WorkSchedule_id", 
    "TransactionFee_id", "TransactionLimit_id", 
    "createdby", "modifiedby", "createdts", 
    "lastmodifiedts", "synctimestamp", 
    "softdeleteflag", "Status", "Category_Name", 
    "Type_Name", "WorkSchedule_Desc"
  ) AS 
SELECT 
  "service"."id" "id", 
  MIN("service"."Type_id") "Type_id", 
  LISTAGG(
    CAST(
      sc."Channel_id" as varchar2(2000)
    ), 
    ','
  ) "Channel_id", 
  LISTAGG(
    CAST(
      "servicechannel"."Description" as varchar2(2000)
    ), 
    ','
  ) "Channel", 
  MIN("service"."Name") "Name", 
  MIN("service"."Description") "Description", 
  MIN("service"."DisplayName") "DisplayName", 
  MIN("service"."DisplayDescription") "DisplayDescription", 
  MIN("service"."Category_id") "Category_Id", 
  MIN("service"."code") "Code", 
  MIN("service"."Status_id") "Status_id", 
  MIN("service"."Notes") "Notes", 
  MIN("service"."MaxTransferLimit") "MaxTransferLimit", 
  MIN("service"."MinTransferLimit") "MinTransferLimit", 
  MIN(
    "service"."TransferDenominations"
  ) "TransferDenominations", 
  (
    "service"."IsFutureTransaction"
  ) "IsFutureTransaction", 
  MIN("service"."TransactionCharges") "TransactionCharges", 
  (
    "service"."IsAuthorizationRequired"
  ) "IsAuthorizationRequired", 
  (
    "service"."IsSMSAlertActivated"
  ) "IsSMSAlertActivated", 
  MIN("service"."SMSCharges") "SMSCharges", 
  (
    "service"."IsBeneficiarySMSAlertActivated"
  ) "IsBeneficiarySMSAlertActivated", 
  MIN(
    "service"."BeneficiarySMSCharge"
  ) "BeneficiarySMSCharge", 
  (
    "service"."HasWeekendOperation"
  ) "HasWeekendOperation", 
  (
    "service"."IsOutageMessageActive"
  ) "IsOutageMessageActive", 
  ("service"."IsAlertActive") "IsAlertActive", 
  ("service"."IsTCActive") "IsTCActive", 
  ("service"."IsAgreementActive") "IsAgreementActive", 
  ("service"."IsCampaignActive") "IsCampaignActive", 
  MIN("service"."WorkSchedule_id") "WorkSchedule_id", 
  MIN("service"."TransactionFee_id") "TransactionFee_id", 
  MIN(
    "service"."TransactionLimit_id"
  ) "TransactionLimit_id", 
  MIN("service"."createdby") "createdby", 
  MIN("service"."modifiedby") "modifiedby", 
  MIN("service"."createdts") "createdts", 
  MIN("service"."lastmodifiedts") "lastmodifiedts", 
  MIN("service"."synctimestamp") "synctimestamp", 
  ("service"."softdeleteflag") "softdeleteflag", 
  MIN("status"."Description") STATUS, 
  MIN("category"."Name") "Category_Name", 
  MIN("servicetype"."Description") TYPE_NAME, 
  MIN("workschedule"."Description") "WorkSchedule_Desc" 
FROM 
  (
    (
      (
        (
          (
            (
              "service" 
              LEFT JOIN "service_channels" sc ON (
                (sc."Service_id" = "service"."id")
              )
            ) 
            LEFT JOIN "servicechannel" ON (
              (
                sc."Channel_id" = "servicechannel"."id"
              )
            )
          ) 
          LEFT JOIN "category" ON (
            (
              "service"."Category_id" = "category"."id"
            )
          )
        ) 
        LEFT JOIN "status" ON (
          (
            "service"."Status_id" = "status"."id"
          )
        )
      ) 
      LEFT JOIN "servicetype" ON (
        (
          "service"."Type_id" = "servicetype"."id"
        )
      )
    ) 
    LEFT JOIN "workschedule" ON (
      (
        "service"."WorkSchedule_id" = "workschedule"."id"
      )
    )
  ) 
GROUP BY 
  "service"."id", 
  "service"."IsFutureTransaction", 
  "service"."IsAuthorizationRequired", 
  "service"."IsSMSAlertActivated", 
  "service"."IsBeneficiarySMSAlertActivated", 
  "service"."HasWeekendOperation", 
  "service"."IsOutageMessageActive", 
  "service"."IsAlertActive", 
  "service"."IsTCActive", 
  "service"."IsAgreementActive", 
  "service"."IsCampaignActive", 
  "service"."softdeleteflag";

--  DDL for View servicedefinition_features_actions_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "servicedefinition_features_actions_view" (
  "serviceDefinitionId", "actionId", 
  "limitTypeId", "value", "serviceDefinitionActionLimitId", 
  "softdelete", "serviceType", "serviceDefinitionName", 
  "serviceDefinitionDescription", 
  "actionName", "actionDescription", 
  "actionTypeId", "featureId", "isMFAApplicable", 
  "isAccountLevel", "isPrimary", "actionDisplaysequence", 
  "actionDependency", "actionStatus", 
  "accessPolicy", "accessPolicyId", 
  "limitGroupId", "limitGroup", "actionlevel", 
  "actionlevelId", "dependentactionId", 
  "dependentFeatureId", "dependentActionName", 
  "dependentFeatureName", "featureName", 
  "featureDescription", "featureTypeId", 
  "featureStatusId", "featureDisplaysequence", 
  "companyLegalUnit", "featureIsPrimary"
) AS 
SELECT 
  "servicedefinitionactionlimit"."serviceDefinitionId" "serviceDefinitionId", 
  "servicedefinitionactionlimit"."actionId" "actionId", 
  "servicedefinitionactionlimit"."limitTypeId" "limitTypeId", 
  "servicedefinitionactionlimit"."value" "value", 
  "servicedefinitionactionlimit"."id" "serviceDefinitionActionLimitId", 
  "servicedefinitionactionlimit"."softdeleteflag" "softdelete", 
  "servicedefinition"."serviceType" "serviceType", 
  "servicedefinition"."name" "serviceDefinitionName", 
  "servicedefinition"."description" "serviceDefinitionDescription", 
  "featureaction"."name" "actionName", 
  "featureaction"."description" "actionDescription", 
  "featureaction"."Type_id" "actionTypeId", 
  "featureaction"."Feature_id" "featureId", 
  "featureaction"."isMFAApplicable" "isMFAApplicable", 
  "featureaction"."isAccountLevel" "isAccountLevel", 
  "featureaction"."isPrimary" "isPrimary", 
  "featureaction"."DisplaySequence" "actionDisplaysequence", 
  "featureaction"."dependency" "actionDependency", 
  "featureaction"."status" "actionStatus", 
  "accesspolicy"."name" "accessPolicy", 
  "featureaction"."accesspolicyId" "accessPolicyId", 
  "featureaction"."limitgroupId" "limitGroupId", 
  "limitgroup"."name" "limitGroup", 
  "actionlevel"."name" "actionlevel", 
  "featureaction"."actionlevelId" "actionlevelId", 
  "dependentactions"."dependentactionId" "dependentactionId", 
  "dependentactions"."featureId" "dependentFeatureId", 
  "dependentactions"."actionName" "dependentActionName", 
  "dependentactions"."featureName" "dependentFeatureName", 
  "feature"."name" "featureName", 
  "feature"."description" "featureDescription", 
  "feature"."Type_id" "featureTypeId", 
  "feature"."Status_id" "featureStatusId", 
  "feature"."DisplaySequence" "featureDisplaysequence", 
  "feature"."companyLegalUnit" "companyLegalUnit", 
  "feature"."isPrimary" "featureIsPrimary" 
FROM 
  (
    (
      (
        (
          (
            (
              (
                "servicedefinitionactionlimit" 
                LEFT JOIN "servicedefinition" ON (
                  (
                    "servicedefinition"."id" = "servicedefinitionactionlimit"."serviceDefinitionId" 
                    AND "servicedefinition"."companyLegalUnit" = "servicedefinitionactionlimit"."companyLegalUnit"
                  )
                )
              ) 
              LEFT JOIN "featureaction" ON (
                (
                  "featureaction"."id" = "servicedefinitionactionlimit"."actionId" 
                  AND "featureaction"."companyLegalUnit" = "servicedefinitionactionlimit"."companyLegalUnit"
                )
              )
            ) 
            LEFT JOIN "dependentactions" ON (
              (
                "featureaction"."id" = "dependentactions"."actionId" 
                AND "featureaction"."companyLegalUnit" = "dependentactions"."companyLegalUnit"
              )
            )
          ) 
          LEFT JOIN "feature" ON (
            (
              "feature"."id" = "featureaction"."Feature_id" 
              AND "feature"."companyLegalUnit" = "featureaction"."companyLegalUnit"
            )
          )
        ) 
        LEFT JOIN "accesspolicy" ON (
          (
            "featureaction"."accesspolicyId" = "accesspolicy"."id"
          )
        )
      ) 
      LEFT JOIN "limitgroup" ON (
        (
          "featureaction"."limitgroupId" = "limitgroup"."id"
        )
      )
    ) 
    LEFT JOIN "actionlevel" ON (
      (
        "featureaction"."actionlevelId" = "actionlevel"."id"
      )
    )
  );
--  DDL for View servicedefinition_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "servicedefinition_view" (
  "id", "name", "description", "companyLegalUnit", 
  "serviceType", "status", "numberOfRoles", 
  "numberOfActiveRoles", "defaultRole", 
  "numberOfFeatures", "numberOfContracts"
) AS 
SELECT 
  "servicedefinition"."id" "id", 
  "servicedefinition"."name" "name", 
  "servicedefinition"."description" "description", 
  "servicedefinition"."companyLegalUnit" "companyLegalUnit", 
  "servicedefinition"."serviceType" "serviceType", 
  "servicedefinition"."status" "status", 
  (
    SELECT 
      COUNT(
        "groupservicedefinition"."Group_id"
      ) 
    FROM 
      "groupservicedefinition" 
    WHERE 
      (
        "groupservicedefinition"."serviceDefinitionId" = "servicedefinition"."id"
      )
  ) "numberOfRoles", 
  (
    SELECT 
      COUNT("membergroup"."id") 
    FROM 
      "membergroup" 
    WHERE 
      "Status_id" LIKE 'SID_ACTIVE' 
      AND "id" IN (
        SELECT 
          "groupservicedefinition"."Group_id" 
        FROM 
          "groupservicedefinition" 
        WHERE 
          (
            "groupservicedefinition"."serviceDefinitionId" = "servicedefinition"."id"
          )
      )
  ) "numberOfActiveRoles", 
  (
    SELECT 
      max(
        "groupservicedefinition"."Group_id"
      ) 
    FROM 
      "groupservicedefinition" 
    WHERE 
      (
        (
          "groupservicedefinition"."serviceDefinitionId" = "servicedefinition"."id"
        ) 
        AND (
          "groupservicedefinition"."isDefaultGroup" = 1
        ) 
        AND (
          "groupservicedefinition"."companyLegalUnit" = "servicedefinition"."companyLegalUnit"
        )
      )
  ) "defaultRole", 
  (
    SELECT 
      COUNT(
        DISTINCT "servicedefinition_features_actions_view"."featureId"
      ) 
    FROM 
      "servicedefinition_features_actions_view" 
    WHERE 
      (
        (
          "servicedefinition"."id" = "servicedefinition_features_actions_view"."serviceDefinitionId"
        ) 
        AND (
          "servicedefinition_features_actions_view"."softdelete" = '0'
        )
      )
  ) "numberOfFeatures", 
  (
    SELECT 
      COUNT("contract"."id") 
    FROM 
      "contract" 
    WHERE 
      (
        "contract"."servicedefinitionId" = "servicedefinition"."id"
      )
  ) "numberOfContracts" 
FROM 
  "servicedefinition";

--  DDL for View systemuser_permissions_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "systemuser_permissions_view" (
  "User_id", "Permission_id", "Permission_name", 
  "Permission_status"
) AS 
SELECT 
  up."User_id" "User_id", 
  up."Permission_id" "Permission_id", 
  p."Name" "Permission_name", 
  p."Status_id" "Permission_status" 
FROM 
  (
    "userpermission" up 
    JOIN "permission" p ON (
      (up."Permission_id" = p."id")
    )
  ) 
UNION 
SELECT 
  ur."User_id" "User_id", 
  p."id" "Permission_id", 
  p."Name" "Permission_name", 
  p."Status_id" "Permission_status" 
FROM 
  (
    (
      (
        "role" r 
        JOIN "userrole" ur ON (
          (r."id" = ur."Role_id")
        )
      ) 
      JOIN "rolepermission" rp ON (
        (ur."Role_id" = rp."Role_id")
      )
    ) 
    JOIN "permission" p ON (
      (rp."Permission_id" = p."id")
    )
  );
