--  DDL for View user_customers_view

CREATE 
OR REPLACE FORCE NONEDITIONABLE VIEW "user_customers_view" (
  "customerId", "coreCustomerId", "contractId", 
  "contractName", "isPrimary", "coreCustomerName", 
  "isBusiness", "serviceDefinitionId", 
  "serviceDefinitionName", "serviceDefinitionType", 
  "roleId", "userRole"
) AS 
SELECT 
  "contractcustomers"."customerId" "customerId", 
  "contractcustomers"."coreCustomerId" "coreCustomerId", 
  "contractcustomers"."contractId" "contractId", 
  "contract"."name" "contractName", 
  "contractcustomers"."isPrimary" "isPrimary", 
  "contractcorecustomers"."coreCustomerName" "coreCustomerName", 
  "contractcorecustomers"."isBusiness" "isBusiness", 
  "contract"."servicedefinitionId" "serviceDefinitionId", 
  "servicedefinition"."name" "serviceDefinitionName", 
  "membergrouptype"."description" "serviceDefinitionType", 
  "membergroup"."id" "roleId", 
  "membergroup"."Name" "userRole" 
FROM 
  (
    (
      (
        "contractcustomers" 
        LEFT JOIN "contractcorecustomers" ON (
          (
            (
              "contractcorecustomers"."contractId" = "contractcustomers"."contractId"
            ) 
            AND (
              "contractcorecustomers"."coreCustomerId" = "contractcustomers"."coreCustomerId"
            )
          )
        )
      ) 
      LEFT JOIN "contract" ON (
        (
          "contract"."id" = "contractcorecustomers"."contractId"
        )
      )
    ) 
    LEFT JOIN "servicedefinition" ON (
      (
        "servicedefinition"."id" = "contract"."servicedefinitionId"
      )
    ) 
    LEFT JOIN "membergrouptype" ON (
      (
        "membergrouptype"."id" = "servicedefinition"."serviceType"
      )
    ) 
    LEFT JOIN "customergroup" ON (
      (
        "customergroup"."Customer_id" = "contractcustomers"."customerId" 
        AND "customergroup"."contractId" = "contractcustomers"."contractId" 
        AND "customergroup"."coreCustomerId" = "contractcustomers"."coreCustomerId"
      )
    ) 
    LEFT JOIN "membergroup" ON (
      "membergroup"."id" = "customergroup"."Group_id"
    )
  );
