CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "ach_file_record_subrecord_create_proc" (
  v__recordvalues IN VARCHAR2, iv__subRecordvalues IN VARCHAR2
) AS v__subRecordvalues VARCHAR2(4000) := iv__subRecordvalues;
v_index1 NUMBER(10, 0) := 0;
v_numOfRecords NUMBER(10, 0);
v_recordsData VARCHAR2(4000);
v_query VARCHAR2(4000);
v_subRecordsData VARCHAR2(4000);
v_subRecordData VARCHAR2(4000);
v_subRecordIndex NUMBER(10, 0);
v_numberOfSubRecords NUMBER(10, 0);
v_id VARCHAR2(4000);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_numOfRecords := LENGTH(v__recordvalues) - LENGTH(
  REPLACE(v__recordvalues, '|', ' ')
) || 1;
v_index1 := v_index1 + 1;
WHILE (v_index1 != v_numOfRecords + 1) LOOP BEGIN v_recordsData := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__recordvalues, '|', v_index1), 
  '|', 
  -1
);
v_query := (
  'INSERT INTO "achfilerecord"(
                                 "achfilerecord"."achFileId",
                                 "achfilerecord"."offsetAccountNumber",
                                 "achfilerecord"."offsetAmount",
                                 "achfilerecord"."offsetTransactionType",
                                 "achfilerecord"."effectiveDate",
                                 "achfilerecord"."requestType",
                                 "achfilerecord"."totalCreditAmount",
                                 "achfilerecord"."totalDebitAmount",
                                 "achfilerecord"."transactionType"
                              ) VALUES ('
) || (
  REPLACE(v_recordsData, '"', '''')
) || (');');
EXECUTE IMMEDIATE v_query;
--NEED TO CHECK
v_id := utils.getidentity();
IF v__subRecordvalues IS NOT NULL THEN BEGIN v__subRecordvalues := (
  REPLACE(v__subRecordvalues, '"', '''')
);
v_subRecordsData := (
  UTILS.SUBSTRING_INDEX(
    (
      UTILS.SUBSTRING_INDEX(
        (v__subRecordvalues), 
        '|', 
        v_index1
      )
    ), 
    '|', 
    -1
  )
);
IF v_subRecordsData IS NOT NULL THEN BEGIN v_numberOfSubRecords := LENGTH(v_subRecordsData) - LENGTH(
  REPLACE(v_subRecordsData, ';', ' ')
) || 1;
v_subRecordIndex := 1;
WHILE (1 = 1) LOOP BEGIN IF v_subRecordIndex = v_numberOfSubRecords + 1 THEN EXIT;
ELSE BEGIN v_subRecordData := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(
    v_subRecordsData, ';', v_subRecordIndex
  ), 
  ';', 
  -1
);
v_query := (
  '
                                                                     INSERT INTO "achfilesubrecord"(
                                                                        "achfilesubrecord". "amount",
                                                                        "achfilesubrecord". "receiverAccountNumber",
                                                                        "achfilesubrecord". "receiverAccountType",
                                                                        "achfilesubrecord". "receiverName",
                                                                        "achfilesubrecord". "receiverTransactionType",
                                                                        "achfilesubrecord". "achFileRecordId"
                                                                     ) VALUES ('
) || v_subRecordData || (',') || (v_id) || (');');
EXECUTE IMMEDIATE v_query;
v_subRecordIndex := v_subRecordIndex + 1;
END;
END IF;
END;
END LOOP;
END;
END IF;
END;
END IF;
v_index1 := v_index1 + 1;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

