--  DDL for Procedure achtransactions_fetch_records_subrecords_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "achtransactions_fetch_records_subrecords_proc" (
  v__transactionId IN NUMBER, "achtransaction" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "achtransaction" FOR 
SELECT 
  achtransaction."transaction_id", 
  achtransaction."fromAccount", 
  achtransaction."effectiveDate", 
  achtransaction."requestId", 
  achtransaction."createdby", 
  achtransaction."createdts" createdOn, 
  achtransaction."maxAmount", 
  achtransaction."status", 
  achtransaction."transactionType_id", 
  achtransaction."templateType_id", 
  achtransaction."companyId", 
  achtransaction."templateRequestType_id", 
  achtransaction."templateName", 
  achtransaction."confirmationNumber", 
  achtransaction."actedBy", 
  achtransaction."template_id", 
  achtransaction."totalAmount", 
  achtransaction."featureActionId", 
  bbtemplaterequesttype."templateRequestTypeName" templateRequestType, 
  achtransactionrecord."transactionRecord_id", 
  achtransactionrecord."toAccountNumber", 
  achtransactionrecord."toAccountType", 
  achtransactionrecord."abatrcNumber", 
  achtransactionrecord."detail_id", 
  achtransactionrecord."amount", 
  achtransactionrecord."additionalInfo", 
  achtransactionrecord."eIN", 
  achtransactionrecord."isZeroTaxDue", 
  achtransactionrecord."taxType_id", 
  achtransactionrecord."templateRequestType_id", 
  achtransactionrecord."transaction_id" transaction_id_reclevel, 
  achtransactionrecord."record_Name", 
  achtransactionsubrecord."transcationSubRecord_id", 
  achtransactionsubrecord."amount" subrecordamount, 
  achtransactionsubrecord."taxSubCategory_id", 
  bbtaxtype."taxType", 
  bbtaxsubtype."taxSubType", 
  achtransactionsubrecord."transactionRecord_id" transactionRecord_id_subreclevel 
FROM 
  (
    (
      (
        (
          (
            "achtransaction" achTransaction 
            LEFT JOIN "achtransactionrecord" achTransactionRecord ON achtransaction."transaction_id" = achtransactionrecord."transaction_id"
          ) 
          LEFT JOIN "achtransactionsubrecord" achTransactionSubRecord ON achtransactionrecord."transactionRecord_id" = achtransactionsubrecord."transactionRecord_id"
        ) 
        LEFT JOIN "bbtaxtype" bbTaxType ON achtransactionrecord."taxType_id" = bbtaxtype."id"
      ) 
      LEFT JOIN "bbtaxsubtype" bbTaxSubtype ON achtransactionsubrecord."taxSubCategory_id" = bbtaxsubtype."id"
    ) 
    LEFT JOIN "bbtemplaterequesttype" bbTemplateRequestType ON achTransaction."templateRequestType_id" = bbtemplaterequesttype."templateRequestType_id"
  ) 
WHERE 
  achTransaction."transaction_id" = v__transactionId 
ORDER BY 
  achTransaction."transaction_id", 
  achtransactionrecord."transactionRecord_id", 
  achtransactionsubrecord."transactionRecord_id";
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure action_limits_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "action_limits_update_proc" (
  v__action IN VARCHAR2, v__minTxLimit IN NUMBER, 
  v__maxTxLimit IN NUMBER, v__dailyLimit IN NUMBER, 
  v__weeklyLimit IN NUMBER
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
UPDATE 
  "actionlimit" 
SET 
  "value" = v__minTxLimit 
WHERE 
  "actionlimit"."Action_id" = v__action 
  AND "actionlimit"."LimitType_id" = 'MIN_TRANSACTION_LIMIT';
UPDATE 
  "actionlimit" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "actionlimit"."Action_id" = v__action 
  AND "actionlimit"."LimitType_id" = 'MAX_TRANSACTION_LIMIT';
UPDATE 
  "actionlimit" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "actionlimit"."Action_id" = v__action 
  AND "actionlimit"."LimitType_id" = 'DAILY_LIMIT';
UPDATE 
  "actionlimit" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "actionlimit"."Action_id" = v__action 
  AND "actionlimit"."LimitType_id" = 'WEEKLY_LIMIT';
UPDATE 
  "groupactionlimit" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "groupactionlimit"."Action_id" = v__action 
  AND "groupactionlimit"."LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "groupactionlimit"."value" > v__maxTxLimit;
UPDATE 
  "groupactionlimit" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "groupactionlimit"."Action_id" = v__action 
  AND "groupactionlimit"."LimitType_id" = 'DAILY_LIMIT' 
  AND "groupactionlimit"."value" > v__dailyLimit;
UPDATE 
  "groupactionlimit" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "groupactionlimit"."Action_id" = v__action 
  AND "groupactionlimit"."LimitType_id" = 'WEEKLY_LIMIT' 
  AND "groupactionlimit"."value" > v__weeklyLimit;
UPDATE 
  "organisationactionlimit" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "organisationactionlimit"."Action_id" = v__action 
  AND "organisationactionlimit"."LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "organisationactionlimit"."value" > v__maxTxLimit;
UPDATE 
  "organisationactionlimit" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "organisationactionlimit"."Action_id" = v__action 
  AND "organisationactionlimit"."LimitType_id" = 'DAILY_LIMIT' 
  AND "organisationactionlimit"."value" > v__dailyLimit;
UPDATE 
  "organisationactionlimit" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "organisationactionlimit"."Action_id" = v__action 
  AND "organisationactionlimit"."LimitType_id" = 'WEEKLY_LIMIT' 
  AND "organisationactionlimit"."value" > v__weeklyLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'PRE_APPROVED_TRANSACTION_LIMIT' 
  AND "customeraction"."value" > v__maxTxLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'PRE_APPROVED_DAILY_LIMIT' 
  AND "customeraction"."value" > v__dailyLimit;
UPDATE 
