WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'PRE_APPROVED_WEEKLY_LIMIT' 
  AND "customeraction"."value" > v__weeklyLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'AUTO_DENIED_TRANSACTION_LIMIT' 
  AND "customeraction"."value" > v__maxTxLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'AUTO_DENIED_DAILY_LIMIT' 
  AND "customeraction"."value" > v__dailyLimit;
UPDATE 
