WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'AUTO_DENIED_WEEKLY_LIMIT' 
  AND "customeraction"."value" > v__weeklyLimit;
UPDATE 
