SET 
  "value" = v__maxTxLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "customeraction"."value" > v__maxTxLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "customeraction"."Action_id" = v__action 
  AND "customeraction"."LimitType_id" = 'DAILY_LIMIT' 
  AND "customeraction"."value" > v__dailyLimit;
UPDATE 
  "customeraction" 
SET 
