--  DDL for Procedure alert_history_proc


CREATE OR REPLACE NONEDITIONABLE PROCEDURE "alert_history_proc" 
(
  v__customerId IN VARCHAR2,
    "alerthistory" OUT SYS_REFCURSOR
)
AS
 

BEGIN

--   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
   OPEN  "alerthistory" FOR
      SELECT "alerthistory"."id" alerthistory_id  ,
             "alerthistory"."EventId" alerthistory_EventId  ,
             "alerthistory"."AlertSubTypeId" alerthistory_AlertSubTypeId  ,
             "alerthistory"."AlertTypeId" alerthistory_AlertTypeId  ,
             "alerthistory"."AlertCategoryId" alerthistory_AlertCategoryId  ,
             "alerthistory"."Customer_Id" alerthistory_Customer_Id  ,
             "alerthistory"."LanguageCode" alerthistory_LanguageCode  ,
             "alerthistory"."ChannelId" alerthistory_ChannelId  ,
             "alerthistory"."Status" alerthistory_Status  ,
             "alerthistory"."Subject" alerthistory_Subject  ,
             "alerthistory"."Message" alerthistory_Message  ,
             "alerthistory"."SenderName" alerthistory_SenderName  ,
             "alerthistory"."SenderEmail" alerthistory_SenderEmail  ,
             "alerthistory"."ReferenceNumber" alerthistory_ReferenceNumber  ,
             "alerthistory"."createdts" alerthistory_sentDate  ,
             "alerthistory"."softdeleteflag" alerthistory_softdeleteflag  ,
             "alertsubtype"."Name" alertsubtype_Name  ,
             "alertsubtype"."Description" alertsubtype_Description  ,
             "channeltext"."Description" channeltext_Description  
        FROM "alerthistory" 
               JOIN "alertsubtype"    ON ( "alertsubtype"."id" = "alerthistory"."AlertSubTypeId" )
               JOIN "channeltext"    ON ( "channeltext"."channelID" = "alerthistory"."ChannelId" )
       WHERE  ( "alerthistory"."Customer_Id" = v__customerId
                AND "channeltext"."LanguageCode" = 'en-US' )
        ORDER BY "alerthistory"."DispatchDate" DESC
        FETCH FIRST 800 ROWS ONLY ;
      --DBMS_SQL.RETURN_RESULT(v_cursor);

EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE,SQLERRM);
END;
/

--  DDL for Procedure approval_matrix_manual_cleanup_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approval_matrix_manual_cleanup_proc" (
  v__contractId IN VARCHAR2, v__coreCustomerId IN VARCHAR2, 
  "contractaccounts" OUT SYS_REFCURSOR
) AS v_customerAccounts CLOB;
v_customerActions CLOB;
BEGIN 
UPDATE 
  "approvalmatrix" 
SET 
  "softdeleteflag" = '1' 
WHERE 
  "approvalmatrix"."coreCustomerId" = v__coreCustomerId;
SELECT 
  DISTINCT LISTAGG("contractaccounts"."accountId") INTO v_customerAccounts 
FROM 
  "contractaccounts" 
WHERE 
  (
    "contractId" = v__contractId 
    AND "coreCustomerId" = v__coreCustomerId
  );
SELECT 
  DISTINCT LISTAGG("actionId") INTO v_customerActions 
FROM 
  "contractactionlimit" 
  LEFT JOIN "featureaction" ON (
    "featureaction"."id" = "contractactionlimit"."actionId"
  ) 
WHERE 
  (
    "contractId" = v__contractId 
    AND "coreCustomerId" = v__coreCustomerId
  ) 
  AND "featureaction"."approveFeatureAction" IS NOT NULL;
--APPROVALMATRIX_DEFAULT_CREATE_PROC(v_customerActions,
--                                        v__contractId,
--                                      v_customerAccounts,
--                                    v__coreCustomerId,
--                                  v_cursor) ;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure approvalmatrix_create_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalmatrix_create_proc" (
  "_matrixValues" IN NVARCHAR2, "_approverIds" IN NVARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_length NUMBER(19, 0);
v_index2 NUMBER(10, 0) := 0;
v_id NUMBER(10, 0);
v_customerIds NVARCHAR2(2000);
v_customerIdsComma NVARCHAR2(2000);
v_length2 NUMBER(10, 0);
v_customerId NVARCHAR2(100);
v_matrixRecord NVARCHAR2(2000);
v_matrixComma VARCHAR2(4000);
v_query NVARCHAR2(2000);
identity_value NUMBER(10);
BEGIN v_length := LENGTH("_matrixValues") - LENGTH(
  REPLACE("_matrixValues", ',', '')
) + 1;
<< loop_2 >> WHILE (1 = 1) LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_length + 1 THEN EXIT;
ELSE BEGIN v_matrixRecord := SUBSTRING_INDEX(
  SUBSTRING_INDEX("_matrixValues", ',', v_index1), 
  ',', 
  -1
);
v_matrixComma := REPLACE(v_matrixRecord, ';', ',');
v_matrixComma := REPLACE(v_matrixComma, '"', '''');
v_query := (
  '
                                 INSERT into "approvalmatrix"(
                                    "approvalmatrix"."name",
                                    "approvalmatrix"."contractId",
                        "approvalmatrix"."coreCustomerId",
                                    "approvalmatrix"."actionId",
                                    "approvalmatrix"."accountId",
                                    "approvalmatrix"."approvalruleId",
                                    "approvalmatrix"."limitTypeId",
                                    "approvalmatrix"."lowerlimit",
                                    "approvalmatrix"."upperlimit",
                                    "approvalmatrix"."currency"
                                 ) VALUES ('
) || (v_matrixComma) || (')');
EXECUTE IMMEDIATE v_query;
select 
  "id" INTO identity_value 
from 
  "approvalmatrix" 
where 
  rowid =(
    select 
      max(rowid) 
    from 
      "approvalmatrix"
  );
v_id := identity_value;
v_customerIds := SUBSTRING_INDEX(
  SUBSTRING_INDEX("_approverIds", ',', v_index1), 
  ',', 
  -1
);
v_customerIdsComma := REPLACE(v_customerIds, ';', ',');
v_length2 := LENGTH(v_customerIdsComma) - LENGTH(
  REPLACE(v_customerIdsComma, ',', '')
) + 1;
v_index2 := 0;
<< loop_1 >> WHILE (1 = 1) LOOP BEGIN v_index2 := v_index2 + 1;
IF v_index2 = v_length2 + 1 THEN EXIT;
ELSE BEGIN v_customerId := SUBSTRING_INDEX(
  SUBSTRING_INDEX(
    v_customerIdsComma, ',', v_index2
  ), 
  ',', 
  -1
);
INSERT INTO "customerapprovalmatrix" (
  "customerapprovalmatrix"."customerId", 
  "customerapprovalmatrix"."approvalMatrixId"
) 
VALUES 
  (v_customerId, v_id);
GOTO loop_1;
END;
END IF;
END;
END LOOP;
GOTO loop_2;
END;
END IF;
END;
END LOOP;
END;
/

--  DDL for Procedure approvalmatrix_default_create_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalmatrix_default_create_proc" (
  v__actionIds IN VARCHAR2, v__contractId IN VARCHAR2, 
  v__accountIds IN VARCHAR2, v__cif IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v_accountList CLOB := '0';
v_limitTypeId_1 VARCHAR2(255) := 'DAILY_LIMIT';
v_limitTypeId_2 VARCHAR2(255) := 'MAX_TRANSACTION_LIMIT';
v_limitTypeId_3 VARCHAR2(255) := 'WEEKLY_LIMIT';
v_accountIndex NUMBER(10, 0) := 0;
v_actionIndex NUMBER(10, 0) := 0;
v_typeId CLOB := '';
v_numOfAccounts NUMBER(10, 0);
v_numOfActions NUMBER(10, 0);
v_accountId VARCHAR2(50);
v_actionId VARCHAR2(255);
BEGIN IF v__actionIds IS NULL 
OR v__actionIds = '' THEN RETURN;
END IF;
IF v__contractId IS NULL 
OR v__contractId = '' THEN RETURN;
END IF;
IF v__cif IS NULL 
OR v__cif = '' THEN RETURN;
END IF;
IF v__accountIds IS NULL 
OR v__accountIds = '' THEN RETURN;
END IF;
v_numOfAccounts := LENGTH(v__accountIds) - LENGTH(
  REPLACE(v__accountIds, ',', ' ')
) || 1;
v_numOfActions := LENGTH(v__actionIds) - LENGTH(
  REPLACE(v__actionIds, ',', ' ')
) || 1;
<< getAccount >> WHILE 1 = 1 LOOP BEGIN v_accountIndex := v_accountIndex + 1;
IF v_accountIndex = v_numOfAccounts + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_accountId := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(
    v__accountIds, ',', v_accountIndex
  ), 
  ',', 
  -1
);
v_actionIndex := 0;
<< getAction >> WHILE 1 = 1 LOOP BEGIN v_actionIndex := v_actionIndex + 1;
IF v_actionIndex = v_numOfActions + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_actionId := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__actionIds, ',', v_actionIndex), 
  ',', 
  -1
);
SELECT 
  "Type_id" INTO v_typeId 
FROM 
  "featureaction" 
WHERE 
  "id" = v_actionId;
IF v_typeId = 'MONETARY' THEN BEGIN INSERT INTO "approvalmatrix" (
  "contractId", "name", "accountId", 
  "actionId", "limitTypeId", "coreCustomerId", 
  "approvalruleId"
) 
VALUES 
  (
    v__contractId, 
    (
      v_actionId || '_' || v_accountId || '_' || v_limitTypeId_1 || '_' || v__contractId
    ), 
    v_accountId, 
    v_actionId, 
    v_limitTypeId_1, 
    v__cif, 
    'NO_APPROVAL'
  );
INSERT INTO "approvalmatrix" (
  "contractId", "name", "accountId", 
  "actionId", "limitTypeId", "coreCustomerId", 
  "approvalruleId"
) 
VALUES 
  (
    v__contractId, 
    (
      v_actionId || '_' || v_accountId || '_' || v_limitTypeId_2 || '_' || v__contractId
    ), 
    v_accountId, 
    v_actionId, 
    v_limitTypeId_2, 
    v__cif, 
    'NO_APPROVAL'
  );
INSERT INTO "approvalmatrix" (
  "contractId", "name", "accountId", 
  "actionId", "limitTypeId", "coreCustomerId", 
  "approvalruleId"
) 
VALUES 
  (
    v__contractId, 
    (
      v_actionId || '_' || v_accountId || '_' || v_limitTypeId_3 || '_' || v__contractId
    ), 
    v_accountId, 
    v_actionId, 
    v_limitTypeId_3, 
    v__cif, 
    'NO_APPROVAL'
  );
END;
ELSE IF v_typeId = 'NON_MONETARY' THEN BEGIN INSERT INTO "approvalmatrix" (
  "contractId", "name", "accountId", 
  "actionId", "limitTypeId", "coreCustomerId", 
  "approvalruleId"
) 
VALUES 
  (
    v__contractId, 
    (
      v_actionId || '_' || v_accountId || '_' || 'NON_MONETARY_LIMIT' || '_' || v__contractId
    ), 
    v_accountId, 
    v_actionId, 
    'NON_MONETARY_LIMIT', 
    v__cif, 
    'NO_APPROVAL'
  );
END;
END IF;
END IF;
END;
END IF;
END;
END LOOP;
v_accountList := (
  v_accountId || ',' || v_accountList
);
END;
END IF;
END;
END LOOP;
SELECT 
  SUBSTR(
    v_accountList, 
    1, 
    (
      LENGTH(v_accountList) -1
    )
  ) INTO v_accountList 
FROM 
  DUAL;
OPEN v_cursor FOR 
SELECT 
  v_accountList accountList 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure approvalmatrix_default_delete_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalmatrix_default_delete_proc" (
  v__contractId IN VARCHAR2, v__cif IN VARCHAR2, 
  v__filterColumnIds IN VARCHAR2, v__filterColumnName IN VARCHAR2
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
IF v__filterColumnName = 'actionId' THEN BEGIN DELETE "approvalmatrix" 
WHERE 
  "approvalmatrix"."contractId" = v__contractId 
  AND "approvalmatrix"."coreCustomerId" = v__cif 
  AND "approvalmatrix"."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__filterColumnIds)
      )
  );
END;
ELSE IF v__filterColumnName = 'accountId' THEN BEGIN DELETE "approvalmatrix" 
WHERE 
  "approvalmatrix"."contractId" = v__contractId 
  AND "approvalmatrix"."coreCustomerId" = v__cif 
  AND "approvalmatrix"."accountId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__filterColumnIds)
      )
  );
END;
ELSE IF v__filterColumnName = 'cif' THEN BEGIN DELETE "approvalmatrix" 
WHERE 
  "approvalmatrix"."contractId" = v__contractId 
  AND "approvalmatrix"."coreCustomerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__filterColumnIds)
      )
  );
END;
END IF;
END IF;
END IF;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure approvalmatrix_fetch_grouprecords_proc


create or replace NONEDITIONABLE PROCEDURE         "approvalmatrix_fetch_grouprecords_proc" 
(
  "_contractId" IN VARCHAR2,
  "_cif" IN VARCHAR2,
  "_accountId" IN VARCHAR2,
  "_limitTypeId" IN VARCHAR2,
  "_actions" IN VARCHAR2,
  "records" OUT SYS_REFCURSOR
)
AS
   v__cif VARCHAR2(50) := "_cif";
   v__accountId VARCHAR2(50) := "_accountId";
   v__limitTypeId VARCHAR2(50) := "_limitTypeId";


BEGIN

--   /*TODO:SQLDEV*/ SET XACT_ABORT ON /*END:SQLDEV*/
   IF v__cif = '' THEN
    v__cif := '%' ;
   END IF;
   IF v__accountId = '' THEN
    v__accountId := '%' ;
   END IF;
   IF v__limitTypeId = '' THEN
    v__limitTypeId := '%' ;
   END IF;
   OPEN  "records" FOR
      SELECT approvalmatrix."id" ,
             approvalmatrix."contractId" ,
             approvalmatrix."accountId" ,
             approvalmatrix."limitTypeId" ,
             featureaction."id" "actionId"  ,
             featureaction."name" "actionName"  ,
             featureaction."description" "actionDescription"  ,
             featureaction."Feature_id" "featureId"  ,
             featureaction."Type_id" "actionType"  ,
             featureaction."isAccountLevel" "isAccountLevel"  ,
             feature."name" "featureName"  ,
             feature."Status_id" "fifeaturestatus"  ,
             approvalrule."id" "approvalruleId"  ,
             approvalrule."numberOfApprovals" ,
             approvalrule."name" "approvalRuleName"  ,
             approvalmatrix."lowerlimit" ,
             approvalmatrix."upperlimit" ,
--             approvalmatrix."currency",
             signatorygroupmatrix."groupList" "groupList"  ,
             signatorygroupmatrix."groupRule" "groupRule"  ,
             contractcorecustomers."coreCustomerId" "cifId"  ,
             contractcorecustomers."coreCustomerName" "cifName"  ,
             approvalmatrix."invalid" ,
             approvalmatrix."isGroupMatrix"  
        FROM ( ( ( ( ( ( "approvalmatrix" approvalmatrix
                         LEFT JOIN "signatorygroupmatrix" signatoryGroupMatrix   ON approvalmatrix."id" = signatorygroupmatrix."approvalMatrixId"
                          ) 
                       LEFT JOIN "featureaction" featureaction   ON approvalmatrix."actionId" = featureaction."id"
                        ) 
                     LEFT JOIN "approvalrule" approvalRule   ON approvalmatrix."approvalruleId" = approvalrule."id"
                      ) 
                   LEFT JOIN "feature" feature   ON featureaction."Feature_id" = feature."id"
                    ) 
                 LEFT JOIN "contractfeatures" contractfeatures   ON feature."id" = contractfeatures."featureId"
                 AND approvalmatrix."contractId" = contractfeatures."contractId"
                 AND approvalmatrix."coreCustomerId" = contractfeatures."coreCustomerId"
                  ) 
               LEFT JOIN "contractcorecustomers" contractcorecustomers   ON approvalmatrix."contractId" = contractcorecustomers."contractId"
               AND approvalmatrix."coreCustomerId" = contractcorecustomers."coreCustomerId"
                ) 
       WHERE  approvalmatrix."contractId" = "_contractId"
                AND approvalmatrix."coreCustomerId" LIKE v__cif
                AND approvalmatrix."isGroupMatrix" = 1
                AND approvalmatrix."accountId" LIKE v__accountId
                AND approvalmatrix."actionId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT("_actions")))
                AND approvalmatrix."limitTypeId" LIKE v__limitTypeId
                AND approvalmatrix."softdeleteflag" = 0
                AND featureaction."approveFeatureAction" IS NOT NULL
                AND featureaction."status" = 'SID_ACTION_ACTIVE'
        ORDER BY approvalmatrix."contractId",
                 approvalmatrix."accountId",
                 approvalmatrix."limitTypeId",
                 approvalmatrix."actionId",
                 approvalmatrix."lowerlimit" ;
      --DBMS_SQL.RETURN_RESULT(v_cursor);

END;
/

--  DDL for Procedure approvalmatrix_fetch_records_proc


create or replace NONEDITIONABLE PROCEDURE "approvalmatrix_fetch_records_proc"
(
  "_contractId" IN VARCHAR2,
  "_cif" IN VARCHAR2,
  "_accountId" IN VARCHAR2,
  "_limitTypeId" IN VARCHAR2,
  "_actions" IN NVARCHAR2,
  "records" OUT SYS_REFCURSOR
)
AS
   iv_cif VARCHAR2(50) := "_cif";
   iv_accountId VARCHAR2(50) := "_accountId";
   iv_limitTypeId VARCHAR2(50) := "_limitTypeId" ;


BEGIN
   IF iv_cif is null THEN
    iv_cif := '%' ;
   END IF;
   IF iv_accountId is null THEN
    iv_accountId := '%' ;
   END IF;
   IF iv_limitTypeId is null THEN
    iv_limitTypeId := '%' ;
   END IF;
   OPEN  "records" FOR
      SELECT "approvalmatrix"."id" ,
             "approvalmatrix"."contractId" ,
             "approvalmatrix"."accountId" ,
             "approvalmatrix"."limitTypeId" ,
             "featureAction"."id" "actionId"  ,
             "featureAction"."name" "actionName"  ,
             "featureAction"."description" "actionDescription"  ,
             "featureAction"."Feature_id" "featureId"  ,
             "featureAction"."Type_id" "actionType"  ,
             "feature"."name" "featureName"  ,
             "feature"."Status_id" "fifeaturestatus"  ,
             "approvalRule"."id" "approvalruleId"  ,
             "approvalRule"."numberOfApprovals" ,
             "approvalRule"."name" "approvalRuleName"  ,
             "approvalmatrix"."lowerlimit" ,
             "approvalmatrix"."upperlimit" ,
--             "approvalmatrix"."currency",
             "customer"."id" "customerId"  ,
             "customer"."FirstName" "firstName"  ,
             "customer"."LastName" "lastName"  ,
             "contractcorecustomers"."coreCustomerId" "cifId"  ,
             "contractcorecustomers"."coreCustomerName" "cifName"  ,
             "approvalmatrix"."invalid" ,
             "approvalmatrix"."isGroupMatrix" 
        FROM ( ( ( ( ( ( ( "approvalmatrix" "approvalmatrix"
                           LEFT JOIN "customerapprovalmatrix" "customerapprovalMatrix"   ON "approvalmatrix"."id" = "customerapprovalMatrix"."approvalMatrixId"
                            ) 
                         LEFT JOIN "customer" "customer"   ON "customerapprovalMatrix"."customerId" = "customer"."id"
                          ) 
                       LEFT JOIN "featureaction" "featureAction"   ON "approvalmatrix"."actionId" = "featureAction"."id"
                        ) 
                     LEFT JOIN "approvalrule" "approvalRule"   ON "approvalmatrix"."approvalruleId" = "approvalRule"."id"
                      ) 
                   LEFT JOIN "feature" "feature"   ON "featureAction"."Feature_id" = "feature"."id"
                    ) 
                 LEFT JOIN "contractfeatures" "contractfeatures"   ON "feature"."id" = "contractfeatures"."featureId"
                 AND "approvalmatrix"."contractId" = "contractfeatures"."contractId"
                 AND "approvalmatrix"."coreCustomerId" = "contractfeatures"."coreCustomerId"
                  ) 
               LEFT JOIN "contractcorecustomers" "contractcorecustomers"   ON "approvalmatrix"."contractId" = "contractcorecustomers"."contractId"
               AND "approvalmatrix"."coreCustomerId" = "contractcorecustomers"."coreCustomerId"
                ) 
       WHERE  
       "approvalmatrix"."contractId" = "_contractId"
                AND
                "approvalmatrix"."coreCustomerId" LIKE iv_cif
                AND "approvalmatrix"."accountId" LIKE iv_accountId
--                AND FIND_IN_SET("approvalmatrix"."actionId", "_actions") > 0
                AND "approvalmatrix"."actionId" IN (SELECT DISTINCT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT("_actions")))
                AND "approvalmatrix"."limitTypeId" LIKE iv_limitTypeId
                AND "approvalmatrix"."softdeleteflag" = 0
                AND "featureAction"."approveFeatureAction" IS NOT NULL
                AND "featureAction"."approveFeatureAction" IS NOT NULL
                AND "featureAction"."status" = 'SID_ACTION_ACTIVE'
        ORDER BY "approvalmatrix"."contractId",
                 "approvalmatrix"."accountId",
                 "approvalmatrix"."limitTypeId",
                 "approvalmatrix"."actionId",
                 "approvalmatrix"."lowerlimit" ;


END;
/

--  DDL for Procedure approvalmatrix_signatorygroupmatrixcreate_proc


CREATE OR REPLACE PROCEDURE "approvalmatrix_signatorygroupmatrixcreate_proc"
(
  "_matrixValues" IN NVARCHAR2,
  "_signatorymatrixValues" IN NVARCHAR2
)
AS
   v_index1 NUMBER(10,0) := 0;
   v_index2 NUMBER(10,0) := 0;
   v_length NUMBER(10,0) := 0;
   v_matrixRecord NVARCHAR2(2000);
   v_matrixComma VARCHAR2(4000);
   v_query NVARCHAR2(2000);
   v_sigValues NVARCHAR2(2000);
   v_id NVARCHAR2(2000);
   v_groupList NVARCHAR2(2000);
   v_groupRule NVARCHAR2(2000);
   identity_value NUMBER(10);

BEGIN

   v_length := LENGTH("_matrixValues") - LENGTH(REPLACE("_matrixValues", ',', '')) + 1 ;
   <<loop_1>>
   WHILE ( 1 = 1 ) 
   LOOP 
      
      BEGIN
         v_index1 := v_index1 + 1 ;
         IF v_index1 = v_length + 1 THEN
          EXIT;
         ELSE
         
         BEGIN
            v_matrixRecord := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX("_matrixValues", ',', v_index1), ',', -1) ;
            v_matrixComma := REPLACE(v_matrixRecord, ';', ',') ;
            v_matrixComma := REPLACE(v_matrixComma, '"', '''') ;
            v_query := ('INSERT INTO "approvalmatrix"("name","contractId","coreCustomerId","actionId","accountId","approvalruleId","isGroupMatrix","limitTypeId","lowerlimit","upperlimit","currency") VALUES ('|| v_matrixComma|| ')') ;
            EXECUTE IMMEDIATE v_query;
            select "id"  INTO identity_value from  "approvalmatrix" where rowid=(select max(rowid) from "approvalmatrix");
      v_sigValues := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX("_signatorymatrixValues", '#', v_index1), '#', -1) ;
      v_id := identity_value ;
            v_groupList := UTILS.SUBSTRING_INDEX(v_sigValues, ';', 1) ;
            v_groupRule := UTILS.SUBSTRING_INDEX(v_sigValues, ';', -1) ;
            v_id := REPLACE(v_id, '"', '''') ;
            v_groupList := REPLACE(v_groupList, '"', '''') ;
            v_groupRule := REPLACE(v_groupRule, '"', '''') ;
            v_query := ('INSERT INTO "signatorygroupmatrix"("approvalMatrixId","groupList","groupRule") VALUES (') || v_id || ',' || '''' || v_groupList || '''' || ',' || '''' || v_groupRule || '''' || ')' ;
            EXECUTE IMMEDIATE v_query;
            GOTO loop_1;
         
         END;
         END IF;
      
      END;
   END LOOP;


END;
/

--  DDL for Procedure approvalmatrix_update_softdeleteflag_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalmatrix_update_softdeleteflag_proc" (
  v__contractId IN VARCHAR2, v__cif IN VARCHAR2, 
  v__accountIds IN VARCHAR2, v__actionId IN VARCHAR2, 
  v__limitTypeId IN VARCHAR2
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
UPDATE 
  "approvalmatrix" 
SET 
  "softdeleteflag" = 1 
WHERE 
  "approvalmatrix"."contractId" = v__contractId 
  AND "approvalmatrix"."coreCustomerId" = v__cif 
  AND CAST(
    "approvalmatrix"."accountId" AS VARCHAR2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__accountIds)
      )
  ) 
  AND "approvalmatrix"."actionId" = v__actionId 
  AND "approvalmatrix"."limitTypeId" = v__limitTypeId;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure approvalmatrixtemplate_cleanup_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalmatrixtemplate_cleanup_proc" (
  v__actionIds IN VARCHAR2, v__contractId IN VARCHAR2, 
  v__cif IN VARCHAR2, v__limitTypeId IN VARCHAR2
) AS BEGIN << MAINLABEL >> BEGIN 
UPDATE 
  "approvalmatrix" 
SET 
  "approvalmatrix"."softdeleteflag" = 1 
WHERE 
  "approvalmatrix"."contractId" = v__contractId 
  AND "approvalmatrix"."coreCustomerId" = v__cif 
  AND "approvalmatrix"."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__actionIds)
      )
  ) 
  AND "approvalmatrix"."limitTypeId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__limitTypeId)
      )
  ) 
  AND "approvalmatrix"."softdeleteflag" = 0;
UPDATE 
  "approvalmatrixtemplate" 
SET 
  "approvalmatrixtemplate"."softdeleteflag" = 1 
WHERE 
  "approvalmatrixtemplate"."contractId" = v__contractId 
  AND "approvalmatrixtemplate"."coreCustomerId" = v__cif 
  AND "approvalmatrixtemplate"."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__actionIds)
      )
  ) 
  AND "approvalmatrixtemplate"."limitTypeId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__limitTypeId)
      )
  ) 
  AND "approvalmatrixtemplate"."softdeleteflag" = 0;
END;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure approvalmatrixtemplate_create_proc


CREATE OR REPLACE PROCEDURE "approvalmatrixtemplate_create_proc"(
  "_matrixValues" IN NVARCHAR2, 
  "_matrixApprover" IN NVARCHAR2,
  "_isGroupMatrix" IN NUMBER
) AS
    v_index1 NUMBER(10) := 0;
    v_index2 NUMBER(10) := 0;
    v_length NUMBER(19) := 0;
    v_length2 NUMBER(10) := 0;
    v_matrixRecord NVARCHAR2(2000);
    v_matrixComma NVARCHAR2(2000);
    v_query NVARCHAR2(2000);
    v_id NVARCHAR2(50);
    v_customerIds NVARCHAR2(255);
    v_customerIdsComma NVARCHAR2(255);
    v_customerId NVARCHAR2(50);
    v_sigValues NVARCHAR2(255);
    v_groupList NVARCHAR2(255);
    v_groupRule NVARCHAR2(255);
    identity_value NUMBER(10);
BEGIN
  
  v_length := LENGTH("_matrixValues") - LENGTH(REPLACE("_matrixValues", ',', '')) + 1;
  <<loop_2>>
    WHILE (1 = 1)
    LOOP
        BEGIN
      v_index1 := v_index1 + 1;
      IF v_index1 = v_length + 1 THEN 
        EXIT;
      ELSE
                BEGIN 
                    SELECT "approvalmatrixtemplate"."id"  INTO identity_value from "approvalmatrixtemplate" ORDER BY "id" desc FETCH FIRST ROW ONLY;
                    v_id := identity_value+1;
                    v_matrixRecord := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX("_matrixValues", ',', v_index1), ',', -1 );
                    v_matrixComma := REPLACE(v_matrixRecord, ';', ',');
                    v_matrixComma := REPLACE(v_matrixComma, '"', '''');
                    v_matrixComma := v_id ||',' ||v_matrixComma;
                    v_query := 'INSERT INTO "approvalmatrixtemplate"("id","contractId","coreCustomerId","actionId","approvalruleId","limitTypeId","lowerlimit","upperlimit","currency","isGroupMatrix") VALUES (' ||v_matrixComma ||')';
                    EXECUTE IMMEDIATE v_query;
                    
                    IF "_isGroupMatrix" = 0 THEN
                        v_customerIds := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX("_matrixApprover", ',', v_index1), ',', -1 );
                        IF (v_customerIds IS NOT NULL AND LENGTH(v_customerIds) > 0) THEN
                            v_customerIdsComma := REPLACE(v_customerIds, ';', ',');
                                v_length2 := LENGTH(v_customerIdsComma) - LENGTH(REPLACE(v_customerIdsComma, ',', '')) + 1;
                                v_index2 := 0;
                                <<loop_1>>
                                WHILE(1 = 1)
                                LOOP
                                    BEGIN
                                    v_index2 := v_index2 + 1;
                                    IF v_index2 = v_length2 + 1 THEN 
                                        EXIT;
                                    ELSE
                                        BEGIN
                                        v_customerId := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX(v_customerIdsComma, ',', v_index2), ',', -1 );
                                        INSERT INTO "customerapprovalmatrixtemplate"("customerId","approvalMatrixId") values (v_customerId,v_id);             
                                        GOTO loop_1;
                                        END;
                                    END IF;
                                    END;
                                END LOOP;
                            END IF; 
                        GOTO loop_2;
                        ELSE IF "_isGroupMatrix" = 1 THEN
                            v_sigValues := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX("_matrixApprover", '#', v_index1), '#', -1 );
                            v_groupList := UTILS.SUBSTRING_INDEX(v_sigValues, ';', 1 );
                            v_groupRule := UTILS.SUBSTRING_INDEX(v_sigValues, ';', -1 );
                            INSERT INTO "signatorygroupmatrixtemplate"("approvalMatrixId", "groupList", "groupRule") values (v_id, v_groupList, v_groupRule);
                        END IF;  
                    END IF;
                END;
                END IF;
            END;
  END LOOP; 
END;
/

--  DDL for Procedure approvalmatrixtemplate_default_create_proc


create 
or replace NONEDITIONABLE PROCEDURE "approvalmatrixtemplate_default_create_proc" (
  "_actionIds" IN NVARCHAR2, "_contractId" IN NVARCHAR2, 
  "_approvalmode" IN NVARCHAR2, "_cif" IN NVARCHAR2, 
  "_currency" IN NVARCHAR2
) AS v_accountList VARCHAR2(4000) := 0;
v_actionIds VARCHAR2(32000) := 0;
v_limitTypeId_1 VARCHAR2(255) := 'DAILY_LIMIT';
v_limitTypeId_2 VARCHAR2(255) := 'MAX_TRANSACTION_LIMIT';
v_limitTypeId_3 VARCHAR2(255) := 'WEEKLY_LIMIT';
v_actionIndex NUMBER(10, 0) := 0;
v_actionId VARCHAR2(2000);
v_typeId VARCHAR2(4000) := ' ';
v_isGroupMatrix NUMBER(10, 0) := 0;
v_cursor SYS_REFCURSOR;
v_numOfActions NUMBER(10,0);
v_legalEntityId varchar2(255) := 'ALL';
BEGIN 
if "_contractId" is not null 
and "_cif" is not null 
and "_actionIds" is not null THEN If "_approvalmode" = '0' THEN v_isGroupMatrix := 0;
else v_isGroupMatrix := 1;
end if;
SELECT 
  "companyLegalUnit" into v_legalEntityId 
from 
  "contractcorecustomers" 
where 
  "coreCustomerId" = "_cif" 
  and "contractId" = "_contractId";
v_numOfActions := CASE WHEN "_actionIds" IS NULL THEN 0 ELSE LENGTH("_actionIds") - LENGTH(REPLACE("_actionIds", ',', '')
) + 1 END;
v_actionIds := REPLACE("_actionIds",' ','');
DBMS_OUTPUT.PUT_LINE('v_actionIds'||v_actionIds);
WHILE (1 = 1) LOOP BEGIN v_actionIndex := v_actionIndex + 1;
IF (v_actionIndex = v_numOfActions + 1) THEN EXIT;
ELSE BEGIN v_actionId := UTILS.SUBSTRING_INDEX(UTILS.SUBSTRING_INDEX(v_actionIds, ',', v_actionIndex),',',-1);
SELECT 
  "Type_id" INTO v_typeId 
FROM 
  "featureaction" 
WHERE 
  "id" = v_actionId 
  and "companyLegalUnit" = v_legalEntityId;
IF v_typeId = 'MONETARY' THEN BEGIN INSERT INTO "approvalmatrixtemplate" (
  "contractId", "actionId", "limitTypeId", 
  "coreCustomerId", "approvalruleId", 
  "isGroupMatrix", "currency"
) 
VALUES 
  (
    "_contractId", v_actionId, V_limitTypeId_1, 
    "_cif", 'NO_APPROVAL', v_isGroupMatrix, 
    "_currency"
  );
INSERT INTO "approvalmatrixtemplate" (
  "contractId", "actionId", "limitTypeId", 
  "coreCustomerId", "approvalruleId", 
  "isGroupMatrix", "currency"
) 
VALUES 
  (
    "_contractId", v_actionId, V_limitTypeId_2, 
    "_cif", 'NO_APPROVAL', v_isGroupMatrix, 
    "_currency"
  );
INSERT INTO "approvalmatrixtemplate" (
  "contractId", "actionId", "limitTypeId", 
  "coreCustomerId", "approvalruleId", 
  "isGroupMatrix", "currency"
) 
VALUES 
  (
    "_contractId", v_actionId, V_limitTypeId_3, 
    "_cif", 'NO_APPROVAL', v_isGroupMatrix, 
    "_currency"
  );
END;
ELSE IF v_typeId = 'NON_MONETARY' THEN BEGIN INSERT INTO "approvalmatrixtemplate" (
  "contractId", "actionId", "limitTypeId", 
  "coreCustomerId", "approvalruleId", 
  "isGroupMatrix", "currency"
) 
VALUES 
  (
    "_contractId", v_actionId, 'NON_MONETARY_LIMIT', 
    "_cif", 'NO_APPROVAL', v_isGroupMatrix, 
    "_currency"
  );
END;
END IF;
END IF;
END;
END IF;
END;
END LOOP;
END IF;
END;
/

--  DDL for Procedure approvalrequest_counts_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "approvalrequest_counts_proc" (
  "_customerId" IN NVARCHAR2, "_approveActionList" IN NVARCHAR2, 
  "_createActionList" IN NVARCHAR2, 
  "records" OUT SYS_REFCURSOR, "records1" out sys_refcursor
) AS iv_approveActionList NVARCHAR2(2000) := "_approveActionList";
iv_createActionList NVARCHAR2(2000) := "_createActionList";
BEGIN DECLARE v_approvalRequestIds NVARCHAR2(2000);
v_companyId NVARCHAR2(2000);
v_features NVARCHAR2(2000);
v_createApproveActions NVARCHAR2(2000);
v_customerMatrixIds NVARCHAR2(2000);
v_select_statement NVARCHAR2(4000);
v_alreadyApprovedIds NVARCHAR2(2000);
BEGIN OPEN "records" FOR 
SELECT 
  0 "count", 
  'ACHFilesForMyApproval' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'ACHTransactionsForMyApproval' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'GeneralTransactionsForMyApproval' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'GeneralTransactionsForMyApproval' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'myRequestsWaiting' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'myRequestsRejected' "TransactionType" 
FROM 
  DUAL 
UNION 
SELECT 
  0 "count", 
  'myRequestsApproved' "TransactionType" 
FROM 
  DUAL;
SELECT 
  "customer"."Organization_Id" INTO v_companyId 
FROM 
  "customer" 
WHERE 
  "customer"."id" = "_customerId";
IF v_companyId IS NULL THEN v_companyId := ' ';
END IF;
IF iv_approveActionList IS NULL THEN iv_approveActionList := ' ';
END IF;
IF iv_createActionList IS NULL THEN iv_createActionList := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."Feature_id" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(iv_approveActionList)
      )
  );
IF v_features IS NULL THEN v_features := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_createApproveActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features)
      )
  ) 
  AND (
    "featureaction"."id" LIKE '%_CREATE' 
    OR "featureaction"."id" LIKE '%_UPLOAD'
  );
IF v_createApproveActions IS NULL THEN v_createApproveActions := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_customerMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."customerId" = "_customerId";
IF v_customerMatrixIds IS NULL THEN v_customerMatrixIds := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbactedrequest"."requestId" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_alreadyApprovedIds 
FROM 
  "bbactedrequest" 
WHERE 
  "bbactedrequest"."createdby" = "_customerId" 
  AND "bbactedrequest"."action" = 'Approved';
IF v_alreadyApprovedIds IS NULL THEN v_alreadyApprovedIds := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "requestapprovalmatrix"."requestId" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_approvalRequestIds 
FROM 
  "requestapprovalmatrix" 
WHERE 
  (
    CAST(
      "requestapprovalmatrix"."approvalMatrixId" AS NVARCHAR2(2000)
    )
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_customerMatrixIds)
      )
  ) 
  AND FIND_IN_SET(
    CAST(
      "requestapprovalmatrix"."requestId" AS NVARCHAR2(2000)
    ), 
    v_alreadyApprovedIds
  ) = 0;
IF v_approvalRequestIds IS NULL THEN v_approvalRequestIds := ' ';
END IF;
v_select_statement := (
  'select count(tablea.requestCountA) as "count", tablea."TransactionType" 
               from (
                 select DISTINCT("bbrequest"."requestId") as requestCountA, 
                       case when "bbrequest"."featureActionId" LIKE ''ACH_FILE%''
                        then  ''ACHFilesForMyApproval'' else(
                           case when "bbrequest"."featureActionId" LIKE ''ACH%''
                              then ''ACHTransactionsForMyApproval'' else 
                              ''GeneralTransactionsForMyApproval'' end
                              ) end
                       as "TransactionType",
                       "bbrequest"."createdby",
                       "bbrequest"."companyId",
                       "bbrequest"."status"
                       FROM (
                           "bbrequest" LEFT JOIN "requestapprovalmatrix" ON 
                           "bbrequest"."requestId" = "requestapprovalmatrix"."requestId"
                       )
                       WHERE FIND_IN_SET(CAST("bbrequest"."requestId" as nvarchar2(2000)),''' || (v_approvalRequestIds) || ''')>0 AND "bbrequest"."companyId" = ''' || (v_companyId) || ''' AND FIND_IN_SET("bbrequest"."featureActionId",''' || (v_createApproveActions) || ''')>0' || ' AND "bbrequest"."status" = ''Pending'') tablea GROUP BY "TransactionType"'
);
v_select_statement := (v_select_statement) || ' UNION select count(tableb.requestCountB) as "count", 
                tableb."TransactionType" from (
                    select  
                        DISTINCT("bbrequest"."requestId") as requestCountB,
                        case when "bbrequest"."status" = ''Pending'' then ''myRequestsWaiting'' else
                            (case when "bbrequest"."status" = ''Rejected'' then ''myRequestsRejected'' else 
                                (case when "bbrequest"."status" = ''Approved'' then ''myRequestsApproved'' else ''myRequestsWithdrawn'' end)end)end as "TransactionType",
                        "bbrequest"."createdby",
                        "bbrequest"."companyId",
                        "bbrequest"."status"
                       FROM "bbrequest" WHERE "bbrequest"."companyId" = ''' || (v_companyId) || '''' || ' AND FIND_IN_SET("bbrequest"."featureActionId",''' || (iv_createActionList) || ''')>0 AND "bbrequest"."createdby" = ' || '''' || "_customerId" || '''' || ') tableb group BY "TransactionType"';
WHILE v_select_statement IS NULL LOOP EXIT;
END LOOP;
open "records1" for v_select_statement;
END;
--<<MAINLABEL$leave>>
END;
/

--  DDL for Procedure archived_request_search_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "archived_request_search_proc" (
  "_dateInitialPoint" IN VARCHAR2, "_dateFinalPoint" IN VARCHAR2, 
  "_requestStatusID" IN VARCHAR2, "_requestCategory" IN VARCHAR2, 
  "_offset" IN VARCHAR2, "_sortCriteria" IN VARCHAR2, 
  "_sortOrder" IN VARCHAR2, "_requestAssignedTo" IN VARCHAR2, 
  "_searchKey" IN VARCHAR2, "_messageRepliedBy" IN VARCHAR2, 
  "_recordsPerPage" IN VARCHAR2, "_queryType" IN VARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS v__searchKey VARCHAR2(50) := "_searchKey";
v_selectClause VARCHAR2(4000);
v_stmt VARCHAR2(4000);
v_whereclause VARCHAR2(4000);
v_joinCustomer VARCHAR2(4000);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_selectClause := CASE WHEN (
  NVL("_queryType", '') = 'count'
) THEN 'count(acr."id") AS cnt ' ELSE 'acr."id" AS customerrequest_id' END;
v_stmt := ('SELECT ') || (v_selectClause) || (
  ' FROM "archivedcustomerrequest" acr '
);
v_whereclause := ' WHERE 1=1 ';
v_joinCustomer := 0;
IF "_dateInitialPoint" <> '' 
AND "_dateFinalPoint" <> '' THEN v_whereclause := (v_whereclause) || (' ' || 'AND acr."createdts" >= ') || '''' || (
  trim("_dateInitialPoint")
)|| '''' || ('   AND ') || (' acr."createdts" <= ') || '''' || (
  trim("_dateFinalPoint") || ''''
);
ELSE IF "_dateInitialPoint" <> '' THEN v_whereclause := (v_whereclause) || ('    AND acr."createdts" = ') || '''' || (
  trim("_dateInitialPoint") || ''''
);
ELSE BEGIN IF "_dateFinalPoint" <> '' THEN v_whereclause := (v_whereclause) || ('   AND acr."createdts" = ') || '''' || (
  trim("_dateFinalPoint") || ''''
);
END IF;
END;
END IF;
END IF;
IF "_requestStatusID" <> '' THEN v_whereclause := (v_whereclause) || ('  AND acr."Status_id" IN (') || (
  func_escape_input_for_in_operator(
    trim("_requestStatusID")
  )
) || (') ');
END IF;
IF "_requestCategory" <> '' THEN v_whereclause := (v_whereclause) || '  AND acr."RequestCategory_id" = ' || '''' || (
  trim("_requestCategory")
) || '''';
END IF;
IF "_requestAssignedTo" <> '' THEN v_whereclause := (v_whereclause) || (' AND acr."AssignedTo" = ') || '''' || (
  trim("_requestAssignedTo")
) || '''';
END IF;
IF "_messageRepliedBy" <> '' THEN BEGIN v_stmt := (v_stmt) || (
  'LEFT JOIN "archivedrequestmessage" ON (acr."id" = "archivedrequestmessage"."CustomerRequest_id") '
);
v_whereclause := (v_whereclause) || (
  ' ' || '  AND "archivedrequestmessage"."RepliedBy_id" = '
) || '''' || (
  trim("_messageRepliedBy")
) || '''';
END;
END IF;
IF v__searchKey <> '' THEN BEGIN v_joinCustomer := 1;
v__searchKey := '%' || v__searchKey || '%';
v_whereclause := (v_whereclause) || (
  ' AND ' || ' (' || '  acr."Customer_id" LIKE '
) || '''' || (v__searchKey) || '''' || (' OR acr."id" LIKE ') || '''' || (v__searchKey) || '''' || (
  ' OR "customer"."UserName" LIKE '
) || '''' || (v__searchKey) || '''' || (')');
END;
END IF;
IF "_queryType" <> 'count' THEN DECLARE v_sortColumn VARCHAR2(4000);
BEGIN IF "_sortCriteria" = 'customer_Fullname' THEN v_joinCustomer := 1;
END IF;
v_sortColumn := 'acr."lastmodifiedts"';
IF (
  "_sortCriteria" = 'customerrequest_Customer_id'
) THEN v_sortColumn := 'acr."Customer_id"';
ELSE IF (
  "_sortCriteria" = 'customerrequest_AssignedTo'
) THEN v_sortColumn := 'acr."AssignedTo"';
ELSE IF (
  "_sortCriteria" = 'customerrequest_createdts'
) THEN v_sortColumn := 'acr."createdts"';
ELSE IF (
  "_sortCriteria" = 'customerrequest"_requestCategory"_id'
) THEN v_sortColumn := ' acr."RequestCategory_id" ';
ELSE IF (
  "_sortCriteria" = 'customer_Fullname'
) THEN v_sortColumn := '("customer"."FirstName", "customer"."LastName")';
ELSE IF (
  "_sortCriteria" = 'customerrequest_Status_id'
) THEN v_sortColumn := 'acr."Status_id"';
ELSE BEGIN IF (
  "_sortCriteria" = 'customerrequest_AssignedTo_Name'
) THEN v_sortColumn := '("systemuser"."FirstName", "systemuser"."LastName")';
END IF;
END;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
v_whereclause := (v_whereclause) || ('  ORDER BY ') || (
  CASE WHEN (v_sortColumn = '') THEN ' acr."lastmodifiedts" ' ELSE v_sortColumn END
) || (' ') || (
  CASE WHEN (
    v_sortColumn = '' 
    OR "_sortOrder" = ''
  ) THEN ' DESC' ELSE "_sortOrder" END
);
v_whereclause := (v_whereclause) || (' OFFSET ') || (
  CASE WHEN ("_offset" = '') THEN '0' ELSE "_offset" END
) || (' ROWS FETCH NEXT ') || (
  CASE WHEN ("_recordsPerPage" = '') THEN '10' || (' ROWS ONLY ') ELSE "_recordsPerPage" || (' ROWS ONLY ') END
);
END;
END IF;
IF v_joinCustomer = 1 THEN v_stmt := (v_stmt) || (
  'LEFT JOIN "customer" ON (acr."Customer_id" = "customer"."id") '
);
END IF;
IF "_sortCriteria" = 'customerrequest_AssignedTo_Name' THEN v_stmt := (v_stmt) || (
  'LEFT JOIN "systemuser" ON (acr."AssignedTo" = "systemuser"."id") '
);
END IF;
v_stmt := (v_stmt) || (v_whereclause);
EXECUTE IMMEDIATE v_stmt;
OPEN "records" FOR v_stmt;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure authorizationCheckForRejectAndWithdrawl_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "authorizationCheckForRejectAndWithdrawl_proc" (
  "_requestId" IN NVARCHAR2, "_companyId" IN NVARCHAR2, 
  "_featureactionlist" IN NVARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS v_group_concat_max_len NUMBER(19, 0);
v_features NVARCHAR2(2000);
v_createActions NVARCHAR2(2000);
BEGIN v_group_concat_max_len := 100000000;
SELECT 
  listagg(
    CAST(
      "featureaction"."Feature_id" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  FIND_IN_SET(
    "featureaction"."id", "_featureactionlist"
  ) > 0;
IF v_features IS NULL THEN v_features := ' ';
END IF;
SELECT 
  listagg(
    CAST(
      "featureaction"."id" AS NVARCHAR2(2000)
    ), 
    ','
  ) INTO v_createActions 
FROM 
  "featureaction" 
WHERE 
  FIND_IN_SET(
    "featureaction"."Feature_id", v_features
  ) > 0 
  AND "featureaction"."approveFeatureAction" IS NOT NULL;
IF v_createActions IS NULL THEN v_createActions := ' ';
END IF;
OPEN "records" FOR 
SELECT 
  "bbrequest"."requestId", 
  "bbrequest"."transactionId", 
  "bbrequest"."featureActionId", 
  "bbrequest"."createdby", 
  "bbrequest"."companyId", 
  "bbrequest"."requiredSets", 
  "bbrequest"."receivedSets", 
  "bbrequest"."createdts", 
  "bbrequest"."status", 
  "bbrequest"."softDelete", 
  "bbrequest"."accountId" 
FROM 
  "bbrequest" 
WHERE 
  "bbrequest"."requestId" = CAST(
    "_requestId" AS FLOAT(53)
  ) 
  AND FIND_IN_SET(
    "bbrequest"."companyId", "_companyId"
  ) <> 0 
  AND FIND_IN_SET(
    "bbrequest"."featureActionId", v_createActions
  ) <> 0;
END;
/

--  DDL for Procedure auto_reject_invalid_pending_requests_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "auto_reject_invalid_pending_requests_proc" (v__customerId IN VARCHAR2) AS BEGIN DECLARE v_oldMatrixIds CLOB;
v_newMatrixIds CLOB;
v_invalidMatrixIds CLOB;
v_invalidRequestIds CLOB;
v_companyId CLOB;
v_numOfParams NUMBER(10, 0);
v_idx NUMBER(10, 0);
v_select_statement VARCHAR2(4000);
v_SQL_SAFE_UPDATES VARCHAR2(4000);
v_requestId VARCHAR2(4000);
BEGIN --      /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS VARCHAR2(255)
    )
  ) INTO v_oldMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."customerId" = v__customerId;
IF (v_oldMatrixIds IS NULL) THEN RETURN;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS VARCHAR2(255)
    )
  ) INTO v_newMatrixIds 
FROM 
  "customerapprovalmatrix" 
  LEFT JOIN "approvalmatrix" ON (
    "customerapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id"
  ) 
  JOIN (
    SELECT 
      DISTINCT "customeraction"."Account_id", 
      "featureaction"."Feature_id" FeatureId, 
      map.monetaryAction Action_id 
    FROM 
      "customeraction" 
      JOIN "featureaction" ON (
        "customeraction"."Action_id" = "featureaction"."id"
      ) 
      JOIN (
        SELECT 
          a."id" monetaryAction, 
          b."id" approveAction 
        FROM 
          "featureaction" a 
          JOIN "featureaction" b ON (a."Feature_id" = b."Feature_id") 
        WHERE 
          a."Type_id" = 'MONETARY'
      ) map ON (
        "customeraction"."Action_id" = map.approveAction
      ) 
    WHERE 
      "customeraction"."Customer_id" = v__customerId 
      AND "customeraction"."isAllowed" = 1 
      AND "customeraction"."Account_id" IS NOT NULL 
      AND "customeraction"."Action_id" LIKE '%_APPROVE'
  ) can ON (
    (
      "approvalmatrix"."actionId" = can.Action_id
    ) 
    AND (
      "approvalmatrix"."accountId" = can."Account_id"
    )
  ) 
WHERE 
  "customerapprovalmatrix"."customerId" = v__customerId;
IF (v_newMatrixIds IS NULL) THEN v_newMatrixIds := '';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "id" AS VARCHAR2(255)
    )
  ) INTO v_invalidMatrixIds 
FROM 
  "approvalmatrix" 
WHERE 
  CAST(
    "approvalmatrix"."id" AS VARCHAR2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_oldMatrixIds)
      )
  ) 
  AND CAST(
    "approvalmatrix"."id" AS VARCHAR2(255)
  ) NOT IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_oldMatrixIds)
      )
  );
IF (v_invalidMatrixIds IS NULL) THEN RETURN;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbrequest"."requestId" AS VARCHAR2(255)
    )
  ) INTO v_invalidRequestIds 
FROM 
  "bbrequest" 
  LEFT JOIN "requestapprovalmatrix" ON (
    "bbrequest"."requestId" = "requestapprovalmatrix"."requestId"
  ) 
  JOIN (
    SELECT 
      "approvalmatrix"."id" approvalMatrixId, 
      "approvalrule"."numberOfApprovals" numberOfApprovalsRequired, 
      (
        SELECT 
          COUNT(
            DISTINCT (
              "customerapprovalmatrix"."customerId"
            )
          ) 
        FROM 
          "customerapprovalmatrix" 
        WHERE 
          "customerapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id"
      ) numberOfApprovers 
    FROM 
      "approvalmatrix" 
      LEFT JOIN "approvalrule" ON (
        "approvalmatrix"."approvalruleId" = "approvalrule"."id"
      )
  ) temp_request_table ON (
    "requestapprovalmatrix"."approvalMatrixId" = temp_request_table.approvalmatrixId
  ) 
WHERE 
  CAST(
    "requestapprovalmatrix"."approvalMatrixId" AS VARCHAR2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_invalidMatrixIds)
      )
  ) 
  AND (
    temp_request_table.numberOfApprovalsRequired = -1 
    OR temp_request_table.numberOfApprovalsRequired >= temp_request_table.numberOfApprovers
  );
v_SQL_SAFE_UPDATES := 0;
v_select_statement := (
  'DELETE FROM "customerapprovalmatrix" WHERE "customerapprovalmatrix"."approvalMatrixId" in (' || (v_invalidMatrixIds) || ') AND "customerapprovalmatrix"."customerId" = '''
) || (v__customerId) || ('''');
v_select_statement := (
  'UPDATE "approvalmatrix" SET invalid = ''1'' WHERE "approvalmatrix"."id" in  ('
) || (v_invalidMatrixIds) || (')');
IF (v_invalidRequestIds IS NULL) THEN BEGIN v_SQL_SAFE_UPDATES := 1;
RETURN;
END;
END IF;
v_select_statement := (
  'UPDATE "bbrequest" SET status = ''Rejected'' WHERE "bbrequest"."requestId" in  ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "billpaytransfers" INNER JOIN "bbrequest"ON "billpaytransfers"."requestId" = "bbrequest"."requestId" SET "billpaytransfers"."status" =  ''Rejected'' WHERE "billpaytransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "ownaccounttransfers" INNER JOIN "bbrequest"ON "ownaccounttransfers"."requestId" = "bbrequest"."requestId" SET "ownaccounttransfers"."status" =  ''Rejected'' WHERE "ownaccounttransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "interbankfundtransfers" INNER JOIN "bbrequest"ON "interbankfundtransfers"."requestId" = "bbrequest"."requestId" SET "interbankfundtransfers"."status" =  ''Rejected'' WHERE "interbankfundtransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "intrabanktransfers" INNER JOIN "bbrequest"ON "intrabanktransfers"."requestId" = "bbrequest"."requestId" SET "intrabanktransfers"."status" =  ''Rejected'' WHERE "intrabanktransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "p2ptransfers" INNER JOIN "bbrequest"ON "p2ptransfers"."requestId" = "bbrequest"."requestId" SET "p2ptransfers"."status" =  ''Rejected'' WHERE "p2ptransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "wiretransfers" INNER JOIN "bbrequest"ON "wiretransfers"."requestId" = "bbrequest"."requestId" SET "wiretransfers"."status" =  ''Rejected'' WHERE "wiretransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "internationalfundtransfers" INNER JOIN "bbrequest"ON "internationalfundtransfers"."requestId" = "bbrequest".requestId SET "internationalfundtransfers"."status" = ''Rejected'' WHERE "internationalfundtransfers"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "achtransaction" INNER JOIN "bbrequest"ON "achtransaction".requestId = "bbrequest"."requestId" SET "achtransaction"."status" =  ''Rejected'' WHERE "achtransaction"."requestId" in ('
) || (v_invalidRequestIds) || (')');
v_select_statement := (
  'UPDATE "achfile" INNER JOIN "bbrequest"ON "achfile"."requestId" = "bbrequest"."requestId" SET "achfile"."status" = ''Rejected'' WHERE "achfile"."requestId" in ('
) || (v_invalidRequestIds) || (')');
SELECT 
  "customer"."Organization_Id" INTO v_companyId 
FROM 
  "customer" 
WHERE 
  "customer"."id" = v__customerId;
IF (v_companyId IS NULL) THEN RETURN;
END IF;
v_numOfParams := 0;
IF (
  LENGTHB(v_invalidRequestIds) > 0
) THEN v_numOfParams := LENGTHB(v_invalidRequestIds) - LENGTHB(
  REPLACE(v_invalidRequestIds, ',', ' ')
) + 1;
END IF;
v_select_statement := '';
v_idx := 1;
WHILE (1 = 1) LOOP BEGIN IF (v_idx > v_numOfParams) THEN EXIT;
END IF;
/* SET @requestId = substring(@invalidRequestIds, , @idx) */
v_requestId := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v_invalidRequestIds, ',', v_idx), 
  ',', 
  -1
);
/* SET @requestId = m2ss.UTILS.SUBSTRING_INDEX(m2ss.UTILS.SUBSTRING_INDEX([@invalidRequestIds], N',', [@idx]), N',', -1) */
v_select_statement := (
  '
                           INSERT INTO "bbactedrequest"(
                              "bbactedrequest"."requestId", 
                              "bbactedrequest"."companyId", 
                              "bbactedrequest"."comments", 
                              "bbactedrequest"."status", 
                              "bbactedrequest"."action"
                           ) VALUES ('
) || (v_requestId) || (',') || (v_companyId) || (
  ''' , ''Rejected by system as one of the approver lost his permission'', ''Rejected'', ''Rejected'');'
);
v_idx := v_idx + 1;
END;
END LOOP;
v_SQL_SAFE_UPDATES := 1;
END;
--   <<MAINLABEL$leave>>
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

