--  DDL for Procedure campaign_c360_count_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "campaign_c360_count_proc" (
  "defaultcampaignspecification" OUT SYS_REFCURSOR
) AS 
/*
         *   SSMA warning messages:
         *   M2SS0104: Non aggregated column CHANNEL is aggregated with Min(..) in Select, Orderby and Having clauses.
         *   M2SS0104: Non aggregated column SCREEN is aggregated with Min(..) in Select, Orderby and Having clauses.
         *   M2SS0104: Non aggregated column IMAGE_RESOLUTION is aggregated with Min(..) in Select, Orderby and Having clauses.
         */
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "defaultcampaignspecification" FOR 
SELECT 
  MIN(
    "campaignplaceholder"."channel"
  ) channel, 
  MIN("campaignplaceholder"."screen") screen, 
  MIN(
    "campaignplaceholder"."image_resolution"
  ) image_resolution, 
  COUNT(*) campaign_count 
FROM 
  "defaultcampaignspecification" 
  LEFT JOIN "campaignplaceholder" ON (
    "defaultcampaignspecification"."campaignplaceholder_id" = "campaignplaceholder"."id"
  ) 
GROUP BY 
  "campaignplaceholder"."id" 
ORDER BY 
  "campaignplaceholder"."id";
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure campaign_c360_customergroup_delete_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "campaign_c360_customergroup_delete_proc" (v__groupId IN VARCHAR2) AS v_cursorFinished NUMBER(10, 0) := 0;
v_customerId VARCHAR2(50);
CURSOR customerGroupCursor IS 
SELECT 
  "customergroup"."Customer_id" 
FROM 
  "customergroup" 
WHERE 
  "customergroup"."Group_id" = v__groupId;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN customerGroupCursor;
WHILE (1 = 1) LOOP BEGIN FETCH customerGroupCursor INTO v_customerId;
IF (customerGroupCursor % FOUND) = TRUE THEN v_cursorFinished := 1;
END IF;
IF v_cursorFinished = 1 THEN EXIT;
END IF;
DELETE "customergroup" 
WHERE 
  "customergroup"."Customer_id" = v_customerId 
  AND "customergroup"."Group_id" = v__groupId;
END;
END LOOP;
CLOSE customerGroupCursor;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure campaign_c360_datacontextsandattributes_get_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "campaign_c360_datacontextsandattributes_get_proc" ("records" OUT SYS_REFCURSOR) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "records" FOR 
SELECT 
  model."id" "modelId", 
  model."name" "modelName", 
  model."endpoint_url" "endpoint", 
  attr."id" "attributeid", 
  attr."endpoint_attribute_id" "attributendpoint", 
  attr."name" "attributename", 
  attr."attributetype" "attributetype", 
  attr."range" "range", 
  attr."helptext" "helptext", 
  attr."criterias" "criterias", 
  attr."options" "options" 
FROM 
  "attribute" attr 
  JOIN "modelattribute" ma ON attr."id" = ma."attribute_id" 
  JOIN "model" model ON ma."model_id" = model."id" 
ORDER BY 
  model."name", 
  attr."name" DESC;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
