--  DDL for Procedure campaign_dbp_count_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "campaign_dbp_count_proc" (
  "defaultcampaignspecification" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/

/*
         *   SSMA warning messages:
         *   M2SS0088: Unable to determine if GROUP BY clause contains constant expression or alias, because it contains unresolved identifiers.
         */
OPEN "defaultcampaignspecification" FOR 
SELECT 
  campaignplaceholder_groupby_id.channel, 
  campaignplaceholder_groupby_id.screen, 
  campaignplaceholder_groupby_id.campaign_count 
FROM 
  (
    
    /*
                                   *   SSMA warning messages:
                                   *   M2SS0104: Non aggregated column CHANNEL is aggregated with Min(..) in Select, Orderby and Having clauses.
                                   *   M2SS0104: Non aggregated column SCREEN is aggregated with Min(..) in Select, Orderby and Having clauses.
                                   */
    SELECT 
      MIN(
        "campaignplaceholder"."channel"
      ) channel, 
      MIN("campaignplaceholder"."screen") screen, 
      COUNT(*) campaign_count 
    FROM 
      "defaultcampaignspecification" 
      LEFT JOIN "campaignplaceholder" ON (
        "defaultcampaignspecification"."campaignplaceholder_id" = "campaignplaceholder"."id"
      ) 
    GROUP BY 
      "campaignplaceholder"."id" 
    ORDER BY 
      "campaignplaceholder"."id" FETCH FIRST 9223372036854775807 ROWS ONLY
  ) campaignplaceholder_groupby_id 
GROUP BY 
  campaignplaceholder_groupby_id.channel, 
  campaignplaceholder_groupby_id.screen, 
  campaignplaceholder_groupby_id.campaign_count 
ORDER BY 
  campaignplaceholder_groupby_id.channel, 
  campaignplaceholder_groupby_id.screen, 
  campaignplaceholder_groupby_id.campaign_count;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

