--  DDL for Procedure campaign_dbp_specification_get_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "campaign_dbp_specification_get_proc" (
  v__currentTimestamp IN VARCHAR2, v__scale IN VARCHAR2, 
  v__username IN VARCHAR2, v__channel IN VARCHAR2, 
  v__screen IN VARCHAR2, "campaignspecification" OUT SYS_REFCURSOR
) AS v_placeholderId VARCHAR2(4000);
v_customerId VARCHAR2(4000);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  "campaignplaceholder"."id" INTO v_placeholderId 
FROM 
  "campaignplaceholder" 
WHERE 
  "campaignplaceholder"."channel" = v__channel 
  AND "campaignplaceholder"."screen" = v__screen 
  AND "campaignplaceholder"."image_scale" = v__scale;
SELECT 
  "customer"."id" INTO v_customerId 
FROM 
  "customer" 
WHERE 
  "customer"."UserName" = v__username;
OPEN "campaignspecification" FOR 
SELECT 
  "campaignspecification"."campaign_id", 
  "campaignspecification"."campaignplaceholder_id", 
  "campaignspecification"."image_url", 
  "campaignspecification"."destination_url", 
  1 image_index, 
  "campaign"."priority" 
FROM 
  "campaignspecification" 
  LEFT JOIN "campaign" ON (
    "campaignspecification"."campaign_id" = "campaign"."id"
  ) 
WHERE 
  "campaignspecification"."campaignplaceholder_id" = v_placeholderId 
  AND "campaign"."status_id" = 'SID_SCHEDULED_ACTIVE_COMPLETED' 
  AND "campaignspecification"."campaign_id" IN (
    SELECT 
      "campaigngroup"."campaign_id" 
    FROM 
      "campaigngroup" 
    WHERE 
      "campaigngroup"."group_id" IN (
        SELECT 
          "customergroup"."Group_id" 
        FROM 
          "customergroup" 
        WHERE 
          "customergroup"."Customer_id" = v_customerId
      )
  ) 
  AND "campaign"."start_datetime" <= TO_DATE(
    v__currentTimestamp, 'YYYY-MON-DD HH24:MI:SS'
  ) 
  AND "campaign"."end_datetime" >= TO_DATE(
    v__currentTimestamp, 'YYYY-MON-DD HH24:MI:SS'
  ) 
  AND "campaign"."id" NOT IN (
    SELECT 
      "custcompletedcampaign"."campaign_id" 
    FROM 
      "custcompletedcampaign" 
    WHERE 
      "custcompletedcampaign"."customer_id" = v_customerId
  ) 
UNION ALL 
SELECT 
  cast(
    'DEFAULT_CAMPAIGN' as nvarchar2(255)
  ) campaign_id, 
  "defaultcampaignspecification"."campaignplaceholder_id", 
  "defaultcampaignspecification"."image_url", 
  "defaultcampaignspecification"."destination_url", 
  "defaultcampaignspecification"."image_index", 
  1000 priority 
FROM 
  "defaultcampaignspecification" 
WHERE 
  "defaultcampaignspecification"."campaignplaceholder_id" = v_placeholderId 
ORDER BY 
  5, 
  4;
--DBMS_SQL.RETURN_RESULT("campaignspecification");
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

