--  DDL for Procedure customer_action_group_action_limits_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customer_action_group_action_limits_proc" (
  v__customerID IN VARCHAR2, "customeractionlimits" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "customeractionlimits" FOR 
SELECT 
  "customeractionlimits"."Customer_id" Customer_id, 
  "customeractionlimits"."LimitType_id" Customer_LimitType_id, 
  ("customeractionlimits"."value") Customer_Limit_Value, 
  NULL Group_LimitType_id, 
  NULL Group_Limit_Value, 
  "service"."id" Action_id, 
  "service"."Name" Action_Name, 
  "service"."code" Action_Code, 
  "service"."Description" Action_Description, 
  "service"."Status_id" Action_Status_id, 
  "app"."id" App_id, 
  "app"."Name" APP_NAME, 
  "appactionlimit"."limitType_Id" LimitType_id, 
  "appactionlimit"."Value" Limit_Value, 
  "feature"."id" Feature_id, 
  "feature"."name" Feature_Name, 
  --             "feature"."code" Feature_Code  ,
  "feature"."description" Feature_Description, 
  "feature"."Status_id" Feature_Status_id 
FROM 
  "customeractionlimits" 
  JOIN "service" ON (
    (
      "service"."id" = "customeractionlimits"."Action_id"
    )
  ) 
  LEFT JOIN "appaction" ON (
    (
      "service"."id" = "appaction"."Action_id"
    )
  ) 
  JOIN "app" ON (
    (
      "appaction"."App_id" = "app"."id"
    )
  ) 
  JOIN "service" ON (
    (
      "service"."id" = "customeractionlimits"."Action_id"
    )
  ) 
  LEFT JOIN "feature" ON (
    (
      "feature"."id" = "service"."Feature_id"
    )
  ) 
  LEFT JOIN "appactionlimit" ON (
    (
      "appaction"."id" = "appactionlimit"."appaction_Id"
    )
  ) 
WHERE 
  "customeractionlimits"."Customer_id" = v__customerID 
UNION 
SELECT 
  "customergroup"."Customer_id" Customer_id, 
  NULL Customer_LimitType_id, 
  NULL Customer_Limit_Value, 
  "groupactionlimit"."LimitType_id" Group_LimitType_id, 
  CAST(
    "groupactionlimit"."value" AS VARCHAR2(50)
  ) Group_Limit_Value, 
  "service"."id" Action_id, 
  "service"."Name" Action_Name, 
  "service"."code" Action_Code, 
  "service"."Description" Action_Description, 
  "service"."Status_id" Action_Status_id, 
  "app"."id" App_id, 
  "app"."Name" APP_NAME, 
  "appactionlimit"."limitType_Id" LimitType_id, 
  ("appactionlimit"."Value") Limit_Value, 
  "feature"."id" Feature_id, 
  "feature"."name" Feature_Name, 
  --             "feature"."CODE" Feature_Code  ,
  "feature"."description" Feature_Description, 
  "feature"."Status_id" Feature_Status_id 
FROM 
  "customergroup" 
  LEFT JOIN "groupactionlimit" ON (
    (
      "groupactionlimit"."Group_id" = "customergroup"."Group_id"
    )
  ) 
  JOIN "service" ON (
    (
      "service"."id" = "groupactionlimit"."Action_id"
    )
  ) 
  LEFT JOIN "appaction" ON (
    (
      "service"."id" = "appaction"."Action_id"
    )
  ) 
  JOIN "app" ON (
    (
      "appaction"."App_id" = "app"."id"
    )
  ) 
  LEFT JOIN "feature" ON (
    (
      "feature"."id" = "service"."Feature_id"
    )
  ) 
  LEFT JOIN "appactionlimit" ON (
    (
      "appaction"."id" = "appactionlimit"."appaction_Id"
    )
  ) 
WHERE 
  "customergroup"."Customer_id" = v__customerID 
  AND "service"."Status_id" <> 'SID_INACTIVE' 
  AND "feature"."Status_id" <> 'SID_INACTIVE';
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
