  v_business_customer_enabled_actions
) || (
  ''' as nvarchar2(2000))) <> 0 then ''true'' else ''false'' end) else ''true'' end AS "isAllowed","featureaction"."id" AS "Action_id", case when "featureaction"."isAccountLevel" = ''1'' then ''true'' else ''false'' end AS "isAccountLevel","feature"."Status_id" AS "Feature_Status_id","feature"."id" AS "Feature_id","membergroup"."Type_id" AS "RoleType_id","groupactionlimit"."LimitType_id" AS "LimitType_id","groupactionlimit"."value" AS "value" FROM ("customergroup" LEFT JOIN "membergroup" ON ("membergroup"."id" = "customergroup"."Group_id") LEFT JOIN "groupactionlimit" ON ("groupactionlimit"."Group_id" = "customergroup"."Group_id") LEFT JOIN "featureaction" ON ("featureaction"."id" = "groupactionlimit"."Action_id") LEFT JOIN "feature" ON ("feature"."id" = "featureaction"."Feature_id")) where "customergroup"."Customer_id" =''' || ("_customerId") || ''' and "feature"."Status_id" = ''SID_FEATURE_ACTIVE'' and "featureaction"."status" = ''SID_ACTION_ACTIVE'' and FIND_IN_SET("groupactionlimit"."Action_id", CAST('''
) || (v_customer_disabled_actions) || (
  ''' as nvarchar2(2000))) = 0 and '
) || (v_active_feature_condition);
