--  DDL for Procedure customer_group_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customer_group_proc" (
  v__customerIds IN VARCHAR2, v__groupId IN VARCHAR2, 
  v__numberOfRows IN NUMBER, v__userId IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v_INSERTED_RECORDS_COUNT NUMBER(19, 0) := 0;
v_INDEXVALUE NUMBER(19, 0) := 1;
v_CustomerId VARCHAR2(4000) := NULL;
v_buffer VARCHAR2(4000) := NULL;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_buffer := '';
/*
         *   SSMA informational messages:
         *   M2SS0003: The following SQL clause was ignored during conversion:
         *   iterator : .
         */
WHILE (1 = 1) LOOP DECLARE v_temp NUMBER(1, 0) := 0;
BEGIN IF LENGTHB(
  LTRIM(
    RTRIM(v__customerIds)
  )
) = 0 
OR v__customerIds IS NULL 
OR v_INDEXVALUE > v__numberOfRows THEN EXIT;
END IF;
v_CustomerId := func_split_str(
  v__customerIds, ',', v_INDEXVALUE
);
/*
                     *   SSMA warning messages:
                     *   M2SS0097: IGNORE was not converted
                     */
BEGIN 
SELECT 
  1 INTO v_temp 
FROM 
  DUAL 
WHERE 
  CASE WHEN EXISTS (
    SELECT 
      "customergroup"."Customer_id", 
      "customergroup"."Group_id", 
      "customergroup"."createdby", 
      "customergroup"."modifiedby", 
      "customergroup"."createdts", 
      "customergroup"."lastmodifiedts", 
      "customergroup"."synctimestamp", 
      "customergroup"."softdeleteflag" 
    FROM 
      "customergroup" 
    WHERE 
      "customergroup"."Customer_id" = v_CustomerId 
      AND "customergroup"."Group_id" = v__groupId
  ) THEN 1 ELSE 0 END <> 0;
EXCEPTION WHEN OTHERS THEN NULL;
END;
IF v_temp = 1 THEN v_INDEXVALUE := v_INDEXVALUE + 1;
ELSE BEGIN INSERT INTO "customergroup" (
  "customergroup"."Customer_id", "customergroup"."Group_id", 
  "customergroup"."createdby"
) 
VALUES 
  (
    v_CustomerId, v__groupId, v__userId
  );
IF (SQL % ROWCOUNT = 0) THEN v_buffer := v_buffer || ',' || v_CustomerId;
END IF;
v_INSERTED_RECORDS_COUNT := v_INSERTED_RECORDS_COUNT + SQL % ROWCOUNT;
v_INDEXVALUE := v_INDEXVALUE + 1;
END;
END IF;
END;
END LOOP;
v_buffer := SUBSTR(
  v_buffer, 
  - LENGTHB(v_buffer) -1, 
  LENGTHB(v_buffer) -1
);
OPEN v_cursor FOR 
SELECT 
  v_buffer N_FAILED_RECORDS_ 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

