--  DDL for Procedure customer_request_archive_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customer_request_archive_proc" (v_cursor OUT SYS_REFCURSOR) AS v_customer_request_cursor_done NUMBER(1, 0) := 0;
v_customer_requestmessage_cursor_done NUMBER(1, 0) := 0;
v_customer_requestmessageattachment_cursor_done NUMBER(1, 0) := 0;
v_curr_request_id VARCHAR2(50) := '';
v_curr_requestmessage_id VARCHAR2(50) := '';
v_curr_media_id VARCHAR2(50) := '';
v_curr_messageattachment_id VARCHAR2(50) := '0';
v_media_count NUMBER(10, 0) := 0;
CURSOR customer_request_cursor IS 
SELECT 
  "id" 
FROM 
  "customerrequest" 
WHERE 
  "Status_id" = 0 
  AND (
    to_date(SYSDATE, 'yyyy-MM-dd')- to_date("lastmodifiedts", 'yyyy-MM-dd')
  ) >= 180;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
--   OPEN customer_request_cursor;
WHILE(1 = 1) LOOP BEGIN FETCH customer_request_cursor INTO v_curr_request_id;
IF(customer_request_cursor % FOUND) <> FALSE THEN v_customer_request_cursor_done := 1;
END IF;
v_customer_requestmessage_cursor_done := '1';
v_customer_requestmessageattachment_cursor_done := '1';
IF NOT v_customer_request_cursor_done <> 0 THEN BEGIN INSERT INTO "archivedcustomerrequest" (
  "id", "RequestCategory_id", "Customer_id", 
  "Priority", "Status_id", "RequestSubject", 
  "AssignedTo", "Accountid", "lastupdatedbycustomer", 
  "createdby", "modifiedby", "createdts", 
  "lastmodifiedts", "synctimestamp", 
  "softdeleteflag", "isTypeBusiness"
) (
  SELECT 
    "id", 
    "RequestCategory_id", 
    "Customer_id", 
    "Priority", 
    "Status_id", 
    "RequestSubject", 
    "AssignedTo", 
    "Accountid", 
    "lastupdatedbycustomer", 
    "createdby", 
    "modifiedby", 
    "createdts", 
    "lastmodifiedts", 
    "synctimestamp", 
    "softdeleteflag", 
    "isTypeBusiness" 
  FROM 
    "customerrequest" 
  WHERE 
    "id" = v_curr_request_id
);
UPDATE 
  "archivedcustomerrequest" 
SET 
  "Status_id" = 'SID_ARCHIVED' 
WHERE 
  "id" = v_curr_request_id;
OPEN v_cursor FOR 
SELECT 
  v_curr_request_id REQUESTMESSAGEBLOCK 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
DECLARE CURSOR customer_requestmessage_cursor IS 
SELECT 
  "id" 
FROM 
  "requestmessage" 
WHERE 
  "CustomerRequest_id" = v_curr_request_id;
BEGIN OPEN customer_requestmessage_cursor;
WHILE (1 = 1) LOOP BEGIN FETCH customer_requestmessage_cursor INTO v_curr_requestmessage_id;
IF (
  customer_requestmessage_cursor % FOUND
) <> FALSE THEN v_customer_request_cursor_done := '1';
END IF;
v_customer_requestmessage_cursor_done := '1';
v_customer_requestmessageattachment_cursor_done := '1';
IF NOT v_customer_requestmessage_cursor_done <> 0 THEN BEGIN INSERT INTO "archivedrequestmessage" (
  "id", "CustomerRequest_id", "MessageDescription", 
  "RepliedBy", "RepliedBy_id", "RepliedBy_Name", 
  "ReplySequence", "IsRead", "createdby", 
  "modifiedby", "createdts", "lastmodifiedts", 
  "synctimestamp", "softdeleteflag"
) 
SELECT 
  "id", 
  "CustomerRequest_id", 
  "MessageDescription", 
  "RepliedBy", 
  "RepliedBy_id", 
  "RepliedBy_Name", 
  "ReplySequence", 
  "IsRead", 
  "createdby", 
  "modifiedby", 
  "createdts", 
  "lastmodifiedts", 
  "synctimestamp", 
  "softdeleteflag" 
FROM 
  "requestmessage" 
WHERE 
  "id" = v_curr_requestmessage_id;
<< MESSAGEATTACHMENTBLOCK >> DECLARE CURSOR customer_messageattachment_cursor IS 
SELECT 
  "id" 
FROM 
  "messageattachment" 
WHERE 
  "RequestMessage_id" = v_curr_requestmessage_id;
BEGIN OPEN customer_messageattachment_cursor;
<< customer_messageattachment_loop >> WHILE (1 = 1) LOOP BEGIN FETCH customer_messageattachment_cursor INTO v_curr_messageattachment_id;
IF (
  customer_messageattachment_cursor % FOUND
) <> FALSE THEN v_customer_request_cursor_done := '1';
END IF;
v_customer_requestmessage_cursor_done := '1';
v_customer_requestmessageattachment_cursor_done := '1';
IF NOT v_customer_requestmessageattachment_cursor_done <> 0 THEN BEGIN 
SELECT 
  "Media_id" INTO v_curr_media_id 
FROM 
  "messageattachment" 
WHERE 
  "id" = v_curr_messageattachment_id;
SELECT 
  COUNT("id") INTO v_media_count 
FROM 
  "archivedmedia" 
WHERE 
  "id" = v_curr_media_id;
IF v_media_count = 0 THEN INSERT INTO "archivedmedia" (
  "id", "Name", "Type", "Description", 
  "Url", "Content", "Size", "createdby", 
  "modifiedby", "createdts", "lastmodifiedts", 
  "synctimestamp", "softdeleteflag"
) (
  SELECT 
    "id", 
    "Name", 
    "Type", 
    "Description", 
    "Url", 
    "Content", 
    "Size", 
    "createdby", 
    "modifiedby", 
    "createdts", 
    "lastmodifiedts", 
    "synctimestamp", 
    "softdeleteflag" 
  FROM 
    "media" 
  WHERE 
    "id" = v_curr_media_id
);
END IF;
INSERT INTO "archivedmessageattachment" (
  "id", "RequestMessage_id", "AttachmentType_id", 
  "Media_id", "createdby", "modifiedby", 
  "createdts", "lastmodifiedts", "synctimestamp", 
  "softdeleteflag"
) (
  SELECT 
    "id", 
    "RequestMessage_id", 
    "AttachmentType_id", 
    "Media_id", 
    "createdby", 
    "modifiedby", 
    "createdts", 
    "lastmodifiedts", 
    "synctimestamp", 
    "softdeleteflag" 
  FROM 
    "messageattachment" 
  WHERE 
    "id" = v_curr_messageattachment_id
);
DELETE "messageattachment" 
WHERE 
  "id" = v_curr_messageattachment_id;
SELECT 
  COUNT("id") INTO v_media_count 
FROM 
  "messageattachment" 
WHERE 
  "Media_id" = v_curr_media_id;
IF v_media_count = 0 THEN DELETE "media" 
WHERE 
  "id" = v_curr_media_id;
END IF;
END;
END IF;
IF v_customer_requestmessageattachment_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_customer_request_cursor_done := '0';
v_customer_requestmessage_cursor_done := '0';
v_customer_requestmessageattachment_cursor_done := '0';
CLOSE customer_messageattachment_cursor;
END;
DELETE "requestmessage" 
WHERE 
  "id" = v_curr_requestmessage_id;
END;
END IF;
IF v_customer_requestmessage_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_customer_request_cursor_done := '0';
v_customer_requestmessage_cursor_done := '0';
v_customer_requestmessageattachment_cursor_done := '0';
CLOSE customer_requestmessage_cursor;
END;
DELETE "customerrequest" 
WHERE 
  "id" = v_curr_request_id;
END;
END IF;
IF v_customer_request_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_customer_request_cursor_done := '0';
v_customer_requestmessage_cursor_done := '0';
v_customer_requestmessageattachment_cursor_done := '0';
CLOSE customer_request_cursor;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
