) || '''' || ("_requestCategory") || '''';
END IF;
IF "_requestAssignedTo" <> '' THEN v_whereclause := (v_whereclause) || ('  AND cr."AssignedTo" = ') || '''' || ("_requestAssignedTo") || '''';
END IF;
IF "_messageRepliedBy" <> '' THEN BEGIN v_stmt := (v_stmt) || (
  'JOIN "requestmessage" ON (cr."id" = "requestmessage"."CustomerRequest_id") '
);
v_whereclause := (v_whereclause) || (
  '  AND "requestmessage"."RepliedBy_id" = '
) || '''' || ("_messageRepliedBy") || '''';
END;
END IF;
IF v__searchKey <> '' THEN BEGIN v_joinCustomer := 1;
v__searchKey := '%' || v__searchKey || '%';
v_whereclause := (v_whereclause) || (
  '  AND ' || '  (' || '    cr."Customer_id" LIKE '
) || '''' || (v__searchKey) || '''' || (' OR cr."id" LIKE ') || '''' || (v__searchKey) || '''' || (
  ' OR "customer"."UserName" LIKE '
) || '''' || (v__searchKey) || '''' || (')');
END;
END IF;
IF "_queryType" <> 'count' THEN BEGIN IF "_sortCriteria" = 'customer_Fullname' THEN v_joinCustomer := 1;
END IF;
v_sortColumn := 'cr."lastmodifiedts"';
IF (
  "_sortCriteria" = 'customerrequest_Customer_id'
) THEN v_sortColumn := 'cr."Customer_id"';
ELSE IF (
  "_sortCriteria" = 'customerrequest_AssignedTo'
) THEN v_sortColumn := 'cr."AssignedTo"';
ELSE IF (
  "_sortCriteria" = 'customerrequest_createdts'
) THEN v_sortColumn := 'cr."createdts"';
ELSE IF (
  "_sortCriteria" = 'customerrequest_RequestCategory_id'
) THEN v_sortColumn := 'cr."RequestCategory_id"';
ELSE IF (
  "_sortCriteria" = 'customer_Fullname'
) THEN v_sortColumn := '("customer"."FirstName"' || '"customer"."LastName")';
ELSE IF (
  "_sortCriteria" = 'customerrequest_Status_id'
) THEN v_sortColumn := 'cr."Status_id"';
ELSE BEGIN IF (
  "_sortCriteria" = 'customerrequest_AssignedTo_Name'
) THEN v_sortColumn := '("systemuser"."FirstName"' || '"systemuser"."LastName")';
END IF;
END;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
v_whereclause := (v_whereclause) || (' ORDER BY ' || '  ') || (
  CASE WHEN (
    NVL(v_sortColumn, '') = ' '
  ) THEN 'cr.lastmodifiedts' ELSE v_sortColumn END
) || (' ') || (
  CASE WHEN (
    (
      NVL(v_sortColumn, '') = ' '
    ) 
    OR "_sortOrder" = ''
  ) THEN 'DESC' ELSE "_sortOrder" END
);
v_whereclause := (v_whereclause) || (' offset ') || (
  CASE WHEN ("_offset" = '') THEN '0' ELSE "_offset" END
) || (' rows fetch next ') || (
  CASE WHEN ("_recordsPerPage" = '') THEN '10' ELSE "_recordsPerPage" END
) || (' rows only');
END;
END IF;
IF v_joinCustomer = 1 THEN v_stmt := (v_stmt) || (
  'JOIN "customer" ON (cr."Customer_id" = "customer"."id") '
);
END IF;
IF "_sortCriteria" = 'customerrequest_AssignedTo_Name' THEN v_stmt := (v_stmt) || (
  'LEFT JOIN "systemuser" ON (cr."AssignedTo" = "systemuser"."id") '
);
END IF;
v_stmt := (v_stmt) || (v_whereclause);
EXECUTE IMMEDIATE v_stmt;
OPEN "records" for v_stmt;
--EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE,SQLERRM);
END;
/

