  'UPDATE "customerrequest" SET "customerrequest"."AssignedTo" = '
) || (
  (
    '''' ||(
      (v__csrID)|| ''''
    )
  )
) || (
  ' where "customerrequest"."id" in ('
) || (
  func_escape_input_for_in_operator(v__requestIds)
) || (')');
EXECUTE IMMEDIATE v_updateclause;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
