--  DDL for Procedure customer_unread_message_count_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customer_unread_message_count_proc" (
  "_customerId" IN VARCHAR2, "records" OUT SYS_REFCURSOR, 
  "records1" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "records" FOR 
SELECT 
  COUNT("requestmessage"."id") "messageCount" 
FROM 
  (
    "customerrequest" 
    JOIN "requestmessage" ON (
      (
        "requestmessage"."CustomerRequest_id" = "customerrequest"."id"
      )
    )
  ) 
WHERE 
  (
    "requestmessage"."IsRead" = 'FALSE' 
    AND "customerrequest"."softdeleteflag" = 0 
    AND "customerrequest"."Customer_id" = "_customerId" 
    AND "customerrequest"."Status_id" <> 'SID_DELETED'
  );
--DBMS_SQL.RETURN_RESULT("customerrequest");
OPEN "records1" FOR 
SELECT 
  COUNT("requestmessage"."id") "priorityMessageCount" 
FROM 
  (
    "customerrequest" 
    JOIN "requestmessage" ON (
      (
        "requestmessage"."CustomerRequest_id" = "customerrequest"."id"
      )
    )
  ) 
WHERE 
  (
    "requestmessage"."IsRead" = 'FALSE' 
    AND "customerrequest"."softdeleteflag" = 0 
    AND "customerrequest"."Customer_id" = "_customerId" 
    AND "customerrequest"."Status_id" <> 'SID_DELETED' 
    AND "requestmessage"."isPriorityMessage" = '1'
  );
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure customeraccounts_sweepinfoupdate_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customeraccounts_sweepinfoupdate_proc" (
  v__customerId IN VARCHAR2, v__primaryAccount IN VARCHAR2, 
  v__secondaryAccount IN VARCHAR2, 
  v__sweepFlag IN VARCHAR2, v__previousAccount IN VARCHAR2
) AS v_sweepFlag NUMBER(1, 0);
BEGIN v_sweepFlag := 1;
IF (v__sweepFlag = 'false') THEN v_sweepFlag := 0;
END IF;
IF (
  v__primaryAccount IS NOT NULL 
  AND v__primaryAccount != ''
) THEN 
UPDATE 
  "customeraccounts" 
SET 
  "isSweepCreated" = v_sweepFlag 
WHERE 
  "id" IN (
    SELECT 
      "customeraccounts"."id" 
    FROM 
      "customeraccounts" 
    WHERE 
      "customeraccounts"."Customer_id" = v__customerId 
      AND "customeraccounts"."Account_id" = v__primaryAccount
  );
END IF;
IF (
  v__secondaryAccount IS NOT NULL 
  AND v__secondaryAccount != ''
) THEN 
UPDATE 
  "customeraccounts" 
SET 
  "isSweepCreated" = v_sweepFlag 
WHERE 
  "id" IN (
    SELECT 
      "customeraccounts"."id" 
    FROM 
      "customeraccounts" 
    WHERE 
      "customeraccounts"."Customer_id" = v__customerId 
      AND "customeraccounts"."Account_id" = v__secondaryAccount
  );
END IF;
IF (
  v__previousAccount IS NOT NULL 
  AND v__previousAccount != ''
) THEN 
UPDATE 
  "customeraccounts" 
SET 
  "isSweepCreated" = 0 
WHERE 
  "id" IN (
    SELECT 
      "customeraccounts"."id" 
    FROM 
      "customeraccounts" 
    WHERE 
      "customeraccounts"."Customer_id" = v__customerId 
      AND "customeraccounts"."Account_id" = v__previousAccount
  );
END IF;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure customeractionlimits_create_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "customeractionlimits_create_proc" (
  v__customerActionsCSV IN VARCHAR2, 
  v__accountsCSV IN VARCHAR2, v__customerId IN VARCHAR2, 
  v__businessTypeId IN VARCHAR2, v__groupId IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v_finished NUMBER(10, 0) := 0;
v_id NUMBER(10, 0);
v_featureActionId VARCHAR2(4000);
v_actionslist VARCHAR2(4000);
v_limitId VARCHAR2(4000);
v_entryStatus NUMBER(10, 0) := 0;
v_accountId VARCHAR2(4000);
v_actualLimitId VARCHAR2(4000);
v_groupId VARCHAR2(4000);
v_validActionsList VARCHAR2(4000);
v_limitvalue VARCHAR2(4000);
CURSOR accounts IS 
SELECT 
  "Account_id" 
FROM 
  "accounts" 
WHERE 
  "Account_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__accountsCSV)
      )
  );
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
IF (
  CASE WHEN v__groupId IS NULL THEN 1 ELSE 0 END <> 0 
  OR v__groupId = ''
) THEN 
SELECT 
  "groupbusinesstype"."Group_id" INTO v_groupId 
FROM 
  "groupbusinesstype" 
WHERE 
  "groupbusinesstype"."BusinessType_id" = v__businessTypeId 
  AND "groupbusinesstype"."isDefaultGroup" = 1;
ELSE v_groupId := v__groupId;
END IF;
SELECT 
  "membergroup"."id" INTO v_groupId 
FROM 
  "membergroup" 
WHERE 
  "membergroup"."id" = v_groupId 
  AND "membergroup"."Type_id" = 'TYPE_ID_BUSINESS' 
  AND "membergroup"."Status_id" = 'SID_ACTIVE';
SELECT 
  NULL INTO v_validActionsList 
FROM 
  "groupactionlimit" 
WHERE 
  "groupactionlimit"."Group_id" = v_groupId 
  AND (
    "groupactionlimit"."Action_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT(v__customerActionsCSV)
        )
    )
  );
<< loop_3 >> WHILE (1 = 1) LOOP DECLARE CURSOR actions IS 
SELECT 
  "featureaction"."id" 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_validActionsList)
      )
  );
BEGIN FETCH accounts INTO v_accountId;
IF (accounts % FOUND) <> FALSE THEN v_finished := 1;
END IF;
IF v_finished = 1 THEN EXIT;
ELSE BEGIN << loop_2 >> WHILE (1 = 1) LOOP DECLARE CURSOR limits IS 
SELECT 
  "actionlimit"."LimitType_id" 
FROM 
  "actionlimit" 
WHERE 
  "actionlimit"."Action_id" = v_featureActionId;
BEGIN v_entryStatus := 0;
IF (accounts % FOUND) <> TRUE THEN v_finished := 1;
END IF;
IF v_finished = 1 THEN EXIT;
ELSE BEGIN OPEN limits;
<< loop_1 >> WHILE (1 = 1) LOOP BEGIN FETCH limits INTO v_limitId;
IF (limits % FOUND) <> TRUE THEN v_finished := 1;
END IF;
IF v_finished = 1 THEN EXIT;
ELSE BEGIN 
SELECT 
  "actionlimit"."value" INTO v_limitvalue 
FROM 
  "actionlimit" 
WHERE 
  "actionlimit"."Action_id" = v_featureActionId 
  AND "actionlimit"."LimitType_id" = v_limitId;
IF (
  v_limitId = 'MAX_TRANSACTION_LIMIT'
) THEN v_actualLimitId := 'AUTO_DENIED_TRANSACTION_LIMIT';
ELSE IF (
  v_limitId = 'MIN_TRANSACTION_LIMIT'
) THEN v_actualLimitId := 'PRE_APPROVED_TRANSACTION_LIMIT';
ELSE IF (v_limitId = 'DAILY_LIMIT') THEN BEGIN v_actualLimitId := 'PRE_APPROVED_DAILY_LIMIT';
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeractionlimits" (
  "customeractionlimits"."id", "customeractionlimits"."RoleType_id", 
  "customeractionlimits"."Customer_id", 
  "customeractionlimits"."Action_id", 
  "customeractionlimits"."Account_id", 
  "customeractionlimits"."isAllowed", 
  "customeractionlimits"."LimitType_id", 
  "customeractionlimits"."value"
) 
VALUES 
  (
    v_id, 'TYPE_ID_BUSINESS', v__customerId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, 0.00
  );
v_actualLimitId := 'AUTO_DENIED_DAILY_LIMIT';
END;
ELSE BEGIN IF (v_limitId = 'WEEKLY_LIMIT') THEN BEGIN v_actualLimitId := 'PRE_APPROVED_WEEKLY_LIMIT';
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeractionlimits" (
  "customeractionlimits"."id", "customeractionlimits"."RoleType_id", 
  "customeractionlimits"."Customer_id", 
  "customeractionlimits"."Action_id", 
  "customeractionlimits"."Account_id", 
  "customeractionlimits"."isAllowed", 
  "customeractionlimits"."LimitType_id", 
  "customeractionlimits"."value"
) 
VALUES 
  (
    v_id, 'TYPE_ID_BUSINESS', v__customerId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, 0.00
  );
v_actualLimitId := 'AUTO_DENIED_WEEKLY_LIMIT';
END;
END IF;
END;
END IF;
END IF;
END IF;
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeractionlimits" (
  "customeractionlimits"."id", "customeractionlimits"."RoleType_id", 
  "customeractionlimits"."Customer_id", 
  "customeractionlimits"."Action_id", 
  "customeractionlimits"."Account_id", 
  "customeractionlimits"."isAllowed", 
  "customeractionlimits"."LimitType_id", 
  "customeractionlimits"."value"
) 
VALUES 
  (
    v_id, 'TYPE_ID_BUSINESS', v__customerId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, v_limitvalue
  );
v_entryStatus := 1;
GOTO loop_1;
END;
END IF;
END;
END LOOP;
CLOSE limits;
v_finished := 0;
IF v_entryStatus = 0 THEN BEGIN 
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeractionlimits" (
  "customeractionlimits"."id", "customeractionlimits"."RoleType_id", 
  "customeractionlimits"."Customer_id", 
  "customeractionlimits"."Action_id", 
  "customeractionlimits"."Account_id", 
  "customeractionlimits"."isAllowed"
) 
VALUES 
  (
    v_id, 'TYPE_ID_BUSINESS', v__customerId, 
    v_featureActionId, v_accountId, 
    1
  );
END;
END IF;
v_actionslist := v_featureActionId || ',' || v_actionslist;
GOTO loop_2;
END;
END IF;
END;
END LOOP;
CLOSE actions;
GOTO loop_3;
END;
END IF;
END;
END LOOP;
CLOSE accounts;
SELECT 
  SUBSTR(
    v_actionslist, 
    1, 
    (
      LENGTH(v_actionslist) -1
    )
  ) INTO v_actionslist 
FROM 
  DUAL;
OPEN v_cursor FOR 
SELECT 
  v_actionslist 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure customeralertchannel_sync


CREATE OR REPLACE NONEDITIONABLE PROCEDURE "customeralertchannel_sync" 
(
  iv_operationType IN VARCHAR2,
  v_changedLevel IN VARCHAR2,
  v_channelsStr IN VARCHAR2,
  v_filterValue IN VARCHAR2
)
AS
   v_operationType VARCHAR2(20) := iv_operationType;
   v_preference VARCHAR2(4000);
   v_channels_list CLOB;

BEGIN

--   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
   SELECT "alertPreferenceView" 

     INTO v_preference
     FROM "customerviewalertconfiguration" 
    WHERE  1 = 1;
   IF v_operationType IS NULL THEN

   BEGIN
      v_operationType := ' ' ;

   END;
   ELSE
      IF v_operationType = 'edit'
        AND v_changedLevel IS NOT NULL THEN

      BEGIN
         SELECT String_agg(CAST("id" AS VARCHAR2(255)), ',') 

           INTO v_channels_list
           FROM "channel" 
          WHERE  "id" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_channelsStr)));
         IF v_channels_list IS NULL THEN

         BEGIN
            v_channels_list := ' ' ;

         END;
         END IF;

      END;
      END IF;
   END IF;
   IF ( v_preference = v_changedLevel
     AND v_changedLevel LIKE 'CATEGORY' ) THEN

   BEGIN
      DELETE "customeralertchannel"

       WHERE  "alertCategoryId" = v_filterValue
                AND "channelId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_channels_list)));

   END;
   ELSE
      IF ( v_preference = v_changedLevel
        AND v_changedLevel LIKE 'GROUP' ) THEN

      BEGIN
         DELETE "customeralertchannel"

          WHERE  "alertTypeId" = v_filterValue
                   AND "channelId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_channels_list)));

      END;
      ELSE
         IF ( v_preference = v_changedLevel
           AND v_changedLevel LIKE 'ALERT' ) THEN

         BEGIN
            DELETE "customeralertchannel"

             WHERE  "alertSubTypeId" = v_filterValue
                      AND "channelId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_channels_list)));

         END;
         ELSE
            IF v_operationType = 'reassign' THEN

            BEGIN
               IF ( v_preference != 'CATEGORY' ) THEN

               BEGIN
                  DELETE "customeralertchannel"

                   WHERE  "alertTypeId" = v_filterValue;

               END;
               END IF;

            END;
            END IF;
         END IF;
      END IF;
   END IF;

EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE,SQLERRM);
END;
/

--  DDL for Procedure customeralertFrequency_sync


CREATE OR REPLACE NONEDITIONABLE PROCEDURE "customeralertFrequency_sync" 
(
  "operationType" IN VARCHAR2,
