   END;
   ELSE
      IF ( iv_operationType LIKE 'edit'
        AND v_preference = 'ALERT' ) THEN
       
      BEGIN
         DELETE "customeralertfrequency"

          WHERE  "alertSubTypeId" = "filterValue";
      
      END;
      ELSE
         IF ( iv_operationType LIKE 'reassign' ) THEN
          
         BEGIN
            IF ( v_preference != 'CATEGORY' ) THEN
             
            BEGIN
               DELETE "customeralertfrequency"

                WHERE  "alertTypeId" = "filterValue";
            
            END;
            END IF;
         
         END;
         END IF;
      END IF;
   END IF;


