--  DDL for Procedure erasure_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "erasure_proc" (v__input IN VARCHAR2) AS v_customerId VARCHAR2(4000) := ' ';
v_personalData VARCHAR2(4000) := ' ';
v_personalDataIndex NUMBER(10, 0) := 0;
v_personalDataSize NUMBER(10, 0);
v_statusQuery VARCHAR2(4000) := ' ';
BEGIN v_customerId := JSON_VALUE(v__input, '$.partyId');
v_personalData := JSON_QUERY(v__input, '$.personalData');
SELECT 
  COUNT(*) INTO v_personalDataSize 
FROM 
  (
    JSON_TABLE(
      v_personalData, 
      '$' COLUMNS (outer_value_0 NUMBER PATH '$[0]')
    )
  );
v_statusQuery := (
  'UPDATE "customer" SET "Status_id" = ''SID_CUS_ERASURE_INPROGRESS'' WHERE "id" = ''' || v_customerId || ''''
);
EXECUTE IMMEDIATE (v_statusQuery);
WHILE (
  v_personalDataIndex <> v_personalDataSize
) LOOP DECLARE v_personalDataObject VARCHAR2(4000) := ' ';
v_dataDefinitionsArray VARCHAR2(4000) := ' ';
v_datadefindex NUMBER(10, 0) := 0;
v_dataDefinitionsLength NUMBER(10, 0);
BEGIN v_personalDataObject := JSON_QUERY(
  v_personalData, 
  ('$[' || v_personalDataIndex || ']')
);
v_dataDefinitionsArray := JSON_QUERY(
  v_personalDataObject, '$.dataDefinitions'
);
SELECT 
  COUNT(*) INTO v_dataDefinitionsLength 
FROM 
  (
    JSON_TABLE(v_dataDefinitionsArray, '$')
  );
WHILE (
  v_datadefindex <> v_dataDefinitionsLength
) LOOP DECLARE v_queryString VARCHAR2(4000) := ' ';
v_columnsArray VARCHAR2(4000) := ' ';
v_columnIndex NUMBER(10, 0) := 0;
v_columnsArraySize NUMBER(10, 0);
v_tableObject VARCHAR2(4000) := ' ';
v_tableName VARCHAR2(4000) := ' ';
v_dbName VARCHAR2(4000) := ' ';
v_updateQuery VARCHAR2(4000) := ' ';
v_columnQuery VARCHAR2(4000) := ' ';
v_ParmDefinition VARCHAR2(4000) := ' ';
v_execQuery VARCHAR2(4000) := ' ';
BEGIN v_tableObject := JSON_QUERY(
  v_dataDefinitionsArray, 
  ('$[' || v_datadefindex || ']')
);
-- Getting table object
v_tableName := JSON_VALUE(
  v_tableObject, '$.dataEntityName'
);
-- extracting table name from table object
SELECT 
  querystring, 
  dbname INTO v_queryString, 
  v_dbName 
FROM 
  queryconfig 
WHERE 
  tablename = v_tableName;
v_columnsArray := JSON_QUERY(
  v_tableObject, '$.dataEntityFields'
);
SELECT 
  COUNT(*) INTO v_columnsArraySize 
FROM 
  TABLE(
    OPENJSON(v_columnsArray, '$')
  );
WHILE (
  v_columnIndex <> v_columnsArraySize
) LOOP DECLARE v_columnCondition VARCHAR2(4000) := ' ';
v_fieldObject VARCHAR2(4000) := ' ';
v_fieldName VARCHAR2(4000) := ' ';
v_fieldType VARCHAR2(4000) := ' ';
v_erasureOptionsId VARCHAR2(4000) := ' ';
v_erasureOptionsValue VARCHAR2(4000) := ' ';
v_updatedValue VARCHAR2(100) := ' ';
BEGIN v_fieldObject := JSON_QUERY(
  v_columnsArray, 
  CONCAT('$[', v_columnIndex, ']')
);
v_fieldName := JSON_VALUE(
  v_fieldObject, '$.dataEntityFieldName'
);
v_fieldType := JSON_VALUE(
  v_fieldObject, '$.dataEntityFieldDataType'
);
v_erasureOptionsId := JSON_VALUE(
  v_fieldObject, '$.erasureOptions.optionsId'
);
v_erasureOptionsValue := JSON_VALUE(
  v_fieldObject, '$.erasureOptions.optionsValue'
);
IF v_erasureOptionsId <> 'NO ACTION' THEN BEGIN IF v_erasureOptionsId = 'NULLIFY' THEN BEGIN v_columnCondition := CONCAT(v_fieldName, '=NULL');
END;
ELSE BEGIN IF v_tableName = 'customerdevice' 
AND v_fieldName = 'LastLoginTime' THEN BEGIN v_updatedValue := '1753-01-01 00:00:00';
END;
ELSE IF v_fieldType = 'ALPHA' THEN BEGIN v_updatedValue := LPAD('', 10, v_erasureOptionsValue);
END;
ELSE IF v_fieldType = 'NUMBER' THEN BEGIN v_updatedValue := 9;
END;
ELSE IF v_fieldType = 'DATE' THEN BEGIN v_updatedValue := v_updatedValue;
v_updatedValue := '9999-12-31';
END;
END IF;
END IF;
END IF;
END IF;
v_columnCondition := CONCAT(
  v_fieldName, '=''', v_updatedValue, 
  ''''
);
END;
END IF;
END;
END IF;
IF v_columnQuery <> '' THEN v_columnQuery := CONCAT(v_columnQuery, ',');
END IF;
v_columnQuery := CONCAT(
  v_columnQuery, v_columnCondition
);
v_columnIndex := v_columnIndex + 1;
END;
END LOOP;
v_queryString := REPLACE(
  v_queryString, 
  '?', 
  CONCAT('''', v_customerId, '''')
);
v_execQuery := CONCAT(
  'UPDATE [', v_tableName, '] SET ', 
  v_columnQuery, ' ', v_queryString, 
  ' '
);
EXEC(v_execQuery);
v_datadefindex := v_datadefindex + 1;
END;
END LOOP;
v_personalDataIndex := v_personalDataIndex + 1;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure feature_action_limits_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "feature_action_limits_update_proc" (
  v__action IN VARCHAR2, v__companyLegalUnit IN VARCHAR2, 
  v__minTxLimit IN NUMBER, v__maxTxLimit IN NUMBER, 
  v__dailyLimit IN NUMBER, v__weeklyLimit IN NUMBER
) AS BEGIN 
UPDATE 
  "actionlimit" 
SET 
  "value" = v__minTxLimit 
WHERE 
  "Action_id" = v__action 
  AND "LimitType_id" = 'MIN_TRANSACTION_LIMIT' 
  AND "companyLegalUnit" = v__companyLegalUnit;
UPDATE 
  "actionlimit" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "Action_id" = v__action 
  AND "LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "companyLegalUnit" = v__companyLegalUnit;
UPDATE 
  "actionlimit" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "Action_id" = v__action 
  AND "LimitType_id" = 'DAILY_LIMIT' 
  AND "companyLegalUnit" = v__companyLegalUnit;
UPDATE 
  "actionlimit" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "Action_id" = v__action 
  AND "LimitType_id" = 'WEEKLY_LIMIT' 
  AND "companyLegalUnit" = v__companyLegalUnit;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_accountdetails_proc


create or replace NONEDITIONABLE PROCEDURE         "fetch_accountdetails_proc" 
(
  "_contractId" IN VARCHAR2,
  "_cif" IN VARCHAR2,
  "_accountIds" IN VARCHAR2,
  "records" OUT SYS_REFCURSOR
)
AS
   v__cif VARCHAR2(50) := "_cif";


BEGIN

   IF v__cif = '' THEN

   BEGIN
      v__cif := '%' ;

   END;
   END IF;
   OPEN  "records" FOR
      SELECT customeraccounts."Account_id" ,
             customeraccounts."AccountName" ,
             customeraccounts."accountType" ,
             contractaccounts."ownerType" "ownershipType"
        FROM ( "customeraccounts" customeraccounts
               LEFT JOIN "contractaccounts" contractaccounts   ON customeraccounts."Account_id" = contractaccounts."accountId"
                ) 
       WHERE  customeraccounts."contractId" = "_contractId"
                AND customeraccounts."coreCustomerId" LIKE v__cif
                AND customeraccounts."Account_id" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT("_accountIds")))
        ORDER BY customeraccounts."contractId",
                 customeraccounts."coreCustomerId" ;
      --DBMS_SQL.RETURN_RESULT(v_cursor);

END;

/

--  DDL for Procedure fetch_accountlevelcustomerlimits_for_featureaction_proc

create or replace NONEDITIONABLE PROCEDURE  "fetch_accountlevelcustomerlimits_for_featureaction_proc" (
  "_customerId" IN VARCHAR2,
  "_featureActionId"  IN VARCHAR2,
     "records" OUT SYS_REFCURSOR)
AS
  v_orgId CLOB;
BEGIN
  SELECT "Organization_Id" INTO v_orgId FROM "customer"WHERE "id" = "_customerId";

  IF v_orgId IS NULL OR v_orgId = '' THEN
    OPEN "records" FOR 
    SELECT ca."Customer_id" AS "customerId",
      cg."Group_id" AS "roleId",
      sdal."serviceDefinitionId",
      ca."Account_id" AS "accountId",
      ca."contractId",
      ca."coreCustomerId",
      al."Action_id" AS "baseActionId",
      sdal."actionId" AS "serviceDefActionId",
      cal."actionId" AS "contractActionId",
      gal."Action_id" AS "roleActionId",
      al."LimitType_id" AS "baseLimitTypeId",
      sdal."limitTypeId" AS "serviceDefLimitTypeId",
      cal."limitTypeId" AS "contractLimitTypeId",
      gal."LimitType_id" AS "roleLimitTypeId",
      al."value" AS "baseLimitValue",
      sdal."value" AS "serviceDevLimitValue",
      cal."value" AS "contractLimitValue",
      gal."value" AS "roleLimitValue",
      LEAST (al."value", gal."value", sdal."value", cal."value") AS "minLimitValue"
      FROM "customeraccounts" ca
      INNER JOIN "customergroup"  cg ON 
        ca."Customer_id" = cg."Customer_id"
      INNER JOIN "groupactionlimit"  gal ON 
        gal."Group_id" = cg."Group_id"
      INNER JOIN "contract"  c ON 
        c."id" = ca."contractId"
      INNER JOIN "servicedefinitionactionlimit"  sdal ON 
        sdal."serviceDefinitionId" = c."servicedefinitionId" AND sdal."actionId" = gal."Action_id" AND sdal."limitTypeId" = gal."LimitType_id"
      INNER JOIN "contractactionlimit"  cal ON
        cal."contractId" = ca."contractId" AND cal."actionId" = sdal."actionId" AND cal."limitTypeId" = sdal."limitTypeId"
      INNER JOIN "actionlimit"  al ON
        al."Action_id" = cal."actionId" AND al."LimitType_id" = cal."limitTypeId" AND al."companyLegalUnit" = ca."companyLegalUnit"
      WHERE ca."Customer_id" = "_customerId" AND al."Action_id" = "_featureActionId" ORDER BY ca."Account_id";
  ELSE
    OPEN "records" FOR SELECT
      ca."Customer_id" AS "customerId",
      cg."Group_id" AS "roleId",
      sdal."serviceDefinitionId",
      ca."Account_id" AS "accountId",
      ca."contractId",
      ca."coreCustomerId",
      al."Action_id" AS "baseActionId",
      sdal."actionId" AS "serviceDefActionId",
      cal."actionId" AS "contractActionId",
      gal."Action_id" AS "roleActionId",
      al."LimitType_id" AS "baseLimitTypeId",
      sdal."limitTypeId" AS "serviceDefLimitTypeId",
      cal."limitTypeId" AS "contractLimitTypeId",
      gal."LimitType_id" AS "roleLimitTypeId",
      al."value" AS "baseLimitValue",
      sdal."value" AS "serviceDevLimitValue",
      cal."value" AS "contractLimitValue",
      gal."value" AS "roleLimitValue",
      LEAST (al."value", gal."value", sdal."value", cal."value") AS "minLimitValue"
      FROM "customeraccounts" ca
      INNER JOIN "customergroup"  cg ON 
        ca."Customer_id" = cg."Customer_id"
      INNER JOIN "groupactionlimit"  gal ON 
        gal."Group_id" = cg."Group_id"
      INNER JOIN "contract"  c ON 
        c."id" = ca."contractId"
      INNER JOIN "servicedefinitionactionlimit"  sdal ON 
        sdal."serviceDefinitionId" = c."servicedefinitionId" AND sdal."actionId" = gal."Action_id" AND sdal."limitTypeId" = gal."LimitType_id"
      INNER JOIN "contractactionlimit" cal ON
        cal."contractId" = ca."contractId" AND cal."actionId" = sdal."actionId" AND cal."limitTypeId" = sdal."limitTypeId"
      INNER JOIN "actionlimit"  al ON
        al."Action_id" = cal."actionId" AND al."LimitType_id" = cal."limitTypeId" AND al."companyLegalUnit" = ca."companyLegalUnit"
      INNER JOIN "customer" cu ON
        cu."id" = ca."Customer_id" AND cu."id" = "_customerId"
      INNER JOIN "organisationactionlimit"  oal ON
        oal."Organisation_id" = cu."Organization_Id" AND oal."Action_id" = al."Action_id" AND oal."LimitType_id" = al."LimitType_id"
      WHERE ca."Customer_id" = "_customerId" AND al."Action_id" = "_featureActionId" ORDER BY ca."Account_id";
  END IF;

END;
/

--  DDL for Procedure fetch_achfiles_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_achfiles_proc" (
  v__customerId IN VARCHAR2, iv__achFile_id IN VARCHAR2, 
  v__featureactionlist IN VARCHAR2, 
  v__queryType IN VARCHAR2, iv__filterByParam IN VARCHAR2, 
  iv__filterByValue IN VARCHAR2, v__searchString IN VARCHAR2, 
  iv__sortByParam IN VARCHAR2, iv__sortOrder IN VARCHAR2, 
  v__pageSize IN VARCHAR2, v__pageOffset IN VARCHAR2, 
  "achfile" OUT SYS_REFCURSOR
) AS v__filterByParam VARCHAR2(4000) := iv__filterByParam;
v__filterByValue VARCHAR2(4000) := iv__filterByValue;
v__achFile_id VARCHAR2(50) := iv__achFile_id;
v__sortByParam VARCHAR2(50) := iv__sortByParam;
v__sortOrder VARCHAR2(50) := iv__sortOrder;
v_sql_approvalCount1 VARCHAR2(4000);
v_sql_approvalCount2 VARCHAR2(4000);
curid INTEGER;
BEGIN DECLARE v_combinedIds VARCHAR2(4000);
v_numOfParams NUMBER(10, 0);
v_searchQuery VARCHAR2(4000);
v_idx NUMBER(10, 0);
v_filterParam VARCHAR2(4000);
v_filterValue VARCHAR2(4000);
v_companyId VARCHAR2(4000);
v_customerMatrixIds VARCHAR2(4000);
v_alreadyApprovedIds VARCHAR2(4000);
v_approvalRequestIds CLOB;
v_queryTypecondition VARCHAR2(4000);
v_paginationQuery VARCHAR2(4000);
v_features VARCHAR2(4000);
v_createActions VARCHAR2(4000);
v_companyRequestIds CLOB;
-- Since this variable might grow more than 4000 character, convert this as CLOB and use binding variable in case if used in dynamic sql
v_customerAcounts VARCHAR2(4000);
v_select_statement VARCHAR2(4000);
v_isSelfApprovalenabled NUMBER(1, 0);
v_notCreatedBySelf VARCHAR2(4000);
BEGIN --      /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_numOfParams := 0;
v_searchQuery := '';
v_idx := 1;
v_paginationQuery := 0;
SELECT 
  LISTAGG(
    CAST(
      "customer"."id" AS varchar2(255)
    ), 
    ','
  ) INTO v_combinedIds 
FROM 
  "customer" 
WHERE 
  "customer"."combinedUserId" = v__customerId;
IF v_combinedIds IS NULL THEN v_combinedIds := v__customerId;
ELSE v_combinedIds := (
  v__customerId || ',' || v_combinedIds
);
END IF;
SELECT 
  "isSelfApprovalEnabled" INTO v_isSelfApprovalenabled 
FROM 
  "application";
IF (v_isSelfApprovalenabled = 0) THEN v_notCreatedBySelf := ' AND "achfile"."createdby" NOT IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(''' || v_combinedIds || ''')))';
ELSE v_notCreatedBySelf := '';
END IF;
v__filterByParam := CASE WHEN (
  v__filterByParam IS NULL 
  OR v__filterByParam = ''
) THEN '' ELSE v__filterByParam END;
v__filterByValue := CASE WHEN (
  v__filterByValue IS NULL 
  OR v__filterByValue = ''
) THEN '' ELSE v__filterByValue END;
v__achFile_id := CASE WHEN (
  v__achFile_id = '' 
  OR v__achFile_id IS NULL
) THEN '%' ELSE v__achFile_id END;
IF LENGTHB(v__filterByParam) > 0 THEN v_numOfParams := LENGTHB(v__filterByParam) - LENGTHB(
  REPLACE(v__filterByParam, ',', ' ')
) + 1;
END IF;
WHILE (v_idx < v_numOfParams) LOOP BEGIN v_filterParam := UTILS.SUBSTRING_INDEX(
  ',', 
  UTILS.SUBSTRING_INDEX(',', v__filterByParam, v_idx), 
  -1
);
v_filterValue := UTILS.SUBSTRING_INDEX(
  ',', 
  UTILS.SUBSTRING_INDEX(',', v__filterByValue, v_idx), 
  -1
);
v_searchQuery := v_searchQuery || ' AND (' || v_filterParam || ' LIKE ''' || v_filterValue || ''' )';
v_idx := v_idx + 1;
END;
END LOOP;
SELECT 
  LISTAGG(
    CAST(
      (
        "contractcustomers"."contractId" || '_' || "contractcustomers"."coreCustomerId"
      ) AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = v__customerId;
IF v_companyId IS NULL THEN v_companyId := '';
END IF;
IF v__featureactionlist IS NULL THEN RETURN;
END IF;
v__sortByParam := CASE WHEN (
  v__sortByParam = '' 
  OR v__sortByParam IS NULL
) THEN 'createdts' ELSE v__sortByParam END;
v__sortOrder := CASE WHEN (
  v__sortOrder = '' 
  OR v__sortOrder IS NULL
) THEN 'DESC' ELSE v__sortOrder END;
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_customerMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."customerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  );
IF v_customerMatrixIds IS NULL THEN v_customerMatrixIds := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbactedrequest"."requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_alreadyApprovedIds 
FROM 
  "bbactedrequest" 
WHERE 
  "bbactedrequest"."createdby" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  ) 
  AND "bbactedrequest"."action" = 'Approved';
IF v_alreadyApprovedIds IS NULL THEN v_alreadyApprovedIds := '';
END IF;
-- Using LISTAGG since this may grow more than 4000 character if there could be many pending requests
SELECT 
  LISTAGG(
    CAST(
      "requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_approvalRequestIds 
FROM 
  "requestapprovalmatrix" 
  JOIN "approvalmatrix" ON "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" 
  JOIN "approvalrule" ON "approvalmatrix"."approvalruleId" = "approvalrule"."id" 
WHERE 
  "requestapprovalmatrix"."approvalMatrixId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_customerMatrixIds)
      )
  ) 
  AND "requestapprovalmatrix"."requestId" NOT IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_alreadyApprovedIds)
      )
  ) 
  AND (
    (
      "approvalrule"."numberOfApprovals" = -1 
      AND "requestapprovalmatrix"."receivedApprovals" < (
        SELECT 
          COUNT(
            DISTINCT ("customerId")
          ) 
        FROM 
          "customerapprovalmatrix" 
        WHERE 
          "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
      )
    ) 
    OR (
      "approvalrule"."numberOfApprovals" != -1 
      AND "requestapprovalmatrix"."receivedApprovals" < "approvalrule"."numberOfApprovals"
    )
  );
IF v_approvalRequestIds IS NULL THEN v_approvalRequestIds := '';
END IF;
-- Since the value of v_approvalRequestIds might be larger than 4000 characters, using binding mechanism so as to bind it CLOB data type (since we cannot use || symbol to pass on value)
v_queryTypecondition := CASE WHEN (v__queryType = 'myRequests') THEN ' AND "achfile"."createdby" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(''' || (v_combinedIds) || '''))) AND ("bbrequest"."status" = ''Pending'' OR "bbrequest"."status" = ''Approved'' OR "bbrequest"."status" = ''Rejected'' ) ' WHEN (
  v__queryType = 'pendingForMyApprovals'
) THEN ' AND "achfile".requestId IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(:v_approvalRequestIds))) AND "achfile"."status" = ''Pending'' ' || v_notCreatedBySelf WHEN (v__queryType = 'rejected') THEN ' AND "achfile"."status" = ''Rejected'' ' WHEN (v__achFile_id = '%') THEN ' AND NOT "achfile"."status" = ''Withdrawn'' ' ELSE '' END;
v_searchQuery := CASE WHEN (
  v__searchString IS NULL 
  OR v__searchString = ''
) THEN v_searchQuery ELSE (
  v_searchQuery || ' AND ("achfile"."achFileName" LIKE ''%' || v__searchString || '%'' OR "achfile"."requestType" LIKE ''%' || v__searchString || '%'')'
) END;
v_paginationQuery := CASE WHEN (
  v__pageOffset IS NULL 
  OR v__pageOffset = '' 
  OR v__pageSize IS NULL 
  OR v__pageSize = ''
) THEN '' ELSE (
  ' OFFSET ' || v__pageOffset || '  ROWS FETCH NEXT  ' || v__pageSize || '  ROWS ONLY'
) END;
-- Using LISTAGG_VAR since this may not grow more than 4000 character
SELECT 
  LISTAGG(
    "featureaction"."Feature_id", ','
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__featureactionlist)
      )
  );
IF v_features IS NULL THEN v_features := '';
END IF;
-- Using LISTAGG_VAR since this may not grow more than 4000 character
SELECT 
  LISTAGG("featureaction"."id", ',') INTO v_createActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features)
      )
  ) 
  AND "featureaction"."id" LIKE '%_UPLOAD';
IF v_createActions IS NULL THEN v_createActions := ' ';
END IF;
-- Use LISTAGG if this lenght can grow more than 4000 characters, else use LISTAGG_VAR that would build and return VARCHAR2 which can be used
-- by UTILS.STRING_SPLIT to break it as well.
SELECT 
  LISTAGG("bbrequest"."requestId", ',') INTO v_companyRequestIds 
FROM 
  "bbrequest" 
WHERE 
  "bbrequest"."companyId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_companyId)
      )
  ) 
  AND "bbrequest"."featureActionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_createActions)
      )
  );
IF v_companyRequestIds IS NULL THEN v_companyRequestIds := ' ';
END IF;
-- Build this as query to be used for WITH (CTE replacement), we are using bind variable to pass the CLOB value to this query
-- required value to the dynamic sql
v_sql_approvalCount1 := '
        SELECT customerCnt ,
              requestId 
          FROM ( SELECT COUNT(DISTINCT ("customerId")) customerCnt ,
                       "requestapprovalmatrix"."requestId" requestId  
                FROM "customerapprovalmatrix"
                       JOIN "requestapprovalmatrix"  ON ( "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                 WHERE "requestapprovalmatrix"."requestId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(:v_companyRequestIds)))
                  GROUP BY "requestapprovalmatrix"."requestId" )';
-- Note here, we are using binding variable to pass the CLOB value as we cannot use || symbol to concate them as pass to dynamic sql
-- Build this as query to be used for WITH (CTE replacement), we are using bind variable to pass the CLOB value to this query
-- required value to the dynamic sql
v_sql_approvalCount2 := 'SELECT requestId ,
              totalCnt 
          FROM ( SELECT "requestId" ,
                       SUM(t)  totalCnt  
                FROM ( SELECT 
              "bbrequest"."requestId" requestId ,
                        CASE WHEN "approvalrule".numberOfApprovals = -1 THEN ( SELECT COUNT(*)FROM "customerapprovalmatrix" 
                  WHERE  "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                                   WHEN "approvalrule"."numberOfApprovals" IS NULL
                                     OR "approvalrule"."numberOfApprovals" = '''' THEN 0
                             ELSE "approvalrule"."numberOfApprovals"
                        END t  
                       FROM "customerapprovalmatrix"
                          LEFT JOIN "requestapprovalmatrix"    ON "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
                          LEFT JOIN "bbrequest"    ON ( "bbrequest"."requestId" = "requestapprovalmatrix"."requestId" )
                          LEFT JOIN "approvalmatrix"    ON ( "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" )
                          LEFT JOIN "approvalrule"    ON ( "approvalmatrix"."approvalruleId" = "approvalrule"."id" )
                       WHERE "bbrequest"."requestId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(:v_companyRequestIds))))
                  GROUP BY requestId )';
-- Note here, we are using binding variable to pass the CLOB value as we cannot use || symbol to concate them as pass to dynamic sql
--
-- Build the dynamic sql
--          
v_select_statement := '
        WITH 
      approvalCount1 AS ( ' || v_sql_approvalCount1 || ' ),
      approvalCount2 AS ( ' || v_sql_approvalCount2 || ' )
          (SELECT * FROM
              (SELECT 
               "achfile"."achFile_id" AS achFile_id,
               "achfile"."achFileName" AS achFileName,
               "achfile"."featureActionId" AS featureActionId,
               "achfile"."debitAmount" AS debitAmount,
               "achfile"."approvalAccounts" AS approvalAccounts,
               "achfile"."debitAccounts" AS debitAccounts,
               "achfile"."createdby" AS createdby,
               "achfile"."createdts" AS createdts,
               "achfile"."requestType" AS requestType,
               "achfile"."numberOfCredits" AS numberOfCredits,
               "achfile"."numberOfDebits" AS numberOfDebits,
               "achfile"."numberOfPrenotes" AS numberOfPrenotes,
               "achfile"."requestId" AS requestId,
               "achfile"."contents" AS contents,
               "achfile"."fileSize" AS fileSize,
               "achfile"."softDelete" AS softDelete,
               "achfile"."creditAmount" AS creditAmount,
               "achfile"."numberOfRecords" AS numberOfRecords,
               "achfile"."achFileFormatType_id" AS achFileFormatType_id,
            (CASE WHEN "bbrequest"."status" IS NULL THEN "achfile"."status"
                    ELSE "bbrequest"."status" 
            END) AS status,
               "achfile"."companyId" AS companyId,
               "achfile"."confirmationNumber" AS confirmationNumber,
               "customer"."UserName" AS userName,
               "achfileformattype"."fileType" AS achFileFormatType,
               "bbrequest"."createdby" AS requestCreatedby,
              (CASE WHEN UTILS.FIND_IN_SET(CAST("achfile"."createdby" AS VARCHAR2(255)),''' || v_combinedIds || ''') > 0 THEN ''true''
                    ELSE ''false''
                END) as amICreator,
              (CASE WHEN UTILS.FIND_IN_SET(CAST("bbrequest"."requestId" AS VARCHAR2(255)), :v_approvalRequestIds) > 0 THEN ''true''
                     ELSE ''false''
                END) as amIApprover
            FROM achfile
               LEFT JOIN "customer" ON ("achfile"."createdby" = "customer"."id")
               LEFT JOIN "achfileformattype" ON ("achfile"."achFileFormatType_id" = "achfileformattype"."id")
               LEFT JOIN "bbrequest" ON ("achfile"."requestId" = "bbrequest"."requestId")
               WHERE "achfile"."softDelete" = ''0''
                  AND ("achfile"."companyId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(''' || v_companyId || '''))) OR "achfile"."createdby" IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(''' || v_combinedIds || '''))))
                  AND "achfile"."achFile_id" LIKE ''' || v__achFile_id || '''
                  AND "achfile"."featureActionId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(''' || v_createActions || '''))) ' || v_queryTypecondition || ' ' || v_searchQuery || ')
      ) AS t1
          LEFT JOIN
            (SELECT 
                "bbrequest"."requestId",
                (select count(DISTINCT("bbactedrequest"."createdby")) from "bbactedrequest" where "bbactedrequest"."action" = ''Approved'' AND "bbactedrequest"."requestId" = "bbrequest"."requestId") 
                           as receivedApprovals,
                (LEAST(approvalCount1.customerCnt,approvalCount2.totalCnt)) as requiredApprovals
                FROM "bbrequest", all_bind_variables
          LEFT JOIN approvalCount1 ON (approvalCount1.requestid = "bbrequest"."requestId")
          LEFT JOIN approvalCount2 ON (approvalCount2.requestid = "bbrequest"."requestId")
                  LEFT JOIN "requestapprovalmatrix" ON ("bbrequest"."requestId" = "requestapprovalmatrix"."requestId")
                  LEFT JOIN "approvalmatrix" ON ("requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id")
                  LEFT JOIN "approvalrule" ON ("approvalmatrix"."approvalruleId" = "approvalrule"."id")
                WHERE "bbrequest"."requestId" IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(:v_companyRequestIds))) 
                  GROUP BY "bbrequest"."requestId"
            ) AS t2
            ON  t1.requestId = t2.requestId
            ORDER BY ' || v__sortByParam || ' ' || v__sortOrder || ' ' || v_paginationQuery;
-- Use following mechanism to bind the variables to dynamic sql
curid := dbms_sql.open_cursor;
dbms_sql.parse(
  curid, v_select_statement, dbms_sql.native
);
dbms_sql.bind_variable(
  curid, 'v_companyRequestIds', v_companyRequestIds
);
dbms_sql.bind_variable(
  curid, 'v_approvalRequestIds', v_approvalRequestIds
);
--      ret := dbms_sql.execute(curid);
"achfile" := dbms_sql.to_refcursor(curid);
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount1 ';
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount2 ';
END;
--   <<MAINLABEL$leave>>
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_achtemplaterecords_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_achtemplaterecords_proc" (
  v__templateId IN VARCHAR2, "bbtemplaterecord" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/

/*
         *   SSMA informational messages:
         *   M2SS0052: string literal was converted to NUMERIC literal
         */
OPEN "bbtemplaterecord" FOR 
SELECT 
  "bbtemplaterecord"."templateRecord_id" templateRecord_id, 
  "bbtemplaterecord"."record_Name" record_Name, 
  "bbtemplaterecord"."toAccountNumber" toAccountNumber, 
  "bbtemplaterecord"."abatrcNumber" abatrcNumber, 
  "bbtemplaterecord"."detail_id" detail_id, 
  "bbtemplaterecord"."amount" amount, 
  "bbtemplaterecord"."additionalInfo" additionalInfo, 
  "bbtemplaterecord"."ein" ein, 
  "bbtemplaterecord"."isZeroTaxDue" isZeroTaxDue, 
  "bbtemplaterecord"."template_id" template_id, 
  "bbtemplaterecord"."taxType_id" taxType_id, 
  "bbtemplaterecord"."templateRequestType_id" templateRequestType_id, 
  "bbtemplaterecord"."softDelete" softDelete, 
  "bbtemplaterecord"."toAccountType" toAccountType, 
  "bbtaxtype"."taxType" taxType, 
  "achaccountstype"."accountType" accountType, 
  "bbtemplaterequesttype"."templateRequestTypeName" templateRequestTypeName 
FROM 
  (
    (
      (
        "bbtemplaterecord" 
        LEFT JOIN "bbtaxtype" ON (
          "bbtemplaterecord"."taxType_id" = "bbtaxtype"."id"
        )
      ) 
      LEFT JOIN "achaccountstype" ON (
        "bbtemplaterecord"."toAccountType" = "achaccountstype"."id"
      )
    ) 
    LEFT JOIN "bbtemplaterequesttype" ON (
      "bbtemplaterecord"."templateRequestType_id" = "bbtemplaterequesttype"."templateRequestType_id"
    )
  ) 
WHERE 
  "bbtemplaterecord"."softDelete" = 0 
  AND "bbtemplaterecord"."template_id" = v__templateId;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

