--  DDL for Procedure fetch_achtransaction_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_achtransaction_proc" (
  v__customerId IN VARCHAR2, iv__transactionId IN VARCHAR2, 
  v__featureactionlist IN VARCHAR2, 
  v__queryType IN VARCHAR2, iv__filterByParam IN VARCHAR2, 
  iv__filterByValue IN VARCHAR2, v__searchString IN VARCHAR2, 
  iv__sortByParam IN VARCHAR2, iv__sortOrder IN VARCHAR2, 
  v__pageSize IN VARCHAR2, v__pageOffset IN VARCHAR2, 
  "achtransaction" OUT SYS_REFCURSOR
) AS v__filterByParam VARCHAR2(4000) := iv__filterByParam;
v__filterByValue VARCHAR2(4000) := iv__filterByValue;
v__transactionId VARCHAR2(4000) := iv__transactionId;
v__sortByParam VARCHAR2(4000) := iv__sortByParam;
v__sortOrder VARCHAR2(4000) := iv__sortOrder;
BEGIN DECLARE v_group_concat_max_len NUMBER(19, 0);
v_combinedIds CLOB;
v_numOfParams NUMBER(10, 0);
v_searchQuery VARCHAR2(4000);
v_idx NUMBER(10, 0);
v_filterParam VARCHAR2(4000);
v_filterValue VARCHAR2(4000);
v_companyId CLOB;
v_customerMatrixIds CLOB;
v_alreadyApprovedIds CLOB;
v_approvalRequestIds CLOB;
v_queryTypecondition VARCHAR2(4000);
v_paginationQuery VARCHAR2(4000);
v_features CLOB;
v_createActions CLOB;
v_companyRequestIds CLOB;
v_customerAcounts CLOB;
v_select_statement VARCHAR2(4000);
v_validAccountsJoin VARCHAR2(4000);
v_isSelfApprovalenabled NUMBER(1, 0);
v_notCreatedBySelf VARCHAR2(4000);
v_db_null_statement NUMBER(10, 0);
v_db_null_statement$2 NUMBER(10, 0);
v_approvalCount2_2 VARCHAR2(4000);
v_approvalCount1_2 VARCHAR2(4000);
BEGIN --      /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_numOfParams := 0;
v_searchQuery := '';
v_idx := 1;
v_paginationQuery := 0;
SELECT 
  LISTAGG("customer"."id", ',') INTO v_combinedIds 
FROM 
  "customer" 
WHERE 
  "customer"."combinedUserId" = v__customerId;
IF v_combinedIds IS NULL THEN BEGIN v_combinedIds := v__customerId;
END;
ELSE v_combinedIds := (
  v__customerId || ',' || v_combinedIds
);
END IF;
SELECT 
  "isSelfApprovalEnabled" INTO v_isSelfApprovalenabled 
FROM 
  "application";
IF (v_isSelfApprovalenabled = 0) THEN v_notCreatedBySelf := (
  ' AND "achtransaction"."createdby" NOT IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT( ''' || v_combinedIds || ''')))'
);
ELSE v_notCreatedBySelf := ' ';
END IF;
v__filterByParam := CASE WHEN (
  v__filterByParam IS NULL 
  OR v__filterByParam = ''
) THEN ' ' ELSE v__filterByParam END;
v__filterByValue := CASE WHEN (
  v__filterByValue IS NULL 
  OR v__filterByValue = ''
) THEN ' ' ELSE v__filterByValue END;
v__transactionId := CASE WHEN (
  v__transactionId = '' 
  OR v__transactionId IS NULL
) THEN '%' ELSE v__transactionId END;
v_numOfParams := 0;
IF LENGTH(v__filterByParam) > 0 THEN BEGIN v_numOfParams := LENGTH(v__filterByParam) - LENGTH(
  REPLACE(v__filterByParam, ',', ' ')
) || 1;
END;
END IF;
v_searchQuery := ' ';
WHILE (v_idx <= v_numOfParams) LOOP BEGIN v_filterParam := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__filterByParam, ',', v_idx), 
  ',', 
  -1
);
v_filterValue := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__filterByValue, ',', v_idx), 
  ',', 
  -1
);
v_searchQuery := (
  v_searchQuery || ' AND (' || v_filterParam || ' LIKE ''' || v_filterValue || ''' )'
);
v_idx := v_idx + 1;
END;
END LOOP;
SELECT 
  LISTAGG(
    CAST(
      (
        "contractcustomers"."contractId" || '_' || "contractcustomers"."coreCustomerId"
      ) AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = v__customerId;
IF v_companyId IS NULL THEN BEGIN v_companyId := ' ';
END;
END IF;
IF v__featureactionlist IS NULL THEN BEGIN RETURN;
END;
END IF;
v__sortByParam := CASE WHEN (
  v__sortByParam = '' 
  OR v__sortByParam IS NULL
) THEN 'createdts' ELSE v__sortByParam END;
v__sortOrder := CASE WHEN (
  v__sortOrder = '' 
  OR v__sortOrder IS NULL
) THEN 'DESC' ELSE v__sortOrder END;
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS varchar2(255)
    ), 
    ','
  ) INTO v_customerMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."customerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  );
IF v_customerMatrixIds IS NULL THEN BEGIN v_customerMatrixIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbactedrequest"."requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_alreadyApprovedIds 
FROM 
  "bbactedrequest" 
WHERE 
  "bbactedrequest"."createdby" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  ) 
  AND "bbactedrequest"."action" = 'Approved';
IF v_alreadyApprovedIds IS NULL THEN BEGIN v_alreadyApprovedIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_approvalRequestIds 
FROM 
  "requestapprovalmatrix" 
  JOIN "approvalmatrix" ON "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" 
  JOIN "approvalrule" ON "approvalmatrix"."approvalruleId" = "approvalrule"."id" 
WHERE 
  CAST(
    "requestapprovalmatrix"."approvalMatrixId" AS varchar2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_customerMatrixIds)
      )
  ) 
  AND NOT CAST(
    "requestapprovalmatrix"."requestId" AS varchar2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_alreadyApprovedIds)
      )
  ) 
  AND (
    (
      "approvalrule"."numberOfApprovals" = -1 
      AND "requestapprovalmatrix"."receivedApprovals" < (
        SELECT 
          COUNT(
            DISTINCT (
              "customerapprovalmatrix"."customerId"
            )
          ) 
        FROM 
          "customerapprovalmatrix" 
        WHERE 
          "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
      )
    ) 
    OR (
      "approvalrule"."numberOfApprovals" <> -1 
      AND "requestapprovalmatrix"."receivedApprovals" < "approvalrule"."numberOfApprovals"
    )
  );
IF v_approvalRequestIds IS NULL THEN BEGIN v_approvalRequestIds := ' ';
END;
END IF;
v_queryTypecondition := CASE WHEN (v__queryType = 'myRequests') THEN (
  ' AND FIND_IN_SET("achtransaction"."createdby", '''
) || (v_combinedIds) || (
  ''')<>0 AND ("bbrequest"."status" = ''Pending'' OR "bbrequest"."status" = ''Approved'' OR "bbrequest"."status" = ''Rejected'' ) '
) ELSE CASE WHEN (
  v__queryType = 'pendingForMyApprovals'
) THEN (
  ' AND FIND_IN_SET(CAST("achtransaction"."requestId" AS varchar2(255)),  '''
) || (v_approvalRequestIds) || (
  ''')<>0  AND "achtransaction"."status" = ''Pending'' '
) || v_notCreatedBySelf ELSE CASE WHEN (v__queryType = 'rejected') THEN (
  ' AND "achtransaction"."status" = ''Rejected'' '
) ELSE CASE WHEN (v__transactionId = '%') THEN (
  ' AND NOT "achtransaction"."status" = ''Withdrawn'''
) ELSE ' ' END END END END;
v_validAccountsJoin := CASE WHEN (v__queryType = '') THEN (
  ' INNER JOIN (SELECT DISTINCT "Account_id", REPLACE("Action_id", ''_VIEW'', ''_CREATE'') as Action_id
                                                   FROM "customeraction" WHERE "customeraction"."Customer_id" = ''' || v__customerId || ''' AND "customeraction"."isAllowed" = ''1''
                                                   AND "customeraction"."Account_id" is NOT null AND "customeraction"."Action_id" like ''%_VIEW'') as can ON ("achtransaction"."featureActionId" = can."Action_id"
                                                   AND "achtransaction"."fromAccount" = can."Account_id") '
) ELSE ' ' END;
v_searchQuery := CASE WHEN (
  v__searchString IS NULL 
  OR v__searchString = ''
) THEN v_searchQuery ELSE (
  v_searchQuery || ' AND ("achtransaction"."templateName" LIKE ''%' || v__searchString || '%'' OR "customeraccounts"."AccountName" LIKE ''%' || v__searchString || '%'' OR "bbtemplaterequesttype"."templateRequestTypeName" LIKE ''%' || v__searchString || '%'' OR 
                    "achtransaction"."templateName" LIKE ''%' || v__searchString || '%'' OR "achtransaction"."fromAccount" LIKE ''%' || v__searchString || '%'' )'
) END;
v_paginationQuery := CASE WHEN (
  v__pageOffset IS NULL 
  OR v__pageOffset = '' 
  OR v__pageSize IS NULL 
  OR v__pageSize = ''
) THEN ' ' ELSE (
  ' OFFSET ' || v__pageOffset || '   ROWS FETCH NEXT ' || v__pageSize || ' ROWS ONLY '
) END;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."Feature_id" AS varchar2(255)
    ), 
    ','
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__featureactionlist)
      )
  );
IF v_features IS NULL THEN BEGIN v_features := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS varchar2(255)
    ), 
    ','
  ) INTO v_createActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features)
      )
  ) 
  AND "featureaction"."id" LIKE '%_CREATE';
IF v_createActions IS NULL THEN BEGIN v_createActions := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbrequest"."requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_companyRequestIds 
FROM 
  "bbrequest" 
WHERE 
  "bbrequest"."companyId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_companyId)
      )
  ) 
  AND "bbrequest"."featureActionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_createActions)
      )
  );
IF v_companyRequestIds IS NULL THEN BEGIN v_companyRequestIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customeraccounts"."Account_id" AS varchar2(255)
    ), 
    ','
  ) INTO v_customerAcounts 
FROM 
  "customeraccounts" 
WHERE 
  "customeraccounts"."Customer_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  );
IF v_customerAcounts IS NULL THEN BEGIN v_customerAcounts := ' ';
END;
END IF;
--      DELETE FROM tt_approvalCount1_2;
--      UTILS.IDENTITY_RESET('tt_approvalCount1_2');
v_approvalCount1_2 := '( 
        SELECT customerCnt ,
              requestId 
          FROM ( SELECT COUNT(DISTINCT ("customerId"))  customerCnt  ,
                       "requestapprovalmatrix"."requestId" requestId  
                FROM "customerapprovalmatrix" 
                       JOIN "requestapprovalmatrix"    ON ( "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                 WHERE  CAST("requestapprovalmatrix"."requestId" AS varchar2(255)) IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_companyRequestIds)))
                  GROUP BY "requestapprovalmatrix"."requestId" ) )';
--      DELETE FROM tt_approvalCount2_2;
--      UTILS.IDENTITY_RESET('tt_approvalCount2_2');
v_approvalCount2_2 := '( 
        SELECT requestId ,
              totalCnt 
          FROM ( SELECT requestId ,
                       SUM(t)  totalCnt  
                FROM ( SELECT "bbrequest"."requestId" requestId  ,
                              CASE 
                                   WHEN "approvalrule"."numberOfApprovals" = -1 THEN ( SELECT COUNT(*)  
          FROM "customerapprovalmatrix" 
         WHERE  "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                                   WHEN "approvalrule"."numberOfApprovals" IS NULL
                                     OR "approvalrule"."numberOfApprovals" = '''' THEN 0
                              ELSE "approvalrule"."numberOfApprovals"
                                 END t  
                       FROM "customerapprovalmatrix" 
                              LEFT JOIN "requestapprovalmatrix"    ON "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
                              LEFT JOIN "bbrequest"    ON ( "bbrequest"."requestId" = "requestapprovalmatrix"."requestId" )
                              LEFT JOIN "approvalmatrix"    ON ( "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" )
                              LEFT JOIN "approvalrule"    ON ( "approvalmatrix"."approvalruleId" = "approvalrule"."id" )
                        WHERE  CAST("bbrequest"."requestId" AS varchar2(255)) IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_companyRequestIds))) ) approvals
                  GROUP BY requestId ) )';
v_select_statement := '

               SELECT * FROM
                  (SELECT 
               "achtransaction"."templateName" AS transaction_id,
               "achtransaction"."fromAccount" AS fromAccount,
               "achtransaction"."effectiveDate" AS effectiveDate,
               "achtransaction"."requestId" AS requestId,
               "achtransaction"."createdby" AS createdby,
               "achtransaction"."createdts" AS createdts,
               "achtransaction"."maxAmount" AS maxAmount,
           ( CASE 
              WHEN "bbrequest"."status" is NULL THEN "achtransaction"."status"
                      ELSE "bbrequest"."status" 
            END ) AS status,
               "achtransaction"."transactionType_id" AS transactionType_id,
               "achtransaction"."templateType_id" AS templateType_id,
               "achtransaction"."companyId" AS companyId,
               "achtransaction"."templateRequestType_id" AS templateRequestType_id,
               "achtransaction"."softDelete" AS softDelete,
               "achtransaction"."templateName" AS templateName,
               "achtransaction"."template_id" AS template_id,
               "achtransaction"."totalAmount" AS totalAmount,
               "achtransaction"."featureActionId" AS featureActionId,
               "achtransaction"."confirmationNumber" AS confirmationNumber,
               ( CASE 
                  WHEN "customeraccounts"."AccountName" is NULL THEN ''AccountName'' 
                      ELSE "customeraccounts"."AccountName" 
                  END ) AS accountName,
               "customer"."UserName" AS userName,
               "bbtransactiontype"."transactionTypeName" AS transactionTypeName,
               "bbtemplatetype"."templateTypeName" AS templateTypeName,
               "bbtemplaterequesttype"."templateRequestTypeName" AS templateRequestTypeName,
               "bbrequest"."createdby" AS requestCreatedby,
               (CASE
                  WHEN CAST("achtransaction"."createdby" AS varchar2(255)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_combinedIds || ''' as varchar2(255))))) THEN ''true''
                  ELSE ''false''
                END) as amICreator,
               (CASE 
                  WHEN CAST("bbrequest"."requestId" AS nvarchar(max)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_approvalRequestIds || ''' as varchar2(255))))) THEN ''true''
                  ELSE ''false''
               END)
                as amIApprover
            FROM
               (((((("achtransaction"
               LEFT JOIN "customer" ON ("achtransaction"."createdby" = "customer"."id"))
               LEFT JOIN "customeraccounts" ON (("achtransaction"."createdby" = "customeraccounts"."Customer_id")
                  AND ("achtransaction"."fromAccount" = "customeraccounts"."Account_id")))
               LEFT JOIN "bbtransactiontype" ON ("achtransaction"."transactionType_id" = "bbtransactiontype"."transactionType_id"))
               LEFT JOIN "bbtemplatetype" ON ("achtransaction"."templateType_id" = "bbtemplatetype"."templateType_id"))
               LEFT JOIN "bbtemplaterequesttype" ON ("achtransaction"."templateRequestType_id" = "bbtemplaterequesttype"."templateRequestType_id"))
               LEFT JOIN "bbrequest"ON ("achtransaction"."requestId" = "bbrequest"."requestId"))
               WHERE "achtransaction"."softDelete" = ''0''
                  AND ( "achtransaction"."companyId" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_companyId || '''))) OR "achtransaction"."createdby" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_combinedIds || ''' as varchar2(255))))))
                  AND "achtransaction"."templateName" LIKE ''' || v__transactionId || '''
                  AND "achtransaction"."fromAccount" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_customerAcounts || ''' as varchar2(255))))) 
                      AND 
"achtransaction"."featureActionId" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_createActions || ''' as varchar2(255))))) ' || v_queryTypecondition || ' ' || v_searchQuery || ' ) AS t1
                  LEFT JOIN
                  ( 
                  SELECT 
                     "bbrequest"."requestId",
                     (select count(DISTINCT("bbactedrequest"."createdby")) from "bbactedrequest" where "bbactedrequest"."action" = ''Approved'' AND  "bbactedrequest"."requestId" = "bbrequest"."requestId") 
                           as receivedApprovals,
                          (LEASTINT((select customerCnt from v_approvalCount1_2 where "requestid"="bbrequest"."requestId" ),(select totalCnt from (v_approvalCount2_2) where "requestid"="bbrequest"."requestId" ))) as requiredApprovals
                  FROM
                   "bbrequest"
                  LEFT JOIN "requestapprovalmatrix" ON ("bbrequest"."requestId" = "requestapprovalmatrix"."requestId")
                  LEFT JOIN "approvalmatrix" ON ("requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id")
                  LEFT JOIN "approvalrule" ON ("approvalmatrix"."approvalruleId" = "approvalrule"."id")
                      WHERE CAST("bbrequest"."requestId" AS varchar2(255)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_companyRequestIds || ''' as varchar2(255)))))
                  GROUP BY "bbrequest"."requestId"
                  ) AS t2
                  ON 
                  t1."requestId" = t2."requestId"
                  ORDER BY ' || v__sortByParam || ' ' || v__sortOrder || ' ' || v_paginationQuery;
OPEN "achtransaction" FOR v_select_statement;
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount1_2 ';
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount2_2 ';
END;
--   <<MAINLABEL$leave>>
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_achtransactionrecords_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_achtransactionrecords_proc" (
  v__transactionId IN VARCHAR2, "achtransactionrecord" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/

/*
         *   SSMA informational messages:
         *   M2SS0052: string literal was converted to NUMERIC literal
         */
OPEN "achtransactionrecord" FOR 
SELECT 
  "achtransactionrecord"."transactionRecord_id" transactionRecord_id, 
  "achtransactionrecord"."toAccountNumber" toAccountNumber, 
  "achtransactionrecord"."toAccountType" toAccountType, 
  "achtransactionrecord"."abatrcNumber" abatrcNumber, 
  "achtransactionrecord"."detail_id" detail_id, 
  "achtransactionrecord"."amount" amount, 
  "achtransactionrecord"."additionalInfo" additionalInfo, 
  "achtransactionrecord"."eIN" eIN, 
  "achtransactionrecord"."isZeroTaxDue" isZeroTaxDue, 
  "achtransactionrecord"."taxType_id" taxType_id, 
  "achtransactionrecord"."transaction_id" transaction_id, 
  "achtransactionrecord"."softDelete" softDelete, 
  "achtransactionrecord"."templateRequestType_id" templateRequestType_id, 
  "achtransactionrecord"."record_Name" record_Name, 
  "bbtaxtype"."taxType" taxType, 
  "achaccountstype"."accountType" accountType, 
  "bbtemplaterequesttype"."templateRequestTypeName" templateRequestTypeName 
FROM 
  (
    (
      (
        "achtransactionrecord" 
        LEFT JOIN "bbtaxtype" ON (
          "achtransactionrecord"."taxType_id" = "bbtaxtype"."id"
        )
      ) 
      LEFT JOIN "achaccountstype" ON (
        "achtransactionrecord"."toAccountType" = "achaccountstype"."id"
      )
    ) 
    LEFT JOIN "bbtemplaterequesttype" ON (
      "achtransactionrecord"."templateRequestType_id" = "bbtemplaterequesttype"."templateRequestType_id"
    )
  ) 
WHERE 
  "achtransactionrecord"."softDelete" = 0 
  AND "achtransactionrecord"."transaction_id" = v__transactionId;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

