--  DDL for Procedure fetch_approval_history_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_approval_history_proc" (
  v_userId IN VARCHAR2, v_moduleListArr IN VARCHAR2, 
  v_actionListArr IN VARCHAR2, v_featureListArr IN VARCHAR2, 
  v_searchStartDate IN VARCHAR2, v_searchEndDate IN VARCHAR2, 
  v_sortParam IN VARCHAR2, v_sortOrder IN VARCHAR2, 
  "approvalrequests" OUT SYS_REFCURSOR
) AS dateFilterStmt VARCHAR2(256);
dateField VARCHAR2(128);
req_pending_status VARCHAR2(64);
sqlStmt VARCHAR2(4000);
sortParam VARCHAR2(64);
BEGIN dateField := 'ar."checkedts"';
IF v_sortParam IS NOT NULL THEN sortParam := 'ar.' || v_sortParam || '';
END IF;
IF v_searchStartDate IS NULL THEN dateFilterStmt := '';
ELSE dateFilterStmt := ' AND TO_CHAR(' || dateField || ', ''YYYY-MM-DD'') BETWEEN ''' || v_searchStartDate || ''' AND ';
IF v_searchEndDate IS NOT NULL THEN dateFilterStmt := dateFilterStmt || '''' || v_searchEndDate || '''';
ELSE dateFilterStmt := dateFilterStmt || '(SELECT TO_CHAR(SYSDATE, ''YYYY-MM-DD'') FROM DUAL)';
END IF;
END IF;
sqlStmt := 'SELECT ar."requestId", ar."recordId", ar."module", ar."feature", ar."expAPIOperationName", ar."expAPINickName", ar."permissionId", ar."permissionName", cru."Username" as createdby, ar."createdts", ar."status", cku."Username" as checkedBy, ar."checkedts", ar."reason"
                    FROM "approvalrequests" ar
                    LEFT JOIN "systemuser"  cru ON cru."id" = ar."createdby"
                    LEFT JOIN "systemuser" cku ON cku."id" = ar."checkedBy"
                  WHERE  ar."checkedBy" = ''' || v_userId || '''';
IF v_moduleListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar."module" IN (' || v_moduleListArr || ')';
END IF;
IF v_featureListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar."feature" IN (' || v_featureListArr || ')';
END IF;
IF v_actionListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar."expAPINickName" IN (' || v_actionListArr || ')';
END IF;
sqlStmt := sqlStmt || dateFilterStmt;
sqlStmt := sqlStmt || ' ORDER BY ';
IF(
  sortParam IS NOT NULL 
  AND sortParam IN ('ar."status"', dateField)
) THEN sqlStmt := sqlStmt || sortParam;
ELSE sqlStmt := sqlStmt || dateField;
END IF;
IF(
  v_sortOrder IS NOT NULL 
  AND (
    UPPER(v_sortOrder)
  ) IN ('DESC', 'ASC')
) THEN sqlStmt := sqlStmt || ' ' || v_sortOrder;
ELSE sqlStmt := sqlStmt || ' ' || 'DESC';
END IF;
OPEN "approvalrequests" FOR sqlStmt;
END;
/

--  DDL for Procedure fetch_approvalgroups_for_pendingtxn_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_approvalgroups_for_pendingtxn_proc" (
  "signatorygroup" OUT SYS_REFCURSOR
) AS BEGIN OPEN "signatorygroup" FOR 
SELECT 
  "signatorygroup"."signatoryGroupId" 
FROM 
  "signatorygroup" 
WHERE 
  "signatorygroup"."signatoryGroupId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(
          (
            SELECT 
              LISTAGG(
                REPLACE(
                  REPLACE(
                    REPLACE(s."pendingGroupList", ']', ' '), 
                    '[', 
                    ' '
                  ), 
                  '"', 
                  ' '
                ), 
                ','
              ) 
            FROM 
              "signatorygrouprequestmatrix" S 
              JOIN "bbrequest" b ON (S."requestId" = b."requestId") 
            WHERE 
              s."isApproved" = 'false' 
              AND b."status" = 'Pending'
          )
        )
      )
  );
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_approvalmatrixtemplate_proc


create or replace NONEDITIONABLE PROCEDURE         "fetch_approvalmatrixtemplate_proc" (
  "_contractId" IN VARCHAR2, "_cif" IN VARCHAR2, 
  "_limitTypeId" IN VARCHAR2, "_actions" IN VARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS v__cif VARCHAR2(50) := "_cif";
v__limitTypeId VARCHAR2(50) := "_limitTypeId";
v_isGroupMatrix NUMBER(10, 0);
v_legalEntityId VARCHAR2(255);
BEGIN IF "_cif" IS NULL THEN BEGIN v__cif := '%';
END;
END IF;
BEGIN 
SELECT 
  "companyLegalUnit" INTO v_legalEntityId 
FROM 
  "contractcorecustomers" 
WHERE 
  "coreCustomerId" = "_cif" 
  AND "contractId" = "_contractId";
EXCEPTION WHEN NO_DATA_FOUND THEN v_legalEntityId := '';
END;
IF v__limitTypeId IS NULL THEN BEGIN v__limitTypeId := '%';
END;
END IF;
BEGIN 
SELECT 
  "isGroupLevel" INTO v_isGroupMatrix 
FROM 
  "approvalmode" 
WHERE 
  "contractId" = "_contractId" 
  AND "coreCustomerId" = "_cif";
EXCEPTION WHEN NO_DATA_FOUND THEN v_isGroupMatrix := '';
END;
IF v_isGroupMatrix IS NULL THEN BEGIN v_isGroupMatrix := 0;
END;
END IF;
dbms_output.put_line('v_isGroupMatrix'||v_isGroupMatrix);
dbms_output.put_line('v_legalEntityId'||v_legalEntityId);
dbms_output.put_line('_contractId'||"_contractId");
dbms_output.put_line('_cif'||"_cif");
dbms_output.put_line('v__limitTypeId'||v__limitTypeId);
dbms_output.put_line('_actions'||"_actions");
IF v_isGroupMatrix = 0 THEN BEGIN OPEN "records" FOR 
SELECT 
  approvalmatrixtemplate."id", 
  approvalmatrixtemplate."contractId", 
  approvalmatrixtemplate."limitTypeId", 
  featureaction."id" "actionId", 
  featureaction."name" "actionName", 
  featureaction."description" "actionDescription", 
  featureaction."Feature_id" "featureId", 
  featureaction."Type_id" "actionType", 
  featureaction."isAccountLevel" "isAccountLevel", 
  feature."name" "featureName", 
  feature."Status_id" "fifeaturestatus", 
  approvalrule."id" "approvalruleId", 
  approvalrule."numberOfApprovals", 
  approvalrule."name" "approvalRuleName", 
  approvalmatrixtemplate."lowerlimit", 
  approvalmatrixtemplate."upperlimit", 
  approvalmatrixtemplate."currency", 
  customer."id" "customerId", 
  customer."FirstName" "firstName", 
  customer."LastName" "lastName", 
  contractcorecustomers."coreCustomerId" "cifId", 
  contractcorecustomers."coreCustomerName" "cifName", 
  approvalmatrixtemplate."invalid", 
  approvalmatrixtemplate."isGroupMatrix" 
FROM 
  (
    (
      (
        (
          (
            (
              (
                "approvalmatrixtemplate" approvalmatrixtemplate 
                LEFT JOIN "customerapprovalmatrixtemplate" customerapprovalmatrixtemplate ON approvalmatrixtemplate."id" = customerapprovalmatrixtemplate."approvalMatrixId"
              ) 
              LEFT JOIN "customer" customer ON customerapprovalmatrixtemplate."customerId" = customer."id"
            ) 
            LEFT JOIN "featureaction" featureAction ON approvalmatrixtemplate."actionId" = featureAction."id"
          ) 
          LEFT JOIN "approvalrule" approvalRule ON approvalmatrixtemplate."approvalruleId" = approvalRule."id"
        ) 
        LEFT JOIN "feature" feature ON featureaction."Feature_id" = feature."id"
      ) 
      LEFT JOIN "contractfeatures" contractfeatures ON feature."id" = contractfeatures."featureId" 
      AND approvalmatrixtemplate."contractId" = contractfeatures."contractId" 
      AND approvalmatrixtemplate."coreCustomerId" = contractfeatures."coreCustomerId"
    ) 
    LEFT JOIN "contractcorecustomers" contractcorecustomers ON approvalmatrixtemplate."contractId" = contractcorecustomers."contractId" 
    AND approvalmatrixtemplate."coreCustomerId" = contractcorecustomers."coreCustomerId"
  ) 
WHERE 
  approvalmatrixtemplate."contractId" = "_contractId" 
  AND approvalmatrixtemplate."coreCustomerId" LIKE "_cif" 
  AND approvalmatrixtemplate."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT("_actions")
      )
  ) 
  AND approvalmatrixtemplate."limitTypeId" LIKE v__limitTypeId 
  AND approvalmatrixtemplate."softdeleteflag" = 0 
  AND featureaction."approveFeatureAction" IS NOT NULL 
  AND featureaction."status" = 'SID_ACTION_ACTIVE' 
  AND featureaction."companyLegalUnit" = v_legalEntityId 
  AND feature."companyLegalUnit" = v_legalEntityId 
ORDER BY 
  approvalmatrixtemplate."contractId", 
  approvalmatrixtemplate."coreCustomerId", 
  approvalmatrixtemplate."limitTypeId", 
  approvalmatrixtemplate."actionId", 
  approvalmatrixtemplate."lowerlimit";
--DBMS_SQL.RETURN_RESULT(v_cursor);
END;
ELSE IF v_isGroupMatrix = 1 THEN BEGIN -- SQLINES LICENSE FOR EVALUATION USE ONLY
OPEN "records" FOR 
SELECT 
  approvalmatrixtemplate."id", 
  approvalmatrixtemplate."contractId", 
  approvalmatrixtemplate."limitTypeId", 
  featureaction."id" "actionId", 
  featureaction."name" "actionName", 
  featureaction."description" "actionDescription", 
  featureaction."Feature_id" "featureId", 
  featureaction."Type_id" "actionType", 
  featureaction."isAccountLevel" "isAccountLevel", 
  feature."name" "featureName", 
  feature."Status_id" "fifeaturestatus", 
  approvalrule."id" "approvalruleId", 
  approvalrule."numberOfApprovals", 
  approvalrule."name" "approvalRuleName", 
  approvalmatrixtemplate."lowerlimit", 
  approvalmatrixtemplate."upperlimit", 
  approvalmatrixtemplate."currency", 
  signatorygroupmatrixtemplate."groupList" "groupList", 
  signatorygroupmatrixtemplate."groupRule" "groupRule", 
  contractcorecustomers."coreCustomerId" "cifId", 
  contractcorecustomers."coreCustomerName" "cifName", 
  approvalmatrixtemplate."invalid", 
  approvalmatrixtemplate."isGroupMatrix" 
FROM 
  (
    (
      (
        (
          (
            (
              "approvalmatrixtemplate" approvalmatrixtemplate 
              LEFT JOIN "signatorygroupmatrixtemplate" signatorygroupmatrixtemplate ON approvalmatrixtemplate."id" = signatorygroupmatrixtemplate."approvalMatrixId"
            ) 
            LEFT JOIN "featureaction" featureAction ON approvalmatrixtemplate."actionId" = featureAction."id"
          ) 
          LEFT JOIN "approvalrule" approvalRule ON approvalmatrixtemplate."approvalruleId" = approvalRule."id"
        ) 
        LEFT JOIN "feature" feature ON featureAction."Feature_id" = feature."id"
      ) 
      LEFT JOIN "contractfeatures" contractfeatures ON feature."id" = contractfeatures."featureId" 
      AND approvalmatrixtemplate."contractId" = contractfeatures."contractId" 
      AND approvalmatrixtemplate."coreCustomerId" = contractfeatures."coreCustomerId"
    ) 
    LEFT JOIN "contractcorecustomers" contractcorecustomers ON approvalmatrixtemplate."contractId" = contractcorecustomers."contractId" 
    AND approvalmatrixtemplate."coreCustomerId" = contractcorecustomers."coreCustomerId"
  ) 
WHERE 
  approvalmatrixtemplate."contractId" = "_contractId" 
  AND approvalmatrixtemplate."coreCustomerId" LIKE "_cif" 
  AND approvalmatrixtemplate."isGroupMatrix" = 1 
  AND approvalmatrixtemplate."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT("_actions")
      )
  ) 
  AND approvalmatrixtemplate."limitTypeId" LIKE v__limitTypeId 
  AND approvalmatrixtemplate."softdeleteflag" = 0 
  AND featureaction."approveFeatureAction" IS NOT NULL 
  AND featureaction."status" = 'SID_ACTION_ACTIVE' 
  AND featureaction."companyLegalUnit" = v_legalEntityId 
  AND feature."companyLegalUnit" = v_legalEntityId 
ORDER BY 
  approvalmatrixtemplate."contractId", 
  approvalmatrixtemplate."coreCustomerId", 
  approvalmatrixtemplate."limitTypeId", 
  approvalmatrixtemplate."actionId", 
  approvalmatrixtemplate."lowerlimit";
--DBMS_SQL.RETURN_RESULT(v_cursor);
END;
END IF;
END IF;
--EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE,SQLERRM);
END;
/

--  DDL for Procedure fetch_approvalqueue_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_approvalqueue_proc" (
  "_customerId" IN VARCHAR2, "_transactionIds" IN VARCHAR2, 
  "_requestIds" IN VARCHAR2, "_featureactionlist" IN VARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS v__transactionIds VARCHAR2(4000) := "_transactionIds";
v__requestIds VARCHAR2(4000) := "_requestIds";
BEGIN DECLARE v_combinedIds CLOB;
v_alreadyApprovedIds CLOB;
v_companyId CLOB;
v_customerMatrixIds CLOB;
v_customerGroupIds CLOB;
v_approvalRequestIds CLOB;
v_features CLOB;
v_monetaryActions CLOB;
v_groupIds VARCHAR2(4000);
v_strLen VARCHAR2(20);
v_reqIds VARCHAR2(4000);
v_SubStrLen VARCHAR2(20);
v_CurrentGroupId VARCHAR2(4000);
v_PendingGroupList VARCHAR2(4000);
v_requestIds VARCHAR2(4000);
v_companyRequestIds VARCHAR2(4000);
v_query VARCHAR2(4000);
v_select_statement VARCHAR2(4000);
BEGIN --      /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  LISTAGG("customer"."id") INTO v_combinedIds 
FROM 
  "customer" 
WHERE 
  "customer"."combinedUserId" = "_customerId";
IF v_combinedIds IS NULL THEN v_combinedIds := "_customerId";
ELSE v_combinedIds := (
  "_customerId" || ',' || v_combinedIds
);
END IF;
IF (
  v_combinedIds IS NULL 
  OR v_combinedIds = ''
) THEN v_combinedIds := ' ';
ELSE v_combinedIds := v_combinedIds;
END IF;
IF (
  v__transactionIds IS NULL 
  OR v__transactionIds = ''
) THEN v__transactionIds := ' ';
ELSE v__transactionIds := v__transactionIds;
END IF;
IF (
  v__requestIds IS NULL 
  OR v__requestIds = ''
) THEN v__requestIds := ' ';
ELSE v__requestIds := v__requestIds;
END IF;
IF (
  "_featureactionlist" IS NULL 
  OR "_featureactionlist" = ''
) THEN RETURN;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customerapprovalmatrix"."approvalMatrixId" AS varchar2(255)
    )
  ) INTO v_customerMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."customerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds, ',')
      )
  );
IF v_customerMatrixIds IS NULL THEN v_customerMatrixIds := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customersignatorygroup"."signatoryGroupId" AS varchar2(255)
    )
  ) INTO v_customerGroupIds 
FROM 
  "customersignatorygroup" 
WHERE 
  "customersignatorygroup"."customerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds, ',')
      )
  );
IF v_customerGroupIds IS NULL THEN v_customerGroupIds := ' ';
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbactedrequest"."requestId" AS varchar2(255)
    )
  ) INTO v_alreadyApprovedIds 
FROM 
  "bbactedrequest" 
WHERE 
  "bbactedrequest"."createdby" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds, ',')
      )
  ) 
  AND "bbactedrequest"."action" != 'Pending' 
  AND "bbactedrequest"."softdeleteflag" = 0;
IF v_alreadyApprovedIds IS NULL THEN v_alreadyApprovedIds := ' ';
END IF;
IF v_customerMatrixIds = '' THEN v_approvalRequestIds := ' ';
ELSE 
SELECT 
  LISTAGG(
    CAST(
      "RQAMX"."requestId" AS varchar2(255)
    )
  ) INTO v_approvalRequestIds 
FROM 
  "requestapprovalmatrix" "RQAMX" 
  JOIN "approvalmatrix" "APMX" ON (
    "RQAMX"."approvalMatrixId" = "APMX"."id" 
    AND "APMX"."id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT(v_customerMatrixIds, ',')
        )
    )
  ) 
  JOIN "approvalrule" "APRL" ON (
    "APMX"."approvalruleId" = "APRL"."id"
  ) 
WHERE 
  "RQAMX"."isGroupRule" = 0 
  AND "RQAMX"."approvalMatrixId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_customerMatrixIds, ',')
      )
  ) 
  AND "RQAMX"."requestId" NOT IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_alreadyApprovedIds, ',')
      )
  ) 
  AND (
    (
      "APRL"."numberOfApprovals" = -1 
      AND "RQAMX"."receivedApprovals" < (
        SELECT 
          COUNT(
            DISTINCT (
              "customerapprovalmatrix"."customerId"
            )
          ) 
        FROM 
          "customerapprovalmatrix" 
        WHERE 
          "customerapprovalmatrix"."approvalMatrixId" = "RQAMX"."approvalMatrixId"
      )
    ) 
    OR (
      "APRL"."numberOfApprovals" != -1 
      AND "RQAMX"."receivedApprovals" < "APRL"."numberOfApprovals"
    )
  );
END IF;
IF v_approvalRequestIds IS NULL THEN v_approvalRequestIds := ' ';
END IF;
-- GROUP BASED APPROVAL Trxns
v_groupIds := v_customerGroupIds;
v_PendingGroupList := ' ';
<< do_this >> WHILE 1 = 1 LOOP BEGIN v_strLen := LENGTH(v_groupIds);
v_CurrentGroupId := UTILS.SUBSTRING_INDEX(v_groupIds, ',', 1);
IF v_CurrentGroupId != '' THEN BEGIN v_CurrentGroupId := '%' || v_CurrentGroupId || '%';
IF v_PendingGroupList = '' THEN v_PendingGroupList := ' "signatorygrouprequestmatrix"."pendingGroupList" LIKE ''' || v_CurrentGroupId || '''';
ELSE v_PendingGroupList := v_PendingGroupList || ' OR "signatorygrouprequestmatrix"."pendingGroupList" LIKE ''' || v_CurrentGroupId || '''';
END IF;
END;
END IF;
v_SubStrLen := LENGTH(
  UTILS.SUBSTRING_INDEX(v_groupIds, ',', 1)
);
v_groupIds := SUBSTR(
  v_groupIds, 
  TO_NUMBER(v_SubStrLen, 10, 0) + 2, 
  TO_NUMBER(v_strLen, 10, 0)
);
IF LENGTH(v_groupIds) <= 0 THEN BEGIN EXIT;
END;
END IF;
END;
END LOOP;
IF v_PendingGroupList != '' THEN DECLARE v_sql_stmt VARCHAR2(4000);
BEGIN v_sql_stmt := ' SELECT v_reqIds_out = (LISTAGG(CAST("signatorygrouprequestmatrix"."requestId" as varchar2(255))))
                     FROM "signatorygrouprequestmatrix" WHERE "signatorygrouprequestmatrix"."isApproved" = 0 AND ( ' || v_PendingGroupList || ' ) ;';
OPEN "records" FOR v_sql_stmt;
--         sp_executesql(v_sql_stmt,
--                       '@reqIds_out NVARCHAR(MAX) OUTPUT',
--                       v_reqIds_out => v_reqIds) ;
END;
END IF;
IF v_reqIds IS NULL THEN v_reqIds := ' ';
END IF;
IF (
  v_approvalRequestIds = '' 
  OR v_approvalRequestIds IS NULL
) THEN v_approvalRequestIds := v_reqIds;
ELSE BEGIN IF v_reqIds != '' THEN v_approvalRequestIds := (
  v_approvalRequestIds || ',' || v_reqIds
);
END IF;
END;
END IF;
v_approvalRequestIds := (v_approvalRequestIds);
-- Remove duplicates
v_query := ' ';
IF (v__transactionIds != '') THEN BEGIN 
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."Feature_id" AS varchar2(255)
    )
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT("_featureactionlist", ',')
      )
  );
IF v_features IS NULL THEN v_features := ' ';
END IF;
IF v_features != '' THEN 
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS varchar2(255)
    )
  ) INTO v_monetaryActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features, ',')
      )
  );
END IF;
IF v_monetaryActions IS NULL THEN v_monetaryActions := ' ';
END IF;
IF v_monetaryActions != '' THEN v_query := ' "bbrequest"."transactionId" IN ( select VALUE from UTILS.STRING_SPLIT(''' || v__transactionIds || ''', '','')) AND "bbrequest"."featureActionId" IN (select value FROM UTILS.STRING_SPLIT(''' || v_monetaryActions || ''', '','')) ';
END IF;
END;
ELSE BEGIN IF v__requestIds = '' THEN BEGIN 
SELECT 
  LISTAGG(
    CAST(
      (
        "contractcustomers"."contractId" || '_' || "contractcustomers"."coreCustomerId"
      ) AS varchar2(255)
    )
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = "_customerId";
IF v_companyId IS NULL THEN v_companyId := ' ';
ELSE v_companyId := (v_companyId);
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."Feature_id" AS varchar2(255)
    )
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT("_featureactionlist", ',')
      )
  );
IF v_features IS NULL THEN v_features := ' ';
END IF;
IF v_features != '' THEN 
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS varchar2(255)
    )
  ) INTO v_monetaryActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features, ',')
      )
  );
END IF;
IF v_monetaryActions IS NULL THEN v_monetaryActions := ' ';
END IF;
IF v_companyId != '' 
AND v_monetaryActions != '' THEN v_query := ' "bbrequest"."companyId" IN (SELECT value FROM UTILS.STRING_SPLIT(''' || v_companyId || ''', '','')) and "bbrequest"."featureActionId" IN (select value FROM UTILS.STRING_SPLIT(''' || v_monetaryActions || ''', '',''))';
END IF;
END;
ELSE BEGIN v_requestIds := v__requestIds;
IF v_requestIds != '' THEN v_query := ' "bbrequest"."requestId" IN ( select VALUE from UTILS.STRING_SPLIT(''' || v_requestIds || ''', '','')) ';
END IF;
END;
END IF;
END;
END IF;
IF v_query != '' THEN v_select_statement := 'If(OBJECT_ID(''tempdb..#temp_customeraction'') Is Not Null) BEGIN
                      Drop Table #temp_customeraction;
                      DROP INDEX IF EXISTS idx_temp_customeraction ON #temp_customeraction;
                      END;

                    CREATE TABLE #temp_customeraction(
                      id VARCHAR(65),
                      Account_id VARCHAR(65),
                      Action_id VARCHAR(65),
                      companyId VARCHAR(40));

                    CREATE INDEX idx_temp_customeraction ON #temp_customeraction (Account_id, Action_id, companyId);

                      INSERT INTO #temp_customeraction
                      SELECT
                      "customeraction"."id",
                      "customeraction"."Account_id",
                      "customeraction"."Action_id",
                      ("customeraction"."contractId" + ''_'' + "customeraction"."coreCustomerId") as companyId
                      from customeraction
                      where
                      "customeraction"."Customer_id" IN (select VALUE FROM UTILS.STRING_SPLIT(''' || v_combinedIds || ''', '','')) and
                      "customeraction"."isAllowed" = 1 AND
                      "customeraction"."softdeleteflag" = 0;

                  SELECT
                  "bbrequest"."requestId",
                  "bbrequest"."transactionId",
                  "bbrequest"."status",
                  "bbrequest"."featureActionId",
                  "bbrequest"."isGroupMatrix",
            "bbrequest"."additionalMeta",

                  (CASE
                  WHEN (select COUNT(1) FROM UTILS.STRING_SPLIT(''' || v_combinedIds || ''', '','') where value = "bbrequest"."createdby") > 0
                  THEN ''true''
                  ELSE ''false''
                  END) as amICreator,

                  (CASE
                  WHEN
                  ((select COUNT(1) FROM UTILS.STRING_SPLIT(''' || v_approvalRequestIds || ''', '','') WHERE VALUE = "bbrequest"."requestId") > 0) AND                                             
                  ((select TOP 1 #temp_customeraction.id
                  from #temp_customeraction
                  where
                  #temp_customeraction.Account_id = "bbrequest".accountId AND
                  #temp_customeraction.Action_id = (select "featureaction"."approveFeatureAction"  from "featureaction" 
                      where "featureaction"."id" = "bbrequest"."featureActionId") AND #temp_customeraction.companyId = "bbrequest"."companyId") IS NOT NULL)
                  THEN ''true''
                  ELSE ''false''
                  END) as amIApprover,

                  (CASE
                  WHEN (select COUNT(1) FROM UTILS.STRING_SPLIT(''' || v_alreadyApprovedIds || ''', '','') WHERE VALUE = "bbrequest"."requestId") > 0
                  THEN ''true''
                  ELSE ''false''
                  END) as actedByMeAlready,

              (select count(DISTINCT("createdby")) from
              "bbactedrequest" where "bbactedrequest"."action" = ''Approved'' AND 
              "bbactedrequest"."requestId" = "bbrequest"."requestId" AND "bbactedrequest"."softdeleteflag" = 0)
              as receivedApprovals,

              null as requiredApprovals

              FROM
              "bbrequest" WHERE ' || v_query;
END IF;
IF v_select_statement IS NULL THEN RETURN;
END IF;
EXECUTE IMMEDIATE v_select_statement;
END;
--   <<MAINLABEL$leave>>
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_approvalrequests_counts_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_approvalrequests_counts_proc" (
  v__permissionListArr IN VARCHAR2, 
  v__userId IN VARCHAR2, "records" OUT SYS_REFCURSOR
) AS v_req_pending_status VARCHAR2(4000);
v_execStmt VARCHAR2(4000);
BEGIN v_req_pending_status := 'Pending For Approval';
-- set it to the current string used to denote the Pending status
v_execStmt := (
  '
       select ''pendingRequests'' as category, count(*) as counts from "approvalrequests" where "createdby" = ''' || v__userId || ''' and "status" = ''' || v_req_pending_status || '''
       union
       select ''requestHistory'' as category, count(*) as counts from "approvalrequests" where "createdby" = ''' || v__userId || '''
       union
       select ''approvalHistory'' as category, count(*) as counts from "approvalrequests" where "checkedBy" = ''' || v__userId || '''
       union
       select ''pendingApprovals'' as category, count(*) as counts from "approvalrequests" where "status" = ''' || v_req_pending_status || ''' and "createdby" != ''' || v__userId || ''' and "expAPIOperationName" in 
       (select "expAPIOperationName" from "permissionapprovals" where "approvalPermissionName" in (' || v__permissionListArr || '))'
);
EXECUTE IMMEDIATE v_execStmt;
OPEN "records" FOR v_execStmt;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_approvers_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_approvers_proc" (
  v__requestId IN VARCHAR2, "customerapprovalmatrix" OUT SYS_REFCURSOR
) AS BEGIN OPEN "customerapprovalmatrix" FOR 
SELECT 
  "customerapprovalmatrix"."customerId" customerId 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerapprovalmatrix"."approvalMatrixId" IN (
    SELECT 
      "requestapprovalmatrix"."approvalMatrixId" 
    FROM 
      "requestapprovalmatrix" 
    WHERE 
      "requestapprovalmatrix"."requestId" = v__requestId
  );
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_bbtemplate_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_bbtemplate_proc" (
  v__customerId IN VARCHAR2, iv__templateId IN VARCHAR2, 
  v__featureactionlist IN VARCHAR2, 
  v__queryType IN VARCHAR2, iv__filterByParam IN VARCHAR2, 
  iv__filterByValue IN VARCHAR2, v__searchString IN VARCHAR2, 
  iv__sortByParam IN VARCHAR2, iv__sortOrder IN VARCHAR2, 
  v__pageSize IN VARCHAR2, v__pageOffset IN VARCHAR2, 
  "bbrequest" OUT SYS_REFCURSOR
) AS v__filterByParam VARCHAR2(4000) := iv__filterByParam;
v__filterByValue VARCHAR2(4000) := iv__filterByValue;
v__templateId VARCHAR2(50) := iv__templateId;
v__sortByParam VARCHAR2(50) := iv__sortByParam;
v__sortOrder VARCHAR2(50) := iv__sortOrder;
v_approvalCount1_3 VARCHAR2(4000);
v_approvalCount2_3 VARCHAR2(4000);
BEGIN DECLARE v_group_concat_max_len NUMBER(19, 0);
v_combinedIds CLOB;
v_numOfParams NUMBER(10, 0);
v_searchQuery VARCHAR2(4000);
v_idx NUMBER(10, 0);
v_filterParam VARCHAR2(4000);
v_filterValue VARCHAR2(4000);
v_companyId CLOB;
v_customerMatrixIds CLOB;
v_alreadyApprovedIds CLOB;
v_approvalRequestIds CLOB;
v_queryTypecondition VARCHAR2(4000);
v_paginationQuery VARCHAR2(4000);
v_features CLOB;
v_createActions CLOB;
v_companyRequestIds CLOB;
v_customerAcounts CLOB;
v_select_statement VARCHAR2(4000);
BEGIN << MAINLABEL >> --      /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_group_concat_max_len := 100000000;
SELECT 
  LISTAGG("id", ',') INTO v_combinedIds 
FROM 
  "customer" 
WHERE 
  "combinedUserId" = v__customerId;
IF v_combinedIds IS NULL THEN v_combinedIds := v__customerId;
ELSE v_combinedIds := (
  v__customerId || ',' || v_combinedIds
);
END IF;
v__filterByParam := CASE WHEN v__filterByParam IS NULL 
OR v__filterByParam = '' THEN ' ' ELSE v__filterByParam END;
v__filterByValue := CASE WHEN v__filterByValue IS NULL 
OR v__filterByValue = '' THEN ' ' ELSE v__filterByValue END;
v__templateId := CASE WHEN v__templateId = '' 
OR v__templateId IS NULL THEN '%' ELSE v__templateId END;
v_numOfParams := 0;
IF LENGTHB(v__filterByParam) > 0 THEN v_numOfParams := LENGTHB(v__filterByParam) - LENGTHB(
  REPLACE(v__filterByParam, ',', ' ')
) + 1;
END IF;
v_searchQuery := ' ';
v_idx := 1;
WHILE (v_idx <= v_numOfParams) LOOP BEGIN v_filterParam := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__filterByParam, ',', v_idx), 
  ',', 
  -1
);
v_filterValue := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__filterByValue, ',', v_idx), 
  ',', 
  -1
);
v_searchQuery := v_searchQuery || ' AND (' || v_filterParam || ' LIKE ''' || v_filterValue || ''' )';
v_idx := v_idx + 1;
END;
END LOOP;
SELECT 
  LISTAGG(
    CAST(
      (
        trim(
          "contractcustomers"."contractId"
        )|| '_' || trim(
          "contractcustomers"."coreCustomerId"
        )
      ) AS varchar2(255)
    ), 
    ','
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = v__customerId;
IF v_companyId IS NULL THEN BEGIN v_companyId := ' ';
END;
END IF;
IF v__featureactionlist IS NULL THEN BEGIN RETURN;
END;
END IF;
v__sortByParam := CASE WHEN v__sortByParam = '' 
OR v__sortByParam IS NULL THEN 'createdts' ELSE v__sortByParam END;
v__sortOrder := CASE WHEN v__sortOrder = '' 
OR v__sortOrder IS NULL THEN 'DESC' ELSE v__sortOrder END;
SELECT 
  LISTAGG(
    CAST(
      "approvalMatrixId" AS varchar2(255)
    ), 
    ','
  ) INTO v_customerMatrixIds 
FROM 
  "customerapprovalmatrix" 
WHERE 
  "customerId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  );
IF v_customerMatrixIds IS NULL THEN BEGIN v_customerMatrixIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_alreadyApprovedIds 
FROM 
  "bbactedrequest" 
WHERE 
  "createdby" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_combinedIds)
      )
  ) 
  AND "bbactedrequest"."action" = 'Approved';
IF v_alreadyApprovedIds IS NULL THEN BEGIN v_alreadyApprovedIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_approvalRequestIds 
FROM 
  "requestapprovalmatrix" 
  JOIN "approvalmatrix" ON "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" 
  JOIN "approvalrule" ON "approvalmatrix"."approvalruleId" = "approvalrule"."id" 
WHERE 
  CAST(
    "requestapprovalmatrix"."approvalMatrixId" AS varchar2(255)
  ) IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_customerMatrixIds)
      )
  ) 
  AND CAST(
    "requestapprovalmatrix"."requestId" AS varchar2(255)
  ) NOT IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_alreadyApprovedIds)
      )
  ) 
  AND (
    (
      "approvalrule"."numberOfApprovals" = -1 
      AND "requestapprovalmatrix"."receivedApprovals" < (
        SELECT 
          COUNT(
            DISTINCT ("customerId")
          ) 
        FROM 
          "customerapprovalmatrix" 
        WHERE 
          "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
      )
    )
  );
IF v_approvalRequestIds IS NULL THEN BEGIN v_approvalRequestIds := ' ';
END;
END IF;
v_queryTypecondition := CASE WHEN (v__queryType = 'myRequests') THEN (
  ' AND  "bbtemplate"."createdby" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || (v_combinedIds) || '''))) AND ("bbrequest"."status" = ''Pending'' OR "bbrequest"."status" = ''Approved'' OR "bbrequest"."status" = ''Rejected'') '
) ELSE CASE WHEN (
  v__queryType = 'pendingForMyApprovals'
) THEN (
  ' AND "bbtemplate"."requestId"  IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_approvalRequestIds || ''')))  AND "bbtemplate"."status" = ''Pending'' '
) ELSE CASE WHEN v__templateId = '%' THEN ' AND NOT "bbtemplate"."status" = ''Withdrawn''' ELSE ' ' END END END;
v_searchQuery := CASE WHEN (
  v__searchString IS NULL 
  OR v__searchString = ''
) THEN v_searchQuery ELSE v_searchQuery || ' AND ("bbtemplate"."templateName" LIKE ''%' || v__searchString || '%'' OR "customeraccounts"."AccountName" LIKE ''%' || v__searchString || '%'' OR "bbtemplaterequesttype"."templateRequestTypeName" LIKE ''%' || v__searchString || '%'' OR "bbtemplate"."fromAccount" LIKE ''%' || v__searchString || '%'')' END;
v_paginationQuery := CASE WHEN (
  v__pageOffset IS NULL 
  OR v__pageOffset = '' 
  OR v__pageSize IS NULL 
  OR v__pageSize = ''
) THEN ' ' ELSE ' OFFSET ' || v__pageOffset || '  ROWS FETCH NEXT ' || v__pageSize || ' ROWS ONLY' END;
SELECT 
  LISTAGG(
    CAST(
      "Feature_id" AS varchar2(255)
    ), 
    ','
  ) INTO v_features 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__featureactionlist)
      )
  );
IF v_features IS NULL THEN BEGIN v_features := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS varchar2(255)
    ), 
    ','
  ) INTO v_createActions 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."Feature_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_features)
      )
  ) 
  AND "featureaction"."id" LIKE '%_CREATE_TEMPLATE';
IF v_createActions IS NULL THEN BEGIN v_createActions := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "bbrequest"."requestId" AS varchar2(255)
    ), 
    ','
  ) INTO v_companyRequestIds 
FROM 
  "bbrequest" 
WHERE 
  "bbrequest"."companyId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_companyId)
      )
  ) 
  AND "bbrequest"."featureActionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_createActions)
      )
  );
IF v_companyRequestIds IS NULL THEN BEGIN v_companyRequestIds := ' ';
END;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "customeraccounts"."Account_id" AS varchar2(255)
    ), 
    ','
  ) INTO v_customerAcounts 
FROM 
  "customeraccounts" 
WHERE 
  "customeraccounts"."Customer_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__customerId)
      )
  );
IF v_customerAcounts IS NULL THEN BEGIN v_customerAcounts := ' ';
END;
END IF;
--      DELETE FROM tt_approvalCount1_3;
--      UTILS.IDENTITY_RESET('tt_approvalCount1_3');
v_approvalCount1_3 := '( 
        SELECT customerCnt ,
              "requestId" 
          FROM ( SELECT COUNT(DISTINCT ("customerId"))  customerCnt  ,
                       "requestapprovalmatrix"."requestId" requestId  
                FROM "customerapprovalmatrix" 
                       JOIN "requestapprovalmatrix"    ON ( "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                 WHERE  CAST("requestapprovalmatrix"."requestId" AS varchar2(255)) IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_companyRequestIds)))
                  GROUP BY "requestapprovalmatrix"."requestId" ) approvalCount1 )';
--      DELETE FROM tt_approvalCount2_3;
--      UTILS.IDENTITY_RESET('tt_approvalCount2_3');
v_approvalCount2_3 := '( 
        SELECT "requestId" ,
              totalCnt 
          FROM ( SELECT "requestId" ,
                       SUM(t)  totalCnt  
                FROM ( SELECT "bbrequest"."requestId" requestId  ,
                              CASE 
                                   WHEN "approvalrule"."numberOfApprovals" = -1 THEN ( SELECT COUNT(*)  
          FROM "customerapprovalmatrix" 
         WHERE  "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId" )
                                   WHEN "approvalrule"."numberOfApprovals" IS NULL
                                     OR "approvalrule"."numberOfApprovals" = '''' THEN 0
                              ELSE "approvalrule"."numberOfApprovals"
                                 END t  
                       FROM "customerapprovalmatrix" 
                              LEFT JOIN "requestapprovalmatrix"    ON "customerapprovalmatrix"."approvalMatrixId" = "requestapprovalmatrix"."approvalMatrixId"
                              LEFT JOIN "bbrequest"    ON ( "bbrequest"."requestId" = "requestapprovalmatrix"."requestId" )
                              LEFT JOIN "approvalmatrix"    ON ( "requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id" )
                              LEFT JOIN "approvalrule"    ON ( "approvalmatrix"."approvalruleId" = "approvalrule"."id" )
                        WHERE CAST("bbrequest"."requestId" AS varchar2(255)) IN (SELECT COLUMN_VALUE FROM TABLE(UTILS.STRING_SPLIT(v_companyRequestIds))) ) approvals
                  GROUP BY "requestId" ) approvalCount2 )';
v_select_statement := '
          SELECT * FROM
                (SELECT 
                  "bbtemplate"."templateId" AS templateId,
                  "bbtemplate"."templateName" AS templateName,
                  "bbtemplate"."templateDescription" AS templateDescription,
                  "bbtemplate"."featureActionId" AS featureActionId,
                  "bbtemplate"."fromAccount" AS fromAccount,
                  "bbtemplate"."effectiveDate" AS effectiveDate,
                  "bbtemplate"."requestId" AS requestId,
                  "bbtemplate"."createdby" AS createdby,
                  "bbtemplate"."updatedBy" AS updatedBy,
                  "bbtemplate"."createdts" AS createdts,
                  "bbtemplate"."maxAmount" AS maxAmount,
                  "bbtemplate"."status" AS status,
                  "bbtemplate"."transactionType_id" AS transactionType_id,
                  "bbtemplate"."templateType_id" AS templateType_id,
                  "bbtemplate"."companyId" AS companyId,
                  "bbtemplate"."templateRequestType_id" AS templateRequestType_id,
                  "bbtemplate"."softDelete" AS softDelete,
                  "bbtemplate"."totalAmount" AS totalAmount,
                  ( 
                  CASE 
                     WHEN "customeraccounts"."AccountName" is NULL THEN ''AccountName'' 
                     ELSE "customeraccounts"."AccountName" 
                  END 
                  ) AS accountName,
                  "customer"."UserName" AS userName,
                  "bbtransactiontype"."transactionTypeName" AS transactionTypeName,
                  "bbtemplatetype"."templateTypeName" AS templateTypeName,
                  "bbtemplaterequesttype"."templateRequestTypeName" AS templateRequestTypeName,
                  "bbrequest"."createdby" AS requestCreatedby,
                  (
                  CASE
                    WHEN CAST("bbtemplate"."createdby" as varchar2(255)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_combinedIds || ''' as varchar2(4000))))) THEN ''true''
                    ELSE ''false''
                  END
                  ) as amICreator,
                  (
                  CASE 
                    WHEN CAST("bbrequest"."requestId" AS varchar2(255)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(CAST(''' || v_approvalRequestIds || ''' as varchar2(4000))))) THEN ''true''
                    ELSE ''false''
                  END
                  ) as amIApprover
                  FROM
                  (((((((bbtemplate
                  LEFT JOIN "customer" ON ("bbtemplate"."createdby" = "customer"."id"))
                  LEFT JOIN "customeraccounts" ON (("bbtemplate"."createdby" = "customeraccounts"."Customer_id") AND ("bbtemplate"."fromAccount" = "customeraccounts"."Account_id")))
                  LEFT JOIN "bbtransactiontype" ON ("bbtemplate"."transactionType_id" = "bbtransactiontype"."transactionType_id"))
                  LEFT JOIN "bbtemplatetype" ON ("bbtemplate"."templateType_id" = "bbtemplatetype"."templateType_id"))
                  LEFT JOIN "bbtemplaterequesttype" ON ("bbtemplate"."templateRequestType_id" = "bbtemplaterequesttype"."templateRequestType_id"))
                  LEFT JOIN "organisation" ON ("bbtemplate"."companyId" = "organisation"."id"))
                  LEFT JOIN "bbrequest"ON ("bbtemplate"."requestId" = "bbrequest"."requestId"))
                  WHERE "bbtemplate"."softDelete" = ''0''
                  AND ("bbtemplate"."companyId" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_companyId || ''')))  OR "bbtemplate"."createdby" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_combinedIds || '''))))
                  AND "bbtemplate"."templateId" LIKE ''' || v__templateId || '''
                  AND "bbtemplate"."fromAccount" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_customerAcounts || ''')))
                      AND "bbtemplate"."featureActionId" IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_createActions || ''')))' || v_queryTypecondition || ' ' || v_searchQuery || ' ) AS t1
                  LEFT JOIN
                  ( 
                  SELECT 
                     "bbrequest"."requestId",
                     (select count(DISTINCT("bbactedrequest"."createdby")) from "bbactedrequest" where "bbactedrequest".action = ''Approved'' AND  "bbactedrequest"."requestId" = "bbrequest"."requestId") 
                           as receivedApprovals,
                          (LEASTINT((select customerCnt from (v_approvalCount1_3) where "requestid"="bbrequest"."requestId" ),(select totalCnt from (v_approvalCount2_3) where requestid="bbrequest"."requestId" ))) as requiredApprovals
                  FROM
                  "bbrequest"
                  LEFT JOIN "requestapprovalmatrix" ON ("bbrequest"."requestId" = "requestapprovalmatrix"."requestId")
                  LEFT JOIN "approvalmatrix" ON ("requestapprovalmatrix"."approvalMatrixId" = "approvalmatrix"."id")
                  LEFT JOIN "approvalrule" ON ("approvalmatrix"."approvalruleId" = "approvalrule"."id")
                      WHERE CAST("bbrequest"."requestId" AS varchar2(255)) IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_companyRequestIds || ''')))
                  GROUP BY "bbrequest"."requestId","requestapprovalmatrix"."approvalMatrixId","approvalrule"."numberOfApprovals"
                  ) AS t2
                  ON 
                  t1.requestId = t2.requestId
                  ORDER BY ' || v__sortByParam || ' ' || v__sortOrder || ' ' || v_paginationQuery;
OPEN "bbrequest" FOR v_select_statement;
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount1_3 ';
--      EXECUTE IMMEDIATE ' TRUNCATE TABLE tt_approvalCount2_3 ';
END;
--   <<MAINLABEL$leave>>
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_contractaccounts_for_user_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_contractaccounts_for_user_proc" (
  "_contractIdList" IN NVARCHAR2, "_contractId" IN NVARCHAR2, 
  "_coreCustomerId" IN NVARCHAR2, "records" out sys_refcursor
) AS v_query NVARCHAR2(2000);
BEGIN IF (
  "_contractIdList" != '' 
  or "_contractIdList" IS NOT NULL
) THEN BEGIN v_query := (
  'select * from "contractaccounts" where "contractId" IN (select regexp_substr('
) || '''' || "_contractIdList" || '''' || (
  ',''[^,]+'', 1, level) from dual CONNECT BY LEVEL <= REGEXP_COUNT('
) || '''' || "_contractIdList" || '''' || (',''[,]'')+1)');
END;
ELSE IF (
  (
    "_contractId" IS NOT NULL 
    and LENGTH("_contractId")> 0
  ) 
  AND (
    "_coreCustomerId" IS NOT NULL 
    and LENGTH("_coreCustomerId")> 0
  )
) THEN BEGIN v_query := (
  'select * from "contractaccounts" where "contractId" = '
) || "_contractId" || (' and "coreCustomerId" =') || "_coreCustomerId" || (' ');
END;
END IF;
END IF;
open "records" for v_query;
END;
/

