--  DDL for Procedure fetch_organisation_customroles_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_organisation_customroles_proc" (
  v_organisationId IN VARCHAR2, v_customRoleId IN VARCHAR2, 
  "customrole" OUT SYS_REFCURSOR
) AS v_select_roles VARCHAR2(4000);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_select_roles := 'SELECT "customrole"."synctimestamp","customrole"."status_id","customrole"."softdeleteflag",
       "customrole"."parent_id","customrole"."organization_id","customrole"."name","customrole"."modifiedby","customrole"."lastmodifiedts",
       "customrole"."id","customrole"."description","customrole"."createdts","customrole"."createdby","customer"."UserName" as userName,
       "membergroup"."Name" as parentRoleName,"status"."Description" as statusValue FROM 
       "customrole" LEFT JOIN "customer" ON ("customrole".createdby = "customer"."id") LEFT JOIN "status" 
       ON ("customrole"."status_id" = "status"."id") LEFT JOIN "membergroup" ON ("customrole"."parent_id" = "membergroup"."id") 
       WHERE "customrole"."organization_id" = ''' || (v_organisationId) || (''' and ') || (
  '"customrole"."softdeleteflag" = 0'
);
IF (v_customRoleId = '') THEN v_select_roles := (v_select_roles);
ELSE v_select_roles := (v_select_roles) || (' and "customrole"."id" =') || (v_customRoleId);
END IF;
EXECUTE IMMEDIATE v_select_roles;
OPEN "customrole" FOR v_select_roles;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_pending_approvals_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_pending_approvals_proc" (
  v_permissionListArr IN VARCHAR2, v_userId IN VARCHAR2, 
  v_moduleListArr IN VARCHAR2, v_actionListArr IN VARCHAR2, 
  v_featureListArr IN VARCHAR2, v_searchStartDate IN VARCHAR2, 
  v_searchEndDate IN VARCHAR2, v_sortParam IN VARCHAR2, 
  v_sortOrder IN VARCHAR2, "approvalrequests" OUT SYS_REFCURSOR
) AS dateFilterStmt VARCHAR2(256);
dateField VARCHAR2(128);
req_pending_status VARCHAR2(64);
sqlStmt VARCHAR2(4000);
sortParam VARCHAR2(64);
BEGIN dateField := 'ar.createdts';
IF v_sortParam IS NOT NULL THEN sortParam := 'ar.' || v_sortParam || ' ';
END IF;
IF v_searchStartDate IS NULL THEN dateFilterStmt := '';
ELSE dateFilterStmt := ' AND TO_CHAR(' || dateField || ', ''YYYY-MM-DD'') BETWEEN ''' || v_searchStartDate || ''' AND ';
IF v_searchEndDate IS NOT NULL THEN dateFilterStmt := dateFilterStmt || '''' || v_searchEndDate || '''';
ELSE dateFilterStmt := dateFilterStmt || '(SELECT TO_CHAR(SYSDATE, ''YYYY-MM-DD'') FROM DUAL)';
END IF;
END IF;
req_pending_status := 'Pending For Approval';
sqlStmt := 'SELECT ar. "requestId" , ar. "recordId" , ar. "module" , ar. "feature" , ar. "expAPIOperationName" , ar. "expAPINickName" , ar. "permissionId" , ar. "permissionName" , cru. "Username"  asCREATEdby , ar. "createdts" , ar. "status" , cku. "Username"  as  checkedBy , ar. "checkedts" , ar. "reason" 
               FROM  "approvalrequests"  ar
                  LEFT JOIN  "systemuser"   cru ON cru. "id"  = ar. "createdby" 
                  LEFT JOIN  "systemuser"  cku ON cku. "id"  = ar. "checkedBy" 
               WHERE ar. "status"  = ''' || req_pending_status || ''' AND ar. "createdby"  != ''' || v_userId || '''';
IF v_moduleListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar. "module"  IN (' || v_moduleListArr || ')';
END IF;
IF v_featureListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar. "feature"  IN (' || v_featureListArr || ')';
END IF;
IF v_actionListArr IS NOT NULL THEN sqlStmt := sqlStmt || ' AND ar. "expAPINickName"  IN (' || v_actionListArr || ')';
END IF;
sqlStmt := sqlStmt || dateFilterStmt;
sqlStmt := sqlStmt || ' AND ar. "expAPIOperationName"  IN( 
                           SELECT  "expAPIOperationName"  FROM  "permissionapprovals"  
                           WHERE  "approvalPermissionName"  IN (' || v_permissionListArr || ') )';
sqlStmt := sqlStmt || ' ORDER BY ';
IF(
  sortParam IS NOT NULL 
  AND sortParam IN (dateField)
) THEN sqlStmt := sqlStmt || sortParam;
ELSE sqlStmt := sqlStmt || dateField;
END IF;
IF(
  v_sortOrder IS NOT NULL 
  AND (
    UPPER(v_sortOrder)
  ) IN ('DESC', 'ASC')
) THEN sqlStmt := sqlStmt || ' ' || v_sortOrder;
ELSE sqlStmt := sqlStmt || ' ' || 'DESC';
END IF;
OPEN "approvalrequests" FOR sqlStmt;
END;
/

--  DDL for Procedure fetch_pending_group_list_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_pending_group_list_proc" (
  v__requestId IN VARCHAR2, "signatorygroup" OUT SYS_REFCURSOR
) AS BEGIN OPEN "signatorygroup" FOR 
SELECT 
  "signatorygroup"."signatoryGroupId", 
  "signatorygroup"."signatoryGroupName" 
FROM 
  "signatorygroup" 
WHERE 
  "signatorygroup"."signatoryGroupId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(
          (
            SELECT 
              LISTAGG(
                REPLACE(
                  REPLACE(
                    REPLACE(
                      REPLACE(
                        "signatorygrouprequestmatrix"."pendingGroupList", 
                        ']', ' '
                      ), 
                      '[', 
                      ' '
                    ), 
                    '"', 
                    ' '
                  ), 
                  ' ', 
                  ' '
                ), 
                ','
              ) 
            FROM 
              "signatorygrouprequestmatrix" 
            WHERE 
              "signatorygrouprequestmatrix"."requestId" = v__requestId 
              AND "signatorygrouprequestmatrix"."isApproved" = 'false'
          )
        )
      )
  );
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_request_history_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_request_history_proc" (
  v__customerId IN VARCHAR2, v__requestId IN VARCHAR2, 
  "bbactedrequest" OUT SYS_REFCURSOR
) AS v_companyId CLOB;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  LISTAGG(
    CAST(
      (
        "contractcustomers"."contractId" || '_' || "contractcustomers"."coreCustomerId"
      ) AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = v__customerId;
IF v_companyId IS NULL THEN v_companyId := ' ';
END IF;
OPEN "bbactedrequest" FOR 
SELECT 
  "bbactedrequest"."approvalId" approvalId, 
  "bbactedrequest"."requestId" requestId, 
  "bbactedrequest"."companyId" companyId, 
  "bbactedrequest"."createdby" requestActedby, 
  "bbactedrequest"."status" STATUS, 
  "bbactedrequest"."comments" comments, 
  "bbactedrequest"."action" ACTION, 
  "bbactedrequest"."groupName" groupName, 
  "bbactedrequest"."createdts" actionts, 
  "bbactedrequest"."softdeleteflag" softdeleteflag, 
  "customer"."UserName" userName, 
  CASE WHEN cast(
    "bbactedrequest"."createdby" as varchar2(255)
  ) IS NULL THEN cast(
    'System' as nvarchar2(255)
  ) ELSE (
    CASE WHEN (
      LENGTHB("customer"."FirstName") <> 0
    ) THEN "customer"."FirstName" ELSE cast(
      '' as nvarchar2(255)
    ) END
  ) || ' ' || (
    CASE WHEN (
      LENGTHB("customer"."MiddleName") <> 0
    ) THEN "customer"."MiddleName" ELSE cast(
      '' as nvarchar2(255)
    ) END
  ) || ' ' || (
    CASE WHEN (
      LENGTHB("customer"."LastName") <> 0
    ) THEN "customer"."LastName" ELSE cast(
      '' as nvarchar2(255)
    ) END
  ) END customerName, 
  "customer"."FullName" customerFullName 
FROM 
  (
    "bbactedrequest" 
    LEFT JOIN "customer" ON (
      "bbactedrequest"."createdby" = "customer"."id"
    )
  ) 
WHERE 
  CAST(
    "bbactedrequest"."requestId" AS VARCHAR2(255)
  ) = v__requestId 
  AND "bbactedrequest"."companyId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_companyId)
      )
  );
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_requestapprovalmatrix_details_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_requestapprovalmatrix_details_proc" (
  v_requestId IN nvarchar2, v_customerId IN nvarchar2, 
  "bbrequest" out SYS_REFCURSOR
) AS v_stmt nvarchar2(2000);
BEGIN OPEN "bbrequest" FOR 
SELECT 
  bb."requestId" requestId, 
  am."id" approvalMatrixId, 
  ram."id" requestApprovalMatrixId, 
  ram."receivedApprovals" receivedApprovals, 
  decode(
    ar."numberOfApprovals", -1, na.numberOfApprovals, 
    ar."numberOfApprovals"
  ) numberOfApprovals, 
  cam."customerId" customerId 
FROM 
  "bbrequest" bb 
  JOIN "requestapprovalmatrix" ram on bb."requestId" = ram."requestId" 
  and CAST(
    bb."requestId" as nvarchar2(2000)
  ) = v_requestId 
  JOIN "approvalmatrix" am on ram."approvalMatrixId" = am."id" 
  JOIN "customerapprovalmatrix" cam on cam."customerId" = v_customerId 
  JOIN "approvalrule" ar on am."approvalruleId" = ar."id" 
  JOIN (
    SELECT 
      "approvalMatrixId", 
      count(
        DISTINCT ("customerId")
      ) numberOfApprovals 
    FROM 
      "customerapprovalmatrix" 
    GROUP BY 
      "approvalMatrixId"
  ) na on na."approvalMatrixId" = am."id";
END;
/

--  DDL for Procedure fetch_signatory_eligible_users_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_signatory_eligible_users_proc" (
  v__coreCustomerId IN VARCHAR2, v__contractId IN VARCHAR2, 
  "customer" OUT SYS_REFCURSOR
) AS BEGIN OPEN "customer" FOR 
SELECT 
  DISTINCT "customer"."id" userId, 
  "customer"."isCombinedUser" isCombinedUser, 
  "customer"."UserName" userName, 
  "customer"."FirstName" firstName, 
  "customer"."LastName" lastName, 
  "membergroup"."Name" role 
FROM 
  "customer" 
  LEFT JOIN "customergroup" ON (
    "customergroup"."Customer_id" = "customer"."id"
  ) 
  LEFT JOIN "membergroup" ON (
    "membergroup"."id" = "customergroup"."Group_id"
  ) 
WHERE 
  "customergroup"."coreCustomerId" = v__coreCustomerId 
  AND "customer"."id" IN (
    SELECT 
      DISTINCT "customeraction"."Customer_id" 
    FROM 
      "customeraction" 
    WHERE 
      "customeraction"."contractId" = v__contractId 
      AND "customeraction"."coreCustomerId" = v__coreCustomerId 
      AND "customeraction"."softdeleteflag" = '0' 
      AND "customeraction"."Action_id" IN (
        SELECT 
          DISTINCT "featureaction"."id" 
        FROM 
          "featureaction" 
        WHERE 
          (
            "featureaction"."id" LIKE '%_APPROVE' 
            OR "featureaction"."id" LIKE '%_SELF_APPROVAL'
          )
      ) 
      AND "customeraction"."Customer_id" NOT IN (
        SELECT 
          "customersignatorygroup"."customerId" 
        FROM 
          "customersignatorygroup" 
        WHERE 
          "customersignatorygroup"."softdeleteflag" = '0' 
          AND "customersignatorygroup"."signatoryGroupId" IN (
            SELECT 
              "signatorygroup"."signatoryGroupId" 
            FROM 
              "signatorygroup" 
            WHERE 
              "signatorygroup"."softdeleteflag" = '0' 
              AND "signatorygroup"."contractId" = v__contractId 
              AND "signatorygroup"."coreCustomerId" = v__coreCustomerId
          )
      )
  ) 
ORDER BY 
  "customer"."id";
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_signatorygroup_customer_details_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_signatorygroup_customer_details_proc" (
  v__signatoryGroupId IN VARCHAR2, "customersignatorygroup" OUT SYS_REFCURSOR
) AS BEGIN OPEN "customersignatorygroup" FOR 
SELECT 
  "customer"."id" userId, 
  "customer"."isCombinedUser" isCombinedUser, 
  "customer"."UserName" userName, 
  "customer"."FirstName" firstName, 
  "customer"."LastName" lastName, 
  "membergroup"."Name" ROLE, 
  "customerimage"."UserImage" userImage 
FROM 
  "customersignatorygroup" 
  LEFT JOIN "customer" ON (
    "customer"."id" = "customersignatorygroup"."customerId"
  ) 
  LEFT JOIN "signatorygroup" ON (
    "signatorygroup"."signatoryGroupId" = "customersignatorygroup"."signatoryGroupId"
  ) 
  LEFT JOIN "customergroup" ON (
    "customergroup"."Customer_id" = "customersignatorygroup"."customerId" 
    AND "customergroup"."coreCustomerId" = "signatorygroup"."coreCustomerId"
  ) 
  LEFT JOIN "membergroup" ON (
    "membergroup"."id" = "customergroup"."Group_id"
  ) 
  LEFT JOIN "customerimage" ON (
    "customerimage"."Customer_id" = "customer"."id"
  ) 
WHERE 
  "customersignatorygroup"."signatoryGroupId" = v__signatoryGroupId;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_signatorygroup_details_proc


create or replace NONEDITIONABLE PROCEDURE "fetch_signatorygroup_details_proc" (
  "_signatoryGroupId" IN VARCHAR2, records OUT SYS_REFCURSOR
) AS BEGIN OPEN records FOR 
SELECT 
  "signatorygroup"."signatoryGroupId" "signatoryGroupId", 
  "signatorygroup"."signatoryGroupName" "signatoryGroupName", 
  "signatorygroup"."signatoryGroupDescription" "signatoryGroupDescription", 
  "signatorygroup"."coreCustomerId" "coreCustomerId", 
  "contractcorecustomers"."coreCustomerName" "coreCustomerName", 
  "signatorygroup"."createdts" "createdts", 
  (
    SELECT 
      (
        "customer"."FirstName" || ' ' || NVL("customer"."LastName", '')
      ) 
    FROM 
      "customer" cust 
    WHERE 
      cust."id" = "signatorygroup"."createdby"
  ) "createdby", 
  "signatorygroup"."lastmodifiedts" "lastmodifiedts", 
  "customersignatorygroup"."customerSignatoryGroupId" "customerSignatoryGroupId", 
  "customersignatorygroup"."customerId" "customerId", 
  "customer"."UserName" "userName", 
  "customer"."FirstName" || ' ' || NVL("customer"."MiddleName", '') || ' ' || NVL("customer"."LastName", '') "fullName", 
  "membergroup"."Name" "customerRole", 
  "customersignatorygroup"."createdts" "signatoryaddedts"
FROM 
  "signatorygroup" 
  LEFT JOIN "customersignatorygroup" ON "signatorygroup"."signatoryGroupId" = "customersignatorygroup"."signatoryGroupId" 
  LEFT JOIN "contractcorecustomers" ON "contractcorecustomers"."coreCustomerId" = "signatorygroup"."coreCustomerId" 
  LEFT JOIN "customer" ON "customer"."id" = "customersignatorygroup"."customerId" 
  LEFT JOIN "customergroup" ON "customergroup"."Customer_id" = "customersignatorygroup"."customerId" 
  AND "customergroup"."coreCustomerId" = "signatorygroup"."coreCustomerId" 
  LEFT JOIN "membergroup" ON "membergroup"."id" = "customergroup"."Group_id" 
WHERE 
  "signatorygroup"."signatoryGroupId" = "_signatoryGroupId";
--DBMS_SQL.RETURN_RESULT(records);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure fetch_signatorygroup_for_customer_and_request_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_signatorygroup_for_customer_and_request_proc" (
  v__requestId IN VARCHAR2, v__customerId IN VARCHAR2, 
  "customersignatorygroup" OUT SYS_REFCURSOR
) AS v_signatoryGroupsList CLOB;
v_signatoryGroupsQuery VARCHAR2(2048);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  LISTAGG(
    REPLACE(
      (
        REPLACE(
          REPLACE("groupList", ']', ''''), 
          '[', 
          ''''
        )
      ), 
      ',', 
      ''','''
    ), 
    ','
  ) INTO v_signatoryGroupsList 
FROM 
  "signatorygroupmatrix" 
WHERE 
  "approvalMatrixId" IN (
    SELECT 
      "approvalMatrixId" 
    FROM 
      "requestapprovalmatrix" 
    WHERE 
      "requestId" = v__requestId
  );
v_signatoryGroupsQuery := (
  'SELECT 
                                                        csg."customerSignatoryGroupId",
                                                        csg."signatoryGroupId",
                                                        sg."signatoryGroupName",
                                                        csg."customerId",
                                                        csg."createdby",
                                                        csg."createdts",
                                                        csg."modifiedby",
                                                        csg."lastmodifiedts",
                                                        csg."synctimestamp",
                                                        csg."softdeleteflag" FROM 
                                                        "customersignatorygroup" csg 
                                                        INNER JOIN "signatorygroup" sg 
                                                        ON csg."signatoryGroupId" = sg."signatoryGroupId" 
                                                            WHERE csg."signatoryGroupId" IN (' || v_signatoryGroupsList || ') 
                                                            AND csg."softdeleteflag" = 0 
                                                            AND sg."softdeleteflag" = 0 
                                                            AND csg."customerId" = ''' || v__customerId || ''';'
);
EXECUTE IMMEDIATE v_signatoryGroupsQuery;
OPEN "customersignatorygroup" FOR v_signatoryGroupsQuery;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
