--  DDL for Procedure fetch_signatorygroups_proc


create or replace NONEDITIONABLE PROCEDURE "fetch_signatorygroups_proc" (
  "_contractId" IN VARCHAR2, "_coreCustomerId" IN VARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS v__contractId VARCHAR2(50) := "_contractId";
v_index1 NUMBER(10, 0) := 1;
v_numOfRecords NUMBER(10, 0);
v_concatstring VARCHAR2(4000);
v_customerId VARCHAR2(4000);
v_execStmt VARCHAR2(4000);
BEGIN IF v__contractId IS NULL THEN BEGIN v__contractId := '%';
END;
END IF;
v_numOfRecords := LENGTH("_coreCustomerId") - LENGTH(
  REPLACE("_coreCustomerId", ',', ' ')
) || 1;
v_concatstring := '''' || UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX("_coreCustomerId", ',', v_index1), 
  ',', 
  -1
) || '''';
<< customerId >> WHILE 1 = 1 LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_numOfRecords + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_customerId := (
  UTILS.SUBSTRING_INDEX(
    UTILS.SUBSTRING_INDEX("_coreCustomerId", ',', v_index1), 
    ',', 
    -1
  )
);
v_concatstring := v_concatstring || ',''' || v_customerId || '''';
END;
END IF;
END;
END LOOP;
v_execStmt := 'select sg."signatoryGroupId", sg."signatoryGroupName", sg."signatoryGroupDescription", cc."coreCustomerId", cc."coreCustomerName",
     c."id" "contractId", c."name" "contractName", sg."createdby", sg."createdts", sg."lastmodifiedts", sg."softdeleteflag" ,
      ( select count(*) from "customersignatorygroup" cs1 where cs1."signatoryGroupId"=sg."signatoryGroupId"  group by cs1."signatoryGroupId" ) as "noOfUsers"
     from "contract" c 
     left join "contractcorecustomers" cc on c."id"=cc."contractId"
     left join "signatorygroup" sg on c."id"=sg."contractId" and cc."coreCustomerId"=sg."coreCustomerId"
     where c."id" LIKE ''' || v__contractId || '''';
IF "_coreCustomerId" IS NOT NULL THEN BEGIN v_execStmt := v_execStmt || ' and cc."coreCustomerId" IN (' || v_concatstring || ' )';
END;
END IF;
EXECUTE IMMEDIATE v_execStmt;
OPEN "records" FOR v_execStmt;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;

/

--  DDL for Procedure fetch_wiretransfer_details_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "fetch_wiretransfer_details_proc" (
  iv__transactionId IN VARCHAR2, iv__wireFileExecution_id IN VARCHAR2, 
  v__customerId IN VARCHAR2, "wiretransfers" OUT SYS_REFCURSOR
) AS v__transactionId VARCHAR2(50) := iv__transactionId;
v__wireFileExecution_id VARCHAR2(50) := iv__wireFileExecution_id;
v_companyId CLOB;
v_filter VARCHAR2(4000);
v_select_statement VARCHAR2(4000);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
SELECT 
  LISTAGG(
    CAST(
      (
        "contractcustomers"."contractId" || '_' || "contractcustomers"."coreCustomerId"
      ) AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_companyId 
FROM 
  "contractcustomers" 
WHERE 
  "contractcustomers"."customerId" = v__customerId;
IF v__transactionId IS NULL THEN v__transactionId := '';
END IF;
IF v__wireFileExecution_id IS NULL THEN v__wireFileExecution_id := '';
END IF;
IF v_companyId IS NULL THEN v_companyId := '';
END IF;
v_filter := CASE WHEN (v__transactionId <> ' ') THEN ('transactionId = ') || (v__transactionId) || ' AND companyId IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_companyId || ''')))' ELSE CASE WHEN (v__wireFileExecution_id <> ' ') THEN ('wireFileExecution_id = ') || (v__wireFileExecution_id) || ' AND companyId IN ( SELECT column_value from TABLE(UTILS.STRING_SPLIT(''' || v_companyId || ''')))' ELSE '' END END;
v_select_statement := (
  'SELECT ' || '"wiretransfers"."transactionId",' || '"wiretransfers"."featureActionId",' || '        "wiretransfers"."confirmationNumber",' || '        "wiretransfers"."companyId",' || '        "wiretransfers"."createdby",' || '        "wiretransfers"."requestId",' || '        "wiretransfers"."status",' || '        "wiretransfers"."onetime_id",' || '        "wiretransfers"."wireFileExecution_id",' || '        "wiretransfers"."notes",' || '        "wiretransfers"."amount",' || '        "wiretransfers"."fromAccountNumber",' || '        "wiretransfers"."payeeAccountNumber",' || '        "wiretransfers"."transactionType",' || '        "wiretransfers"."payeeId",' || '        "wiretransfers"."payeeCurrency",' || '        "onetimepayee"."payeeName",' || '"onetimepayee"."payeeNickName",' || '"onetimepayee"."payeetype",' || '"onetimepayee"."wireAccountType",' || '"onetimepayee"."swiftCode",' || '"onetimepayee"."routingNumber",' || '"onetimepayee"."zipCode",' || '"onetimepayee"."cityName",' || '"onetimepayee"."state",' || '"onetimepayee"."country",' || '"onetimepayee"."payeeAddressLine1",' || '"onetimepayee"."payeeAddressLine2",' || '"onetimepayee"."bankName",' || '"onetimepayee"."internationalRoutingCode",' || '"onetimepayee"."bankAddressLine1",' || '"onetimepayee"."bankAddressLine2",' || '"onetimepayee"."bankCity",' || '"onetimepayee"."bankState",' || '"onetimepayee"."bankZip"' || '        ' || '    FROM' || '        ("wiretransfers"' || ' LEFT JOIN "onetimepayee" ON ("wiretransfers"."onetime_id" = "onetimepayee"."onetime_id"))' || ' WHERE '
) || (v_filter);
EXECUTE IMMEDIATE v_select_statement;
OPEN "wiretransfers" FOR v_select_statement;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure get_feature_actions_view_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "get_feature_actions_view_proc" (
  "_roleTypeId" IN NVARCHAR2, "_companyLegalUnit" IN NVARCHAR2, 
  "records" out SYS_REFCURSOR
) AS v_select_statement NCLOB;
BEGIN v_select_statement := 'SELECT 
    "featureaction"."id" "actionId", 
    "featureaction"."Feature_id" "featureId", 
    "featureaction"."name" "actionName", 
    "featureaction"."isAccountLevel", 
    "featureaction"."description" "actionDescription",
    "featureaction"."isMFAApplicable", 
  "featureaction"."isPrimary", 
  "featureaction"."notes", 
  "featureaction"."Type_id" "typeId", 
  "featureaction"."DisplaySequence" "actionDisplaySequence",
    "featureaction"."dependency" "actionDependency", 
  "featureaction"."status" "actionStatus", 
    "featureaction"."companyLegalUnit" AS "companyLegalUnit",
  "featureactionroletype"."RoleType_id" "actionType",
    "featureactionroletype"."Action_id" "Action_id",
  "accesspolicy"."name" "accesspolicy",
    "limitgroup"."name" "limitgroup", 
  "featureaction"."accesspolicyId", 
  "featureaction"."limitgroupId", 
  "feature"."Status_id" "featureStatus", 
  "feature"."name" "featureName",
    "feature"."description" "featureDescription", 
  "feature"."Type_id" "featureType", 
  "featureroletype"."RoleType_id" "featureGroup", 
  "feature"."DisplaySequence" "featureDisplaySequence",
    "feature"."isPrimary" "isFeaturePrimary", 
  "actionlevel"."name" "actionlevel", 
  "featureaction"."actionlevelId", 
  "actiondisplaynamedescription"."Locale_id" "localeId",
    "actiondisplaynamedescription"."displayName", 
  "actiondisplaynamedescription"."displayDescription", 
  "actionlimit"."LimitType_id" "limitTypeId", 
  "actionlimit"."value",
    "dependentactions_view"."dependentactionId", 
  "dependentactions_view"."featureName" "dependentFeatureName", 
  "dependentactions_view"."actionName" "dependentActionName",
    "dependentactions_view"."featureId" "dependentFeatureId", 
  "termandcondition"."Code" "termsAndConditionCode", 
  "termandcondition"."Title" "termsAndConditionTitle",
    "termandcondition"."Description" "termsAndConditionDescription", 
  "membergrouptype"."description" "roleTypeName"
FROM "featureaction" 
LEFT JOIN "feature" ON ((("feature"."id" = "featureaction"."Feature_id") AND ("feature"."companyLegalUnit" = "featureaction"."companyLegalUnit")))
LEFT JOIN "actiondisplaynamedescription" ON ((("actiondisplaynamedescription"."Action_id" = "featureaction"."id" AND ("actiondisplaynamedescription"."companyLegalUnit" = "featureaction"."companyLegalUnit"))))
LEFT JOIN "accesspolicy" ON (("featureaction"."accesspolicyId" = "accesspolicy"."id"))
LEFT JOIN "featureroletype" ON (("featureroletype"."Feature_id" = "feature"."id") AND ("featureroletype"."companyLegalUnit" = "feature"."companyLegalUnit"))
LEFT JOIN "featureactionroletype" ON (("featureaction"."id" = "featureactionroletype"."Action_id") AND ("featureaction"."companyLegalUnit" = "featureactionroletype"."companyLegalUnit"))
LEFT JOIN "termandcondition" ON (("featureaction"."TermsAndConditions_id" = "termandcondition"."id")) 
LEFT JOIN "limitgroup" ON (("featureaction"."limitgroupId" = "limitgroup"."id")) 
LEFT JOIN "actionlevel" ON (("featureaction"."actionlevelId" = "actionlevel"."id")) 
LEFT JOIN "dependentactions_view" ON (("featureaction"."id" = "dependentactions_view"."actionId") AND ("feature"."companyLegalUnit" = "dependentactions_view"."companyLegalUnit"))
LEFT JOIN "membergrouptype" ON (("featureactionroletype"."RoleType_id" = "membergrouptype"."id"))
LEFT JOIN "actionlimit" ON (("actionlimit"."Action_id" = "featureaction"."id")  AND ("actionlimit"."companyLegalUnit" = "featureaction"."companyLegalUnit"))';
--DBMS_OUTPUT.put_line('v_select_statement');
IF (
  "_roleTypeId" is not null 
  AND LENGTH(
    RTRIM("_roleTypeId")
  )> 0
) THEN v_select_statement := (v_select_statement) || (
  ' where "featureaction"."companyLegalUnit" =''' || "_companyLegalUnit" || '''' || ' and "featureroletype"."RoleType_id" =''' || "_roleTypeId" || '''' || ' and "featureactionroletype"."RoleType_id" =''' || "_roleTypeId" || ''''
);
END IF;
open "records" for v_select_statement;
END;
/

