--  DDL for Procedure get_reports_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "get_reports_proc" (
  "p_userId" IN VARCHAR2, "p_roleId" IN VARCHAR2, 
  "records" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "records" FOR 
SELECT 
  * 
FROM 
  "report" rp 
WHERE 
  rp."createdby" = "p_userId" 
UNION 
SELECT 
  rp.* 
FROM 
  "report" rp, 
  "sharedreport" sr 
WHERE 
  sr."reportId" = rp."id" 
  AND sr."userId" = "p_userId" 
UNION 
SELECT 
  rp.* 
FROM 
  "report" rp, 
  "sharedreport" sr 
WHERE 
  sr."reportId" = rp."id" 
  AND sr."roleId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT("p_roleId")
      )
  ) 
ORDER BY 
  8 DESC;
--DBMS_SQL.RETURN_RESULT("region");
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

