--  DDL for Procedure GetExternalPayeesProc


create or replace NONEDITIONABLE PROCEDURE         "GetExternalPayeesProc" 
(
  "userId" IN VARCHAR2,
  "legalEntityId" IN VARCHAR2,
  "records" OUT SYS_REFCURSOR
)
AS
   

BEGIN

   IF ( "legalEntityId" IS NOT NULL ) THEN
    OPEN  "records" FOR
      SELECT *
        FROM "internationalpayee" "ip"
               JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
       WHERE  "isInternationalAccount" = 1
                AND "softDelete" = 0
                AND "cif" IN ( SELECT "coreCustomerId" 
                             FROM "customeraction" 
                              WHERE  "Customer_id" = "userId"
                                       AND "Action_id" = 'INTERNATIONAL_ACCOUNT_FUND_TRANSFER_VIEW_RECEPIENT'
                                       AND "isAllowed" = 1 )

                AND "ip"."legalEntityId" = "legalEntityId"
      UNION 
      SELECT * 
        FROM "interbankpayee"  "ip"
               JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
       WHERE  "isInternationalAccount" = 0
                AND "isSameBankAccount" = 0
                AND "softDelete" = 0
                AND "cif" IN ( SELECT "coreCustomerId" 
                             FROM "customeraction" 
                              WHERE  "Customer_id" = "userId"
                                       AND "Action_id" = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_VIEW_RECEPIENT'
                                       AND "isAllowed" = 1 )

                AND "ip"."legalEntityId" = "legalEntityId"
      UNION 
      SELECT * 
        FROM "intrabankpayee" "ip"
               JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
       WHERE  "isSameBankAccount" = 1
                AND "softDelete" = 0
                AND "cif" IN ( SELECT "coreCustomerId" 
                             FROM "customeraction" 
                              WHERE  "Customer_id" = "userId"
                                       AND "Action_id" = 'INTRA_BANK_FUND_TRANSFER_VIEW_RECEPIENT'
                                       AND "isAllowed" = 1 )

                AND "ip"."legalEntityId" = "legalEntityId" ;
      --DBMS_SQL.RETURN_RESULT("internationalpayee");
   ELSE
      OPEN  "records" FOR
         SELECT * 
           FROM "internationalpayee" "ip"
                  JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
          WHERE  "isInternationalAccount" = 1
                   AND "softDelete" = 0
                   AND "cif" IN ( SELECT "coreCustomerId" 
                                FROM "customeraction" 
                                 WHERE  "Customer_id" = "userId"
                                          AND "Action_id" = 'INTERNATIONAL_ACCOUNT_FUND_TRANSFER_VIEW_RECEPIENT'
                                          AND "isAllowed" = 1 )

         UNION 
         SELECT * 
           FROM "interbankpayee"  "ip"
                  JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
          WHERE  "isInternationalAccount" = 0
                   AND "isSameBankAccount" = 0
                   AND "softDelete" = 0
                   AND "cif" IN ( SELECT "coreCustomerId" 
                                FROM "customeraction" 
                                 WHERE  "Customer_id" = "userId"
                                          AND "Action_id" = 'INTER_BANK_ACCOUNT_FUND_TRANSFER_VIEW_RECEPIENT'
                                          AND "isAllowed" = 1 )

         UNION 
         SELECT * 
           FROM "intrabankpayee" "ip"
                  JOIN "externalaccount"  "ea"   ON "ip"."payeeId" = "ea"."Id"
          WHERE  "isSameBankAccount" = 1
                   AND "softDelete" = 0
                   AND "cif" IN ( SELECT "coreCustomerId" 
                                FROM "customeraction" 
                                 WHERE  "Customer_id" = "userId"
                                          AND "Action_id" = 'INTRA_BANK_FUND_TRANSFER_VIEW_RECEPIENT'
                                          AND "isAllowed" = 1 )
       ;
         --DBMS_SQL.RETURN_RESULT("internationalpayee");
   END IF;

EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE,SQLERRM);
END;
/

--  DDL for Procedure group_actions_remove_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "group_actions_remove_proc" (
  v__action IN VARCHAR2, v__customerIdValues IN VARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_numOfRecords NUMBER(10, 0);
v_customerValues VARCHAR2(4000);
v_customerId VARCHAR2(4000);
v_coreCustomerId VARCHAR2(4000);
BEGIN v_numOfRecords := LENGTH(v__customerIdValues) - LENGTH(
  REPLACE(v__customerIdValues, ',', ' ')
) || 1;
WHILE 1 = 1 LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_numOfRecords + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_customerValues := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(
    v__customerIdValues, ',', v_index1
  ), 
  ',', 
  -1
);
v_customerId := UTILS.SUBSTRING_INDEX(v_customerValues, '.', 1);
v_coreCustomerId := UTILS.SUBSTRING_INDEX(v_customerValues, '.', -1);
DELETE "customeraction" 
WHERE 
  "Customer_id" = v_customerId 
  AND "coreCustomerId" = v_coreCustomerId 
  AND "Action_id" = v__action;
END;
END IF;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure group_features_actions_view_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "group_features_actions_view_proc" (
  "_groupId" IN VARCHAR2, "_companyLegalUnit" IN VARCHAR2, 
  "records" out SYS_REFCURSOR
) AS v_select_statement NCLOB;
BEGIN v_select_statement := (
  'SELECT "groupactionlimit"."Group_id", 
"groupactionlimit"."Action_id", 
"groupactionlimit"."LimitType_id", 
"groupactionlimit"."value", 
"groupactionlimit"."id" "groupactionlimit_id",
"groupactionlimit"."softdeleteflag" "softdelete", 
"membergroup"."Type_id", 
"membergroup"."Name" "Group_name",
"membergroup"."Description" "Group_description",
"featureaction"."name" "Action_name",
"featureaction"."description" "Action_description", 
"featureaction"."Type_id" "Action_Type_id", 
"featureaction"."Feature_id", 
"featureaction"."isMFAApplicable", 
"featureaction"."isAccountLevel",
"featureaction"."isPrimary", 
"featureaction"."DisplaySequence" "Action_displaysequence", 
"featureaction"."dependency" "Action_dependency", 
"featureaction"."status" "actionStatus",
"accesspolicy"."name" "accessPolicy", 
"featureaction"."accesspolicyId", 
"featureaction"."limitgroupId", 
"featureaction"."companyLegalUnit",
"limitgroup"."name" "limitGroup", 
"actionlevel"."name" "actionlevel", 
"featureaction"."actionlevelId",
"feature"."name" "featureName", 
"feature"."name" "Feature_name", 
"feature"."description" "Feature_description", 
"feature"."Type_id" "Feature_Type_id", 
"feature"."Status_id" "Feature_Status_id",
"feature"."DisplaySequence" "Feature_displaysequence", 
"feature"."isPrimary" "Feature_isPrimary"
FROM ("groupactionlimit" 
LEFT OUTER JOIN
"membergroup" ON ("membergroup"."id" = "groupactionlimit"."Group_id") 
LEFT OUTER JOIN
"featureaction" ON ("featureaction"."id" = "groupactionlimit"."Action_id") 
LEFT OUTER JOIN
"feature" ON ("feature"."id" = "featureaction"."Feature_id") 
LEFT OUTER JOIN
"accesspolicy" ON ("featureaction"."accesspolicyId" = "accesspolicy"."id") 
LEFT OUTER JOIN
"limitgroup" ON ("featureaction"."limitgroupId" = "limitgroup"."id") 
LEFT OUTER JOIN
"actionlevel" ON ("featureaction"."actionlevelId" = "actionlevel"."id"))'
);
IF (
  "_groupId" is not null 
  AND LENGTH(
    RTRIM("_groupId")
  )> 0
) THEN v_select_statement := (v_select_statement) || (
  ' where "groupactionlimit"."Group_id" =''' || "_groupId" || '''' || ' and "featureaction"."companyLegalUnit" =''' || "_companyLegalUnit" || ''''
);
END IF;
open "records" for v_select_statement;
END;
/

--  DDL for Procedure group_limits_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "group_limits_update_proc" (
  v__action IN VARCHAR2, v__maxTxLimit IN NUMBER, 
  v__dailyLimit IN NUMBER, v__weeklyLimit IN NUMBER, 
  v__customerIdValues IN VARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_numOfRecords NUMBER(10, 0);
v_customerValues VARCHAR2(4000);
v_customerId VARCHAR2(4000);
v_coreCustomerId VARCHAR2(4000);
BEGIN v_numOfRecords := LENGTH(v__customerIdValues) - LENGTH(
  REPLACE(v__customerIdValues, ',', ' ')
) || 1;
WHILE 1 = 1 LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_numOfRecords + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_customerValues := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(
    v__customerIdValues, ',', v_index1
  ), 
  ',', 
  -1
);
v_customerId := UTILS.SUBSTRING_INDEX(v_customerValues, '.', 1);
v_coreCustomerId := UTILS.SUBSTRING_INDEX(v_customerValues, '.', -1);
UPDATE 
  "customeraction" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "Customer_id" = v_customerId 
  AND "coreCustomerId" = v_coreCustomerId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > v__maxTxLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "Customer_id" = v_customerId 
  AND "coreCustomerId" = v_coreCustomerId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'DAILY_LIMIT' 
  AND "value" > v__dailyLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "Customer_id" = v_customerId 
  AND "coreCustomerId" = v_coreCustomerId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'WEEKLY_LIMIT' 
  AND "value" > v__weeklyLimit;
END;
END IF;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure increment_receivedapprovals_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "increment_receivedapprovals_proc" (
  v__requestId IN VARCHAR2, v__approvalMatrixId IN VARCHAR2
) AS BEGIN 
UPDATE 
