SET 
  "receivedApprovals" = "receivedApprovals" + 1 
WHERE 
  (
    "requestId" = v__requestId 
    AND "approvalMatrixId" = v__approvalMatrixId
  );
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure infinity_customer_from_servicedefinition_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "infinity_customer_from_servicedefinition_proc" (
  v__servicedefinitionIds IN VARCHAR2, 
  "contractcustomers" OUT SYS_REFCURSOR
) AS v_group_concat_max_len NUMBER(19, 0);
v_contractIdList CLOB;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_group_concat_max_len := 100000000;
SELECT 
  LISTAGG("id", ',') INTO v_contractIdList 
FROM 
  "contract" 
WHERE 
  "contract"."servicedefinitionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v__servicedefinitionIds)
      )
  );
OPEN "contractcustomers" FOR 
SELECT 
  DISTINCT "customerId" custId 
FROM 
  "contractcustomers" 
WHERE 
  "customerId" IS NOT NULL 
  AND "contractcustomers"."contractId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_contractIdList)
      )
  );
--DBMS_SQL.RETURN_RESULT("contractcustomers");
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure internal_user_access_on_given_customer_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "internal_user_access_on_given_customer_proc" (
  v__roleIds IN VARCHAR2, iv__customerId IN VARCHAR2, 
  v__customerUsername IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v__customerId VARCHAR2(50) := iv__customerId;
v_isCustomerAccessible VARCHAR2(6);
v_temp NUMBER(1, 0) := 0;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
IF (
  v__customerId = ' ' 
  AND v__customerUsername != ' '
) THEN 
SELECT 
  "id" INTO v__customerId 
FROM 
  "customer" 
WHERE 
  "UserName" = v__customerUsername;
END IF;
BEGIN 
SELECT 
  1 INTO v_temp 
FROM 
  DUAL 
WHERE 
  v__customerId IN (
    SELECT 
      "customergroup"."Customer_id" 
    FROM 
      "userrole" 
      LEFT JOIN "userrolecustomerrole" ON "userrolecustomerrole"."UserRole_id" = "userrole"."Role_id" 
      LEFT JOIN "customergroup" ON "customergroup"."Group_id" = "userrolecustomerrole"."CustomerRole_id" 
    WHERE 
      "userrolecustomerrole"."UserRole_id" IN (
        SELECT 
          COLUMN_VALUE 
        FROM 
          TABLE(
            UTILS.STRING_SPLIT(v__roleIds)
          )
      )
  );
EXCEPTION WHEN OTHERS THEN NULL;
END;
IF v_temp = 1 THEN OPEN v_cursor FOR 
SELECT 
  'true' isCustomerAccessible 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
ELSE OPEN v_cursor FOR 
SELECT 
  'false' isCustomerAccessible 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
END IF;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure internal_user_access_to_customer_on_servicedefinition_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "internal_user_access_to_customer_on_servicedefinition_proc" (
  "_roleIds" IN VARCHAR2, "_customerId" IN NVARCHAR2, 
  "_customerUsername" IN NVARCHAR2, 
  "records" out SYS_REFCURSOR
) AS v__customerId NVARCHAR2(50) := "_customerId";
v_isCustomerAccessible VARCHAR2(6);
v_group_concat_max_len NUMBER(19, 0);
v_servicedefinitionIds NVARCHAR2(2000);
v_contractIdList NVARCHAR2(2000);
v_temp NUMBER(1, 0) := 0;
BEGIN v_group_concat_max_len := 100000000;
IF (
  v__customerId = ' ' 
  AND "_customerUsername" != ' '
) THEN 
SELECT 
  "id" INTO v__customerId 
FROM 
  "customer" 
WHERE 
  "customer"."UserName" = "_customerUsername";
END IF;
SELECT 
  LISTAGG("servicedefinitionId", ',') INTO v_servicedefinitionIds 
FROM 
  (
    SELECT 
      DISTINCT "servicedefinitionId" 
    FROM 
      "userroleservicedefinition" 
    WHERE 
      FIND_IN_SET(
        "userroleservicedefinition"."UserRole_id", 
        "_roleIds"
      ) > 0
  ) T;
SELECT 
  LISTAGG("id", ',') INTO v_contractIdList 
FROM 
  "contract" 
WHERE 
  FIND_IN_SET(
    "contract"."servicedefinitionId", 
    v_servicedefinitionIds
  ) > 0;
BEGIN 
SELECT 
  1 INTO v_temp 
FROM 
  DUAL 
WHERE 
  v__customerId IN (
    SELECT 
      "custId" 
    FROM 
      (
        SELECT 
          DISTINCT "customerId" "custId" 
        FROM 
          "contractcustomers" 
        WHERE 
          "customerId" IS NOT NULL 
          AND FIND_IN_SET(
            "contractcustomers"."contractId", 
            v_contractIdList
          ) > 0 
        UNION ALL 
        SELECT 
          DISTINCT CAST(
            "coreCustomerId" AS NVARCHAR2(50)
          ) "custId" 
        FROM 
          "contractcustomers" 
        WHERE 
          "coreCustomerId" IS NOT NULL 
          AND FIND_IN_SET(
            "contractcustomers"."contractId", 
            v_contractIdList
