--  DDL for Procedure lead_archive_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "lead_archive_proc" (
  v__leadId IN VARCHAR2, v__leadClosureReason IN VARCHAR2, 
  v__modifiedby IN VARCHAR2, v_cursor OUT SYS_REFCURSOR
) AS v_lead_note_cursor_done NUMBER(1, 0) := 0;
v_curr_leadnote_id VARCHAR2(50) := ' ';
v_lead_note_count NUMBER(10, 0) := 0;
CURSOR leadnote_cursor IS 
SELECT 
  "leadnote"."id" 
FROM 
  "leadnote" 
WHERE 
  "leadnote"."lead_Id" = v__leadId;
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
INSERT INTO "archivedlead" (
  "id", "firstName", "middleName", "lastName", 
  "salutation", "isCustomer", "customerId", 
  "product_id", "csr_id", "status_id", 
  "countryCode", "phoneNumber", "extension", 
  "email", "closureReason", "createdby", 
  "modifiedby", "createdts", "lastmodifiedts", 
  "synctimestamp", "softdeleteflag"
) (
  SELECT 
    "lead"."id", 
    "lead"."firstName", 
    "lead"."middleName", 
    "lead"."lastName", 
    "lead"."salutation", 
    "lead"."isCustomer", 
    "lead"."customerId", 
    "lead"."product_id", 
    "lead"."csr_id", 
    "lead"."status_id", 
    "lead"."countryCode", 
    "lead"."phoneNumber", 
    "lead"."extension", 
    "lead"."email", 
    "lead"."closureReason", 
    "lead"."createdby", 
    "lead"."modifiedby", 
    "lead"."createdts", 
    "lead"."lastmodifiedts", 
    "lead"."synctimestamp", 
    "lead"."softdeleteflag" 
  FROM 
    "lead" 
  WHERE 
    "lead"."id" = v__leadId
);
UPDATE 
  "archivedlead" 
SET 
  "status_id" = 'SID_ARCHIVED', 
  "closureReason" = v__leadClosureReason, 
  "lastmodifiedts" = NVL(SYSDATE, SYSDATE), 
  "modifiedby" = v__modifiedby 
WHERE 
  "archivedlead"."id" = v__leadId;
OPEN v_cursor FOR 
SELECT 
  v__leadId 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
OPEN leadnote_cursor;
WHILE (1 = 1) LOOP BEGIN FETCH leadnote_cursor INTO v_curr_leadnote_id;
IF (leadnote_cursor % FOUND) <> FALSE THEN v_lead_note_cursor_done := '1';
END IF;
IF NOT v_lead_note_cursor_done <> 0 THEN BEGIN INSERT INTO "archivedleadnote" (
  "id", "lead_Id", "note", "createdby", 
  "modifiedby", "createdts", "lastmodifiedts", 
  "synctimestamp", "softdeleteflag"
) (
  SELECT 
    "leadnote"."id", 
    "leadnote"."lead_Id", 
    "leadnote"."note", 
    "leadnote"."createdby", 
    "leadnote"."modifiedby", 
    "leadnote"."createdts", 
    "leadnote"."lastmodifiedts", 
    "leadnote"."synctimestamp", 
    "leadnote"."softdeleteflag" 
  FROM 
    "leadnote" 
  WHERE 
    "leadnote"."id" = v_curr_leadnote_id
);
DELETE "leadnote" 
WHERE 
  "leadnote"."id" = v_curr_leadnote_id;
END;
END IF;
IF v_lead_note_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_lead_note_cursor_done := '0';
CLOSE leadnote_cursor;
DELETE "lead" 
WHERE 
  "lead"."id" = v__leadId;
v_lead_note_cursor_done := '0';
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

