    "lead"."countryCode", 
    "lead"."phoneNumber", 
    "lead"."extension", 
    "lead"."email", 
    "lead"."closureReason", 
    "lead"."createdby", 
    "lead"."modifiedby", 
    "lead"."createdts", 
    "lead"."lastmodifiedts", 
    "lead"."synctimestamp", 
    "lead"."softdeleteflag" 
  FROM 
    "lead" 
  WHERE 
    "lead"."id" = v_curr_lead_id
);
UPDATE 
  "archivedlead" 
SET 
  "status_id" = 'SID_ARCHIVED', 
  "closureReason" = 'Automatically archived' 
WHERE 
  "archivedlead"."id" = v_curr_lead_id;
OPEN v_cursor FOR 
SELECT 
  v_curr_lead_id 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
DECLARE CURSOR leadnote_cursor IS 
SELECT 
  "leadnote"."id" 
FROM 
  "leadnote" 
WHERE 
  "leadnote"."lead_Id" = v_curr_lead_id;
BEGIN OPEN leadnote_cursor;
WHILE (1 = 1) LOOP BEGIN FETCH leadnote_cursor INTO v_curr_leadnote_id;
IF (leadnote_cursor % FOUND) <> FALSE THEN v_lead_cursor_done := '1';
END IF;
v_lead_note_cursor_done := '1';
IF NOT v_lead_note_cursor_done <> 0 THEN BEGIN INSERT INTO "archivedleadnote" (
  "id", "lead_Id", "note", "createdby", 
  "modifiedby", "createdts", "lastmodifiedts", 
  "synctimestamp", "softdeleteflag"
) (
  SELECT 
    "leadnote"."id", 
    "leadnote"."lead_Id", 
    "leadnote"."note", 
    "leadnote"."createdby", 
    "leadnote"."modifiedby", 
    "leadnote"."createdts", 
    "leadnote"."lastmodifiedts", 
    "leadnote"."synctimestamp", 
    "leadnote"."softdeleteflag" 
  FROM 
    "leadnote" 
  WHERE 
    "leadnote"."id" = v_curr_leadnote_id
);
DELETE "leadnote" 
WHERE 
  "leadnote"."id" = v_curr_leadnote_id;
END;
END IF;
IF v_lead_note_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_lead_cursor_done := '0';
v_lead_note_cursor_done := '0';
CLOSE leadnote_cursor;
END;
DELETE "lead" 
WHERE 
  "lead"."id" = v_curr_lead_id;
END;
END IF;
IF v_lead_cursor_done <> 0 THEN EXIT;
END IF;
END;
END LOOP;
v_lead_cursor_done := '0';
v_lead_note_cursor_done := '0';
CLOSE lead_cursor;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
