--  DDL for Procedure limits_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "limits_update_proc" (
  "_action" IN VARCHAR2, "_companyLegalUnit" IN VARCHAR2, 
  "_maxTxLimit" IN NUMBER, "_dailyLimit" IN NUMBER, 
  "_weeklyLimit" IN NUMBER
) AS BEGIN 
UPDATE 
  "groupactionlimit" 
SET 
  "value" = "_maxTxLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > "_maxTxLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "groupactionlimit" 
SET 
  "value" = "_dailyLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'DAILY_LIMIT' 
  AND "value" > "_dailyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "groupactionlimit" 
SET 
  "value" = "_weeklyLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'WEEKLY_LIMIT' 
  AND "value" > "_weeklyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "servicedefinitionactionlimit" 
SET 
  "value" = "_maxTxLimit" 
WHERE 
  'actionId' = "_action" 
  AND "limitTypeId" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > "_maxTxLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "servicedefinitionactionlimit" 
SET 
  "value" = "_dailyLimit" 
WHERE 
  "actionId" = "_action" 
  AND "limitTypeId" = 'DAILY_LIMIT' 
  AND "value" > "_dailyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "servicedefinitionactionlimit" 
SET 
  "value" = "_weeklyLimit" 
WHERE 
  "actionId" = "_action" 
  AND "limitTypeId" = 'WEEKLY_LIMIT' 
  AND "value" > "_weeklyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "contractactionlimit" 
SET 
  "value" = "_maxTxLimit" 
WHERE 
  "actionId" = "_action" 
  AND "limitTypeId" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > "_maxTxLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "contractactionlimit" 
SET 
  "value" = "_dailyLimit" 
WHERE 
  "actionId" = "_action" 
  AND "limitTypeId" = 'DAILY_LIMIT' 
  AND "value" > "_dailyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "contractactionlimit" 
SET 
  "value" = "_weeklyLimit" 
WHERE 
  "actionId" = "_action" 
  AND "limitTypeId" = 'WEEKLY_LIMIT' 
  AND "value" > "_weeklyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "customeraction" 
SET 
  "value" = "_maxTxLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > "_maxTxLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "customeraction" 
SET 
  "value" = "_dailyLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'DAILY_LIMIT' 
  AND "value" > "_dailyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
UPDATE 
  "customeraction" 
SET 
  "value" = "_weeklyLimit" 
WHERE 
  "Action_id" = "_action" 
  AND "LimitType_id" = 'WEEKLY_LIMIT' 
  AND "value" > "_weeklyLimit" 
  AND "companyLegalUnit" = "_companyLegalUnit";
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure Location_address_suggestions_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "Location_address_suggestions_proc" (
  "_CURRLATITUDE" IN nvarchar2, "_CURRLONGITUDE" IN nvarchar2, 
  "_RADIUS" IN float, "_VAR" IN nvarchar2, 
  "records" out SYS_REFCURSOR
) AS BEGIN DECLARE v_rad float(53) := "_RADIUS";
v_variable nvarchar2(2000) := "_VAR";
BEGIN v_variable := ('%' || v_variable || '%');
v_rad := v_rad / 1000;
OPEN "records" FOR 
SELECT 
  ("location"."id") "locationId", 
  (
    SELECT 
      DISTINCT (
        LISTAGG(
          (
            UPPER(
              SUBSTR(
                "dayschedule"."WeekDayName", 1, 1
              )
            )+ LOWER(
              SUBSTR(
                "dayschedule"."WeekDayName", 1, 2
              )
            )+ ':' + SUBSTR(
              CAST(
                "dayschedule"."StartTime" AS nvarchar2(2000)
              ), 
              1, 
              5
            )+ '-' + SUBSTR(
              CAST(
                "dayschedule"."EndTime" AS nvarchar2(2000)
              ), 
              1, 
              5
            )
          ), 
          ' || '
        )
      ) 
    FROM 
      "dayschedule", 
      "location" 
    WHERE 
      "dayschedule"."WorkSchedule_id" = "location"."WorkSchedule_id" 
      AND ("location"."id") = "location"."id"
  ) "workingHours", 
  "location"."Name" "informationTitle", 
  "location"."Description" "description", 
  "location"."PhoneNumber" "phone", 
  "location"."EmailId" "email", 
  CASE "location"."softdeleteflag" WHEN 0 THEN 'OPEN' ELSE 'CLOSED' END "status", 
  CASE "location"."Type_id" WHEN 'ATM' THEN 'ATM' ELSE 'BRANCH' END "type", 
  "location"."Status_id" "isVisible", 
  (
    SELECT 
      LISTAGG("facility"."name", '||') WITHIN GROUP (
        ORDER BY 
          "facility"."id" ASC
      ) 
    FROM 
      (
        "facility" CROSS 
        JOIN "locationfacility"
      ) 
    WHERE 
      (
        (
          "facility"."id" = (
            "locationfacility"."facility_id"
          )
        ) 
        AND (
          (
            "locationfacility"."Location_id"
          ) = "location"."id"
        )
      )
  ) "services", 
  (
    SELECT 
      "address"."cityName" 
    FROM 
      "address" 
    WHERE 
      "address"."id" = "location"."Address_id"
  ) "city", 
  (
    SELECT 
      "region"."Name" 
    FROM 
      "region" 
    WHERE 
      (
        "region"."id" = "address"."Region_id"
      )
  ) "Region", 
  (
    SELECT 
      "country"."Name" 
    FROM 
      "country" 
    WHERE 
      (
        ("country"."id") = (
          SELECT 
            "region"."Country_id" 
          FROM 
            "region" 
          WHERE 
            (
              "region"."id" = "address"."Region_id"
            )
        )
      )
  ) "country", 
  "address"."addressLine1" "addressLine1", 
  "address"."addressLine2" "addressLine2", 
  "address"."addressLine3" "addressLine3", 
  "address"."zipCode" "zipCode", 
  "address"."latitude" "latitude", 
  "address"."logitude" "longitude", 
  (
    6371 * 2 * asin(
      sqrt(
        power(
          sin(
            (
              (
                CAST(
                  "address"."latitude" AS float(53)
                )
              ) - abs(
                CAST(
                  "_CURRLATITUDE" AS float(53)
                )
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        ) + cos(
          (
            CAST(
              "address"."latitude" AS float(53)
            )
          ) * (
            2 * asin(1)
          ) / 180
        ) * cos(
          abs(
            CAST(
              "_CURRLATITUDE" AS float(53)
            )
          ) * (
            2 * asin(1)
          ) / 180
        ) * power(
          sin(
            (
              (
                CAST(
                  "address"."logitude" AS float(53)
                )
              ) - (
                CAST(
                  "_CURRLONGITUDE" AS float(53)
                )
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        )
      )
    )
  ) AS "distance" 
FROM 
  "address", 
  "location" 
WHERE 
  "address"."id" = "location"."Address_id" 
GROUP BY 
  "location"."Address_id", 
  "address"."latitude", 
  "address"."logitude", 
  "address"."type", 
  "location"."Name", 
  "location"."PhoneNumber", 
  "address"."country", 
  "location"."Status_id", 
  "address"."Region_id", 
  "location"."id", 
  "location"."Description", 
  "location"."EmailId", 
  "location"."softdeleteflag", 
  "location"."Type_id", 
  "address"."addressLine1", 
  "address"."addressLine2", 
  "address"."addressLine3", 
  "address"."zipCode" 
HAVING 
  (
    (
      6371 * 2 * asin(
        sqrt(
          power(
            sin(
              (
                (
                  CAST(
                    "address"."latitude" AS float(53)
                  )
                ) - abs(
                  CAST(
                    "_CURRLATITUDE" AS float(53)
                  )
                )
              ) * (
                2 * asin(1)
              ) / 180 / 2
            ), 
            2
          ) + cos(
            (
              CAST(
                "address"."latitude" AS float(53)
              )
            ) * (
              2 * asin(1)
            ) / 180
          ) * cos(
            abs(
              CAST(
                "_CURRLATITUDE" AS float(53)
              )
            ) * (
              2 * asin(1)
            ) / 180
          ) * power(
            sin(
              (
                (
                  CAST(
                    "address"."logitude" AS float(53)
                  )
                ) - (
                  CAST(
                    "_CURRLONGITUDE" AS float(53)
                  )
                )
              ) * (
                2 * asin(1)
              ) / 180 / 2
            ), 
            2
          )
        )
      )
    )
  ) <= v_rad 
  AND (
    (
      (
        SELECT 
          "address"."cityName" 
        FROM 
          "address" 
        WHERE 
          "address"."id" = "location"."Address_id"
      )
    ) LIKE v_variable 
    OR "address"."type" LIKE v_variable 
    OR (
      SELECT 
        "region"."Name" 
      FROM 
        "region" 
      WHERE 
        (
          "region"."id" = "address"."Region_id"
        )
    ) LIKE v_variable 
    OR "location"."Name" LIKE v_variable 
    OR "location"."PhoneNumber" LIKE v_variable 
    OR "address"."country" LIKE v_variable
  ) 
  AND ("location"."Status_id") = 'SID_ACTIVE';
END;
END;
/

--  DDL for Procedure location_details_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "location_details_proc" (
  v_locationId IN char, "location" out SYS_REFCURSOR
) AS BEGIN DECLARE v_workingHours nvarchar2(2000) := '';
v_tempDayName nvarchar2(2000) := '';
v_tempStartTime nvarchar2(2000) := '';
v_tempEndTime nvarchar2(2000) := '';
v_servicesList nvarchar2(2000);
v_currencyList varchar2(2000);
v_b int;
v_a varchar2(2000) := '';
v_wh varchar2(2000) := '';
v_pipeFlag int := 0;
CURSOR cur_1 IS 
SELECT 
  "dayschedule"."WeekDayName", 
  "dayschedule"."StartTime", 
  "dayschedule"."EndTime" 
FROM 
  "dayschedule", 
  "location" 
WHERE 
  "location"."WorkSchedule_id" = "dayschedule"."WorkSchedule_id" 
  AND "location"."id" = v_locationId;
BEGIN OPEN cur_1;
LOOP FETCH cur_1 INTO v_tempDayName, 
v_tempStartTime, 
v_tempEndTime;
EXIT WHEN cur_1 % notfound;
IF v_tempDayName <> '' THEN BEGIN IF v_pipeFlag = 0 THEN v_a := (
  upper(
    SUBSTR(v_tempDayName, 1, 1)
  )
) + (
  lower(
    substr(
      v_tempDayName, 
      2, 
      LENGTH(v_tempDayName)
    )
  )
) + (': ') + (
  substr(v_tempStartTime, 1, 5)
) + ('AM') + (' - ') + (
  substr(v_tempEndTime, 1, 5)
) + ('PM');
ELSE v_a := (' || ') + (
  upper(
    SUBSTR(v_tempDayName, 1, 1)
  )
) + (
  lower(
    substr(
      v_tempDayName, 
      2, 
      LENGTH(v_tempDayName)
    )
  )
) + (': ') + (
  substr(v_tempStartTime, 1, 5)
) + ('AM') + (' - ') + (
  substr(v_tempEndTime, 1, 5)
) + ('PM');
v_pipeFlag := 1;
v_a := (' || ') + (v_tempDayName) + (': ') + (v_tempStartTime) + ('AM') + (' - ') + (v_tempEndTime) + ('PM');
v_wh := (v_wh) + (' ') + (v_a) + ('');
-- END;
END IF;
END;
END IF;
IF v_b = 1 THEN EXIT;
END IF;
END LOOP;
CLOSE cur_1;
--DEALLOCATE cur_1;
v_workingHours := v_wh;
SELECT 
  listagg(
    CAST(
      "service"."Name" as nvarchar2(2000)
    ), 
    ' || '
  ) WITHIN GROUP (
    ORDER BY 
      "service"."Name" ASC
  ) services INTO v_servicesList 
FROM 
  "service", 
  "locationservice" 
WHERE 
  "service"."id" = "locationservice"."Service_id" 
  AND "locationservice"."Location_id" = v_locationId;
SELECT 
  listagg("currency"."code", ',') WITHIN GROUP (
    ORDER BY 
      "currency"."code" ASC
  ) currencies INTO v_currencyList 
FROM 
  "currency", 
  "locationcurrency" 
WHERE 
  "currency"."code" = "locationcurrency"."currency_code" 
  AND "locationcurrency"."Location_id" = v_locationId;
OPEN "location" FOR 
SELECT 
  "location"."id" locationId, 
  "location"."Type_id" type, 
  "location"."Name" informationTitle, 
  CASE "location"."Status_id" WHEN cast(
    'SID_ACTIVE' as nvarchar2(255)
  ) THEN 'OPEN' ELSE 'CLOSED' END AS status, 
  "location"."DisplayName" displayName, 
  "location"."Description" description, 
  "location"."PhoneNumber" phone, 
  "location"."EmailId" email, 
  "location"."WorkingDays" workingDays, 
  "location"."IsMainBranch" isMainBranch, 
  "location"."MainBranchCode" mainBranchCode, 
  "address"."addressLine1" addressLine1, 
  "address"."addressLine2" addressLine2, 
  "address"."addressLine3" addressLine3, 
  "address"."latitude" latitude, 
  "address"."logitude" longitude, 
  v_workingHours workingHours, 
  v_servicesList services, 
  v_currencyList currencies 
FROM 
  (
    (
      "location" 
      INNER JOIN "address" ON (
        (
          "location"."Address_id" = "address"."id"
        )
      )
    )
  ) 
WHERE 
  "location"."id" = v_locationId;
END;
END;
/

--  DDL for Procedure location_range_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "location_range_proc" (
  v_currLatitude IN nvarchar2, v_currLongitude IN nvarchar2, 
  v_radius IN number, records1 out SYS_REFCURSOR
) AS BEGIN OPEN records1 FOR 
SELECT 
  min("location"."id") locationId, 
  (
    SELECT 
      DISTINCT(
        listagg(
          (
            upper(
              SUBSTR(
                "dayschedule"."WeekDayName", 1, 1
              )
            )+ lower(
              SUBSTR(
                "dayschedule"."WeekDayName", 
                2, 
                LENGTH("dayschedule"."WeekDayName")
              )
            )+ ':' + SUBSTR(
              CAST(
                "dayschedule"."StartTime" AS VARCHAR2(2000)
              ), 
              1, 
              5
            )+ '-' + SUBSTR(
              CAST(
                "dayschedule"."EndTime" AS VARCHAR2(2000)
              ), 
              1, 
              5
            )
          ), 
          ' || '
        )
      ) 
    FROM 
      "dayschedule", 
      "location" 
    WHERE 
      "dayschedule"."WorkSchedule_id" = "location"."WorkSchedule_id" 
      AND "location"."id" = "location"."id"
  ) workingHours, 
  min("location"."Name") informationTitle, 
  min("location"."PhoneNumber") phone, 
  min("location"."EmailId") email, 
  CASE min("location"."Status_id") WHEN cast(
    'SID_ACTIVE' as nvarchar2(255)
  ) THEN 'OPEN' ELSE 'CLOSED' END as status, 
  min("location"."Type_id") type, 
  min("location"."Status_id") isVisible, 
  (
    SELECT 
      listagg(
        CAST(
          "facility"."name" as nvarchar2(2000)
        ), 
        '||'
      ) WITHIN GROUP (
        ORDER BY 
          "facility"."id" ASC
      ) 
    FROM 
      "facility", 
      "locationfacility" 
    WHERE 
      "facility"."id" = "locationfacility"."facility_id" 
      AND "locationfacility"."Location_id" = (
        select 
          min("location"."id") 
        from 
          "location"
      )
  ) services, 
  (
    SELECT 
      "city"."Name" 
    FROM 
      "city" 
    WHERE 
      "city"."id" = (
        select 
          min("address"."City_id") 
        from 
          "address"
      )
  ) city, 
  min("address"."addressLine1") addressLine1, 
  min("address"."addressLine2") addressLine2, 
  min("address"."addressLine3") addressLine3, 
  min("address"."zipCode") zipCode, 
  min("address"."latitude") latitude, 
  min("address"."logitude") longitude, 
  (
    6371 * 2 * asin(
      sqrt(
        power(
          sin(
            (
              CAST(
                min("address"."latitude") AS float(53)
              ) - abs(
                CAST(
                  v_currLatitude AS float(53)
                )
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        ) + cos(
          CAST(
            min("address"."latitude") AS float(53)
          ) * (
            2 * asin(1)
          ) / 180
        ) * cos(
          abs(
            CAST(
              v_currLatitude AS float(53)
            )
          ) * (
            2 * asin(1)
          ) / 180
        ) * power(
          sin(
            (
              CAST(
                min("address"."logitude") AS float(53)
              ) - CAST(
                v_currLongitude AS float(53)
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        )
      )
    )
  ) AS distance 
FROM 
  "address", 
  "location" 
WHERE 
  "address"."id" = "location"."Address_id" 
group by 
  "address"."id", 
  "location"."Address_id" 
having 
  (
    6371 * 2 * asin(
      sqrt(
        power(
          sin(
            (
              CAST(
                min("address"."latitude") AS float(53)
              ) - abs(
                CAST(
                  v_currLatitude AS float(53)
                )
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        ) + cos(
          CAST(
            min("address"."latitude") AS float(53)
          ) * (
            2 * asin(1)
          ) / 180
        ) * cos(
          abs(
            CAST(
              v_currLatitude AS float(53)
            )
          ) * (
            2 * asin(1)
          ) / 180
        ) * power(
          sin(
            (
              CAST(
                min("address"."logitude") AS float(53)
              ) - CAST(
                v_currLongitude AS float(53)
              )
            ) * (
              2 * asin(1)
            ) / 180 / 2
          ), 
          2
        )
      )
    )
  ) <= v_radius;
END;
/

--  DDL for Procedure location_search_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "location_search_proc" -- ddl_admin.sql starts
(
  iv__searchKeyword IN VARCHAR2, v_cursor OUT SYS_REFCURSOR
) AS v__searchKeyword VARCHAR2(1000) := iv__searchKeyword;
v__next VARCHAR2(4000) := NULL;
v__nextlen NUMBER(10, 0) := NULL;
v__value VARCHAR2(4000) := NULL;
v_sql1 VARCHAR2(4000);
v_sqlFrontPart VARCHAR2(4000);
v_sqlresult VARCHAR2(4000) := NULL;
v_counter NUMBER(10, 0);
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
v_sqlFrontPart := 'SELECT * FROM "locationdetails_view" where ';
v_counter := 1;
WHILE (1 = 1) LOOP DECLARE v_var VARCHAR2(4000) := NULL;
BEGIN IF LENGTHB(
  LTRIM(
    RTRIM(v__searchKeyword)
  )
) = 0 
OR v__searchKeyword IS NULL THEN EXIT;
END IF;
v__next := UTILS.SUBSTRING_INDEX(v__searchKeyword, ',', 1);
v__nextlen := LENGTHB(v__next);
v__value := LOWER(
  LTRIM(
    RTRIM(v__next)
  )
);
v_sql1 := NULL;
v_var := NULL;
v_var := REPLACE(
  LTRIM(
    RTRIM(v__value)
  ), 
  ' ', 
  '%'
);
v_sql1 := ('( LOWER("city") like (''') || ('%') || (v_var) || ('%') || (
  ''')  or LOWER("informationTitle") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("name") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("Description") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("Code") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("phoneNumber") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("email") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("status") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("type") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("services") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''')  or LOWER("region") like ('''
) || ('%') || (v_var) || ('%') || (
  ''')  or LOWER("addressLine1") like ('''
) || ('%') || (v_var) || ('%') || +(
  ''') or LOWER("addressLine2") like ('''
) || ('%') || (v_var) || ('%') || (
  ''')  or LOWER("addressLine3") like ('''
) || ('%') || (v_var) || ('%') || (
  ''')  or LOWER("country") like ('''
) || ('%') || (v_var) || ('%') || (
  ''')  or LOWER("zipcode") like ('''
) || ('%') || (v_var) || ('%') || ('''))');
IF v_counter = 1 THEN v_sqlresult := v_sql1;
ELSE v_sqlresult := (v_sql1) || (' AND ') || (v_sqlresult);
END IF;
v_counter := v_counter + 1;
v__searchKeyword := REPLACE(
  v__searchKeyword, 
  SUBSTR(
    v__searchKeyword, 1, v__nextlen + 1
  ), 
  ''
);
END;
END LOOP;
v_sqlresult := ('(') || (v_sqlFrontPart) || (v_sqlresult) || (')');
EXECUTE IMMEDIATE v_sqlresult;
OPEN v_cursor FOR v_sqlresult;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure manageapprovalmatrix_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "manageapprovalmatrix_update_proc" (
  "_contractId" IN NVARCHAR2, "_cifList" IN NVARCHAR2, 
  "_isDisabledflag" IN NVARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_numOfRecords NUMBER(10, 0);
v_recordsData NVARCHAR2(2000);
v_count NUMBER(10, 0) := 0;
v_query NVARCHAR2(2000);
v_query2 NVARCHAR2(2000);
v_cquery NVARCHAR2(2000);
v_var NVARCHAR2(2000);
stmt varchar2(2000);
stmt1 varchar2(2000);
stmt2 varchar2(2000);
v_temp varchar2(2000);
cnt NUMBER;
BEGIN 
SELECT 
  COUNT(*) INTO cnt 
FROM 
  user_tables 
WHERE 
  table_name = 'ora$ptt_v_resultcount';
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ora$ptt_v_resultcount';
EXCEPTION WHEN OTHERS THEN dbms_output.put_line('No temp table found');
END;
v_numOfRecords := LENGTH("_cifList") - LENGTH(
  REPLACE("_cifList", ',', '')
) + 1;
stmt := 'CREATE PRIVATE TEMPORARY TABLE ora$ptt_v_resultcount
(
  rowcount NUMBER(10,0) 
)ON COMMIT PRESERVE DEFINITION';
execute immediate stmt;
WHILE (1 = 1) LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_numOfRecords + 1 THEN EXIT;
ELSE BEGIN v_recordsData := (
  SUBSTRING_INDEX(
    SUBSTRING_INDEX("_cifList", ',', v_index1), 
    ',', 
    -1
  )
);
select 
  count(*) into v_temp 
from 
  "manageapprovalmatrix" 
where 
  "contractId" = "_contractId" 
  and "coreCustomerId" = v_recordsData;
execute immediate q '[INSERT INTO ora$ptt_v_resultcount VALUES(]' || v_temp || q '[)]';
commit;
-- CLOSE cv_ins;
execute immediate 'SELECT rowcount FROM ora$ptt_v_resultcount  
              FETCH FIRST 1 ROWS ONLY ' into v_count;
IF v_count = 0 THEN BEGIN v_query := CONCAT(
  'INSERT INTO "manageapprovalmatrix"("contractId","coreCustomerId","isDisabled") VALUES (' || "_contractId" || ',' || v_recordsData || ',' || "_isDisabledflag", 
  ')'
);
EXECUTE IMMEDIATE v_query;
dbms_output.put_line(v_query);
END;
ELSE BEGIN v_query2 := 'UPDATE "manageapprovalmatrix" set "isDisabled"=' || "_isDisabledflag" || ' where "contractId"=' || "_contractId" || ' and "coreCustomerId"=' || v_recordsData;
EXECUTE IMMEDIATE v_query2;
dbms_output.put_line(v_query2);
END;
END IF;
END;
END IF;
END;
END LOOP;
EXECUTE IMMEDIATE 'DROP TABLE ora$ptt_v_resultcount';
END;
