--  DDL for Procedure requestmessages_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "requestmessages_proc" (
  "_customerRequestID" IN VARCHAR2, 
  "_fetchDraftMessages" IN NUMBER, 
  "records" OUT SYS_REFCURSOR
) AS BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN "records" FOR 
SELECT 
  "requestmessage"."id" "Message_id", 
  (
    SELECT 
      COUNT("messageattachment"."id") 
    FROM 
      "messageattachment" 
    WHERE 
      "messageattachment"."RequestMessage_id" = "requestmessage"."id"
  ) "totalAttachments", 
  "messageattachment"."id" "Messageattachment_id", 
  "messageattachment"."Media_id" "Media_id", 
  "media"."Name" "Media_Name", 
  "media"."Type" "Media_Type", 
  "media"."Size" "Media_Size_", 
  --replaced Size_ with Size
  "requestmessage"."CustomerRequest_id" "CustomerRequest_id", 
  "requestmessage"."RepliedBy" "RepliedBy", 
  "requestmessage"."MessageDescription" "MessageDescription", 
  "requestmessage"."ReplySequence" "ReplySequence", 
  "requestmessage"."IsRead" "IsRead", 
  "requestmessage"."createdby" "createdby", 
  "requestmessage"."RepliedBy_Name" "createdby_name", 
  "requestmessage"."modifiedby" "modifiedby", 
  "requestmessage"."createdts" "createdts", 
  "requestmessage"."lastmodifiedts" "lastmodifiedts", 
  "requestmessage"."synctimestamp" "synctimestamp", 
  "requestmessage"."softdeleteflag" "softdeleteflag" 
FROM 
  (
    (
      "requestmessage" 
      LEFT JOIN "messageattachment" ON (
        (
          "requestmessage"."id" = "messageattachment"."RequestMessage_id"
        )
      )
    ) 
    LEFT JOIN "media" ON (
      (
        "messageattachment"."Media_id" = "media"."id"
      )
    )
  ) 
WHERE 
  "requestmessage"."CustomerRequest_id" = "_customerRequestID" 
  AND CASE WHEN ("_fetchDraftMessages" = 1) THEN 1 ELSE CASE WHEN (
    "requestmessage"."IsRead" <> 'draft'
  ) THEN 1 ELSE 0 END END <> 0 
ORDER BY 
  "requestmessage"."ReplySequence" ASC;
--DBMS_SQL.RETURN_RESULT("requestmessage");
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

