OR REPLACE NONEDITIONABLE PROCEDURE "rolepermission_update_approval_proc" (
  v__roleId IN VARCHAR2, v__PermissionIds IN CLOB, 
  v__requestId IN VARCHAR2
) AS v_caid VARCHAR2(50);
v_isEnabled VARCHAR2(10);
v_finished NUMBER(10, 0) := 0;
v_caid_count NUMBER(10, 0) := 0;
CURSOR caids IS 
SELECT 
  c."id", 
  c."isEnabled" 
FROM 
  "compositeaction" c 
WHERE 
  (
    "Permission_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
