BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
OPEN caids;
<< MANAGECAIDS >> WHILE 1 = 1 LOOP BEGIN FETCH caids INTO v_caid, 
v_isEnabled;
IF caids % FOUND <> FALSE THEN BEGIN GOTO MANAGECAIDS$LEAVE;
END;
