SET 
  "crudAction" = 'DEL' 
WHERE 
  "aprRequestId" = v__requestId 
  AND "CompositeAction_id" = v_caid;
END;
END IF;
END;
END LOOP;
<< MANAGECAIDS$LEAVE >> CLOSE caids;
UPDATE 
  "rolepermission_approval" 
SET 
  "crudAction" = 'DEL' 
WHERE 
  "aprRequestId" = v__requestId 
  AND "Role_id" = v__roleId 
  AND (
    "Permission_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT(v__PermissionIds)
