--  DDL for Procedure rolePermissionDelete_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "rolePermissionDelete_proc" (
  "_roleId" IN VARCHAR2, "_PermissionIds" IN VARCHAR2, 
  "_companyLegalUnit" IN VARCHAR2
) AS v_caid VARCHAR2(50);
v_isEnabled VARCHAR2(10);
v_finished NUMBER(10, 0) := 0;
v_caid_count NUMBER(10, 0) := 0;
CURSOR caids IS 
SELECT 
  c."id", 
  c."isEnabled" 
FROM 
  "compositeaction" c 
WHERE 
  FIND_IN_SET(
    "Permission_id", "_PermissionIds"
  ) > 0;
BEGIN OPEN caids;
WHILE 1 = 1 LOOP BEGIN FETCH caids INTO v_caid, 
v_isEnabled;
