  AND c."id" = v_caid;
IF v_caid_count = 0 THEN BEGIN DELETE "rolecompositeaction" 
WHERE 
  "Role_id" = "_roleId" 
  AND "CompositeAction_id" = v_caid 
  AND "companyLegalUnit" = "_companyLegalUnit";
END;
END IF;
END;
