--  DDL for Procedure rolescompositeactions_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "rolescompositeactions_proc" (
  "_roleIds" IN VARCHAR2, "_isEnabled" IN NUMBER, 
  "records" out SYS_REFCURSOR
) AS BEGIN IF "_isEnabled" is NOT NULL then OPEN "records" FOR 
SELECT 
  "CompositeAction_id" "CompositeAction_id", 
  CASE WHEN "isEnabled" = '1' THEN 'true' ELSE 'false' END "isEnabled" 
FROM 
  "rolecompositeaction" 
WHERE 
  FIND_IN_SET(
    "rolecompositeaction"."Role_id", 
    "_roleIds"
  ) > 0 
  AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" = 1 THEN 1 ELSE 0 END 
UNION 
SELECT 
  "CompositeAction_id" CompositeAction_id, 
  CASE WHEN "isEnabled" = 1 THEN 'true' ELSE 'false' END isEnabled 
FROM 
  "rolecompositeaction" 
WHERE 
  (
    "rolecompositeaction"."Role_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT("_roleIds")
        )
    )
  ) 
  AND "rolecompositeaction"."CompositeAction_id" NOT IN (
    SELECT 
      "CompositeAction_id" CompositeAction_id 
    FROM 
      "rolecompositeaction" 
    WHERE 
      (
        "rolecompositeaction"."Role_id" IN (
          SELECT 
            COLUMN_VALUE 
          FROM 
            TABLE(
              UTILS.STRING_SPLIT("_roleIds")
            )
        )
      ) 
      AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" IS NULL THEN 1 ELSE NULL END
  ) 
  AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" IS NULL THEN 0 ELSE NULL END;
ELSE OPEN "records" for 
SELECT 
  "CompositeAction_id" CompositeAction_id, 
  CASE WHEN "isEnabled" = 1 THEN 'true' ELSE 'false' END isEnabled 
FROM 
  "rolecompositeaction" 
WHERE 
  (
    "rolecompositeaction"."Role_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT("_roleIds")
        )
    )
  ) 
  AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" IS NULL THEN 1 ELSE NULL END 
UNION 
SELECT 
  "CompositeAction_id" CompositeAction_id, 
  CASE WHEN "isEnabled" = 1 THEN 'true' ELSE 'false' END isEnabled 
FROM 
  "rolecompositeaction" 
WHERE 
  (
    "rolecompositeaction"."Role_id" IN (
      SELECT 
        COLUMN_VALUE 
      FROM 
        TABLE(
          UTILS.STRING_SPLIT("_roleIds")
        )
    )
  ) 
  AND "rolecompositeaction"."CompositeAction_id" NOT IN (
    SELECT 
      "CompositeAction_id" CompositeAction_id 
    FROM 
      "rolecompositeaction" 
    WHERE 
      (
        "rolecompositeaction"."Role_id" IN (
          SELECT 
            COLUMN_VALUE 
          FROM 
            TABLE(
              UTILS.STRING_SPLIT("_roleIds")
            )
        )
      ) 
      AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" IS NULL THEN 1 ELSE NULL END
  ) 
  AND "rolecompositeaction"."isEnabled" = CASE WHEN "_isEnabled" IS NULL THEN 0 ELSE NULL END;
END IF;
END;
/

--  DDL for Procedure servicedefinition_action_limits_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "servicedefinition_action_limits_update_proc" (
  v__action IN VARCHAR2, v__maxTxLimit IN NUMBER, 
  v__dailyLimit IN NUMBER, v__weeklyLimit IN NUMBER, 
  v__contractIdValues IN VARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_numOfRecords NUMBER(10, 0);
v_contractId VARCHAR2(50);
BEGIN v_numOfRecords := LENGTH(v__contractIdValues) - LENGTH(
  REPLACE(v__contractIdValues, ',', ' ')
) || 1;
WHILE 1 = 1 LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_numOfRecords + 1 THEN BEGIN EXIT;
END;
ELSE BEGIN v_contractId := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(
    v__contractIdValues, ',', v_index1
  ), 
  ',', 
  -1
);
UPDATE 
  "contractactionlimit" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "contractId" = v_contractId 
  AND "actionId" = v__action 
  AND "limitTypeId" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > v__maxTxLimit;
UPDATE 
  "contractactionlimit" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "contractId" = v_contractId 
  AND "actionId" = v__action 
  AND "limitTypeId" = 'DAILY_LIMIT' 
  AND "value" > v__dailyLimit;
UPDATE 
  "contractactionlimit" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "contractId" = v_contractId 
  AND "actionId" = v__action 
  AND "limitTypeId" = 'WEEKLY_LIMIT' 
  AND "value" > v__weeklyLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__maxTxLimit 
WHERE 
  "contractId" = v_contractId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'MAX_TRANSACTION_LIMIT' 
  AND "value" > v__maxTxLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__dailyLimit 
WHERE 
  "contractId" = v_contractId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'DAILY_LIMIT' 
  AND "value" > v__dailyLimit;
UPDATE 
  "customeraction" 
SET 
  "value" = v__weeklyLimit 
WHERE 
  "contractId" = v_contractId 
  AND "Action_id" = v__action 
  AND "LimitType_id" = 'WEEKLY_LIMIT' 
  AND "value" > v__weeklyLimit;
END;
END IF;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure servicedefinition_defaultgroup_update_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "servicedefinition_defaultgroup_update_proc" (
  v__serviceDefinitionId IN VARCHAR2, 
  v__groupId IN VARCHAR2, v__isDefault IN VARCHAR2, 
  v__companyLegalUnit IN VARCHAR2
) AS BEGIN IF (v__isDefault = '0') THEN 
UPDATE 
  "groupservicedefinition" 
SET 
  "isDefaultGroup" = '0' 
WHERE 
  "groupservicedefinition"."serviceDefinitionId" = v__serviceDefinitionId 
  AND "groupservicedefinition"."Group_id" = v__groupId 
  AND "groupservicedefinition"."companyLegalUnit" = v__companyLegalUnit;
ELSE BEGIN 
UPDATE 
  "groupservicedefinition" 
SET 
  "isDefaultGroup" = '0' 
WHERE 
  "groupservicedefinition"."serviceDefinitionId" = v__serviceDefinitionId 
  AND "groupservicedefinition"."companyLegalUnit" = v__companyLegalUnit;
UPDATE 
  "groupservicedefinition" 
SET 
  "isDefaultGroup" = '1' 
WHERE 
  "groupservicedefinition"."serviceDefinitionId" = v__serviceDefinitionId 
  AND "groupservicedefinition"."Group_id" = v__groupId 
  AND "groupservicedefinition"."companyLegalUnit" = v__companyLegalUnit;
END;
END IF;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

