CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "update_bbactedrequest_proc" (v__requestId IN VARCHAR2) AS BEGIN 
UPDATE 
  "bbactedrequest" 
SET 
  "softdeleteflag" = '1' 
WHERE 
  ("requestId" = v__requestId);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
