/

--  DDL for Procedure update_customer_erasure_status_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "update_customer_erasure_status_proc" (
  v__customerId IN VARCHAR2, v__erasureStatus IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v_currentStatusId VARCHAR2(100) := '';
v_executeQuery VARCHAR2(4000) := '';
v_updatedStatusId VARCHAR2(100) := '';
BEGIN IF v__customerId <> ' ' THEN BEGIN 
SELECT 
  "Status_id" INTO v_currentStatusId 
FROM 
  "customer" 
WHERE 
  "id" = v__customerId;
IF v_currentStatusId <> '' THEN BEGIN IF v__erasureStatus = 'ERASED' THEN BEGIN IF v_currentStatusId = 'SID_CUS_ERASURE_INPROGRESS' THEN BEGIN v_updatedStatusId := 'SID_CUS_ERASURE_COMPLETED';
v_executeQuery := (
  'UPDATE "customer" SET Status_id = ''' || v_updatedStatusId || ''' WHERE id = ''' || v__customerId || ''''
);
EXECUTE IMMEDIATE v_executeQuery;
END;
ELSE IF v_currentStatusId <> 'SID_CUS_ERASURE_COMPLETED' THEN BEGIN OPEN v_cursor FOR 
SELECT 
  'ERASURE_NOT_INITIATED' errmsg 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
END;
END IF;
END IF;
END;
ELSE IF v__erasureStatus = 'ERASURE.IN.PROGRESS' THEN BEGIN IF v_currentStatusId <> 'SID_CUS_ERASURE_INPROGRESS' 
AND v_currentStatusId <> 'SID_CUS_ERASURE_COMPLETED' THEN BEGIN v_updatedStatusId := 'SID_CUS_ERASURE_INPROGRESS';
v_executeQuery := (
  'UPDATE "customer" SET "Status_id" = ''' || v_updatedStatusId || ''' WHERE "id" = ''' || v__customerId || ''''
);
EXECUTE IMMEDIATE v_executeQuery;
END;
ELSE IF v_currentStatusId = 'SID_CUS_ERASURE_COMPLETED' THEN BEGIN OPEN v_cursor FOR 
SELECT 
  'ALREADY_ERASED' errmsg 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
END;
END IF;
END IF;
END;
END IF;
END IF;
END;
END IF;
END;
END IF;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure update_requestapprovalmatrix_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "update_requestapprovalmatrix_proc" (
  v__requestApprovalMatrixId IN VARCHAR2
) AS BEGIN 
UPDATE 
  "requestapprovalmatrix" 
SET 
  "receivedApprovals" = "receivedApprovals" + 1 
WHERE 
  "requestapprovalmatrix"."id" IN (
    SELECT 
      column_value 
    from 
      TABLE(
        UTILS.STRING_SPLIT(v__requestApprovalMatrixId)
      )
  );
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure update_signatorygroup_for_user_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "update_signatorygroup_for_user_proc" (
  v__coreCustomerId IN VARCHAR2, v__contractId IN VARCHAR2, 
  v__customerId IN VARCHAR2, v__signatorygroupId IN VARCHAR2
) AS v_index1 NUMBER(10, 0) := 0;
v_length NUMBER(10, 0) := 0;
v_cusrecord VARCHAR2(4000);
v_cus VARCHAR2(4000);
BEGIN v_length := LENGTH(v__customerId) - LENGTH(
  REPLACE(v__customerId, ',', ' ')
) || 1;
<< loop_1 >> WHILE (1 = 1) LOOP BEGIN v_index1 := v_index1 + 1;
IF v_index1 = v_length + 1 THEN EXIT;
ELSE BEGIN v_cusrecord := UTILS.SUBSTRING_INDEX(
  UTILS.SUBSTRING_INDEX(v__customerId, ',', v_index1), 
  ',', 
  -1
);
v_cus := REPLACE(v_cusrecord, ';', ',');
v_cus := REPLACE(v_cus, '"', '''');
DELETE "customersignatorygroup" 
WHERE 
  "customerId" = v_cus 
  AND "signatoryGroupId" IN (
    SELECT 
      "signatoryGroupId" 
    FROM 
      "signatorygroup" 
    WHERE 
      "coreCustomerId" = v__coreCustomerId 
      AND "contractId" = v__contractId
  );
IF v__signatorygroupId != ' ' THEN BEGIN INSERT INTO "customersignatorygroup" (
  "customerSignatoryGroupId", "signatoryGroupId", 
  "customerId", "createdby"
) 
VALUES 
  (
    SYS_GUID(), 
    v__signatorygroupId, 
    v_cus, 
    v_cus
  );
END;
END IF;
GOTO loop_1;
END;
END IF;
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure update_transaction_status_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "update_transaction_status_proc" (
  v__featureId IN VARCHAR2, v__status IN VARCHAR2, 
  v__confirmationNumber IN VARCHAR2, 
  v_cursor OUT SYS_REFCURSOR
) AS v_isSuccess VARCHAR2(50);
BEGIN v_isSuccess := 'true';
IF (v__featureId = 'ACH_COLLECTION') THEN 
UPDATE 
  "achtransaction" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (v__featureId = 'ACH_PAYMENT') THEN 
UPDATE 
  "achtransaction" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (v__featureId = 'ACH_FILES') THEN 
UPDATE 
  "achfile" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (v__featureId = 'BILL_PAY') THEN 
UPDATE 
  "billpaytransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'DOMESTIC_WIRE_TRANSFER'
) THEN 
UPDATE 
  "wiretransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'INTERNATIONAL_WIRE_TRANSFER'
) THEN 
UPDATE 
  "wiretransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'INTERNATIONAL_ACCOUNT_FUND_TRANSFER'
) THEN 
UPDATE 
  "internationalfundtransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'INTER_BANK_ACCOUNT_FUND_TRANSFER'
) THEN 
UPDATE 
  "interbankfundtransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'INTRA_BANK_FUND_TRANSFER'
) THEN 
UPDATE 
  "intrabanktransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (v__featureId = 'P2P') THEN 
UPDATE 
  "p2ptransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE IF (
  v__featureId = 'TRANSFER_BETWEEN_OWN_ACCOUNT'
) THEN 
UPDATE 
  "ownaccounttransfers" 
SET 
  "status" = v__status 
WHERE 
  "confirmationNumber" = v__confirmationNumber;
ELSE v_isSuccess := 'false';
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
END IF;
OPEN v_cursor FOR 
SELECT 
  v_isSuccess isSuccess 
FROM 
  DUAL;
--DBMS_SQL.RETURN_RESULT(v_cursor);
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure useractions_relative_create_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "useractions_relative_create_proc" (
  v__userId IN VARCHAR2, iv__accountsCSV IN VARCHAR2, 
  v__coreCustomerId IN VARCHAR2, v__contractId IN VARCHAR2, 
  iv__groupId IN VARCHAR2
) AS v__accountsCSV CLOB := iv__accountsCSV;
v__groupId VARCHAR2(50) := iv__groupId;
v_finished NUMBER(10, 0) := 0;
v_featureActionId VARCHAR2(255) := '';
v_actionslist VARCHAR2(4000) := '';
v_limitId VARCHAR2(255) := '';
v_entryStatus NUMBER(10, 0) := 0;
v_accountId VARCHAR2(255) := '';
v_actualLimitId VARCHAR2(255) := '';
v_serviceDefinitionId VARCHAR2(255) := '';
v_serviceType VARCHAR2(255) := '';
v_validFIActions CLOB := '';
v_validServiceDefinitionActions CLOB := '';
v_validGroupActions CLOB := '';
v_validActionsList CLOB := '';
v_groupId VARCHAR2(255) := '';
v_featureId VARCHAR2(255) := '';
v_limitvalue VARCHAR2(255) := '';
v_id VARCHAR2(255) := '';
CURSOR limits IS 
SELECT 
  "LimitType_id" 
FROM 
  "actionlimit" 
WHERE 
  "Action_id" = v_featureActionId;
CURSOR nonaccountlevelactions IS 
SELECT 
  "id" 
FROM 
  "featureaction" 
WHERE 
  INSTR(v_validActionsList, "id") <> 0 
  AND (
    "featureaction"."isAccountLevel" = '0'
  );
CURSOR accounts IS 
SELECT 
  "customeraccounts"."Account_id" 
FROM 
  "customeraccounts" 
WHERE 
  "customeraccounts"."contractId" = v__contractId 
  AND "customeraccounts"."coreCustomerId" = v__coreCustomerId 
  AND "customeraccounts"."Customer_id" = v__userId 
  AND INSTR(v__accountsCSV, "Account_id") <> 0;
CURSOR actions IS 
SELECT 
  "id" 
FROM 
  "featureaction" 
WHERE 
  INSTR(v_validActionsList, "id") <> 0 
  AND (
    "featureaction"."isAccountLevel" = '1'
  );
BEGIN --   /*TODO:SQLDEV*/ SET  XACT_ABORT  ON /*END:SQLDEV*/
IF (
  CASE WHEN v__accountsCSV IS NULL THEN 1 ELSE 0 END <> 0 
  OR v__accountsCSV = ' '
) THEN 
SELECT 
  LISTAGG(
    CAST(
      "customeraccounts"."Account_id" AS varchar2(255)
    ), 
    ','
  ) INTO v__accountsCSV 
FROM 
  "customeraccounts" 
WHERE 
  "customeraccounts"."Customer_id" = v__userId 
  AND "customeraccounts"."contractId" = v__contractId 
  AND "customeraccounts"."coreCustomerId" = v__coreCustomerId;
END IF;
SELECT 
  "contract"."servicedefinitionId" INTO v_serviceDefinitionId 
FROM 
  "contract" 
WHERE 
  "contract"."id" = v__contractId;
SELECT 
  "servicedefinition"."serviceType" INTO v_serviceType 
FROM 
  "servicedefinition" 
WHERE 
  "servicedefinition"."id" = v_serviceDefinitionId;
IF (
  CASE WHEN v__groupId IS NULL THEN 1 ELSE 0 END <> 0 
  OR v__groupId = ' '
) THEN 
SELECT 
  "groupservicedefinition"."Group_id" INTO v_groupId 
FROM 
  "groupservicedefinition" 
WHERE 
  "groupservicedefinition"."serviceDefinitionId" = v_serviceDefinitionId 
  AND "groupservicedefinition"."Group_id" = v__groupId;
END IF;
SELECT 
  LISTAGG(
    CAST(
      "featureaction"."id" AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_validFIActions 
FROM 
  "featureaction";
SELECT 
  LISTAGG(
    CAST(
      "servicedefinitionactionlimit"."actionId" AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_validServiceDefinitionActions 
FROM 
  "servicedefinitionactionlimit" 
WHERE 
  "servicedefinitionactionlimit"."serviceDefinitionId" = v_serviceDefinitionId 
  AND "servicedefinitionactionlimit"."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_validFIActions)
      )
  );
SELECT 
  "groupservicedefinition"."Group_id" INTO v__groupId 
FROM 
  "groupservicedefinition" 
WHERE 
  "groupservicedefinition"."serviceDefinitionId" = v_serviceDefinitionId 
  AND "groupservicedefinition"."Group_id" = v__groupId;
SELECT 
  LISTAGG(
    CAST(
      "groupactionlimit"."Action_id" AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_validGroupActions 
FROM 
  "groupactionlimit" 
WHERE 
  "groupactionlimit"."Group_id" = v__groupId 
  AND "groupactionlimit"."Action_id" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(
          v_validServiceDefinitionActions
        )
      )
  );
SELECT 
  LISTAGG(
    CAST(
      "contractactionlimit"."actionId" AS VARCHAR2(255)
    ), 
    ','
  ) INTO v_validActionsList 
FROM 
  "contractactionlimit" 
WHERE 
  "contractactionlimit"."contractId" = v__contractId 
  AND "contractactionlimit"."actionId" IN (
    SELECT 
      COLUMN_VALUE 
    FROM 
      TABLE(
        UTILS.STRING_SPLIT(v_validGroupActions)
      )
  );
OPEN accounts;
FETCH accounts INTO v_accountId;
<< loop_3 >> WHILE (accounts % FOUND = TRUE) LOOP BEGIN OPEN actions;
FETCH actions INTO v_featureActionId;
<< loop_2 >> WHILE (actions % FOUND = TRUE) LOOP BEGIN 
SELECT 
  "featureaction"."Feature_id" INTO v_featureId 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" = v_featureActionId;
v_entryStatus := 0;
OPEN limits;
FETCH limits INTO v_limitId;
<< loop_1 >> WHILE (limits % FOUND = TRUE) LOOP BEGIN 
SELECT 
  "contractactionlimit"."value" INTO v_limitvalue 
FROM 
  "contractactionlimit" 
WHERE 
  "contractactionlimit"."actionId" = v_featureActionId 
  AND "contractactionlimit"."limitTypeId" = v_limitId 
  AND "contractactionlimit"."contractId" = v__contractId 
  AND "contractactionlimit"."coreCustomerId" = v__coreCustomerId;
IF (
  v_limitId = 'MAX_TRANSACTION_LIMIT'
) THEN v_actualLimitId := 'AUTO_DENIED_TRANSACTION_LIMIT';
ELSE IF (
  v_limitId = 'MIN_TRANSACTION_LIMIT'
) THEN v_actualLimitId := 'PRE_APPROVED_TRANSACTION_LIMIT';
ELSE IF (v_limitId = 'DAILY_LIMIT') THEN BEGIN v_actualLimitId := 'PRE_APPROVED_DAILY_LIMIT';
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."Account_id", 
  "customeraction"."isAllowed", "customeraction"."LimitType_id", 
  "customeraction"."value"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, 0.00
  );
v_actualLimitId := 'AUTO_DENIED_DAILY_LIMIT';
END;
ELSE BEGIN IF (v_limitId = 'WEEKLY_LIMIT') THEN BEGIN v_actualLimitId := 'PRE_APPROVED_WEEKLY_LIMIT';
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."Account_id", 
  "customeraction"."isAllowed", "customeraction"."LimitType_id", 
  "customeraction"."value"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, 0.00
  );
v_actualLimitId := 'AUTO_DENIED_WEEKLY_LIMIT';
END;
END IF;
END;
END IF;
END IF;
END IF;
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."Account_id", 
  "customeraction"."isAllowed", "customeraction"."LimitType_id", 
  "customeraction"."value"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, v_accountId, 
    1, v_actualLimitId, v_limitvalue
  );
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."Account_id", 
  "customeraction"."isAllowed", "customeraction"."LimitType_id", 
  "customeraction"."value"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, v_accountId, 
    1, v_limitId, v_limitvalue
  );
v_entryStatus := 1;
FETCH limits INTO v_limitId;
GOTO loop_1;
END;
END LOOP;
CLOSE limits;
IF v_entryStatus = 0 THEN BEGIN 
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."Account_id", 
  "customeraction"."isAllowed"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, v_accountId, 
    1
  );
END;
END IF;
v_actionslist := v_featureActionId || ',' || v_actionslist;
FETCH actions INTO v_featureActionId;
GOTO loop_2;
END;
END LOOP;
CLOSE actions;
FETCH accounts INTO v_accountId;
GOTO loop_3;
END;
END LOOP;
CLOSE accounts;
OPEN nonaccountlevelactions;
FETCH nonaccountlevelactions INTO v_featureActionId;
<< loop_1 >> WHILE (
  nonaccountlevelactions % FOUND = TRUE
) LOOP BEGIN 
SELECT 
  "featureaction"."Feature_id" INTO v_featureId 
FROM 
  "featureaction" 
WHERE 
  "featureaction"."id" = v_featureActionId;
SELECT 
  SUBSTR(
    SYS_GUID(), 
    0, 
    50
  ) INTO v_id 
FROM 
  DUAL;
INSERT INTO "customeraction" (
  "customeraction"."id", "customeraction"."RoleType_id", 
  "customeraction"."Customer_id", 
  "customeraction"."contractId", 
  "customeraction"."coreCustomerId", 
  "customeraction"."featureId", "customeraction"."Action_id", 
  "customeraction"."isAllowed"
) 
VALUES 
  (
    v_id, v_serviceType, v__userId, v__contractId, 
    v__coreCustomerId, v_featureId, 
    v_featureActionId, 1
  );
FETCH nonaccountlevelactions INTO v_featureActionId;
GOTO loop_1;
END;
END LOOP;
CLOSE nonaccountlevelactions;
EXCEPTION WHEN OTHERS THEN utils.handleerror(SQLCODE, SQLERRM);
END;
/

--  DDL for Procedure userPermissionDelete_proc


CREATE 
OR REPLACE NONEDITIONABLE PROCEDURE "userPermissionDelete_proc" (
  "_USERID" IN VARCHAR2, "_PERMISSIONIDS" IN LONG
) AS v_caid VARCHAR2(50);
v_isEnabled VARCHAR2(10);
v_finished NUMBER(10, 0) := 0;
v_caid_count NUMBER(10, 0) := 0;
CURSOR caids IS 
SELECT 
  c."id" 
FROM 
  "compositeaction" c 
WHERE 
  FIND_IN_SET(
    "Permission_id", "_PERMISSIONIDS"
  ) > 0;
BEGIN OPEN caids;
WHILE(1 = 1) LOOP BEGIN FETCH caids INTO v_caid;
IF (caids % NOTFOUND) THEN BEGIN exit;
END;
END IF;
SELECT 
  COUNT(*) INTO v_caid_count 
FROM 
  "compositeaction" c, 
  "userpermission" up 
WHERE 
  up."User_id" = "_USERID" 
  AND up."Permission_id" = c."Permission_id" 
  AND FIND_IN_SET(
    up."Permission_id", "_PERMISSIONIDS"
  ) = 0 
  AND c."id" = v_caid;
IF v_caid_count = 0 THEN BEGIN DELETE "usercompositeaction" 
WHERE 
  "User_id" = "_USERID" 
  AND "CompositeAction_id" = v_caid;
END;
DELETE "userpermission" 
WHERE 
  "User_id" = "_USERID" 
  AND FIND_IN_SET(
    "Permission_id", "_PERMISSIONIDS"
  ) > 0;
END IF;
END;
END LOOP;
CLOSE caids;
END;
/